async function loadStaffPeople(ctx: TenantContext): Promise<Person[]> {
  return getPartyRepository().listAllPeople<Person>(ctx, {
    employeesAndLeaversOnly: true,
  });
}

function dedupeById<T extends { id: string }>(items: readonly T[]): T[] {
  const seen = new Set<string>();
  const out: T[] = [];
  for (const item of items) {
    if (!item?.id || seen.has(item.id)) continue;
    seen.add(item.id);
    out.push(item);
  }
  return out;
}

export interface ScopedConflictSignals {
  readonly terms?: readonly string[];
  readonly emails?: readonly string[];
  readonly phones?: readonly string[];
  readonly postcodes?: readonly string[];
  readonly companyNumbers?: readonly string[];
  readonly linkedPersonIds?: readonly string[];
  readonly linkedOrganisationIds?: readonly string[];
  readonly excludeEnquiryId?: string | null;
}

export function extractConflictSignalsFromParties(
  parties: readonly ConflictCheckParty[],
  opts?: { readonly excludeEnquiryId?: string | null },
): ScopedConflictSignals {
  const termSet = new Set<string>();
  const emailSet = new Set<string>();
  const companySet = new Set<string>();
  const linkedPersonSet = new Set<string>();
  const linkedOrgSet = new Set<string>();

  for (const p of parties) {
    const trimmedName = typeof p.name === 'string' ? p.name.trim() : '';
    if (trimmedName) {
      termSet.add(trimmedName);
      if (trimmedName.includes('@')) {
        emailSet.add(trimmedName.toLowerCase());
      }
    }
    const trimmedSub =
      typeof p.subtitle === 'string' ? p.subtitle.trim() : '';
    if (trimmedSub && trimmedSub.includes('@')) {
      emailSet.add(trimmedSub.toLowerCase());
    }
    const rawPrev = p.identifiers?.previousNames;
    if (typeof rawPrev === 'string' && rawPrev.trim()) {
      for (const token of rawPrev.split(/[,;/\n]+/)) {
        const clean = token.trim();
        if (clean) termSet.add(clean);
      }
    }
    const compNo = p.identifiers?.companyNumber?.trim();
    if (compNo) companySet.add(compNo);
    if (p.linkedRecordId) {
      if (p.entityType === 'person') linkedPersonSet.add(p.linkedRecordId);
      else linkedOrgSet.add(p.linkedRecordId);
    }
  }

  return {
    terms: Array.from(termSet),
    emails: Array.from(emailSet),
    companyNumbers: Array.from(companySet),
    linkedPersonIds: Array.from(linkedPersonSet),
    linkedOrganisationIds: Array.from(linkedOrgSet),
    excludeEnquiryId: opts?.excludeEnquiryId ?? null,
  };
}

export async function loadFullConflictSearchGraph(
  ctx: TenantContext,
  _signals: ScopedConflictSignals,
  viewerId: string,
  staffPeople: readonly Person[],
  teams: readonly Team[],
  rbacConfig?: RbacConfiguration,
): Promise<{
  people: Person[];
  organisations: Organisation[];
  links: PersonOrganisationLink[];
  matters: Matter[];
  enquiries: Enquiry[];
  canViewMatter: (m: Matter) => boolean;
  canViewEnquiry: (e: Enquiry) => boolean;
}> {
  const partyRepo = getPartyRepository();
  const matterRepo = getMatterRepository();
  const intakeRepo = getIntakeQuoteRepository();

  const [peopleRaw, organisations, links, matters, enquiries] = await Promise.all([
    partyRepo.listAllPeople<Person>(ctx),
    partyRepo.listAllOrganisations<Organisation>(ctx),
    partyRepo.listAllLinks<PersonOrganisationLink>(ctx),
    matterRepo.listAllMattersUnfiltered<Matter>(ctx),
    intakeRepo.listAllEnquiriesUnfiltered<Enquiry>(ctx),
  ]);

  const allPeopleOut = dedupeById([...staffPeople, ...peopleRaw]);
  const actor = allPeopleOut.find((p) => p.id === viewerId) ?? null;
  const activeSession = getActiveActorSession();
  const effectiveTokenRoles =
    actor && activeSession?.personId === actor.id
      ? activeSession.tokenRoles
      : undefined;
  const hasRestrictedAccess = hasPersonPermission(
    actor,
    'matter:restricted:access',
    {
      allPeople: allPeopleOut,
      teams: [...teams],
      tokenRoles: effectiveTokenRoles,
      tokenRolesActorId: viewerId,
      ...(rbacConfig ? { config: { rbac: rbacConfig } } : {}),
    },
  );
  const hiddenEnquiryIdList = await intakeRepo.listHiddenEnquiryIds(ctx, viewerId, {
    hasRestrictedMatterAccess: hasRestrictedAccess,
  });
  const hiddenEnquiryIds = new Set(hiddenEnquiryIdList);

  return {
    people: allPeopleOut,
    organisations,
    links,
    matters,
    enquiries,
    canViewMatter: (m: Matter) =>
      Boolean(viewerId) &&
      canPersonAccessMatter(m, viewerId, actor, {
        allPeople: allPeopleOut,
        teams: [...teams],
        tokenRoles: effectiveTokenRoles,
        tokenRolesActorId: viewerId,
        ...(rbacConfig ? { config: { rbac: rbacConfig } } : {}),
      }),
    canViewEnquiry: (e: Enquiry) =>
      Boolean(viewerId) && !hiddenEnquiryIds.has(e.id),
  };
}

export async function loadScopedConflictSearchGraphForParity(
  ctx: TenantContext,
  signals: ScopedConflictSignals,
  viewerId: string,
  staffPeople: readonly Person[],
  teams: readonly Team[],
  rbacConfig?: RbacConfiguration,
) {
  return loadScopedConflictSearchGraph(
    ctx,
    signals,
    viewerId,
    staffPeople,
    teams,
    rbacConfig,
  );
}

async function loadScopedConflictSearchGraph(
  ctx: TenantContext,
  signals: {
    readonly terms?: readonly string[];
    readonly emails?: readonly string[];
    readonly phones?: readonly string[];
    readonly postcodes?: readonly string[];
    readonly companyNumbers?: readonly string[];
    readonly linkedPersonIds?: readonly string[];
    readonly linkedOrganisationIds?: readonly string[];
    readonly excludeEnquiryId?: string | null;
  },
  viewerId: string,
  staffPeople: readonly Person[],
  teams: readonly Team[],
  rbacConfig?: RbacConfiguration,
): Promise<{
  people: Person[];
  organisations: Organisation[];
  links: PersonOrganisationLink[];
  matters: Matter[];
  enquiries: Enquiry[];
  canViewMatter: (m: Matter) => boolean;
  canViewEnquiry: (e: Enquiry) => boolean;
}> {
  const partyRepo = getPartyRepository();
  const matterRepo = getMatterRepository();
  const intakeRepo = getIntakeQuoteRepository();

  const harvestPersonSignals = (
    p: Person,
    termSet: Set<string>,
    emailSet: Set<string>,
    phoneSet: Set<string>,
    postcodeSet: Set<string>,
  ) => {
    for (const nm of [
      personDisplayName(p),
      `${p.firstName} ${p.surname}`,
      p.preferredName ? `${p.preferredName} ${p.surname}` : '',
      ...(p.otherNames ?? []).map((n) => n.name),
    ]) {
      const t = nm?.trim();
      if (t) termSet.add(t);
    }
    for (const em of p.emails ?? []) {
      const addr = em?.address?.trim().toLowerCase();
      if (addr) emailSet.add(addr);
    }
    for (const ph of p.phones ?? []) {
      const num = ph?.number?.trim();
      if (num) phoneSet.add(num);
    }
    for (const a of p.addresses ?? []) {
      const pc = a?.postcode?.trim();
      if (pc) postcodeSet.add(pc);
    }
  };

  const harvestOrgSignals = (
    o: Organisation,
    termSet: Set<string>,
    emailSet: Set<string>,
    phoneSet: Set<string>,
    postcodeSet: Set<string>,
    companySet: Set<string>,
  ) => {
    for (const nm of [o.legalName, ...(o.otherNames ?? []).map((n) => n.name)]) {
      const t = nm?.trim();
      if (t) termSet.add(t);
    }
    if (o.generalEmail?.trim()) emailSet.add(o.generalEmail.trim().toLowerCase());
    if (o.mainPhone?.trim()) phoneSet.add(o.mainPhone.trim());
    for (const a of [
      o.registeredAddress,
      o.correspondenceAddress,
      o.billingAddress,
    ]) {
      const pc = a?.postcode?.trim();
      if (pc) postcodeSet.add(pc);
    }
    if (o.companyNumber?.trim()) companySet.add(o.companyNumber.trim());
  };

  const seedTermSet = new Set((signals.terms ?? []).map((t) => t.trim()).filter(Boolean));
  const seedEmailSet = new Set(
    (signals.emails ?? []).map((e) => e.trim().toLowerCase()).filter(Boolean),
  );
  const seedPhoneSet = new Set((signals.phones ?? []).map((p) => p.trim()).filter(Boolean));
  const seedPostcodeSet = new Set(
    (signals.postcodes ?? []).map((pc) => pc.trim()).filter(Boolean),
  );
  const seedCompanySet = new Set(
    (signals.companyNumbers ?? []).map((c) => c.trim()).filter(Boolean),
  );

  // Hydrate explicitly linked entities first so their otherNames, emails & company numbers seed candidate lookup
  const [seedPeopleLoaded, seedOrgsLoaded] = await Promise.all([
    (signals.linkedPersonIds ?? []).length > 0
      ? partyRepo.listPeopleByIds<Person>(ctx, signals.linkedPersonIds ?? [])
      : Promise.resolve<Person[]>([]),
    (signals.linkedOrganisationIds ?? []).length > 0
      ? partyRepo.listOrganisationsByIds<Organisation>(
          ctx,
          signals.linkedOrganisationIds ?? [],
        )
      : Promise.resolve<Organisation[]>([]),
  ]);
  for (const p of seedPeopleLoaded) {
    harvestPersonSignals(p, seedTermSet, seedEmailSet, seedPhoneSet, seedPostcodeSet);
  }
  for (const o of seedOrgsLoaded) {
    harvestOrgSignals(
      o,
      seedTermSet,
      seedEmailSet,
      seedPhoneSet,
      seedPostcodeSet,
      seedCompanySet,
    );
  }

  const cand = await partyRepo.findSqlConflictCandidates<
    Person,
    Organisation,
    PersonOrganisationLink
  >(ctx, {
    terms: Array.from(seedTermSet),
    emails: Array.from(seedEmailSet),
    phones: Array.from(seedPhoneSet),
    postcodes: Array.from(seedPostcodeSet),
    companyNumbers: Array.from(seedCompanySet),
    linkedPersonIds: signals.linkedPersonIds,
    linkedOrganisationIds: signals.linkedOrganisationIds,
  });

  const mergedOrganisationsMap = new Map<string, Organisation>();
  for (const o of [...seedOrgsLoaded, ...cand.organisations]) {
    if (o?.id && !mergedOrganisationsMap.has(o.id)) {
      mergedOrganisationsMap.set(o.id, o);
    }
  }
  const mergedPeopleMap = new Map<string, Person>();
  for (const p of [...seedPeopleLoaded, ...cand.people]) {
    if (p?.id && !mergedPeopleMap.has(p.id)) {
      mergedPeopleMap.set(p.id, p);
    }
  }

  const seedOrgIds = Array.from(
    new Set(
      [
        ...(signals.linkedOrganisationIds ?? []),
        ...mergedOrganisationsMap.keys(),
        ...cand.links.map((l) => l.organisationId).filter(Boolean),
      ].filter(Boolean),
    ),
  );
  const corpGroupOrgs =
    seedOrgIds.length > 0
      ? await partyRepo.expandCorporateGroupOrganisationIds<Organisation>(
          ctx,
          seedOrgIds,
        )
      : [];
  for (const o of corpGroupOrgs) {
    if (o?.id && !mergedOrganisationsMap.has(o.id)) {
      mergedOrganisationsMap.set(o.id, o);
    }
  }

  const preLinkPersonIds = Array.from(
    new Set(
      [
        ...(signals.linkedPersonIds ?? []),
        ...mergedPeopleMap.keys(),
        ...cand.links.map((l) => l.personId).filter(Boolean),
      ].filter(Boolean),
    ),
  );
  const preLinkOrgIds = Array.from(mergedOrganisationsMap.keys());
  const graphLinks =
    preLinkPersonIds.length > 0 || preLinkOrgIds.length > 0
      ? await partyRepo.listLinksForEntities<PersonOrganisationLink>(ctx, {
          personIds: preLinkPersonIds,
          organisationIds: preLinkOrgIds,
        })
      : [];

  // Hydrate all link & corporate-group counterparts before querying matters & enquiries
  const expandedPersonIdSet = new Set<string>(preLinkPersonIds);
  const expandedOrgIdSet = new Set<string>(preLinkOrgIds);
  for (const l of [...cand.links, ...graphLinks]) {
    if (l.personId) expandedPersonIdSet.add(l.personId);
    if (l.organisationId) expandedOrgIdSet.add(l.organisationId);
  }
  const missingCounterpartPersonIds = Array.from(expandedPersonIdSet).filter(
    (id) => !mergedPeopleMap.has(id),
  );
  const missingCounterpartOrgIds = Array.from(expandedOrgIdSet).filter(
    (id) => !mergedOrganisationsMap.has(id),
  );
  if (
    missingCounterpartPersonIds.length > 0 ||
    missingCounterpartOrgIds.length > 0
  ) {
    const [cpPeople, cpOrgs, cpGroupOrgs] = await Promise.all([
      missingCounterpartPersonIds.length > 0
        ? partyRepo.listPeopleByIds<Person>(ctx, missingCounterpartPersonIds)
        : Promise.resolve<Person[]>([]),
      missingCounterpartOrgIds.length > 0
        ? partyRepo.listOrganisationsByIds<Organisation>(
            ctx,
            missingCounterpartOrgIds,
          )
        : Promise.resolve<Organisation[]>([]),
      missingCounterpartOrgIds.length > 0
        ? partyRepo.expandCorporateGroupOrganisationIds<Organisation>(
            ctx,
            missingCounterpartOrgIds,
          )
        : Promise.resolve<Organisation[]>([]),
    ]);
    for (const p of cpPeople) mergedPeopleMap.set(p.id, p);
    for (const o of [...cpOrgs, ...cpGroupOrgs]) {
      mergedOrganisationsMap.set(o.id, o);
      expandedOrgIdSet.add(o.id);
    }
  }

  // Second-pass signal harvest across candidate + linked counterpart + corporate-group closure
  const expandedTermSet = new Set<string>(seedTermSet);
  const expandedEmailSet = new Set<string>(seedEmailSet);
  const expandedPhoneSet = new Set<string>(seedPhoneSet);
  const expandedPostcodeSet = new Set<string>(seedPostcodeSet);
  const expandedCompanySet = new Set<string>(seedCompanySet);
  for (const p of mergedPeopleMap.values()) {
    harvestPersonSignals(
      p,
      expandedTermSet,
      expandedEmailSet,
      expandedPhoneSet,
      expandedPostcodeSet,
    );
  }
  for (const o of mergedOrganisationsMap.values()) {
    harvestOrgSignals(
      o,
      expandedTermSet,
      expandedEmailSet,
      expandedPhoneSet,
      expandedPostcodeSet,
      expandedCompanySet,
    );
  }

  const allOrgIds = Array.from(expandedOrgIdSet);
  const allCandPersonIds = Array.from(expandedPersonIdSet);
  const expandedTerms = Array.from(expandedTermSet);
  const expandedEmails = Array.from(expandedEmailSet);
  const expandedPhones = Array.from(expandedPhoneSet);

  const [matchedMatterIds, matchedEnquiries] = await Promise.all([
    matterRepo.listMatterIdsMatchingCandidateGraph(ctx, {
      candidateEntityIds: [...allCandPersonIds, ...allOrgIds],
      candidateTerms: expandedTerms,
    }),
    intakeRepo.findSqlConflictEnquiryCandidates<Enquiry>(ctx, {
      terms: expandedTerms,
      emails: expandedEmails,
      phones: expandedPhones,
      linkedPersonIds: allCandPersonIds,
      linkedOrganisationIds: allOrgIds,
      excludeEnquiryId: signals.excludeEnquiryId,
      includeAll: true,
      viewerId,
    }),
  ]);

  // Expand links with any person/org IDs connected across matched matters/enquiries
  const extraLinkPersonIds = new Set<string>(allCandPersonIds);
  const extraLinkOrgIds = new Set<string>(allOrgIds);
  for (const l of graphLinks) {
    if (l.personId) extraLinkPersonIds.add(l.personId);
    if (l.organisationId) extraLinkOrgIds.add(l.organisationId);
  }
  for (const e of matchedEnquiries) {
    if (e.linkedPersonId) extraLinkPersonIds.add(e.linkedPersonId);
    if (e.linkedOrganisationId) extraLinkOrgIds.add(e.linkedOrganisationId);
    if (e.referrerPersonId) extraLinkPersonIds.add(e.referrerPersonId);
  }

  const matters =
    matchedMatterIds.length > 0
      ? await matterRepo.listMattersByIds<Matter>(ctx, matchedMatterIds, {
          includeRestricted: true,
        })
      : [];
  for (const m of matters) {
    if (m.clientId) {
      extraLinkOrgIds.add(m.clientId);
      extraLinkPersonIds.add(m.clientId);
    }
    for (const ac of m.additionalClientIds ?? []) {
      if (ac) {
        extraLinkOrgIds.add(ac);
        extraLinkPersonIds.add(ac);
      }
    }
    if (m.instructingContactId) {
      extraLinkPersonIds.add(m.instructingContactId);
      extraLinkOrgIds.add(m.instructingContactId);
    }
    if (m.billingContactId) {
      extraLinkPersonIds.add(m.billingContactId);
      extraLinkOrgIds.add(m.billingContactId);
    }
    if (m.referrerContactId) {
      extraLinkPersonIds.add(m.referrerContactId);
      extraLinkOrgIds.add(m.referrerContactId);
    }
    if (m.responsiblePartnerId) extraLinkPersonIds.add(m.responsiblePartnerId);
    for (const pt of m.parties ?? []) {
      if (pt.linkedRecordId) {
        if (pt.entityType === 'person') extraLinkPersonIds.add(pt.linkedRecordId);
        else extraLinkOrgIds.add(pt.linkedRecordId);
      }
    }
  }

  const missingPersonIds = Array.from(extraLinkPersonIds).filter(
    (id) => !mergedPeopleMap.has(id),
  );
  const missingOrgIds = Array.from(extraLinkOrgIds).filter(
    (id) => !mergedOrganisationsMap.has(id),
  );
  const [missingPeople, missingOrgs] = await Promise.all([
    missingPersonIds.length > 0
      ? partyRepo.listPeopleByIds<Person>(ctx, missingPersonIds)
      : Promise.resolve<Person[]>([]),
    missingOrgIds.length > 0
      ? partyRepo.listOrganisationsByIds<Organisation>(ctx, missingOrgIds)
      : Promise.resolve<Organisation[]>([]),
  ]);
  for (const p of missingPeople) mergedPeopleMap.set(p.id, p);
  for (const o of missingOrgs) mergedOrganisationsMap.set(o.id, o);

  const actor = staffPeople.find((p) => p.id === viewerId) ?? null;
  const activeSession = getActiveActorSession();
  const effectiveTokenRoles =
    actor && activeSession?.personId === actor.id
      ? activeSession.tokenRoles
      : undefined;
  const hasRestrictedAccess = hasPersonPermission(
    actor,
    'matter:restricted:access',
    {
      allPeople: [...staffPeople],
      teams: [...teams],
      tokenRoles: effectiveTokenRoles,
      tokenRolesActorId: viewerId,
      ...(rbacConfig ? { config: { rbac: rbacConfig } } : {}),
    },
  );
  const hiddenEnquiryIdList = await intakeRepo.listHiddenEnquiryIds(ctx, viewerId, {
    hasRestrictedMatterAccess: hasRestrictedAccess,
  });
  const hiddenEnquiryIds = new Set(hiddenEnquiryIdList);

  const allPeopleOut = dedupeById([
    ...staffPeople,
    ...Array.from(mergedPeopleMap.values()),
  ]);
  const allLinksMap = new Map<string, PersonOrganisationLink>();
  for (const l of [...cand.links, ...graphLinks]) {
    if (l?.id && !allLinksMap.has(l.id)) allLinksMap.set(l.id, l);
  }

  return {
    people: allPeopleOut,
    organisations: Array.from(mergedOrganisationsMap.values()),
    links: Array.from(allLinksMap.values()),
    matters,
    enquiries: matchedEnquiries,
    canViewMatter: (m: Matter) =>
      Boolean(viewerId) &&
      canPersonAccessMatter(m, viewerId, actor, {
        allPeople: allPeopleOut,
        teams: [...teams],
        tokenRoles: effectiveTokenRoles,
        tokenRolesActorId: viewerId,
        ...(rbacConfig ? { config: { rbac: rbacConfig } } : {}),
      }),
    canViewEnquiry: (e: Enquiry) =>
      Boolean(viewerId) && !hiddenEnquiryIds.has(e.id),
  };
}

export interface AuthenticatedActorContext {
  personId: string;
  person: Person;
  session: VerifiedEntraSessionPayload;
  mfaVerified: boolean;
  tenantId: string;
  allPeople?: readonly Person[];
  teams?: readonly Team[];
}

export async function requireAuthenticatedActor(): Promise<AuthenticatedActorContext> {
  const activeConfig = getActiveTenantConfiguration();
  const tenantId = activeConfig.tenantId;
  const entraSession = await getEntraSession();
  if (!entraSession || !entraSession.personId || !entraSession.tenantId?.trim()) {
    throw new AuthorisationError({
      code: 'UNAUTHENTICATED',
      message: 'Authentication is required. Please sign in with Microsoft Entra ID.',
      tenantId,
      correlationId: 'auth-check',
      actorUserId: 'anonymous',
    });
  }
  const authCtx = resolveCurrentTenantContext(
    createVerifiedSessionActorFromEntraSession(entraSession, {
      correlationId: 'auth-check',
    }),
    activeConfig,
  );
  const [allPeople, teams] = await Promise.all([
    loadStaffPeople(authCtx),
    getHrAndRbacRepository().listAllTeams<Team>(authCtx),
  ]);
  const loaded = allPeople.find((p) => p.id === entraSession.personId) ?? null;
  const person =
    loaded && loaded.isEmployee && !loaded.mergedIntoId ? loaded : null;
  if (!person) {
    throw new AuthorisationError({
      code: 'UNAUTHENTICATED',
      message: 'Authenticated employee record was not found or is inactive.',
      tenantId,
      correlationId: 'auth-check',
      actorUserId: entraSession.personId,
    });
  }
  const resolvedTenantId = entraSession.tenantId.trim();
  return {
    personId: person.id,
    person,
    session: entraSession,
    mfaVerified: Boolean(entraSession.mfaVerified),
    tenantId: resolvedTenantId,
    allPeople,
    teams,
  };
}

function nextMonotonicIsoTimestamp(previousIso?: string | null): string {
  const nowMs = Date.now();
  const prevMs = previousIso ? Date.parse(previousIso) : NaN;
  if (!Number.isNaN(prevMs) && nowMs <= prevMs) {
    return new Date(prevMs + 1).toISOString();
  }
  return new Date(nowMs).toISOString();
}

function touchMatter(matter: Matter, byId: string): string {
  const nextIso = nextMonotonicIsoTimestamp(matter.updatedAt);
  matter.updatedAt = nextIso;
  matter.updatedById = byId;
  return nextIso;
}

export async function withAuthenticatedActor<R>(
  fn: (actor: AuthenticatedActorContext) => Promise<R> | R,
): Promise<R> {
  const actor = await requireAuthenticatedActor();
  return runWithActiveActorSession(
    {
      tenantId: actor.tenantId,
      personId: actor.personId,
      tokenRoles: actor.session.mappedRoles,
      expiresAtMs: new Date(actor.session.expiresAt).getTime(),
      verifiedSession: actor.session,
    },
    () => fn(actor),
  );
}

export const withPageActor = withAuthenticatedActor;

export async function getCurrentUserId(): Promise<string> {
  const actor = await requireAuthenticatedActor();
  return actor.personId;
}

export function isDemoModeEnabled(): boolean {
  return isNonLiveDemoEnvironment();
}

export function isDataResetAllowedEnvironment(): boolean {
  return isNonLiveDemoEnvironment();
}

export async function switchUserInDemoMode(targetUserId: string): Promise<{
  ok: boolean;
  personId: string;
}> {
  const actor = await requireAuthenticatedActor();
  const tenantId = getActiveTenantConfiguration().tenantId;
  if (!isDemoModeEnabled()) {
    throw new AuthorisationError({
      code: 'FORBIDDEN',
      message: 'User switching is only permitted when Demo Mode is enabled in tenant configuration (featureFlags.enableDemoMode).',
      tenantId,
      correlationId: 'auth-check',
      actorUserId: actor.personId,
    });
  }
  const ctx = resolveDefaultServiceTenantContext(null, actor.personId, {
    session: actor.session,
  });
  const matterRepo = getMatterRepository();
  const [people, teams, rbacConfig] = await Promise.all([
    loadStaffPeople(ctx),
    getHrAndRbacRepository().listAllTeams<Team>(ctx),
    loadEffectiveTenantRbacConfig(ctx),
  ]);
  const targetPerson = people.find(
    (p) => p.id === targetUserId && p.isEmployee && !p.mergedIntoId,
  );
  if (!targetPerson || !targetPerson.demo) {
    throw new AuthorisationError({
      code: 'FORBIDDEN',
      message: 'User switching in Demo Mode is restricted to designated demo users.',
      tenantId,
      correlationId: 'auth-check',
      actorUserId: actor.personId,
    });
  }

  const actorPerson = people.find((p) => p.id === actor.personId) ?? null;
  const actorPerms = resolvePersonPermissionSet(actorPerson, {
    allPeople: people,
    teams,
    mfaVerified: actor.mfaVerified,
    tokenRoles: actor.session.mappedRoles,
    tokenRolesActorId: actor.personId,
    config: { rbac: rbacConfig },
  });
  const targetPerms = resolvePersonPermissionSet(targetPerson, {
    allPeople: people,
    teams,
    mfaVerified: true,
    config: { rbac: rbacConfig },
  });
  const missingPerm = targetPerms.permissionList.find(
    (perm) => !actorPerms.permissions.has(perm),
  );
  if (missingPerm) {
    throw new AuthorisationError({
      code: 'FORBIDDEN',
      message: `Cannot switch in Demo Mode to a persona holding permission '${missingPerm}' not held by the current actor.`,
      requiredPermission: missingPerm,
      tenantId,
      correlationId: 'auth-check',
      actorUserId: actor.personId,
    });
  }

  // R104: Refuse Demo Mode switch if the target persona can access any restricted/staff matter not accessible to the signed-in actor
  const actorHiddenRestrictedIds = await matterRepo.listHiddenRestrictedMatterIds(
    ctx,
    actor.personId,
    { hasRestrictedMatterAccess: actorPerms.permissions.has('matter:restricted:access') },
  );
  const candidateRestrictedMatters =
    actorHiddenRestrictedIds.length > 0
      ? await matterRepo.listMattersByIds<Matter>(ctx, actorHiddenRestrictedIds, {
          includeRestricted: true,
        })
      : [];
  const restrictedMatterWithTargetAccess = candidateRestrictedMatters.find(
    (m) =>
      Boolean(
        m.isStaffMatter ||
          m.hasEthicalWall ||
          (m.restrictedAccessUserIds && m.restrictedAccessUserIds.length > 0),
      ) &&
      canPersonAccessMatter(m, targetPerson.id, targetPerson, {
        allPeople: people,
        teams,
        config: { rbac: rbacConfig },
      }) &&
      !canPersonAccessMatter(m, actor.personId, actorPerson, {
        allPeople: people,
        teams,
        tokenRoles: actor.session.mappedRoles,
        tokenRolesActorId: actor.personId,
        config: { rbac: rbacConfig },
      }),
  );
  if (restrictedMatterWithTargetAccess) {
    throw new AuthorisationError({
      code: 'FORBIDDEN',
      message:
        'Cannot switch in Demo Mode to a persona who has access to restricted or staff matters not accessible to the current actor.',
      requiredPermission: 'matter:restricted:access',
      tenantId,
      correlationId: 'auth-check',
      actorUserId: actor.personId,
    });
  }

  const now = Date.now();
  const nextSession: EntraSessionPayload = {
    ...actor.session,
    personId: targetPerson.id,
    email: targetPerson.emails?.[0]?.address ?? actor.session.email,
    displayName: personDisplayName(targetPerson),
    mappedRoles: resolveEmployeeRoles(targetPerson, teams),
    authenticatedAt: new Date(now).toISOString(),
    expiresAt: new Date(now + 8 * 60 * 60 * 1000).toISOString(),
  };

  await runWithAuditStagingScope(() =>
    getPartyRepository().withTenantTransaction(ctx, async () => {
      writeAudit(null, {
        recordType: 'person',
        recordId: targetPerson.id,
        action: 'update',
        field: 'Demo user switch',
        oldValue: actor.personId,
        newValue: targetPerson.id,
        byId: actor.personId,
      });
      await flushStagedAuditEntries(ctx);
    }),
  );

  await persistEntraSessionCookie(nextSession);

  return { ok: true, personId: targetPerson.id };
}

export function activeEmployees(
  peopleOrSource:
    | readonly Person[]
    | { people: readonly Person[]; values: readonly ChoiceValue[] },
  valuesArg?: readonly ChoiceValue[],
): Person[] {
  const people = Array.isArray(peopleOrSource)
    ? peopleOrSource
    : (peopleOrSource as { people: readonly Person[]; values: readonly ChoiceValue[] })
        .people;
  const values = Array.isArray(peopleOrSource)
    ? (valuesArg ?? [])
    : (peopleOrSource as { people: readonly Person[]; values: readonly ChoiceValue[] })
        .values;
  return people
    .filter(
      (p) =>
        isSelectableInEmployeeDropdown(p) &&
        !p.mergedIntoId &&
        systemKeyOf(values as ChoiceValue[], p.recordStatusId) === 'active',
    )
    .sort((a, b) => personDisplayName(a).localeCompare(personDisplayName(b)));
}

export function formatContext(
  source: {
    people?: readonly Person[];
    organisations?: readonly Organisation[];
    matters?: readonly Matter[];
    enquiries?: readonly Enquiry[];
    tasks?: readonly Task[];
    teams?: readonly Team[];
    values: ChoiceValue[];
  },
  overrides?: {
    people?: readonly Person[];
    organisations?: readonly Organisation[];
    matters?: readonly Matter[];
  },
): FormatContext {
  const names = new Map<string, string>();
  for (const p of overrides?.people ?? source.people ?? []) {
    names.set(p.id, personDisplayName(p));
  }
  for (const o of overrides?.organisations ?? source.organisations ?? []) {
    names.set(o.id, o.legalName);
  }
  for (const m of overrides?.matters ?? source.matters ?? []) {
    names.set(m.id, `${m.matterNumber} — ${m.title}`);
  }
  for (const e of source.enquiries ?? []) {
    names.set(e.id, `${e.reference} — ${enquiryDisplayName(e)}`);
  }
  for (const t of source.tasks ?? []) {
    names.set(t.id, `${t.reference} — ${t.title}`);
  }
  for (const tm of source.teams ?? []) {
    names.set(tm.id, tm.name);
  }
  return {
    values: source.values,
    nameOf: (id: string) => names.get(id) ?? id,
  };
}

declare global {
  var __oneSquaredKeyDateRepo: TenantKeyDateRepository | undefined;
}

export function getKeyDateRepository(): TenantKeyDateRepository {
  if (!global.__oneSquaredKeyDateRepo) {
    global.__oneSquaredKeyDateRepo = new TenantKeyDateRepository();
  }
  return global.__oneSquaredKeyDateRepo;
}

function resolveDefaultServiceTenantContext(
  _store?: FirmStore | null,
  preferredActorId?: string | null,
  options?: {
    tenantCtx?: TenantContext | null;
    session?: VerifiedEntraSessionPayload | null;
    correlationId?: string;
  },
): TenantContext {
  if (options?.tenantCtx) {
    return options.tenantCtx;
  }
  const activeTenantConfig = getActiveTenantConfiguration();
  const activeActorSession = getActiveActorSession()?.verifiedSession as
    | VerifiedEntraSessionPayload
    | undefined;
  const candidateSession =
    options?.session ??
    activeActorSession ??
    getTestEntraSessionOverride() ??
    undefined;

  if (candidateSession) {
    const cleanActor = preferredActorId?.trim();
    if (
      cleanActor &&
      cleanActor !== 'system' &&
      candidateSession.personId !== cleanActor
    ) {
      const err = new Error(
        `TENANCY_ACTOR_MISMATCH: Verified session personId "${candidateSession.personId}" does not match requested actor "${cleanActor}".`,
      ) as Error & { code: string };
      err.code = 'TENANCY_ACTOR_MISMATCH';
      throw err;
    }
    return resolveCurrentTenantContext(
      createVerifiedSessionActorFromEntraSession(candidateSession, {
        correlationId: options?.correlationId,
      }),
      activeTenantConfig,
    );
  }

  const err = new Error(
    'UNAUTHENTICATED: Verified Entra ID session is required for tenant data access.',
  ) as Error & { code: string };
  err.code = 'UNAUTHENTICATED';
  throw err;
}

async function loadTenantCatalogueStoreView(
  ctx: TenantContext,
  options?: { includePmsLinks?: boolean },
): Promise<FirmStore> {
  const activeTenantConfig = getActiveTenantConfiguration();
  const catSnap =
    await getCatalogueRepository().getFullCatalogueAndConfigsSnapshot<
      FirmStore['firm'],
      ChoiceList,
      ChoiceValue,
      CustomFieldDefinition
    >(ctx, activeTenantConfig);
  const seedLists = buildSeedLists();
  const nowIso = new Date().toISOString();

  const lists: ChoiceList[] = [...catSnap.lists];
  for (const l of seedLists.lists) {
    if (!lists.some((x) => x.key === l.key)) {
      lists.push(l);
    }
  }
  const mpList = lists.find((x) => x.key === 'matter_party_role');
  if (mpList && mpList.label !== 'Matter Parties') {
    mpList.label = 'Matter Parties';
  }

  let values: ChoiceValue[] = [...catSnap.values];
  for (const v of seedLists.values) {
    const existingVal = values.find((x) => x.id === v.id);
    if (!existingVal) {
      values.push(v);
    } else if (v.listKey === 'work_type' && v.meta) {
      if (
        existingVal.meta?.amlInScope === undefined ||
        existingVal.meta?.clientMoneyThresholdGbp === undefined ||
        (v.meta.departmentId !== undefined && existingVal.meta?.departmentId === undefined)
      ) {
        existingVal.meta = {
          ...v.meta,
          ...(existingVal.meta ?? {}),
        };
      }
    }
  }

  const orgStructure: OrgStructureCatalogue =
    (catSnap.moduleConfigs.org_structure as OrgStructureCatalogue | undefined) ??
    buildDefaultOrgStructure({
      legalName: activeTenantConfig.displayName,
    });
  for (const v of values) {
    if (v.listKey === 'work_type' && !v.parentId && !v.meta?.departmentId) {
      const resolvedDept = resolveDepartmentForPracticeArea(v.id, orgStructure, values);
      if (resolvedDept) {
        v.meta = { ...(v.meta ?? {}), departmentId: resolvedDept.id };
      }
    }
  }

  const matterPartyTaxonomy =
    (catSnap.moduleConfigs.matter_party_taxonomy as MatterPartyTaxonomy | undefined) ??
    buildDefaultMatterPartyTaxonomy(values);
  let matterPartyMigrationReport = catSnap.moduleConfigs
    .matter_party_migration_report as MatterPartyMigrationReport | undefined;

  if (
    !catSnap.moduleConfigs.matter_party_taxonomy ||
    !matterPartyMigrationReport
  ) {
    const partyMig = migrateMatterPartiesToTwoFieldModel(
      values,
      [],
      matterPartyTaxonomy,
      nowIso,
    );
    values = partyMig.values;
    if (!matterPartyMigrationReport) {
      matterPartyMigrationReport = partyMig.report;
    }
  }

  const rawHomePages =
    (catSnap.moduleConfigs.home_pages as HomePagesConfig | undefined) ??
    createDefaultHomePagesConfig(
      nowIso,
      activeTenantConfig.branding.primaryDomain,
    );
  const syncedRoles = syncHomeRolesWithEmployeeRoles(
    rawHomePages.roles ?? [],
    values,
    createDefaultRoleConfigs(activeTenantConfig.branding.primaryDomain),
  );
  const homePagesConfig: HomePagesConfig = {
    ...rawHomePages,
    roles: syncedRoles,
  };

  const baseMatterCostsConfig = resolveEffectiveMatterCostsConfig(
    activeTenantConfig,
    catSnap.moduleConfigs.matter_costs as MatterCostsConfig | undefined,
    {
      values,
      clientProfileCode: activeTenantConfig.tenantId,
      displayName: activeTenantConfig.displayName,
      primaryDomain: activeTenantConfig.branding.primaryDomain,
    },
  );
  const matterCostsConfig = catSnap.moduleConfigs.matter_costs
    ? baseMatterCostsConfig
    : syncRateCardsWithPmsFeeEarners(
        baseMatterCostsConfig,
        (await getPmsRepository().listFeeEarnersOnly(ctx)) as unknown as PmsFeeEarner[],
        values,
      );

  const persistedEnquirySettings =
    catSnap.moduleConfigs.enquiry_settings as Partial<EnquirySettings> | undefined;
  const configuredFallbackTeamId =
    activeTenantConfig.enquiries?.fallbackTeamId?.trim() || null;
  const persistedFallbackTeamId =
    typeof persistedEnquirySettings?.fallbackTeamId === 'string' &&
    persistedEnquirySettings.fallbackTeamId.trim().length > 0
      ? persistedEnquirySettings.fallbackTeamId.trim()
      : null;
  const enquirySettings: EnquirySettings = {
    ...DEFAULT_ENQUIRY_SETTINGS,
    ...(persistedEnquirySettings ?? {}),
    fallbackTeamId: persistedFallbackTeamId ?? configuredFallbackTeamId ?? null,
  };

  const taskSettings: TaskSettings =
    (catSnap.moduleConfigs.task_settings as TaskSettings | undefined) ?? {
      templates: DEFAULT_TASK_SETTINGS.templates.map((t) => ({ ...t })),
    };

  const firm = catSnap.firmProfile
    ? {
        name: catSnap.firmProfile.firm.name,
        shortName: catSnap.firmProfile.firm.shortName,
        offices: [...catSnap.firmProfile.firm.offices],
      }
    : {
        name: activeTenantConfig.displayName,
        shortName:
          activeTenantConfig.displayName.replace(/\s+LLP$/i, '').trim() ||
          activeTenantConfig.displayName,
        offices: orgStructure.offices.map((o) => o.name),
      };

  return {
    firmId: catSnap.firmProfile?.firmId ?? ctx.tenantId,
    firm,
    isCleanDeployment: catSnap.firmProfile?.isCleanDeployment ?? false,
    lists,
    values,
    customFields: catSnap.customFields,
    orgStructure,
    matterPartyTaxonomy,
    matterPartyMigrationReport,
    people: [],
    employeeSensitiveRecords: {},
    organisations: [],
    links: [],
    matters: [],
    teams: [],
    tasks: [],
    enquiries: [],
    quotes: [],
    notifications: [],
    enquirySettings,
    taskSettings,
    signOffs: [],
    homePagesConfig,
    matterCostsConfig,
    pmsLinks: options?.includePmsLinks
      ? await getPmsRepository().listPmsLinks<PmsLink>(ctx)
      : [],
    notes: [],
    audit: [],
    mergeHistory: [],
    recentlyViewed: {},
    counters: {},
    keyDates: [],
    keyDateNotApplicable: [],
    keyDateReminderStates: [],
    keyDateCalendarSyncs: [],
    workTypesConfig: resolveEffectiveWorkTypesConfig(
      activeTenantConfig,
      (catSnap.moduleConfigs.work_type_configs as WorkTypesConfiguration | undefined) ?? null,
    ),
    workTypeConfigsOverride:
      (catSnap.moduleConfigs.work_type_configs as WorkTypesConfiguration | undefined) ??
      undefined,
  };
}

async function loadEffectiveTenantRbacConfig(
  ctx: TenantContext,
  preloadedOverride?: Partial<RbacConfiguration> | null,
  explicitTenantConfig?: TenantConfiguration,
): Promise<RbacConfiguration> {
  const activeCfg = getActiveTenantConfiguration();
  let base: RbacConfiguration;
  if (explicitTenantConfig) {
    if (explicitTenantConfig.tenantId !== ctx.tenantId) {
      const mismatchErr = new Error(
        `TENANT_CONFIG_MISMATCH: Supplied TenantConfiguration tenantId "${explicitTenantConfig.tenantId}" does not match caller context tenantId "${ctx.tenantId}".`,
      ) as Error & { code?: string };
      mismatchErr.code = 'TENANT_CONFIG_MISMATCH';
      throw mismatchErr;
    }
    base = explicitTenantConfig.rbac;
  } else if (ctx.tenantId === activeCfg.tenantId) {
    base = getDefaultTenantRbacConfig(ctx.tenantId);
  } else {
    const mismatchErr = new Error(
      `TENANT_CONFIG_MISMATCH: Active process TenantConfiguration tenantId "${activeCfg.tenantId}" does not match caller context tenantId "${ctx.tenantId}", and no explicit tenantConfig was supplied.`,
    ) as Error & { code?: string };
    mismatchErr.code = 'TENANT_CONFIG_MISMATCH';
    throw mismatchErr;
  }
  const override =
    preloadedOverride !== undefined
      ? preloadedOverride
      : await getHrAndRbacRepository().getRbacConfigOverride<RbacConfiguration>(
          ctx,
        );
  const effective = override ? mergeRbacConfigOverlay(base, override) : base;
  const activeSession = getActiveActorSession();
  if (activeSession && activeSession.tenantId === ctx.tenantId) {
    activeSession.effectiveRbacConfig = effective;
  }
  return effective;
}

/**
 * Recomputes and writes `is_staff_matter`, `has_ethical_wall`, and `restricted_access_user_ids_json`
 * for only the affected matter rows inside the caller's active `withTenantTransaction` (`R478`, `R479`).
 * Takes `SELECT ... FOR UPDATE` on the affected matter rows and reads `people` and `teams` inside the same
 * transaction so stale pre-transaction reads or read-only paths can never overwrite access lists.
 */
async function syncAffectedMattersRestrictionsInTx(
  ctx: TenantContext,
  options: {
    matterIds?: readonly string[];
    includeAllRestrictedMatters?: boolean;
    rbacConfig?: RbacConfiguration | null;
  } = {},
): Promise<void> {
  const activeTx = getActiveTenantTransactionState();
  if (!activeTx || activeTx.tenantId !== ctx.tenantId) {
    const err = new Error(
      `TENANCY_TRANSACTION_REQUIRED: syncAffectedMattersRestrictionsInTx requires an active withTenantTransaction for tenant "${ctx.tenantId}".`,
    ) as Error & { code: string };
    err.code = 'TENANCY_TRANSACTION_REQUIRED';
    throw err;
  }
  const matterRepo = getMatterRepository();
  const lockedMatters =
    await matterRepo.lockMattersForRestrictionRecompute<Matter>(ctx, {
      matterIds: options.matterIds,
      includeAllRestrictedMatters: options.includeAllRestrictedMatters,
    });
  if (lockedMatters.length === 0) {
    return;
  }
  const txPeople = await loadStaffPeople(ctx);
  const txTeams = await getHrAndRbacRepository().listAllTeams<Team>(ctx);
  const txRbacOverride =
    options.rbacConfig !== undefined
      ? options.rbacConfig
      : await getHrAndRbacRepository().getRbacConfigOverride<RbacConfiguration>(ctx);
  const baseTenantConfig = getActiveTenantConfiguration();
  const effectiveRbac = txRbacOverride
    ? mergeRbacConfigOverlay(
        getDefaultTenantRbacConfig(ctx.tenantId),
        txRbacOverride,
      )
    : getDefaultTenantRbacConfig(ctx.tenantId);
  const effectiveTenantConfig = { ...baseTenantConfig, rbac: effectiveRbac };
  for (const m of lockedMatters) {
    const meta = computeMatterRestrictionMetadataForStore(
      m,
      txPeople,
      txTeams,
      effectiveTenantConfig,
    );
    await matterRepo.updateLockedMatterRestrictionColumnsInTx(ctx, m.id, {
      isStaffMatter: Boolean(m.isStaffMatter),
      hasEthicalWall: Boolean(m.hasEthicalWall),
      sqlRestrictedAccessUserIds: meta.restrictedAccessUserIds,
    });
  }
}

async function putMatterWithInTxRestrictions(
  ctx: TenantContext,
  matter: Matter,
  options: {
    expectedRowVersion?: number | null;
    rbacConfig?: RbacConfiguration | null;
  } = {},
): Promise<Matter> {
  const activeTx = getActiveTenantTransactionState();
  if (!activeTx || activeTx.tenantId !== ctx.tenantId) {
    const err = new Error(
      `TENANCY_TRANSACTION_REQUIRED: putMatterWithInTxRestrictions requires an active withTenantTransaction for tenant "${ctx.tenantId}".`,
    ) as Error & { code: string };
    err.code = 'TENANCY_TRANSACTION_REQUIRED';
    throw err;
  }
  const matterRepo = getMatterRepository();
  await matterRepo.lockMattersForRestrictionRecompute<Matter>(ctx, {
    matterIds: [matter.id],
  });
  const txPeople = await loadStaffPeople(ctx);
  const txTeams = await getHrAndRbacRepository().listAllTeams<Team>(ctx);
  const txRbacOverride =
    options.rbacConfig !== undefined
      ? options.rbacConfig
      : await getHrAndRbacRepository().getRbacConfigOverride<RbacConfiguration>(ctx);
  const baseTenantConfig = getActiveTenantConfiguration();
  const effectiveRbac = txRbacOverride
    ? mergeRbacConfigOverlay(
        getDefaultTenantRbacConfig(ctx.tenantId),
        txRbacOverride,
      )
    : getDefaultTenantRbacConfig(ctx.tenantId);
  const effectiveTenantConfig = { ...baseTenantConfig, rbac: effectiveRbac };
  const meta = computeMatterRestrictionMetadataForStore(
    matter,
    txPeople,
    txTeams,
    effectiveTenantConfig,
  );
  return matterRepo.putMatter<Matter>(ctx, matter, {
    expectedRowVersion: options.expectedRowVersion,
    sqlRestrictedAccessUserIds: meta.restrictedAccessUserIds,
  });
}

function buildMatterVisibilityForEmployeeRecord(
  matters: readonly Matter[],
  canViewMatter: (matter: Matter) => boolean,
): {
  canViewMatterId: (matterId: string) => boolean;
  visibleMatterNumberById: ReadonlyMap<string, string>;
} {
  const matterById = new Map(matters.map((m) => [m.id, m]));
  const visibleMatterNumberById = new Map<string, string>();
  for (const m of matters) {
    if (canViewMatter(m)) {
      visibleMatterNumberById.set(m.id, m.matterNumber);
    }
  }
  return {
    canViewMatterId: (matterId: string) => {
      const m = matterById.get(matterId);
      return m ? canViewMatter(m) : false;
    },
    visibleMatterNumberById,
  };
}

function redactRestrictedAuditEntryForViewer(
  entry: AuditEntry,
  matters: readonly Matter[],
  canViewMatter: (matter: Matter) => boolean,
): AuditEntry {
  if (entry.recordType !== 'person') return entry;
  const isConflictOnHire =
    entry.field?.startsWith('Conflict check on hire') ||
    (entry.snapshot &&
      typeof entry.snapshot === 'object' &&
      (entry.snapshot as { kind?: unknown }).kind === 'conflict_check_on_hire');
  if (!isConflictOnHire) return entry;

  const matterById = new Map(matters.map((m) => [m.id, m]));
  const hiddenMatters = matters.filter((m) => !canViewMatter(m));
  const sanitizeString = (val: string | null): string | null => {
    if (!val) return val;
    let out = val;
    for (const hm of hiddenMatters) {
      if (hm.matterNumber && out.includes(hm.matterNumber)) {
        out = out.split(hm.matterNumber).join('[restricted matter redacted]');
      }
      if (hm.id && out.includes(hm.id)) {
        out = out.split(hm.id).join('[restricted matter redacted]');
      }
      if (hm.title && out.includes(hm.title)) {
        out = out.split(hm.title).join('[restricted matter redacted]');
      }
    }
    return out;
  };

  let nextNewValue = sanitizeString(entry.newValue);
  let nextSnapshot = entry.snapshot;
  if (
    entry.snapshot &&
    typeof entry.snapshot === 'object' &&
    (entry.snapshot as { kind?: unknown }).kind === 'conflict_check_on_hire'
  ) {
    const snapObj = entry.snapshot as {
      kind?: string;
      openMatterIds?: unknown;
    };
    const rawIds = Array.isArray(snapObj.openMatterIds)
      ? snapObj.openMatterIds.filter((id): id is string => typeof id === 'string')
      : [];
    const visibleMatters = rawIds
      .map((id) => matterById.get(id))
      .filter((m): m is Matter => Boolean(m && canViewMatter(m)));
    const hiddenCount = rawIds.length - visibleMatters.length;
    if (hiddenCount > 0) {
      const summaryParts = [
        ...visibleMatters.map((m) => m.matterNumber),
        `${hiddenCount} restricted matter(s) redacted`,
      ];
      nextNewValue =
        visibleMatters.length > 0
          ? `Person is a party on ${rawIds.length} open matter(s) (${summaryParts.join(', ')}). Flagged to Risk & Compliance to consider an information barrier.`
          : `Person is a party on ${hiddenCount} restricted open matter(s) (details hidden under ethical wall / staff-matter restriction). Flagged to Risk & Compliance to consider an information barrier.`;
      nextSnapshot = {
        kind: 'conflict_check_on_hire',
        openMatterIds: visibleMatters.map((m) => m.id),
      };
    } else if (rawIds.length > 0) {
      const refs = rawIds
        .map((id) => matterById.get(id)?.matterNumber ?? id)
        .join(', ');
      nextNewValue = `Person is a party on ${rawIds.length} open matter(s) (${refs}). Flagged to Risk & Compliance to consider an information barrier.`;
    }
  }

  return {
    ...entry,
    oldValue: sanitizeString(entry.oldValue),
    newValue: nextNewValue,
    ...(nextSnapshot !== undefined ? { snapshot: nextSnapshot } : {}),
  };
}

function mapFirmAuditRecordToAuditEntry(rec: FirmAuditEntryRecord): AuditEntry {
  return {
    id: rec.id,
    recordType: rec.recordType as AuditEntry['recordType'],
    recordId: rec.recordId,
    action: rec.action as AuditEntry['action'],
    field: rec.field,
    oldValue: rec.oldValue,
    newValue: rec.newValue,
    byId: rec.byId,
    at: rec.at,
    ...(rec.reason !== undefined ? { reason: rec.reason } : {}),
    ...(rec.snapshot !== undefined ? { snapshot: rec.snapshot } : {}),
  };
}

function writeAudit(
  _store: FirmStore | null | undefined,
  entry: Omit<AuditEntry, 'id' | 'at'> & { at?: string },
): AuditEntry {
  return stageAuditEntry(entry);
}

export async function getKeyDatesConfig(
  storeOrOptions?:
    | FirmStore
    | {
        ctx?: TenantContext;
        userId?: string;
        tenantConfig?: TenantConfiguration;
      },
): Promise<KeyDatesConfig> {
  const isOptionsObj =
    Boolean(storeOrOptions) &&
    typeof storeOrOptions === 'object' &&
    !('lists' in (storeOrOptions as Record<string, unknown>));
  const opts = isOptionsObj
    ? (storeOrOptions as {
        ctx?: TenantContext;
        userId?: string;
        tenantConfig?: TenantConfiguration;
      })
    : undefined;

  const ctx =
    opts?.ctx ?? resolveDefaultServiceTenantContext(null, opts?.userId);
  const tenantConfig = resolveVerifiedTenantConfiguration(
    ctx,
    opts?.tenantConfig,
  );
  const override = await getKeyDateRepository().getKeyDatesTenantConfig(ctx);
  const raw = override ?? tenantConfig.keyDates ?? { enabled: false };
  return validateKeyDatesConfig(raw) as unknown as KeyDatesConfig;
}

/**
 * Record-scoped audit query for profile pages (R413), hitting idx_audit_entries_tenant_record
 * and enforcing restricted-matter, task/enquiry/quote visibility, and HR payroll/sensitive permissions.
 */
export async function listAuditEntriesForRecord(
  recordType: AuditEntry['recordType'],
  recordId: string,
  viewerId: string,
  options?: { limit?: number; tokenRoles?: readonly string[] },
): Promise<AuditEntry[]> {
  let ctx: TenantContext;
  try {
    ctx = resolveDefaultServiceTenantContext(null, viewerId);
  } catch {
    return [];
  }
  const partyRepo = getPartyRepository();
  const matterRepo = getMatterRepository();
  const intakeRepo = getIntakeQuoteRepository();
  const taskRepo = getTaskWorkflowRepository();
  const [people, teams, rbacConfig] = await Promise.all([
    loadStaffPeople(ctx),
    getHrAndRbacRepository().listAllTeams<Team>(ctx),
    loadEffectiveTenantRbacConfig(ctx),
  ]);
  const viewer = people.find(
    (p) => p.id === viewerId && !p.mergedIntoId,
  );
  if (!viewer) {
    return [];
  }
  const activeSession = getActiveActorSession();
  const effectiveTokenRoles =
    options?.tokenRoles ??
    (activeSession?.personId === viewer.id ? activeSession.tokenRoles : undefined);
  const permSet = resolvePersonPermissionSet(viewer, {
    allPeople: people,
    teams,
    tokenRoles: effectiveTokenRoles,
    tokenRolesActorId: viewer.id,
    config: { ...getActiveTenantConfiguration(), rbac: rbacConfig },
    context: ctx,
    mfaVerified: ctx.mfaVerified,
  });
  const hasRestrictedAccess = permSet.permissions.has('matter:restricted:access');
  const canViewMatterDirect = (m: Matter): boolean =>
    canPersonAccessMatter(m, viewer.id, viewer, {
      allPeople: people,
      teams,
      tokenRoles: effectiveTokenRoles,
      tokenRolesActorId: viewer.id,
      config: { rbac: rbacConfig },
    });

  if (recordType === 'matter') {
    const [m] = await matterRepo.listMattersByIds<Matter>(ctx, [recordId], {
      includeRestricted: true,
    });
    if (!m || !canViewMatterDirect(m)) {
      return [];
    }
  } else if (recordType === 'enquiry') {
    const e = await intakeRepo.getEnquiryById<Enquiry>(ctx, recordId, {
      includeRestricted: true,
    });
    const isHidden = e
      ? await intakeRepo.isEnquiryHiddenFromViewer(ctx, e.id, viewer.id, {
          hasRestrictedMatterAccess: hasRestrictedAccess,
        })
      : false;
    if (!e || isHidden) {
      return [];
    }
  } else if (recordType === 'quote') {
    const q = await intakeRepo.getQuoteByIdOrReference<Quote>(ctx, recordId, {
      includeRestricted: true,
    });
    const isHidden = q
      ? await intakeRepo.isQuoteHiddenFromViewer(ctx, q.id, viewer.id, {
          hasRestrictedMatterAccess: hasRestrictedAccess,
        })
      : false;
    if (!q || isHidden) {
      return [];
    }
  } else if (recordType === 'task') {
    const [t, hiddenTaskIds] = await Promise.all([
      taskRepo.getTaskById<Task>(ctx, recordId, { includeRestricted: true }),
      taskRepo.listHiddenTaskIds(ctx, viewer.id, {
        hasRestrictedMatterAccess: hasRestrictedAccess,
      }),
    ]);
    if (!t || hiddenTaskIds.includes(t.id)) {
      return [];
    }
    const hiddenMatterIds = new Set(
      await matterRepo.listHiddenRestrictedMatterIds(ctx, viewer.id, {
        hasRestrictedMatterAccess: hasRestrictedAccess,
      }),
    );
    const hiddenKdIds = await getKeyDateRepository().listHiddenKeyDateIdsForMatters(
      ctx,
      hiddenMatterIds,
    );
    if (
      (t.linkedKeyDateId && hiddenKdIds.has(t.linkedKeyDateId)) ||
      t.linkedRecords.some(
        (lr) =>
          (lr as { recordType: string }).recordType === 'key_date' &&
          hiddenKdIds.has(lr.recordId),
      )
    ) {
      return [];
    }
  } else if (recordType === 'key_date') {
    const hiddenMatterIds = new Set(
      await matterRepo.listHiddenRestrictedMatterIds(ctx, viewer.id, {
        hasRestrictedMatterAccess: hasRestrictedAccess,
      }),
    );
    const hiddenMatterKeyDateIds =
      await getKeyDateRepository().listHiddenKeyDateIdsForMatters(
        ctx,
        hiddenMatterIds,
      );
    if (hiddenMatterKeyDateIds.has(recordId)) {
      return [];
    }
    const prefix = recordId.split(':')[0];
    if (prefix && hiddenMatterIds.has(prefix)) {
      return [];
    }
  } else if (recordType === 'employee_payroll') {
    if (!hasEmployeePermission(viewer, 'employee:payroll', people, teams, { config: { rbac: rbacConfig } })) {
      return [];
    }
  } else if (recordType === 'employee_sensitive') {
    if (!hasEmployeePermission(viewer, 'employee:sensitive', people, teams, { config: { rbac: rbacConfig } })) {
      return [];
    }
  }

  const rows = await getAuditRepository().listAuditEntriesForRecord(
    ctx,
    recordType,
    recordId,
    { limit: options?.limit ?? 200 },
  );
  const openMatterIds = Array.from(
    new Set(
      rows.flatMap((row) => {
        const snap = row.snapshot as { kind?: unknown; openMatterIds?: unknown } | undefined;
        return snap?.kind === 'conflict_check_on_hire' && Array.isArray(snap.openMatterIds)
          ? snap.openMatterIds.filter((id): id is string => typeof id === 'string')
          : [];
      }),
    ),
  );
  const referencedMatters =
    openMatterIds.length > 0
      ? await matterRepo.listMattersByIds<Matter>(ctx, openMatterIds, {
          includeRestricted: true,
        })
      : [];
  return rows.map((row) =>
    redactRestrictedAuditEntryForViewer(
      mapFirmAuditRecordToAuditEntry(row),
      referencedMatters,
      canViewMatterDirect,
    ),
  );
}

/**
 * Paginated firm-wide audit query for Admin (R413, R451, R452, R457), hitting idx_audit_entries_tenant_seq,
 * enforcing admin:access, and filling each page with visible entries after redacting restricted matters,
 * hidden tasks/enquiries/quotes/key-dates, and unpermitted HR audit rows.
 */
export async function listFirmAuditEntriesPage(
  viewerId: string,
  options?: {
    limit?: number;
    beforeSeq?: number;
    tokenRoles?: readonly string[];
  },
): Promise<
  { entries: AuditEntry[]; nextBeforeSeq: number | null } & Partial<ActionDenied>
> {
  let ctx: TenantContext;
  try {
    ctx = resolveDefaultServiceTenantContext(null, viewerId);
  } catch {
    return {
      ...buildActionDenied(
        'FORBIDDEN',
        'You need "admin:access" permission to view the firm audit log.',
      ),
      entries: [],
      nextBeforeSeq: null,
    };
  }
  const matterRepo = getMatterRepository();
  const intakeRepo = getIntakeQuoteRepository();
  const taskRepo = getTaskWorkflowRepository();
  const [people, teams, rbacConfig] = await Promise.all([
    loadStaffPeople(ctx),
    getHrAndRbacRepository().listAllTeams<Team>(ctx),
    loadEffectiveTenantRbacConfig(ctx),
  ]);
  const viewer = people.find(
    (p) => p.id === viewerId && !p.mergedIntoId,
  );
  const activeSession = getActiveActorSession();
  const effectiveTokenRoles =
    options?.tokenRoles ??
    (viewer && activeSession?.personId === viewer.id
      ? activeSession.tokenRoles
      : undefined);
  const permSet = resolvePersonPermissionSet(viewer ?? null, {
    allPeople: people,
    teams,
    tokenRoles: effectiveTokenRoles,
    tokenRolesActorId: viewer?.id,
    config: { ...getActiveTenantConfiguration(), rbac: rbacConfig },
    context: ctx,
    mfaVerified: ctx.mfaVerified,
  });
  if (!viewer || !permSet.permissions.has('admin:access')) {
    return {
      ...buildActionDenied(
        'FORBIDDEN',
        'You need "admin:access" permission to view the firm audit log.',
      ),
      entries: [],
      nextBeforeSeq: null,
    };
  }
  if (permSet.mfaPendingPermissions.has('admin:access')) {
    return {
      ...buildActionDenied(
        'MFA_REQUIRED',
        'Multi-factor authentication (MFA) is required to view the firm audit log.',
      ),
      entries: [],
      nextBeforeSeq: null,
    };
  }

  const hasRestrictedAccess = permSet.permissions.has('matter:restricted:access');
  const [
    hiddenMatterIdList,
    hiddenEnquiryIdList,
    hiddenQuoteIdList,
    hiddenTaskIdList,
  ] = await Promise.all([
    matterRepo.listHiddenRestrictedMatterIds(ctx, viewer.id, {
      hasRestrictedMatterAccess: hasRestrictedAccess,
    }),
    intakeRepo.listHiddenEnquiryIds(ctx, viewer.id, {
      hasRestrictedMatterAccess: hasRestrictedAccess,
    }),
    intakeRepo.listHiddenQuoteIds(ctx, viewer.id, {
      hasRestrictedMatterAccess: hasRestrictedAccess,
    }),
    taskRepo.listHiddenTaskIds(ctx, viewer.id, {
      hasRestrictedMatterAccess: hasRestrictedAccess,
    }),
  ]);
  const hiddenMatterIds = new Set(hiddenMatterIdList);
  const hiddenEnquiryIds = new Set(hiddenEnquiryIdList);
  const hiddenQuoteIds = new Set(hiddenQuoteIdList);
  const hiddenTaskIds = new Set(hiddenTaskIdList);
  const hiddenMatterKeyDateIds =
    await getKeyDateRepository().listHiddenKeyDateIdsForMatters(
      ctx,
      hiddenMatterIds,
    );
  const canViewMatterDirect = (m: Matter): boolean =>
    canPersonAccessMatter(m, viewer.id, viewer, {
      allPeople: people,
      teams,
      tokenRoles: effectiveTokenRoles,
      tokenRolesActorId: viewer.id,
      config: { rbac: rbacConfig },
    });
  const canPayroll = hasEmployeePermission(
    viewer,
    'employee:payroll',
    people,
    teams,
    { config: { rbac: rbacConfig } },
  );
  const canSensitive = hasEmployeePermission(
    viewer,
    'employee:sensitive',
    people,
    teams,
    { config: { rbac: rbacConfig } },
  );

  const isVisibleAuditRow = (a: FirmAuditEntryRecord): boolean => {
    if (a.recordType === 'matter' && hiddenMatterIds.has(a.recordId)) {
      return false;
    }
    if (a.recordType === 'task' && hiddenTaskIds.has(a.recordId)) {
      return false;
    }
    if (a.recordType === 'enquiry' && hiddenEnquiryIds.has(a.recordId)) {
      return false;
    }
    if (a.recordType === 'quote' && hiddenQuoteIds.has(a.recordId)) {
      return false;
    }
    if (a.recordType === 'key_date') {
      if (hiddenMatterKeyDateIds.has(a.recordId)) return false;
      const prefix = a.recordId.split(':')[0];
      if (prefix && hiddenMatterIds.has(prefix)) return false;
    }
    if (a.recordType === 'employee_payroll' && !canPayroll) {
      return false;
    }
    if (a.recordType === 'employee_sensitive' && !canSensitive) {
      return false;
    }
    return true;
  };

  const targetLimit = Math.min(
    2000,
    Math.max(1, Math.floor(options?.limit ?? 250)),
  );
  const collected: FirmAuditEntryRecord[] = [];
  let cursor = options?.beforeSeq;
  let hasMoreAfterCollected = false;

  while (collected.length < targetLimit) {
    const page = await getAuditRepository().listFirmAuditEntriesPage(ctx, {
      limit: Math.max(targetLimit, 250),
      beforeSeq: cursor,
    });
    if (page.entries.length === 0) {
      hasMoreAfterCollected = false;
      break;
    }
    let stoppedMidBatch = false;
    for (let i = 0; i < page.entries.length; i++) {
      const a = page.entries[i]!;
      if (!isVisibleAuditRow(a)) continue;
      if (collected.length < targetLimit) {
        collected.push(a);
      } else {
        hasMoreAfterCollected = true;
        stoppedMidBatch = true;
        break;
      }
    }
    if (stoppedMidBatch) {
      break;
    }
    if (page.nextBeforeSeq === null) {
      hasMoreAfterCollected = false;
      break;
    }
    if (collected.length >= targetLimit) {
      hasMoreAfterCollected = true;
      break;
    }
    cursor = page.nextBeforeSeq;
  }

  const lastVisible = collected.at(-1);
  const nextBeforeSeq =
    hasMoreAfterCollected && lastVisible?.seq !== undefined
      ? lastVisible.seq
      : null;

  const openMatterIds = Array.from(
    new Set(
      collected.flatMap((row) => {
        const snap = row.snapshot as { kind?: unknown; openMatterIds?: unknown } | undefined;
        return snap?.kind === 'conflict_check_on_hire' && Array.isArray(snap.openMatterIds)
          ? snap.openMatterIds.filter((id): id is string => typeof id === 'string')
          : [];
      }),
    ),
  );
  const referencedMatters =
    openMatterIds.length > 0
      ? await matterRepo.listMattersByIds<Matter>(ctx, openMatterIds, {
          includeRestricted: true,
        })
      : [];

  return {
    entries: collected.map((row) =>
      redactRestrictedAuditEntryForViewer(
        mapFirmAuditRecordToAuditEntry(row),
        referencedMatters,
        canViewMatterDirect,
      ),
    ),
    nextBeforeSeq,
  };
}

function logDocumentLifecycleSyncError(
  err: unknown,
  correlationId: string,
): void {
  const tenantId = getActiveTenantConfiguration().tenantId;
  console.error(
    JSON.stringify({
      level: 'error',
      event: 'document_store.lifecycle_sync_unhandled',
      tenantId,
      correlationId,
      code: (err as { code?: string })?.code ?? 'unavailable',
    }),
  );
}

export async function getAppSnapshot(
  userId: string,
  options?: { tokenRoles?: readonly string[]; includeFirmAudit?: boolean },
): Promise<AppSnapshot> {
  return getAppSnapshotInScope(userId, options);
}

async function getAppSnapshotInScope(
  userId: string,
  options?: { tokenRoles?: readonly string[]; includeFirmAudit?: boolean },
): Promise<AppSnapshot> {
  const now = new Date();
  if (!userId || !userId.trim()) {
    throw new AuthorisationError({
      code: 'UNAUTHENTICATED',
      message: `Authenticated user "${userId}" was not found or is inactive.`,
      tenantId: getActiveTenantConfiguration().tenantId,
      correlationId: 'app-snapshot',
      actorUserId: userId || 'anonymous',
    });
  }
  const snapshotTenantCtx = resolveDefaultServiceTenantContext(null, userId);
  const store = await loadTenantCatalogueStoreView(snapshotTenantCtx, {
    includePmsLinks: true,
  });
  const partyRepo = getPartyRepository();
  const matterRepo = getMatterRepository();
  const intakeRepo = getIntakeQuoteRepository();
  const taskRepo = getTaskWorkflowRepository();
  const hrRepo = getHrAndRbacRepository();
  const [
    people,
    organisations,
    links,
    notes,
    mergeHistory,
    teams,
    dbEmployeeMigrationReport,
    dbRbacOverride,
  ] = await Promise.all([
    partyRepo.listAllPeople<Person>(snapshotTenantCtx),
    partyRepo.listAllOrganisations<Organisation>(snapshotTenantCtx),
    partyRepo.listAllLinks<PersonOrganisationLink>(snapshotTenantCtx),
    partyRepo.listAllNotes<Note>(snapshotTenantCtx),
    partyRepo.listAllMergeHistory<MergeHistory>(snapshotTenantCtx),
    hrRepo.listAllTeams<Team>(snapshotTenantCtx),
    hrRepo.getEmployeeMigrationReport<
      import('@/domain/types').EmployeeMigrationReport
    >(snapshotTenantCtx),
    hrRepo.getRbacConfigOverride<RbacConfiguration>(snapshotTenantCtx),
  ]);
  const rbacConfig = await loadEffectiveTenantRbacConfig(
    snapshotTenantCtx,
    dbRbacOverride,
  );
  const user = people.find(
    (p) => p.id === userId && !p.mergedIntoId,
  );
  if (!user) {
    throw new AuthorisationError({
      code: 'UNAUTHENTICATED',
      message: `Authenticated user "${userId}" was not found or is inactive.`,
      tenantId: getActiveTenantConfiguration().tenantId,
      correlationId: 'app-snapshot',
      actorUserId: userId || 'anonymous',
    });
  }
  const currentUserRole = resolveUserAppRole(user, teams, store.values, {
    config: { rbac: rbacConfig },
  });
  const currentUserEmployeePermissions = resolveEmployeePermissions(
    user,
    people,
    teams,
    { config: { rbac: rbacConfig } },
  );
  const activeSession = getActiveActorSession();
  const effectiveTokenRoles =
    options?.tokenRoles ??
    (activeSession?.personId === user.id ? activeSession?.tokenRoles : undefined);
  const currentUserPermissions = resolvePersonPermissions(user, {
    allPeople: people,
    teams,
    tokenRoles: effectiveTokenRoles,
    tokenRolesActorId: user.id,
    config: { rbac: rbacConfig },
  });
  const orgStructure =
    store.orgStructure ??
    buildDefaultOrgStructure({
      legalName: getActiveTenantConfiguration().displayName,
    });

  // Never bulk-return sensitive HR records in page snapshots (R63); serve only via audited per-person read service.
  const employeeSensitiveRecords: Record<string, EmployeeSensitiveRecord> = {};

  const keyDateRepo = getKeyDateRepository();
  const hasRestrictedAccess = currentUserPermissions.includes(
    'matter:restricted:access',
  );
  const canViewQuotes = currentUserPermissions.includes('quote:view');

  // Data-layer SQL visibility filtering for the signed-in user (S1-02a, R152, R170, Rule 4):
  const [
    visibleMatters,
    hiddenMatterIdList,
    rawVisibleEnquiries,
    hiddenEnquiryIdList,
    visibleQuotes,
    hiddenQuoteIdList,
    rawVisibleTasks,
    hiddenTaskIdList,
    visibleSignOffs,
  ] = await Promise.all([
    matterRepo.listVisibleMatters<Matter>(snapshotTenantCtx, {
      viewerId: user.id,
      hasRestrictedMatterAccess: hasRestrictedAccess,
    }),
    matterRepo.listHiddenRestrictedMatterIds(snapshotTenantCtx, user.id, {
      hasRestrictedMatterAccess: hasRestrictedAccess,
    }),
    intakeRepo.listVisibleEnquiries<Enquiry>(snapshotTenantCtx, user.id, {
      hasRestrictedMatterAccess: hasRestrictedAccess,
    }),
    intakeRepo.listHiddenEnquiryIds(snapshotTenantCtx, user.id, {
      hasRestrictedMatterAccess: hasRestrictedAccess,
    }),
    canViewQuotes
      ? intakeRepo.listVisibleQuotes<Quote>(snapshotTenantCtx, user.id, {
          hasRestrictedMatterAccess: hasRestrictedAccess,
        })
      : Promise.resolve<Quote[]>([]),
    intakeRepo.listHiddenQuoteIds(snapshotTenantCtx, user.id, {
      hasRestrictedMatterAccess: hasRestrictedAccess,
    }),
    taskRepo.listVisibleTasks<Task>(snapshotTenantCtx, user.id, {
      hasRestrictedMatterAccess: hasRestrictedAccess,
    }),
    taskRepo.listHiddenTaskIds(snapshotTenantCtx, user.id, {
      hasRestrictedMatterAccess: hasRestrictedAccess,
    }),
    taskRepo.listVisibleSignOffs<SignOffItem>(snapshotTenantCtx, user.id, {
      hasRestrictedMatterAccess: hasRestrictedAccess,
    }),
  ]);

  const hiddenMatterIds = new Set(hiddenMatterIdList);
  const hiddenMatterKeyDateIds = await keyDateRepo.listHiddenKeyDateIdsForMatters(
    snapshotTenantCtx,
    hiddenMatterIds,
  );
  const hiddenEnquiryIds = new Set(hiddenEnquiryIdList);
  const hiddenQuoteIds = new Set(hiddenQuoteIdList);
  const hiddenTaskIds = new Set(hiddenTaskIdList);

  const visibleTasks: Task[] = [];
  for (const t of rawVisibleTasks) {
    const linksToHiddenKd =
      Boolean(t.linkedKeyDateId && hiddenMatterKeyDateIds.has(t.linkedKeyDateId)) ||
      t.linkedRecords.some(
        (lr) =>
          (lr as { recordType: string }).recordType === 'key_date' &&
          hiddenMatterKeyDateIds.has(lr.recordId),
      );
    if (linksToHiddenKd) {
      hiddenTaskIds.add(t.id);
    } else {
      visibleTasks.push(t);
    }
  }

  // Only conflictCheckOnHire.openMatterIds visible to the signed-in user are exposed via filterEmploymentForUser.
  // Any hidden restricted matter IDs in employment.conflictCheckOnHire.openMatterIds return false from canViewMatterId.
  const visibleMatterById = new Map(visibleMatters.map((m) => [m.id, m]));
  const employeeMatterVisibility = {
    canViewMatterId: (matterId: string) => visibleMatterById.has(matterId),
    visibleMatterNumberById: new Map(
      visibleMatters.map((m) => [m.id, m.matterNumber] as const),
    ),
  };

  // Filter employment records on people at the API level based on requesting user's permissions and matter visibility
  const filteredPeople: Person[] = people.map((p) => {
    if (!p.employment) return p;
    return {
      ...p,
      employment: filterEmploymentForUser(
        p.employment,
        user,
        people,
        teams,
        orgStructure,
        {
          tokenRoles: effectiveTokenRoles,
          tokenRolesActorId: user.id,
          config: { rbac: rbacConfig },
        },
        employeeMatterVisibility,
      ),
    };
  });
  const filteredCurrentUser: Person =
    filteredPeople.find((p) => p.id === user.id) ??
    (user.employment
      ? {
          ...user,
          employment: filterEmploymentForUser(
            user.employment,
            user,
            people,
            teams,
            orgStructure,
            {
              tokenRoles: effectiveTokenRoles,
              tokenRolesActorId: user.id,
              config: { rbac: rbacConfig },
            },
            employeeMatterVisibility,
          ),
        }
      : user);
  const employees = activeEmployees(filteredPeople, store.values);

  const hiddenMatterSourceQuoteIds = new Set<string>();
  for (const q of visibleQuotes) {
    if (q.convertedMatterId && hiddenMatterIds.has(q.convertedMatterId)) {
      hiddenMatterSourceQuoteIds.add(q.id);
    }
  }

  // Strip hidden matter conflict hits from conflictSnapshot.
  const visibleEnquiries: Enquiry[] = rawVisibleEnquiries.map((e) => {
    if (
      !e.conflictSnapshot?.conflicts?.length ||
      hiddenMatterIds.size === 0
    ) {
      return e;
    }
    const filteredConflicts = e.conflictSnapshot.conflicts.filter(
      (c) => !(c.recordType === 'matter' && hiddenMatterIds.has(c.recordId)),
    );
    if (filteredConflicts.length === e.conflictSnapshot.conflicts.length) {
      return e;
    }
    return {
      ...e,
      conflictSnapshot: {
        ...e.conflictSnapshot,
        conflicts: filteredConflicts,
      },
    };
  });

  // Person-to-organisation links only connect People and Organisations.
  const visibleLinks = links;

  const leaverOwnedRecords = findRecordsOwnedByLeavers(
    people,
    organisations,
    visibleMatters,
    visibleTasks,
    visibleEnquiries,
  );

  const activeTenantCfg = getActiveTenantConfiguration();
  const rawHomePagesConfig =
    store.homePagesConfig ??
    createDefaultHomePagesConfig(
      now.toISOString(),
      activeTenantCfg.branding.primaryDomain,
    );
  const homePagesConfig: HomePagesConfig = {
    ...rawHomePagesConfig,
    firmSettings: {
      ...rawHomePagesConfig.firmSettings,
      demoMode: isDemoModeEnabled(),
    },
  };
  const currentUserRoles = resolveEmployeeRoles(user, teams);
  const activeViewingRole = resolveActiveViewingRole(user, homePagesConfig, teams);
  const keyDatesConfig = await getKeyDatesConfig({ ctx: snapshotTenantCtx, userId: user.id });
  const currentUserKeyDatePermissions = resolveKeyDatePermissions(user, {
    config: keyDatesConfig,
    allPeople: people,
    teams,
    rbac: { config: { rbac: rbacConfig } },
  });
  const baseRail = getLeftRailVisibility(activeViewingRole, currentUserRoles, {
    config: { rbac: rbacConfig },
  });
  const leftRailVisibility = {
    ...baseRail,
    keyDates:
      Boolean(keyDatesConfig.enabled) &&
      baseRail.keyDates &&
      currentUserKeyDatePermissions.includes('keydate:view'),
  };

  // Data-layer filtering of key dates from TenantKeyDateRepository for restricted matters & team scoping (R32, R37, S0-15):
  const permittedDiaryTeamIds = new Set(
    resolvePermittedDiaryTeamIds(user, undefined, teams, {
      config: keyDatesConfig,
      allPeople: people,
      teams,
    }),
  );
  const matterByIdForKd = visibleMatterById;
  const canViewKeyDates = currentUserKeyDatePermissions.includes('keydate:view');
  const repoVisibleKeyDates = canViewKeyDates
    ? await keyDateRepo.listAllVisibleKeyDates(snapshotTenantCtx, user.id)
    : [];
  const snapshotKdRbacOptions: ResolvePersonPermissionsOptions = {
    allPeople: people,
    teams,
    tokenRoles: effectiveTokenRoles,
    context: snapshotTenantCtx,
    tokenRolesActorId: user.id,
    config: { rbac: rbacConfig },
    tenantId: snapshotTenantCtx.tenantId,
  };
  const visibleKeyDates: KeyDate[] = repoVisibleKeyDates.filter((kd) => {
    if (!permittedDiaryTeamIds.has(kd.teamId)) return false;
    if (!kd.matterId) return true;
    const m = matterByIdForKd.get(kd.matterId);
    return canViewerAccessMatterKeyDates(m, user.id, user, people, snapshotKdRbacOptions);
  });
  const visibleKeyDateIdSet = new Set(visibleKeyDates.map((kd) => kd.id));
  const repoVisibleNotApplicable = canViewKeyDates
    ? await keyDateRepo.listAllVisibleNotApplicable(snapshotTenantCtx, user.id)
    : [];
  const visibleKeyDateNotApplicable: KeyDateNotApplicable[] = repoVisibleNotApplicable.filter(
    (na) => {
      const m = matterByIdForKd.get(na.matterId);
      return canViewerAccessMatterKeyDates(m, user.id, user, people, snapshotKdRbacOptions);
    },
  );
  const repoReminderStates = canViewKeyDates
    ? await keyDateRepo.listAllReminderStates(snapshotTenantCtx, user.id)
    : [];
  const visibleKeyDateReminderStates: KeyDateReminderState[] = repoReminderStates.filter(
    (rs) => visibleKeyDateIdSet.has(rs.keyDateId),
  );
  const repoCalendarSyncs = canViewKeyDates
    ? await keyDateRepo.listAllVisibleCalendarSyncs(snapshotTenantCtx, user.id)
    : [];
  const visibleKeyDateCalendarSyncs: KeyDateCalendarSync[] = repoCalendarSyncs.filter(
    (cs) => visibleKeyDateIdSet.has(cs.keyDateId),
  );

  // If the current user is a demo user with showsWorkOfId in a non-live demo environment, resolve the underlying filtered employee for personal panels
  const effectiveWorkPerson: Person =
    isNonLiveDemoEnvironment() && user.demo && user.showsWorkOfId
      ? (filteredPeople.find((p) => p.id === user.showsWorkOfId) ??
        filteredCurrentUser)
      : filteredCurrentUser;

  const finance: AppFinanceCapabilities = {
    canViewFirm: currentUserPermissions.includes('finance:view'),
    canViewMatter: currentUserPermissions.includes('finance:view_matter'),
    canCreditControl: currentUserPermissions.includes('finance:credit_control'),
  };

  const pmsSummaryByMatterIdForAttention: Record<string, PmsMatterFinancials> = {};
  if (finance.canViewMatter) {
    const isCleanEmpty = Boolean(store.isCleanDeployment) && store.pmsLinks.length === 0;
    if (!isCleanEmpty) {
      const visiblePmsLinks = store.pmsLinks.filter(
        (l) => !(l.entityType === 'matter' && hiddenMatterIds.has(l.onesquaredId)),
      );
      const visibleMatterPmsCodes = visiblePmsLinks
        .filter((l) => l.entityType === 'matter')
        .map((l) => l.pmsCode);
      const allMatterFins = await getPmsRepository().getMatterFinanceSummaryRows(
        snapshotTenantCtx,
        visibleMatterPmsCodes,
      );
      const finByMatterCode = new Map(
        allMatterFins.map((f) => [
          f.matter_code,
          f as unknown as PmsMatterFinancials,
        ]),
      );
      for (const link of visiblePmsLinks) {
        if (link.entityType === 'matter') {
          const fin = finByMatterCode.get(link.pmsCode);
          if (fin) pmsSummaryByMatterIdForAttention[link.onesquaredId] = fin;
        }
      }
    }
  }

  const attention = attentionList([...people, ...organisations], store.values, now, {
    userId: effectiveWorkPerson.id,
    tasks: visibleTasks,
    enquiries: visibleEnquiries,
    teams,
    matters: visibleMatters,
    pmsSummaryByMatterId: pmsSummaryByMatterIdForAttention,
    canViewFinance: finance.canViewMatter,
  });
  const primaryRecentIds = await taskRepo.getRecentlyViewedForUser(
    snapshotTenantCtx,
    user.id,
    { includeRestricted: true },
  );
  const rawRecentIds =
    primaryRecentIds.length > 0 || effectiveWorkPerson.id === user.id
      ? primaryRecentIds
      : await taskRepo.getRecentlyViewedForUser(
          snapshotTenantCtx,
          effectiveWorkPerson.id,
          { includeRestricted: true },
        );
  const recentIds = rawRecentIds.filter(
    (id) =>
      !hiddenMatterIds.has(id) &&
      !hiddenTaskIds.has(id) &&
      !hiddenEnquiryIds.has(id) &&
      !hiddenQuoteIds.has(id) &&
      (canViewQuotes || !id.startsWith('QUO-')),
  );
  const [primaryNotifications, effectivePersonNotifications, userNotifPrefs] =
    await Promise.all([
      taskRepo.listNotificationsForUser<NotificationItem>(
        snapshotTenantCtx,
        user.id,
        { includeRestricted: true },
      ),
      effectiveWorkPerson.id !== user.id
        ? taskRepo.listNotificationsForUser<NotificationItem>(
            snapshotTenantCtx,
            effectiveWorkPerson.id,
            { includeRestricted: true },
          )
        : Promise.resolve([]),
      getOutboxRepository().listNotificationPreferencesForUser(
        snapshotTenantCtx,
        user.id,
      ),
    ]);
  const inAppDisabledKinds = new Set(
    userNotifPrefs
      .filter((p) => !p.inAppEnabled)
      .map((p) => p.notificationKind),
  );
  const mergedNotificationsMap = new Map<string, NotificationItem>();
  for (const n of [...primaryNotifications, ...effectivePersonNotifications]) {
    mergedNotificationsMap.set(n.id, n);
  }
  const userNotifications = Array.from(mergedNotificationsMap.values())
    .filter(
      (n) =>
        !inAppDisabledKinds.has(n.kind) &&
        !(
          (n.matterId && hiddenMatterIds.has(n.matterId)) ||
          hiddenMatterIds.has(n.recordId) ||
          hiddenTaskIds.has(n.recordId) ||
          hiddenEnquiryIds.has(n.recordId) ||
          hiddenQuoteIds.has(n.recordId) ||
          (!canViewQuotes && n.recordId.startsWith('QUO-'))
        ),
    )
    .sort((a, b) => b.createdAt.localeCompare(a.createdAt));
  const taskBadgeCount = countMyUrgentBadgeTasks(visibleTasks, effectiveWorkPerson.id, now);

  const visibleNotes = notes.filter(
    (n) =>
      !hiddenMatterIds.has(n.recordId) &&
      !hiddenTaskIds.has(n.recordId) &&
      !hiddenEnquiryIds.has(n.recordId) &&
      !hiddenQuoteIds.has(n.recordId) &&
      (canViewQuotes ||
        (!n.recordId.startsWith('QUO-') &&
          (n.recordType as string) !== 'quote')),
  );
  // R413: Do not load the firm-wide audit_entries table on every page snapshot;
  // profile pages use listAuditEntriesForRecord and Admin uses listFirmAuditEntriesPage.
  const visibleAudit: AuditEntry[] = options?.includeFirmAudit
    ? (
        await listFirmAuditEntriesPage(user.id, {
          limit: 250,
          tokenRoles: effectiveTokenRoles,
        })
      ).entries
    : [];

  // Derive expired quote display status in-memory only (read path must remain side-effect free).
  for (const q of visibleQuotes) {
    applyQuoteEffectiveLifecycle(q, now, { appendExpiredTimeline: false });
  }

  const canTakeByTaskId: Record<string, boolean> = {};
  for (const t of visibleTasks) {
    canTakeByTaskId[t.id] = canUserTakeTask(
      user.id,
      t,
      teams,
      people,
      store.values,
      currentUserPermissions,
    );
  }

  const canVerifyByKeyDateId: Record<
    string,
    { allowed: boolean; reason?: string }
  > = {};
  for (const kd of visibleKeyDates) {
    canVerifyByKeyDateId[kd.id] = canUserVerifyKeyDate(user, kd, {
      config: keyDatesConfig,
      allPeople: people,
      teams,
    });
  }

  const canReopenByEnquiryId: Record<string, boolean> = {};
  for (const eq of visibleEnquiries) {
    canReopenByEnquiryId[eq.id] =
      currentUserPermissions.includes('enquiry:reopen') &&
      canUserReopenEnquiry(
        user.id,
        eq,
        teams,
        people,
        store.values,
      );
  }

  const appRoleByPersonId: Record<string, AppRole> = {};
  const rolesByPersonId: Record<string, HomeRoleKey[]> = {};
  const permissionsByPersonId: Record<string, PermissionKey[]> = {};
  for (const emp of people) {
    if (!emp.isEmployee || emp.mergedIntoId) continue;
    appRoleByPersonId[emp.id] = resolveUserAppRole(
      emp,
      teams,
      store.values,
      { config: { rbac: rbacConfig } },
    );
    rolesByPersonId[emp.id] = resolveEmployeeRoles(emp, teams);
    permissionsByPersonId[emp.id] = resolvePersonPermissions(emp, {
      allPeople: people,
      teams,
      config: { rbac: rbacConfig },
    });
  }

  const canSignOffCostsByMatterId: Record<string, boolean> = {};
  const signOffEstimateGbpByMatterId: Record<string, number> = {};
  const actorCanSignOffCosts = currentUserPermissions.includes('matter:costs:sign_off');
  for (const m of visibleMatters) {
    canSignOffCostsByMatterId[m.id] =
      actorCanSignOffCosts &&
      canPersonAccessMatter(m, user.id, user, {
        allPeople: people,
        teams,
        config: { rbac: rbacConfig },
      });
    signOffEstimateGbpByMatterId[m.id] = resolveMatterSignOffEstimateGbp(
      store,
      activeTenantCfg,
      m,
    ).estimatedFeeGbp;
  }

  const conflictReviewCfg = activeTenantCfg.conflictReview;
  const riskReviewer = resolveSuggestedConflictReviewer(
    { teams, orgStructure },
    conflictReviewCfg,
    rolesByPersonId,
    employees,
  );
  const practiceManager =
    employees.find(
      (e) =>
        rolesByPersonId[e.id]?.includes('managing_partner') ||
        e.employeeRoleId === 'employee_role.practice_manager',
    ) ?? null;
  const suggestedMatterGovernanceAssignees = {
    riskReviewerId: riskReviewer?.id ?? null,
    practiceManagerId: practiceManager?.id ?? null,
  };

  const firmPrimaryDomain = resolveConfiguredFirmPrimaryDomain();

  return {
    firm: store.firm,
    tenantId: activeTenantCfg.tenantId,
    firmPrimaryDomain,
    enableAiMatterExtraction: Boolean(activeTenantCfg.featureFlags?.enableAiMatterExtraction),
    aiProviderChoice: activeTenantCfg.integrations?.aiProviderChoice ?? 'disabled',
    enableMatterCostsGovernance: Boolean(activeTenantCfg.featureFlags?.enableMatterCostsGovernance),
    enablePmsLiveRateSync: Boolean(activeTenantCfg.featureFlags?.enablePmsLiveRateSync),
    currentUser: filteredCurrentUser,
    currentUserId: user.id,
    currentUserRole,
    currentUserRoles,
    currentUserEmployeePermissions,
    currentUserPermissions,
    currentUserKeyDatePermissions,
    canTakeByTaskId,
    canVerifyByKeyDateId,
    canReopenByEnquiryId,
    canSignOffCostsByMatterId,
    signOffEstimateGbpByMatterId,
    suggestedMatterGovernanceAssignees,
    appRoleByPersonId,
    rolesByPersonId,
    permissionsByPersonId,
    keyDatesConfig,
    keyDates: visibleKeyDates,
    keyDateNotApplicable: visibleKeyDateNotApplicable,
    keyDateReminderStates: visibleKeyDateReminderStates,
    keyDateCalendarSyncs: visibleKeyDateCalendarSyncs,
    rbacConfig,
    orgStructure,
    matterPartyTaxonomy: store.matterPartyTaxonomy ?? buildDefaultMatterPartyTaxonomy(store.values),
    matterPartyMigrationReport: store.matterPartyMigrationReport,
    employeeSensitiveRecords,
    employeeMigrationReport: dbEmployeeMigrationReport ?? undefined,
    leaverOwnedRecords,
    activeViewingRole,
    leftRailVisibility,
    effectiveWorkPerson,
    homePagesConfig,
    signOffs: visibleSignOffs,
    finance,
    employees,
    lists: store.lists,
    values: store.values,
    customFields: store.customFields,
    people: filteredPeople,
    organisations,
    links: visibleLinks,
    matters: visibleMatters,
    teams,
    tasks: visibleTasks,
    enquiries: visibleEnquiries,
    quotes: visibleQuotes,
    notifications: userNotifications,
    enquirySettings: store.enquirySettings,
    taskSettings: store.taskSettings,
    matterCostsConfig: resolveEffectiveMatterCostsConfig(
      activeTenantCfg,
      store.matterCostsConfig,
      {
        values: store.values,
        clientProfileCode: activeTenantCfg.tenantId,
        displayName: activeTenantCfg.displayName,
        primaryDomain: activeTenantCfg.branding.primaryDomain,
      },
    ),
    workTypesConfig:
      store.workTypesConfig ??
      resolveEffectiveWorkTypesConfig(activeTenantCfg, store.workTypeConfigsOverride ?? null),
    ...(await (async () => {
      const canReadRegisters =
        currentUserPermissions.includes('register:view') ||
        currentUserPermissions.includes('undertaking:manage');
      const dbRegOverride = await getCatalogueRepository().getModuleConfig<RegistersConfiguration>(
        snapshotTenantCtx,
        'registers',
      );
      const effectiveRegistersCfg = mergeRegistersConfigurations(
        activeTenantCfg.registers ?? DEFAULT_REGISTERS_CONFIG,
        dbRegOverride,
      );
      const effectiveRegTypes = resolveEffectiveRegisterTypes(
        activeTenantCfg.registers ?? DEFAULT_REGISTERS_CONFIG,
        dbRegOverride,
      );
      const visibleRegRecords = canReadRegisters
        ? await getRegisterRepository().listVisibleRegisterRecords(snapshotTenantCtx, userId)
        : [];
      return {
        registersConfig: effectiveRegistersCfg,
        registerTypes: effectiveRegTypes,
        registerRecords: visibleRegRecords,
      };
    })()),
    taskBadgeCount,
    notes: visibleNotes,
    audit: visibleAudit,
    mergeHistory,
    searchIndex: [],
    attention,
    recentIds,
  };
}

