export interface NotificationPreferenceUpdateEntry {
  readonly notificationKind: NotificationKind;
  readonly inAppEnabled?: boolean;
  readonly emailFrequency?: NotificationChannelFrequency;
  readonly teamsEnabled?: boolean;
}

function createForbiddenError(message: string): Error {
  const err = new Error(`FORBIDDEN: ${message}`);
  (err as Error & { code?: string }).code = 'FORBIDDEN';
  return err;
}

function createValidationError(code: string, message: string): Error {
  const err = new Error(`${code}: ${message}`);
  (err as Error & { code?: string }).code = code;
  return err;
}

/**
 * Returns all 13 notification preference rows (merged with ADR 0035 S4 defaults)
 * for the signed-in employee. Rejects any cross-user lookup (`actorPersonId !== personId`).
 */
export async function getMyNotificationPreferences(
  personId: string,
  options?: {
    readonly actorPersonId?: string | null;
    readonly tenantCtx?: TenantContext | null;
    readonly tokenRoles?: readonly string[];
  },
): Promise<readonly UserNotificationPreference[]> {
  const cleanTargetId = personId?.trim() || '';
  const fallbackActorId = (
    options?.actorPersonId ??
    options?.tenantCtx?.actorId ??
    ''
  ).trim();
  const ctx =
    options?.tenantCtx ??
    resolveDefaultServiceTenantContext(null, fallbackActorId || cleanTargetId);
  const effectiveActorId = (options?.actorPersonId ?? ctx.actorId).trim();

  if (!cleanTargetId || !effectiveActorId || effectiveActorId !== cleanTargetId) {
    throw createForbiddenError(
      'Users can only view their own notification preferences.',
    );
  }

  const [people, teams, rbacConfig] = await Promise.all([
    loadStaffPeople(ctx),
    getHrAndRbacRepository().listAllTeams<Team>(ctx),
    loadEffectiveTenantRbacConfig(ctx),
  ]);
  const actor =
    people.find((p) => p.id === effectiveActorId && !p.mergedIntoId) ?? null;
  if (!actor || !actor.isEmployee || isLeaverPerson(actor)) {
    throw createForbiddenError(
      'Notification preferences are restricted to active employees.',
    );
  }
  const perms = resolvePersonPermissionSet(actor, {
    allPeople: people,
    teams,
    config: { rbac: rbacConfig },
    tokenRoles: options?.tokenRoles ?? ctx.actorRoles,
    tokenRolesActorId: actor.id,
  });
  if (!perms.permissions.has('notification:view_own')) {
    throw createForbiddenError(
      'Permission "notification:view_own" is required to view notification preferences.',
    );
  }

  return getOutboxRepository().listNotificationPreferencesForUser(ctx, actor.id);
}

/**
 * Updates self-service notification preferences across one or more notification kinds
 * and optional working-day weekly digest schedule (`digestDayOfWeek` 1..5 Mon–Fri),
 * enforcing self-only ownership and same-transaction zero-PII audit logging.
 */
export async function updateMyNotificationPreferences(
  input: {
    readonly personId: string;
    readonly updates: readonly NotificationPreferenceUpdateEntry[];
    readonly digestDayOfWeek?: number;
  },
  options?: {
    readonly actorPersonId?: string | null;
    readonly tenantCtx?: TenantContext | null;
    readonly tokenRoles?: readonly string[];
  },
): Promise<readonly UserNotificationPreference[]> {
  const cleanTargetId = input.personId?.trim() || '';
  const fallbackActorId = (
    options?.actorPersonId ??
    options?.tenantCtx?.actorId ??
    ''
  ).trim();
  const ctx =
    options?.tenantCtx ??
    resolveDefaultServiceTenantContext(null, fallbackActorId || cleanTargetId);
  const effectiveActorId = (options?.actorPersonId ?? ctx.actorId).trim();

  if (!cleanTargetId || !effectiveActorId || effectiveActorId !== cleanTargetId) {
    throw createForbiddenError(
      'Users can only modify their own notification preferences.',
    );
  }

  const validKinds = new Set<string>(ALL_NOTIFICATION_KINDS);
  const validFrequencies = new Set<string>([
    'immediate',
    'daily_digest',
    'weekly_digest',
    'none',
  ]);
  for (const upd of input.updates ?? []) {
    if (!validKinds.has(upd.notificationKind)) {
      throw createValidationError(
        'NOTIFICATION_PREFERENCE_INVALID',
        `Unknown notification kind "${String(upd.notificationKind)}".`,
      );
    }
    if (
      upd.emailFrequency !== undefined &&
      !validFrequencies.has(upd.emailFrequency)
    ) {
      throw createValidationError(
        'NOTIFICATION_PREFERENCE_INVALID',
        `Invalid email frequency "${String(upd.emailFrequency)}".`,
      );
    }
  }
  if (input.digestDayOfWeek !== undefined) {
    if (
      !Number.isInteger(input.digestDayOfWeek) ||
      input.digestDayOfWeek < 1 ||
      input.digestDayOfWeek > 5
    ) {
      throw createValidationError(
        'NOTIFICATION_PREFERENCE_INVALID',
        'digestDayOfWeek must be a working weekday integer between 1 (Monday) and 5 (Friday).',
      );
    }
  }

  const [people, teams, rbacConfig] = await Promise.all([
    loadStaffPeople(ctx),
    getHrAndRbacRepository().listAllTeams<Team>(ctx),
    loadEffectiveTenantRbacConfig(ctx),
  ]);
  const actor =
    people.find((p) => p.id === effectiveActorId && !p.mergedIntoId) ?? null;
  if (!actor || !actor.isEmployee || isLeaverPerson(actor)) {
    throw createForbiddenError(
      'Notification preferences are restricted to active employees.',
    );
  }
  const perms = resolvePersonPermissionSet(actor, {
    allPeople: people,
    teams,
    config: { rbac: rbacConfig },
    tokenRoles: options?.tokenRoles ?? ctx.actorRoles,
    tokenRolesActorId: actor.id,
  });
  if (!perms.permissions.has('notification:manage_own_preferences')) {
    throw createForbiddenError(
      'Permission "notification:manage_own_preferences" is required to update notification preferences.',
    );
  }

  const outboxRepo = getOutboxRepository();
  const nowIso = new Date().toISOString();

  return outboxRepo.withTenantTransaction(ctx, async () => {
    const existingList = await outboxRepo.listNotificationPreferencesForUser(
      ctx,
      actor.id,
    );
    const existingByKind = new Map(
      existingList.map((pref) => [pref.notificationKind, pref]),
    );
    const updatesByKind = new Map<NotificationKind, NotificationPreferenceUpdateEntry>();
    for (const upd of input.updates ?? []) {
      updatesByKind.set(upd.notificationKind, upd);
    }

    const kindsToPersist = new Set<NotificationKind>(updatesByKind.keys());
    if (input.digestDayOfWeek !== undefined) {
      for (const kind of ALL_NOTIFICATION_KINDS) {
        kindsToPersist.add(kind);
      }
    }

    if (kindsToPersist.size > 0) {
      const changedSummaries: string[] = [];
      for (const kind of kindsToPersist) {
        const current = existingByKind.get(kind);
        const defaults =
          DEFAULT_NOTIFICATION_PREFERENCES_BY_KIND[kind] ??
          DEFAULT_NOTIFICATION_PREFERENCES_BY_KIND.general;
        const patch = updatesByKind.get(kind);
        const nextInApp = patch?.inAppEnabled ?? current?.inAppEnabled ?? defaults.inAppEnabled;
        const nextEmailFreq =
          patch?.emailFrequency ?? current?.emailFrequency ?? defaults.emailFrequency;
        const nextTeams = patch?.teamsEnabled ?? current?.teamsEnabled ?? defaults.teamsEnabled;
        const nextDay =
          input.digestDayOfWeek ?? current?.digestDayOfWeek ?? 1;

        await outboxRepo.upsertNotificationPreference(ctx, {
          personId: actor.id,
          notificationKind: kind,
          inAppEnabled: nextInApp,
          emailFrequency: nextEmailFreq,
          teamsEnabled: nextTeams,
          digestDayOfWeek: nextDay,
        });
        if (patch) {
          changedSummaries.push(
            `${kind}:inApp=${nextInApp},email=${nextEmailFreq},teams=${nextTeams}`,
          );
        }
      }

      const dayNote =
        input.digestDayOfWeek !== undefined
          ? `; digestDayOfWeek=${input.digestDayOfWeek}`
          : '';
      await appendTenantAuditEntries(ctx, [
        {
          recordType: 'notification_preferences',
          recordId: actor.id,
          action: 'update',
          field: 'notificationPreferences',
          oldValue: null,
          newValue: `${changedSummaries.length} kind(s) updated${dayNote}`.slice(
            0,
            240,
          ),
          byId: actor.id,
          at: nowIso,
          reason: `Self-service notification preferences updated (${changedSummaries.length} kind(s)${dayNote}).`,
        },
      ]);
    }

    return outboxRepo.listNotificationPreferencesForUser(ctx, actor.id);
  });
}

// ------------------------------------------------------------------ Admin: Teams & Settings
export async function saveTeamRecord(
  input: {
    id?: string;
    name: string;
    description?: string;
    departmentId?: string | null;
    orgTeamId?: string | null;
    systemKey?: string | null;
    memberIds: string[];
    leadIds: string[];
    practiceAreaIds: string[];
    active?: boolean;
  },
  byId: string,
): Promise<{ team?: Team; error?: string } & Partial<ActionDenied>> {
  const now = new Date().toISOString();
  const name = input.name.trim();
  if (!name) return { error: 'Team name is required.' };

  const teamCtx = resolveDefaultServiceTenantContext(null, byId);
  const hrRepo = getHrAndRbacRepository();
  const [existing, allTeams, store] = await Promise.all([
    input.id ? hrRepo.getTeamById<Team>(teamCtx, input.id) : Promise.resolve(null),
    hrRepo.listAllTeams<Team>(teamCtx),
    loadTenantCatalogueStoreView(teamCtx),
  ]);
  if (input.id && !existing) {
    const msg = `Team "${input.id}" not found.`;
    return {
      ...buildActionDenied('FORBIDDEN', msg),
      error: msg,
    };
  }

  // S0-04: Prevent self-escalation into team leadIds (which grants team-lead permissions such as employee:edit_core).
  const isAddingSelfAsLead =
    input.leadIds.includes(byId) && !(existing?.leadIds.includes(byId) ?? false);
  if (isAddingSelfAsLead) {
    const msg =
      'SELF_MODIFICATION_FORBIDDEN: Users cannot make themselves a team lead.';
    return {
      ...buildActionDenied('FORBIDDEN', msg),
      error: msg,
    };
  }

  const nextActive = input.active ?? existing?.active ?? true;
  if (!nextActive && existing && store.enquirySettings.fallbackTeamId === existing.id) {
    return {
      error: 'Cannot deactivate the team currently configured as the fallback enquiry team.',
    };
  }

  const existingDepartmentId = existing?.departmentId?.trim() || null;
  const resolvedDepartmentId =
    input.departmentId !== undefined
      ? input.departmentId?.trim() || null
      : existingDepartmentId;
  const departmentChanged = resolvedDepartmentId !== existingDepartmentId;
  if (resolvedDepartmentId && departmentChanged) {
    const dept = store.orgStructure.departments.find(
      (d) => d.id === resolvedDepartmentId && d.active !== false,
    );
    if (!dept) {
      return {
        error: `Department "${resolvedDepartmentId}" does not match an active department.`,
      };
    }
  }

  const existingOrgTeamId = existing?.orgTeamId?.trim() || null;
  const resolvedOrgTeamId =
    input.orgTeamId !== undefined
      ? input.orgTeamId?.trim() || null
      : existingOrgTeamId;
  const orgTeamChanged = resolvedOrgTeamId !== existingOrgTeamId;
  if (resolvedOrgTeamId && (orgTeamChanged || departmentChanged)) {
    const tpg = store.orgStructure.teamsOrPracticeGroups.find(
      (g) =>
        g.id === resolvedOrgTeamId &&
        (!orgTeamChanged || g.active !== false),
    );
    if (!tpg) {
      return {
        error: `Practice group "${resolvedOrgTeamId}" does not match an active org team.`,
      };
    }
    if (resolvedDepartmentId && tpg.parentDepartmentId !== resolvedDepartmentId) {
      return {
        error: `Practice group "${resolvedOrgTeamId}" does not belong to department "${resolvedDepartmentId}".`,
      };
    }
  }

  const resolvedSystemKey =
    input.systemKey !== undefined
      ? input.systemKey?.trim() || undefined
      : existing?.systemKey;
  if (resolvedSystemKey !== undefined) {
    if (!/^[a-z0-9_]{1,64}$/.test(resolvedSystemKey)) {
      return {
        error: 'Team system key must match ^[a-z0-9_]{1,64}$.',
      };
    }
    if (nextActive) {
      const colliding = allTeams.find(
        (t) =>
          t.id !== existing?.id &&
          t.active &&
          t.systemKey === resolvedSystemKey,
      );
      if (colliding) {
        return {
          error: `Active team "${colliding.name}" already uses system key "${resolvedSystemKey}".`,
        };
      }
    }
  }

  const memberIds = Array.from(new Set([...input.memberIds, ...input.leadIds]));
  const leadIds = input.leadIds.filter((id) => memberIds.includes(id));

  let team!: Team;
  await runWithAuditStagingScope(() =>
    hrRepo.withTenantTransaction(teamCtx, async () => {
      const allocatedTeamId = existing
        ? existing.id
        : await hrRepo.allocateNextTeamId(teamCtx);
      team = {
        id: allocatedTeamId,
        name,
        description: (input.description ?? existing?.description ?? '').trim(),
        ...(resolvedDepartmentId ? { departmentId: resolvedDepartmentId } : {}),
        ...(resolvedOrgTeamId ? { orgTeamId: resolvedOrgTeamId } : {}),
        ...(resolvedSystemKey ? { systemKey: resolvedSystemKey } : {}),
        memberIds,
        leadIds,
        practiceAreaIds: input.practiceAreaIds,
        active: nextActive,
        createdById: existing?.createdById ?? byId,
        createdAt: existing?.createdAt ?? now,
        updatedById: byId,
        updatedAt: now,
      };
      await hrRepo.putTeam(teamCtx, team);
      await syncAffectedMattersRestrictionsInTx(teamCtx, {
        includeAllRestrictedMatters: true,
      });
      if (!existing) {
        writeAudit(null, {
          recordType: 'team',
          recordId: team.id,
          action: 'create',
          field: 'Team created',
          oldValue: null,
          newValue: team.name,
          byId,
          at: now,
        });
      } else {
        writeAudit(null, {
          recordType: 'team',
          recordId: team.id,
          action: 'update',
          field: 'Team updated',
          oldValue: existing.name,
          newValue: `${team.name} (${team.memberIds.length} members, ${team.active ? 'active' : 'inactive'})`,
          byId,
          at: now,
        });
      }
      await flushStagedAuditEntries(teamCtx);
    }),
  );
  return { team };
}

export async function updateEmployeeRoleSetting(
  personId: string,
  appRole: AppRole | null,
  byId: string,
  options: { mfaVerified?: boolean } = {},
): Promise<{ ok: boolean; code?: string; error?: string }> {
  const ctx = resolveDefaultServiceTenantContext(null, byId);
  const partyRepo = getPartyRepository();
  const hrRepo = getHrAndRbacRepository();
  return partyRepo.withTenantTransaction(ctx, async () => {
    const [people, teams, rbacOverride] = await Promise.all([
      loadStaffPeople(ctx),
      hrRepo.listAllTeams<Team>(ctx),
      hrRepo.getRbacConfigOverride<RbacConfiguration>(ctx),
    ]);
    const actor = people.find((p) => p.id === byId);
    const person = people.find((p) => p.id === personId && p.isEmployee);
    if (!actor) return { ok: false, error: 'Acting user not found.' };
    if (!person) return { ok: false, error: 'Employee not found.' };

    const rbacConfig = await loadEffectiveTenantRbacConfig(ctx, rbacOverride);
    const actorPerms = resolvePersonPermissionSet(actor, {
      allPeople: people,
      teams,
      mfaVerified: options.mfaVerified ?? false,
      config: { rbac: rbacConfig },
    });

    const addedRoleKeys: string[] =
      appRole === 'admin'
        ? ['admin']
        : appRole === 'team_lead'
          ? ['partner', 'fee_earner']
          : appRole === 'call_handler'
            ? ['enquiries_coordinator']
            : appRole === 'fee_earner'
              ? ['fee_earner']
              : [];

    try {
      validateUserOverrideOrRoleMutation({
        actorPermissions: actorPerms,
        targetPersonId: person.id,
        addedRoleKeys,
        rbacConfig,
      });
    } catch (err) {
      const code = err instanceof AuthorisationError ? err.code : undefined;
      const message = err instanceof Error ? err.message : String(err);
      return {
        ok: false,
        code,
        error: code ? `${code}: ${message}` : message,
      };
    }

    const beforeJson = JSON.stringify({ appRole: person.appRole ?? null });
    person.appRole = appRole;
    person.updatedAt = new Date().toISOString();
    person.updatedById = byId;
    const afterJson = JSON.stringify({ appRole: person.appRole ?? null });
    await partyRepo.putPerson(ctx, person);
    await syncAffectedMattersRestrictionsInTx(ctx, {
      includeAllRestrictedMatters: true,
    });
    await runWithAuditStagingScope(async () => {
      writeAudit(null, {
        recordType: 'person',
        recordId: person.id,
        action: 'update',
        field: 'App role',
        oldValue: beforeJson,
        newValue: afterJson,
        byId,
      });
      await flushStagedAuditEntries(ctx);
    });
    return { ok: true };
  });
}

export async function saveEnquirySettingsRecord(
  patch: Partial<EnquirySettings>,
  byId: string,
): Promise<(EnquirySettings & { error?: undefined }) | { error: string }> {
  const ctx = resolveDefaultServiceTenantContext(null, byId);
  const catalogueRepo = getCatalogueRepository();
  const hrRepo = getHrAndRbacRepository();
  let result!: (EnquirySettings & { error?: undefined }) | { error: string };
  await runWithAuditStagingScope(() =>
    catalogueRepo.withTenantTransaction(ctx, async () => {
      const [store, rawPersistedSettings, allTeams] = await Promise.all([
        loadTenantCatalogueStoreView(ctx),
        catalogueRepo.getModuleConfig<Partial<EnquirySettings>>(
          ctx,
          'enquiry_settings',
        ),
        hrRepo.listAllTeams<Team>(ctx),
      ]);
      const rawPersistedFallbackTeamId =
        typeof rawPersistedSettings?.fallbackTeamId === 'string' &&
        rawPersistedSettings.fallbackTeamId.trim().length > 0
          ? rawPersistedSettings.fallbackTeamId.trim()
          : null;
      const requestedFallbackTeamId =
        patch.fallbackTeamId === undefined
          ? rawPersistedFallbackTeamId
          : patch.fallbackTeamId?.trim() || null;
      if (
        requestedFallbackTeamId !== null &&
        !allTeams.some((t) => t.id === requestedFallbackTeamId && t.active)
      ) {
        result = {
          error: 'Fallback enquiry team must reference an existing active team.',
        };
        return;
      }
      const { fallbackTeamId: _omittedFallback, ...patchWithoutFallback } = patch;
      void _omittedFallback;
      const persistedToSave: EnquirySettings = {
        ...DEFAULT_ENQUIRY_SETTINGS,
        ...(rawPersistedSettings ?? {}),
        ...patchWithoutFallback,
        fallbackTeamId: requestedFallbackTeamId,
      };
      if (requestedFallbackTeamId === null) {
        delete persistedToSave.fallbackTeamId;
      }
      await catalogueRepo.putEnquirySettingsConfig(ctx, persistedToSave, byId);
      const configuredFallbackTeamId =
        getActiveTenantConfiguration().enquiries?.fallbackTeamId?.trim() || null;
      const nextSettings: EnquirySettings = {
        ...store.enquirySettings,
        ...persistedToSave,
        fallbackTeamId: requestedFallbackTeamId ?? configuredFallbackTeamId ?? null,
      };
      writeAudit(null, {
        recordType: 'system',
        recordId: 'enquiry-settings',
        action: 'update',
        field: 'Enquiry settings',
        oldValue: null,
        newValue: `Emergency ${nextSettings.emergencyHours}h · Hours ${nextSettings.workDayStart}–${nextSettings.workDayEnd} · Attempts ${nextSettings.failedAttemptsBeforeSuggestNoResponse} · Retention ${nextSettings.retentionMonths}m · Fallback ${nextSettings.fallbackTeamId ?? 'intake-default'}`,
        byId,
      });
      await flushStagedAuditEntries(ctx);
      result = nextSettings;
    }),
  );
  return result;
}

export async function saveTaskSettingsRecord(
  settings: TaskSettings,
  byId: string,
): Promise<TaskSettings> {
  const ctx = resolveDefaultServiceTenantContext(null, byId);
  const catalogueRepo = getCatalogueRepository();
  await runWithAuditStagingScope(() =>
    catalogueRepo.withTenantTransaction(ctx, async () => {
      await catalogueRepo.putTaskSettingsConfig(ctx, settings, byId);
      writeAudit(null, {
        recordType: 'system',
        recordId: 'task-settings',
        action: 'update',
        field: 'Task settings',
        oldValue: null,
        newValue: 'Updated automatic task templates and due offsets',
        byId,
      });
      await flushStagedAuditEntries(ctx);
    }),
  );
  return settings;
}

