export interface SaveQuoteInput {
  clientType: 'existing' | 'prospect';
  linkedOrganisationId?: string | null;
  linkedPersonId?: string | null;
  prospectName?: string;
  prospectOrganisationName?: string;
  prospectEmail?: string;
  prospectPhone?: string;
  linkedEnquiryId?: string | null;
  practiceAreaId: string;
  workTypeSubcategoryId?: string | null;
  scope: string;
  assumptions?: string;
  feeBasis: QuoteFeeBasis;
  feeAmountExVat: number;
  hourlyRateGbp?: number | null;
  vatAmount?: number;
  vatOverridden?: boolean;
  disbursements?: QuoteDisbursement[];
  validUntil?: string;
  feeEarnerId?: string;
  followUpAfterDays?: number;
  refreshVatRate?: boolean;
  rateGradeKey?: string;
  refreshRates?: boolean;
  feeArrangementCapCategoryKey?: string;
  feeArrangementPercent?: number | null;
  feeArrangementCapBaseKey?: string;
}

function normalizeQuoteDisbursements(
  rawDisbursements: QuoteDisbursement[] | undefined,
): { disbursements?: QuoteDisbursement[]; error?: string } {
  const list = rawDisbursements ?? [];
  const out: QuoteDisbursement[] = [];
  for (let idx = 0; idx < list.length; idx += 1) {
    const d = list[idx]!;
    if (!d.description?.trim() && !(Number(d.amountExVat) > 0)) {
      continue;
    }
    const amt = Number(d.amountExVat);
    if (!Number.isFinite(amt) || amt < 0) {
      return { error: 'Disbursement amounts must be non-negative numbers.' };
    }
    const vatOverridden = Boolean(d.vatOverridden);
    let vatAmount: number | undefined;
    if (vatOverridden && d.vatAmount !== undefined && d.vatAmount !== null) {
      const parsedVat = Number(d.vatAmount);
      if (!Number.isFinite(parsedVat) || parsedVat < 0) {
        return { error: 'Overridden disbursement VAT amounts must be non-negative numbers.' };
      }
      vatAmount = roundCurrency(parsedVat);
    }
    out.push({
      id: d.id || `QDISB-${Date.now()}-${idx}`,
      description: d.description.trim() || 'Disbursement',
      amountExVat: roundCurrency(amt),
      vatApplicable: Boolean(d.vatApplicable),
      ...(vatOverridden ? { vatOverridden: true } : {}),
      ...(vatAmount !== undefined ? { vatAmount } : {}),
    });
  }
  return { disbursements: out };
}

function hourlyGbpMatchesMinorUnits(
  hourlyRateGbp: number,
  rateMinorUnits: number,
): boolean {
  if (!Number.isFinite(hourlyRateGbp) || hourlyRateGbp < 0) {
    return false;
  }
  if (hourlyRateGbp > 0 && hourlyRateGbp < 1e-6) {
    return rateMinorUnits === 0;
  }
  const raw = String(hourlyRateGbp);
  const converted = /[eE]/.test(raw)
    ? poundsToMinorUnits(hourlyRateGbp.toFixed(4))
    : poundsToMinorUnits(raw);
  return converted === rateMinorUnits;
}

export async function saveQuoteRecord(
  input: SaveQuoteInput,
  opts: { id?: string; byId: string; markAsSent?: boolean; refreshVatRate?: boolean },
): Promise<
  { quote?: Quote; error?: string } & Partial<Omit<ActionDenied, 'code'>> & {
    code?: ActionDenialCode | FeeCapErrorCode;
  }
> {
  return runWithAuditStagingScope(async () => {
  const ctx = resolveDefaultServiceTenantContext(null, opts.byId);
  const partyRepo = getPartyRepository();
  const matterRepo = getMatterRepository();
  const intakeRepo = getIntakeQuoteRepository();
  const [
    catalogueStore,
    staffPeople,
    teams,
    rbacConfig,
    existing,
    linkedOrgDirect,
    linkedPersonDirect,
    linkedEnqDirect,
  ] = await Promise.all([
    loadTenantCatalogueStoreView(ctx),
    loadStaffPeople(ctx),
    getHrAndRbacRepository().listAllTeams<Team>(ctx),
    loadEffectiveTenantRbacConfig(ctx),
    opts.id
      ? intakeRepo.getQuoteById<Quote>(ctx, opts.id, { includeRestricted: true })
      : Promise.resolve<Quote | null>(null),
    input.linkedOrganisationId
      ? partyRepo.getOrganisationById<Organisation>(ctx, input.linkedOrganisationId)
      : Promise.resolve<Organisation | null>(null),
    input.linkedPersonId
      ? partyRepo.getPersonById<Person>(ctx, input.linkedPersonId)
      : Promise.resolve<Person | null>(null),
    input.linkedEnquiryId
      ? intakeRepo.getEnquiryById<Enquiry>(ctx, input.linkedEnquiryId, {
          includeRestricted: true,
        })
      : Promise.resolve<Enquiry | null>(null),
  ]);
  const existingLinkedEnq =
    existing?.linkedEnquiryId && existing.linkedEnquiryId !== input.linkedEnquiryId
      ? await intakeRepo.getEnquiryById<Enquiry>(ctx, existing.linkedEnquiryId, {
          includeRestricted: true,
        })
      : null;
  const refMatterIds = Array.from(
    new Set(
      [
        existing?.convertedMatterId,
        linkedEnqDirect?.convertedMatterId,
        existingLinkedEnq?.convertedMatterId,
      ].filter((x): x is string => Boolean(x)),
    ),
  );
  const refMatters =
    refMatterIds.length > 0
      ? await matterRepo.listMattersByIds<Matter>(ctx, refMatterIds, {
          includeRestricted: true,
        })
      : [];
  const refEnquiries = dedupeById(
    [linkedEnqDirect, existingLinkedEnq].filter((e): e is Enquiry => Boolean(e)),
  );
  const people = dedupeById([
    ...staffPeople,
    ...(linkedPersonDirect ? [linkedPersonDirect] : []),
  ]);
  const organisations = linkedOrgDirect ? [linkedOrgDirect] : [];
  const actor = staffPeople.find((p) => p.id === opts.byId) ?? null;
  if (
    !hasPersonPermission(actor, 'quote:edit', {
      allPeople: staffPeople,
      teams,
      config: { rbac: rbacConfig },
    })
  ) {
    const msg = 'You do not have permission (quote:edit) to create or edit quotes.';
    return { ...buildActionDenied('FORBIDDEN', msg), error: msg };
  }
  const visibility = buildRecordVisibility({ teams }, actor, {
    people: staffPeople,
    matters: refMatters,
    enquiries: refEnquiries,
    quotes: existing ? [existing] : [],
    teams,
    hiddenMatterKeyDateIds: EMPTY_HIDDEN_KEY_DATE_IDS,
    rbacConfig,
  });
  const now = new Date();
  const nowIso = now.toISOString();

  if (opts.id && (!existing || !visibility.canViewQuote(existing))) {
    const msg = 'Quote not found.';
    return { ...buildActionDenied('FORBIDDEN', msg), error: msg };
  }

  const clientType = input.clientType || 'prospect';
  const linkedOrganisationId = input.linkedOrganisationId || null;
  const linkedPersonId = input.linkedPersonId || null;
  if (linkedOrganisationId && !linkedOrgDirect) {
    const msg = 'Linked organisation not found.';
    return { ...buildActionDenied('FORBIDDEN', msg), error: msg };
  }
  if (linkedPersonId && !linkedPersonDirect) {
    const msg = 'Linked person not found.';
    return { ...buildActionDenied('FORBIDDEN', msg), error: msg };
  }
  if (input.linkedEnquiryId) {
    if (!linkedEnqDirect || !visibility.canViewEnquiry(linkedEnqDirect)) {
      const msg = 'Linked enquiry not found or access denied.';
      return { ...buildActionDenied('FORBIDDEN', msg), error: msg };
    }
  }
  const prospectName = (input.prospectName ?? '').trim();
  const prospectOrganisationName = (input.prospectOrganisationName ?? '').trim();
  const prospectEmail = (input.prospectEmail ?? '').trim();
  const prospectPhone = (input.prospectPhone ?? '').trim();

  if (clientType === 'existing' && !linkedOrganisationId && !linkedPersonId) {
    return { error: 'Please select an existing client or switch to entering a new prospect.' };
  }
  if (clientType === 'prospect' && !prospectName && !prospectOrganisationName) {
    return { error: 'Please enter the prospect name or organisation.' };
  }
  if (!input.practiceAreaId) {
    return { error: 'Please select a practice area / work type.' };
  }
  if (!input.scope?.trim()) {
    return { error: 'Please enter the description of work / scope.' };
  }
  if (!Number.isFinite(Number(input.feeAmountExVat)) || Number(input.feeAmountExVat) < 0) {
    return { error: 'Fee amount must be a non-negative number.' };
  }
  if (
    input.vatOverridden &&
    (!Number.isFinite(Number(input.vatAmount)) || Number(input.vatAmount) < 0)
  ) {
    return { error: 'VAT amount must be a non-negative number.' };
  }

  const normalizedDisbursements = normalizeQuoteDisbursements(input.disbursements);
  if (!normalizedDisbursements.disbursements) {
    return { error: normalizedDisbursements.error ?? 'Invalid quote disbursements.' };
  }
  const disbursements = normalizedDisbursements.disbursements;

  const feeEarnerId = input.feeEarnerId || existing?.feeEarnerId || opts.byId;
  const routedTeam = resolveRoutedTeam(
    input.practiceAreaId,
    teams,
    catalogueStore.enquirySettings.fallbackTeamId,
  );
  const feeEarnerTeam = teams.find(
    (t) => t.active && t.memberIds.includes(feeEarnerId),
  );
  const assignedTeamId = routedTeam?.team?.id ?? feeEarnerTeam?.id ?? existing?.assignedTeamId ?? null;

  const followUpAfterDays = Math.max(1, Number(input.followUpAfterDays) || 7);
  const defaultValidUntil = toIsoDate(addDays(now, 30));
  const validUntil = input.validUntil || existing?.validUntil || defaultValidUntil;

  const markSent = Boolean(opts.markAsSent);
  const sentAt = markSent ? nowIso : existing?.sentAt ?? null;
  const nextFollowUpDate = markSent
    ? toIsoDate(addDays(now, followUpAfterDays))
    : existing?.nextFollowUpDate ?? null;

  let status: QuoteStatus = existing?.status ?? 'Draft';
  if (markSent) {
    status = 'Sent';
  }

  if (!existing) {
    return intakeRepo.withTenantTransaction(ctx, async () => {
      const tenantCfg = getActiveTenantConfiguration();
      const dbCostsOverride =
        await getCatalogueRepository().getMatterCostsConfig<MatterCostsConfig>(ctx);
      const effectiveCostsConfig = resolveEffectiveMatterCostsConfig(
        tenantCfg,
        dbCostsOverride,
      );
      const quoteAsAtDate = resolveTenantLocalDateAndHour(
        now,
        tenantCfg.timeZone || 'Europe/London',
      ).localDate;

      const arrangementBasis = mapQuoteFeeBasisToArrangementBasis(
        input.feeBasis,
      );
      let validatedFeeArrangement:
        | {
            feeArrangementCapCategoryKey: string;
            feeArrangementPercent: number;
            feeArrangementCapBaseKey: string;
            feeArrangementCapBaseDescription: string;
            feeArrangementAppliedCapPercent: number;
            feeArrangementCapLevel: EffectiveFeeCapResolution['capLevel'];
          }
        | undefined;
      if (arrangementBasis) {
        const capCheck = await validateInTxFeeArrangementForRecord({
          ctx,
          feeBasis: arrangementBasis,
          workTypeSubcategoryId: input.workTypeSubcategoryId ?? null,
          practiceAreaId: input.practiceAreaId,
          submittedCapCategoryKey: input.feeArrangementCapCategoryKey,
          submittedPercent: input.feeArrangementPercent,
          submittedCapBaseKey: input.feeArrangementCapBaseKey,
          effectiveCostsConfig,
          asAtDate: quoteAsAtDate,
        });
        if (!capCheck.ok) {
          return {
            code: capCheck.code,
            message: capCheck.message,
            error: capCheck.message,
          };
        }
        validatedFeeArrangement = {
          feeArrangementCapCategoryKey: capCheck.resolution.capCategoryKey,
          feeArrangementPercent: capCheck.acceptedPercent,
          feeArrangementCapBaseKey: capCheck.resolution.capBaseKey,
          feeArrangementCapBaseDescription:
            capCheck.resolution.capBaseDescription,
          feeArrangementAppliedCapPercent:
            capCheck.resolution.appliedCapPercent,
          feeArrangementCapLevel: capCheck.resolution.capLevel,
        };
      }

      const rateOverrideRepo = getRateOverrideRepository();
      const targetClientId =
        clientType === 'existing' ? (linkedOrganisationId ?? linkedPersonId ?? null) : null;
      const targetClientType: ClientRateOverrideClientType | undefined = linkedOrganisationId
        ? 'organisation'
        : linkedPersonId
          ? 'person'
          : undefined;
      const resolvedRates = await rateOverrideRepo.resolveApplicableRates(ctx, {
        clientId: targetClientId,
        clientType: targetClientType ?? null,
        practiceAreaId: input.practiceAreaId,
        asAtDate: quoteAsAtDate,
        baseMatterCostsConfig: tenantCfg.matterCosts,
        fallbackRateCardConfig: effectiveCostsConfig,
        timeZone: tenantCfg.timeZone,
      });
      const rateGradeKey = input.rateGradeKey?.trim() || 'associate';
      const gradeRes =
        resolvedRates.grades[rateGradeKey] ?? resolvedRates.grades['associate'];
      const submittedHourly =
        input.feeBasis === 'Hourly rate with estimate' &&
        input.hourlyRateGbp !== undefined &&
        input.hourlyRateGbp !== null &&
        Number(input.hourlyRateGbp) > 0
          ? Number(input.hourlyRateGbp)
          : null;
      const effectiveHourlyRateGbp =
        input.feeBasis === 'Hourly rate with estimate'
          ? (submittedHourly ?? ((gradeRes?.rateGbp ?? resolvedRates.associateRateGbp) || null))
          : null;
      const hourlyMatchesResolved =
        effectiveHourlyRateGbp === null ||
        !gradeRes ||
        hourlyGbpMatchesMinorUnits(effectiveHourlyRateGbp, gradeRes.rateMinorUnits);
      const resolvedRateSource: Quote['rateSource'] =
        input.feeBasis === 'Hourly rate with estimate' && !hourlyMatchesResolved
          ? 'custom_override'
          : (gradeRes?.source ?? resolvedRates.dominantSource);
      const resolvedRateTier =
        resolvedRateSource === 'custom_override'
          ? undefined
          : (gradeRes?.tier ?? resolvedRates.dominantTier);

      const vatRatePercent = effectiveCostsConfig.vatRatePercent;
      const totals = calculateQuoteTotals(
        input.feeAmountExVat,
        input.vatOverridden ? input.vatAmount : null,
        disbursements,
        vatRatePercent,
      );

      const reference = await intakeRepo.allocateNextQuoteReference(ctx, now.getFullYear());
      const timeline: Quote['timeline'] = [
        {
          id: `QT-${Date.now()}-1`,
          kind: 'created',
          at: nowIso,
          byId: opts.byId,
          title: 'Quote created (v1)',
          detail: `${input.feeBasis} — £${totals.feeAmountExVat.toLocaleString('en-GB')} + VAT`,
        },
      ];
      if (markSent) {
        timeline.push({
          id: `QT-${Date.now()}-2`,
          kind: 'sent',
          at: nowIso,
          byId: opts.byId,
          title: 'Marked as sent',
          detail: `First follow-up scheduled for ${nextFollowUpDate}`,
        });
      }

      const created: Quote = {
        id: reference,
        reference,
        version: 1,
        status,
        clientType,
        linkedOrganisationId,
        linkedPersonId,
        prospectName,
        prospectOrganisationName,
        prospectEmail,
        prospectPhone,
        linkedEnquiryId: input.linkedEnquiryId || null,
        convertedMatterId: null,
        practiceAreaId: input.practiceAreaId,
        workTypeSubcategoryId: input.workTypeSubcategoryId || null,
        scope: input.scope.trim(),
        assumptions: (input.assumptions ?? '').trim(),
        feeBasis: input.feeBasis,
        feeAmountExVat: totals.feeAmountExVat,
        hourlyRateGbp: effectiveHourlyRateGbp,
        vatRatePercent,
        vatAmount: totals.vatOnFee,
        vatOverridden: Boolean(input.vatOverridden),
        disbursements,
        totalIncVat: totals.totalIncVat,
        capturedAt: nowIso,
        rateSource: resolvedRateSource,
        ...(resolvedRateTier !== undefined ? { rateTier: resolvedRateTier } : {}),
        rateAsAtDate: resolvedRates.asAtDate,
        rateCardId: resolvedRates.rateCardId,
        rateCardName: resolvedRates.rateCardName,
        rateGradeKey,
        rateProvenanceByGrade: resolvedRates.grades,
        ...(validatedFeeArrangement ?? {}),
        feeEarnerId,
        assignedTeamId,
        validUntil,
        followUpAfterDays,
        sentAt,
        nextFollowUpDate,
        outcomeAt: null,
        declineReason: null,
        followUps: [],
        versionHistory: [],
        timeline,
        createdById: opts.byId,
        createdAt: nowIso,
        updatedById: opts.byId,
        updatedAt: nowIso,
      };

      await intakeRepo.putQuote(ctx, created);
      writeAudit(null, {
        recordType: 'quote',
        recordId: created.id,
        action: 'create',
        field: markSent ? 'Quote created and marked as sent' : 'Quote saved as draft',
        oldValue: null,
        newValue: `${created.reference} — ${quoteClientDisplayName(created, people, organisations)}`,
        byId: opts.byId,
        at: nowIso,
      });
      await flushStagedAuditEntries(ctx);
      if (validatedFeeArrangement) {
        await appendTenantAuditEntries(ctx, [
          {
            recordType: 'quote',
            recordId: created.id,
            action: 'create',
            field: 'Fee arrangement & cap',
            oldValue: null,
            newValue: formatFeeArrangementAuditSummary(created),
            byId: opts.byId,
            at: nowIso,
          },
        ]);
      }
      return { quote: created };
    });
  }

  // Update existing quote inside transaction with live matter_costs VAT, rate & CFA/DBA cap check
  const wasSentNow = markSent && existing.status === 'Draft';
  const prevFeeSummary = formatFeeArrangementAuditSummary(existing);
  const updateTxOutcome = await intakeRepo.withTenantTransaction(ctx, async () => {
    const tenantCfg = getActiveTenantConfiguration();
    const dbCostsOverride =
      await getCatalogueRepository().getMatterCostsConfig<MatterCostsConfig>(ctx);
    const effectiveCostsConfig = resolveEffectiveMatterCostsConfig(
      tenantCfg,
      dbCostsOverride,
    );
    const quoteAsAtDate = resolveTenantLocalDateAndHour(
      now,
      tenantCfg.timeZone || 'Europe/London',
    ).localDate;

    const arrangementBasis = mapQuoteFeeBasisToArrangementBasis(
      input.feeBasis,
    );
    let validatedFeeArrangement:
      | {
          feeArrangementCapCategoryKey: string;
          feeArrangementPercent: number;
          feeArrangementCapBaseKey: string;
          feeArrangementCapBaseDescription: string;
          feeArrangementAppliedCapPercent: number;
          feeArrangementCapLevel: EffectiveFeeCapResolution['capLevel'];
        }
      | undefined;
    if (arrangementBasis) {
      const capCheck = await validateInTxFeeArrangementForRecord({
        ctx,
        feeBasis: arrangementBasis,
        workTypeSubcategoryId: input.workTypeSubcategoryId ?? null,
        practiceAreaId: input.practiceAreaId,
        submittedCapCategoryKey: input.feeArrangementCapCategoryKey,
        submittedPercent: input.feeArrangementPercent,
        submittedCapBaseKey: input.feeArrangementCapBaseKey,
        effectiveCostsConfig,
        asAtDate: quoteAsAtDate,
      });
      if (!capCheck.ok) {
        return {
          code: capCheck.code,
          message: capCheck.message,
          error: capCheck.message,
        };
      }
      validatedFeeArrangement = {
        feeArrangementCapCategoryKey: capCheck.resolution.capCategoryKey,
        feeArrangementPercent: capCheck.acceptedPercent,
        feeArrangementCapBaseKey: capCheck.resolution.capBaseKey,
        feeArrangementCapBaseDescription:
          capCheck.resolution.capBaseDescription,
        feeArrangementAppliedCapPercent:
          capCheck.resolution.appliedCapPercent,
        feeArrangementCapLevel: capCheck.resolution.capLevel,
      };
    }

    const existingVatRate =
      typeof existing.vatRatePercent === 'number' &&
      Number.isFinite(existing.vatRatePercent)
        ? existing.vatRatePercent
        : 20;
    const shouldRefreshVat = Boolean(input.refreshVatRate ?? opts.refreshVatRate);
    const vatRatePercent = shouldRefreshVat
      ? effectiveCostsConfig.vatRatePercent
      : existingVatRate;
    const shouldRefreshRates = Boolean(input.refreshRates) || !existing.rateSource;
    const rateGradeKey = input.rateGradeKey?.trim() || existing.rateGradeKey || 'associate';
    let nextHourlyRateGbp =
      input.feeBasis === 'Hourly rate with estimate'
        ? Math.max(0, Number(input.hourlyRateGbp) || 0) || null
        : null;
    if (shouldRefreshRates) {
      const quoteAsAtDate = resolveTenantLocalDateAndHour(
        now,
        tenantCfg.timeZone || 'Europe/London',
      ).localDate;
      const targetClientId =
        clientType === 'existing' ? (linkedOrganisationId ?? linkedPersonId ?? null) : null;
      const targetClientType: ClientRateOverrideClientType | undefined = linkedOrganisationId
        ? 'organisation'
        : linkedPersonId
          ? 'person'
          : undefined;
      const resolvedRates = await getRateOverrideRepository().resolveApplicableRates(ctx, {
        clientId: targetClientId,
        clientType: targetClientType ?? null,
        practiceAreaId: input.practiceAreaId,
        asAtDate: quoteAsAtDate,
        baseMatterCostsConfig: tenantCfg.matterCosts,
        fallbackRateCardConfig: effectiveCostsConfig,
        timeZone: tenantCfg.timeZone,
      });
      const gradeRes =
        resolvedRates.grades[rateGradeKey] ?? resolvedRates.grades['associate'];
      if (input.feeBasis === 'Hourly rate with estimate' && nextHourlyRateGbp === null) {
        nextHourlyRateGbp = (gradeRes?.rateGbp ?? resolvedRates.associateRateGbp) || null;
      }
      const hourlyMatchesResolved =
        nextHourlyRateGbp === null ||
        !gradeRes ||
        hourlyGbpMatchesMinorUnits(nextHourlyRateGbp, gradeRes.rateMinorUnits);
      existing.rateSource =
        input.feeBasis === 'Hourly rate with estimate' && !hourlyMatchesResolved
          ? 'custom_override'
          : (gradeRes?.source ?? resolvedRates.dominantSource);
      existing.rateTier =
        existing.rateSource === 'custom_override'
          ? undefined
          : (gradeRes?.tier ?? resolvedRates.dominantTier);
      existing.rateAsAtDate = resolvedRates.asAtDate;
      existing.rateCardId = resolvedRates.rateCardId;
      existing.rateCardName = resolvedRates.rateCardName;
      existing.rateGradeKey = rateGradeKey;
      existing.rateProvenanceByGrade = resolvedRates.grades;
    } else if (
      input.feeBasis === 'Hourly rate with estimate' &&
      nextHourlyRateGbp !== existing.hourlyRateGbp
    ) {
      const frozenGradeRes = existing.rateProvenanceByGrade?.[rateGradeKey];
      if (
        frozenGradeRes &&
        nextHourlyRateGbp !== null &&
        hourlyGbpMatchesMinorUnits(nextHourlyRateGbp, frozenGradeRes.rateMinorUnits)
      ) {
        existing.rateSource = frozenGradeRes.source;
        existing.rateTier = frozenGradeRes.tier;
      } else if (nextHourlyRateGbp !== null) {
        existing.rateSource = 'custom_override';
        existing.rateTier = undefined;
      }
      existing.rateGradeKey = rateGradeKey;
    }
    const totals = calculateQuoteTotals(
      input.feeAmountExVat,
      input.vatOverridden ? input.vatAmount : null,
      disbursements,
      vatRatePercent,
    );

    existing.clientType = clientType;
    existing.linkedOrganisationId = linkedOrganisationId;
    existing.linkedPersonId = linkedPersonId;
    existing.prospectName = prospectName;
    existing.prospectOrganisationName = prospectOrganisationName;
    existing.prospectEmail = prospectEmail;
    existing.prospectPhone = prospectPhone;
    existing.linkedEnquiryId =
      input.linkedEnquiryId !== undefined ? input.linkedEnquiryId || null : existing.linkedEnquiryId;
    existing.practiceAreaId = input.practiceAreaId;
    existing.workTypeSubcategoryId = input.workTypeSubcategoryId || null;
    existing.scope = input.scope.trim();
    existing.assumptions = (input.assumptions ?? '').trim();
    existing.feeBasis = input.feeBasis;
    existing.feeAmountExVat = totals.feeAmountExVat;
    existing.hourlyRateGbp = nextHourlyRateGbp;
    existing.vatRatePercent = vatRatePercent;
    existing.vatAmount = totals.vatOnFee;
    existing.vatOverridden = Boolean(input.vatOverridden);
    existing.disbursements = disbursements;
    existing.totalIncVat = totals.totalIncVat;
    existing.capturedAt = shouldRefreshVat
      ? nowIso
      : existing.capturedAt ?? existing.updatedAt ?? existing.createdAt;
    if (validatedFeeArrangement) {
      existing.feeArrangementCapCategoryKey =
        validatedFeeArrangement.feeArrangementCapCategoryKey;
      existing.feeArrangementPercent =
        validatedFeeArrangement.feeArrangementPercent;
      existing.feeArrangementCapBaseKey =
        validatedFeeArrangement.feeArrangementCapBaseKey;
      existing.feeArrangementCapBaseDescription =
        validatedFeeArrangement.feeArrangementCapBaseDescription;
      existing.feeArrangementAppliedCapPercent =
        validatedFeeArrangement.feeArrangementAppliedCapPercent;
      existing.feeArrangementCapLevel =
        validatedFeeArrangement.feeArrangementCapLevel;
    } else {
      delete existing.feeArrangementCapCategoryKey;
      delete existing.feeArrangementPercent;
      delete existing.feeArrangementCapBaseKey;
      delete existing.feeArrangementCapBaseDescription;
      delete existing.feeArrangementAppliedCapPercent;
      delete existing.feeArrangementCapLevel;
    }
    existing.feeEarnerId = feeEarnerId;
    existing.assignedTeamId = assignedTeamId;
    existing.validUntil = validUntil;
    existing.followUpAfterDays = followUpAfterDays;
    existing.updatedById = opts.byId;
    existing.updatedAt = nowIso;

    if (wasSentNow || markSent) {
      existing.status = 'Sent';
      existing.sentAt = nowIso;
      existing.nextFollowUpDate = toIsoDate(addDays(now, followUpAfterDays));
      existing.timeline.push({
        id: `QT-${Date.now()}-sent`,
        kind: 'sent',
        at: nowIso,
        byId: opts.byId,
        title: `v${existing.version} marked as sent`,
        detail: `Follow-up scheduled for ${existing.nextFollowUpDate}`,
      });
    } else {
      applyQuoteEffectiveLifecycle(existing, now, {
        appendExpiredTimeline: true,
      });
    }

    await intakeRepo.putQuote(ctx, existing);
    writeAudit(null, {
      recordType: 'quote',
      recordId: existing.id,
      action: 'update',
      field: wasSentNow ? 'Quote marked as sent' : 'Quote updated',
      oldValue: null,
      newValue: `${existing.reference} (v${existing.version})`,
      byId: opts.byId,
      at: nowIso,
    });
    await flushStagedAuditEntries(ctx);
    const nextFeeSummary = formatFeeArrangementAuditSummary(existing);
    if (
      (nextFeeSummary !== null || prevFeeSummary !== null) &&
      nextFeeSummary !== prevFeeSummary
    ) {
      await appendTenantAuditEntries(ctx, [
        {
          recordType: 'quote',
          recordId: existing.id,
          action: 'update',
          field: 'Fee arrangement & cap',
          oldValue: prevFeeSummary,
          newValue: nextFeeSummary ?? 'Standard fee basis (no CFA/DBA cap)',
          byId: opts.byId,
          at: nowIso,
        },
      ]);
    }
    return null;
  });
  if (updateTxOutcome) {
    return updateTxOutcome;
  }
  return { quote: existing };
  });
}

async function loadScopedQuoteForEdit(
  ctx: TenantContext,
  byId: string,
  quoteId: string,
  noPermMsg: string,
): Promise<
  | { ok: true; quote: Quote }
  | { ok: false; denied: ActionDenied & { error: string } }
> {
  const intakeRepo = getIntakeQuoteRepository();
  const [people, quote, teams, rbacConfig] = await Promise.all([
    loadStaffPeople(ctx),
    intakeRepo.getQuoteById<Quote>(ctx, quoteId, { includeRestricted: true }),
    getHrAndRbacRepository().listAllTeams<Team>(ctx),
    loadEffectiveTenantRbacConfig(ctx),
  ]);
  const actor = people.find((p) => p.id === byId) ?? null;
  if (
    !hasPersonPermission(actor, 'quote:edit', {
      allPeople: people,
      teams,
      config: { rbac: rbacConfig },
    })
  ) {
    return {
      ok: false,
      denied: { ...buildActionDenied('FORBIDDEN', noPermMsg), error: noPermMsg },
    };
  }
  if (!quote) {
    const msg = 'Quote not found.';
    return {
      ok: false,
      denied: { ...buildActionDenied('FORBIDDEN', msg), error: msg },
    };
  }
  const linkedEnq = quote.linkedEnquiryId
    ? await intakeRepo.getEnquiryById<Enquiry>(ctx, quote.linkedEnquiryId, {
        includeRestricted: true,
      })
    : null;
  const refMatterIds = Array.from(
    new Set(
      [quote.convertedMatterId, linkedEnq?.convertedMatterId].filter(
        (x): x is string => Boolean(x),
      ),
    ),
  );
  const refMatters =
    refMatterIds.length > 0
      ? await getMatterRepository().listMattersByIds<Matter>(ctx, refMatterIds, {
          includeRestricted: true,
        })
      : [];
  const visibility = buildRecordVisibility({ teams }, actor, {
    people,
    matters: refMatters,
    enquiries: linkedEnq ? [linkedEnq] : [],
    quotes: [quote],
    teams,
    hiddenMatterKeyDateIds: EMPTY_HIDDEN_KEY_DATE_IDS,
    rbacConfig,
  });
  if (!visibility.canViewQuote(quote)) {
    const msg = 'Quote not found.';
    return {
      ok: false,
      denied: { ...buildActionDenied('FORBIDDEN', msg), error: msg },
    };
  }
  return { ok: true, quote };
}

export async function markQuoteSentRecord(
  quoteId: string,
  byId: string,
): Promise<{ quote?: Quote; error?: string } & Partial<ActionDenied>> {
  return runWithAuditStagingScope(async () => {
  const ctx = resolveDefaultServiceTenantContext(null, byId);
  const intakeRepo = getIntakeQuoteRepository();
  const scoped = await loadScopedQuoteForEdit(
    ctx,
    byId,
    quoteId,
    'You do not have permission (quote:edit) to mark a quote as sent.',
  );
  if (!scoped.ok) return scoped.denied;
  const { quote } = scoped;

  const now = new Date();
  const nowIso = now.toISOString();
  const followUpDays = Math.max(1, quote.followUpAfterDays || 7);
  const nextFollowUpDate = toIsoDate(addDays(now, followUpDays));

  quote.status = 'Sent';
  quote.sentAt = nowIso;
  quote.nextFollowUpDate = nextFollowUpDate;
  quote.updatedAt = nowIso;
  quote.updatedById = byId;

  quote.timeline.push({
    id: `QT-${Date.now()}`,
    kind: 'sent',
    at: nowIso,
    byId,
    title: `v${quote.version} marked as sent`,
    detail: `First follow-up scheduled for ${nextFollowUpDate} (${followUpDays} days)`,
  });

  await intakeRepo.withTenantTransaction(ctx, async () => {
    await intakeRepo.putQuote(ctx, quote);
    writeAudit(null, {
      recordType: 'quote',
      recordId: quote.id,
      action: 'status-change',
      field: 'Mark as sent',
      oldValue: 'Draft',
      newValue: `Sent (follow-up due ${nextFollowUpDate})`,
      byId,
      at: nowIso,
    });
    await flushStagedAuditEntries(ctx);
  });

  return { quote };
  });
}

export async function logQuoteFollowUpRecord(
  quoteId: string,
  input: {
    method: ContactLogMethod;
    note: string;
    nextFollowUpDate: string | null;
  },
  byId: string,
): Promise<{ quote?: Quote; error?: string } & Partial<ActionDenied>> {
  return runWithAuditStagingScope(async () => {
  const ctx = resolveDefaultServiceTenantContext(null, byId);
  const intakeRepo = getIntakeQuoteRepository();
  const scoped = await loadScopedQuoteForEdit(
    ctx,
    byId,
    quoteId,
    'You do not have permission (quote:edit) to log quote follow-ups.',
  );
  if (!scoped.ok) return scoped.denied;
  const { quote } = scoped;
  if (!input.note?.trim()) {
    return { error: 'Please enter a follow-up note.' };
  }

  const now = new Date();
  const nowIso = now.toISOString();
  const todayYmd = toIsoDate(now);
  const nextDate = input.nextFollowUpDate || toIsoDate(addDays(now, quote.followUpAfterDays || 7));

  quote.followUps.unshift({
    id: `QFU-${Date.now()}`,
    at: nowIso,
    method: input.method,
    note: input.note.trim(),
    nextFollowUpDate: nextDate,
    byId,
  });

  quote.nextFollowUpDate = nextDate;
  if (quote.status === 'Follow-up due' && nextDate > todayYmd) {
    quote.status = 'Sent';
  }
  applyQuoteEffectiveLifecycle(quote, now, {
    appendExpiredTimeline: true,
  });
  quote.updatedAt = nowIso;
  quote.updatedById = byId;

  quote.timeline.push({
    id: `QT-${Date.now()}`,
    kind: 'follow_up',
    at: nowIso,
    byId,
    title: `Follow-up logged (${input.method})`,
    detail: `${input.note.trim()}${nextDate ? ` · Next follow-up: ${nextDate}` : ''}`,
  });

  await intakeRepo.withTenantTransaction(ctx, async () => {
    await intakeRepo.putQuote(ctx, quote);
    writeAudit(null, {
      recordType: 'quote',
      recordId: quote.id,
      action: 'contact-log',
      field: `Quote follow-up (${input.method})`,
      oldValue: null,
      newValue: input.note.trim(),
      byId,
      at: nowIso,
    });
    await flushStagedAuditEntries(ctx);
  });

  return { quote };
  });
}

export async function reviseQuoteRecord(
  quoteId: string,
  input: {
    feeBasis: QuoteFeeBasis;
    feeAmountExVat: number;
    hourlyRateGbp?: number | null;
    vatAmount?: number;
    vatOverridden?: boolean;
    disbursements?: QuoteDisbursement[];
    scope: string;
    assumptions?: string;
    validUntil?: string;
    followUpAfterDays?: number;
    revisionNote?: string;
    markAsSent?: boolean;
    refreshVatRate?: boolean;
    rateGradeKey?: string;
    refreshRates?: boolean;
    feeArrangementCapCategoryKey?: string;
    feeArrangementPercent?: number | null;
    feeArrangementCapBaseKey?: string;
  },
  byId: string,
): Promise<
  { quote?: Quote; error?: string } & Partial<Omit<ActionDenied, 'code'>> & {
    code?: ActionDenialCode | FeeCapErrorCode;
  }
> {
  return runWithAuditStagingScope(async () => {
  const ctx = resolveDefaultServiceTenantContext(null, byId);
  const intakeRepo = getIntakeQuoteRepository();
  const scoped = await loadScopedQuoteForEdit(
    ctx,
    byId,
    quoteId,
    'You do not have permission (quote:edit) to revise quotes.',
  );
  if (!scoped.ok) return scoped.denied;
  const { quote } = scoped;

  const now = new Date();
  const nowIso = now.toISOString();

  // Archive current version as Superseded
  if (!Number.isFinite(Number(input.feeAmountExVat)) || Number(input.feeAmountExVat) < 0) {
    return { error: 'Fee amount must be a non-negative number.' };
  }
  if (
    input.vatOverridden &&
    (!Number.isFinite(Number(input.vatAmount)) || Number(input.vatAmount) < 0)
  ) {
    return { error: 'VAT amount must be a non-negative number.' };
  }
  const normalizedDisbursements = normalizeQuoteDisbursements(
    input.disbursements ?? quote.disbursements,
  );
  if (!normalizedDisbursements.disbursements) {
    return { error: normalizedDisbursements.error ?? 'Invalid quote disbursements.' };
  }
  const disbursements = normalizedDisbursements.disbursements;

  const priorVatRatePercent =
    typeof quote.vatRatePercent === 'number' && Number.isFinite(quote.vatRatePercent)
      ? quote.vatRatePercent
      : 20;
  const priorCapturedAt = quote.capturedAt ?? quote.updatedAt ?? quote.createdAt;
  const prevFeeSummary = formatFeeArrangementAuditSummary(quote);

  const prevVersion = quote.version;
  const nextVersion = prevVersion + 1;

  const followUpAfterDays = Math.max(
    1,
    Number(input.followUpAfterDays) || quote.followUpAfterDays || 7,
  );

  const reviseTxOutcome = await intakeRepo.withTenantTransaction(ctx, async () => {
    const tenantCfg = getActiveTenantConfiguration();
    const dbCostsOverride =
      await getCatalogueRepository().getMatterCostsConfig<MatterCostsConfig>(ctx);
    const effectiveCostsConfig = resolveEffectiveMatterCostsConfig(
      tenantCfg,
      dbCostsOverride,
    );
    const quoteAsAtDate = resolveTenantLocalDateAndHour(
      now,
      tenantCfg.timeZone || 'Europe/London',
    ).localDate;

    const arrangementBasis = mapQuoteFeeBasisToArrangementBasis(
      input.feeBasis,
    );
    let validatedFeeArrangement:
      | {
          feeArrangementCapCategoryKey: string;
          feeArrangementPercent: number;
          feeArrangementCapBaseKey: string;
          feeArrangementCapBaseDescription: string;
          feeArrangementAppliedCapPercent: number;
          feeArrangementCapLevel: EffectiveFeeCapResolution['capLevel'];
        }
      | undefined;
    if (arrangementBasis) {
      const capCheck = await validateInTxFeeArrangementForRecord({
        ctx,
        feeBasis: arrangementBasis,
        workTypeSubcategoryId: quote.workTypeSubcategoryId ?? null,
        practiceAreaId: quote.practiceAreaId,
        submittedCapCategoryKey: input.feeArrangementCapCategoryKey,
        submittedPercent: input.feeArrangementPercent,
        submittedCapBaseKey: input.feeArrangementCapBaseKey,
        effectiveCostsConfig,
        asAtDate: quoteAsAtDate,
      });
      if (!capCheck.ok) {
        return {
          code: capCheck.code,
          message: capCheck.message,
          error: capCheck.message,
        };
      }
      validatedFeeArrangement = {
        feeArrangementCapCategoryKey: capCheck.resolution.capCategoryKey,
        feeArrangementPercent: capCheck.acceptedPercent,
        feeArrangementCapBaseKey: capCheck.resolution.capBaseKey,
        feeArrangementCapBaseDescription:
          capCheck.resolution.capBaseDescription,
        feeArrangementAppliedCapPercent:
          capCheck.resolution.appliedCapPercent,
        feeArrangementCapLevel: capCheck.resolution.capLevel,
      };
    }

    // Archive current version as Superseded only after fee arrangement validation passes
    quote.versionHistory.push({
      version: quote.version,
      status: 'Superseded',
      feeBasis: quote.feeBasis,
      feeAmountExVat: quote.feeAmountExVat,
      hourlyRateGbp: quote.hourlyRateGbp,
      vatRatePercent: priorVatRatePercent,
      vatAmount: quote.vatAmount,
      ...(quote.vatOverridden ? { vatOverridden: true } : {}),
      disbursements: structuredClone(quote.disbursements),
      totalIncVat: quote.totalIncVat,
      scope: quote.scope,
      assumptions: quote.assumptions,
      validUntil: quote.validUntil,
      createdAt: quote.createdAt,
      sentAt: quote.sentAt,
      supersededAt: nowIso,
      capturedAt: priorCapturedAt,
      byId,
      revisionNote: input.revisionNote?.trim() || undefined,
      ...(quote.rateSource ? { rateSource: quote.rateSource } : {}),
      ...(typeof quote.rateTier === 'number' ? { rateTier: quote.rateTier } : {}),
      ...(quote.rateAsAtDate ? { rateAsAtDate: quote.rateAsAtDate } : {}),
      ...(quote.rateCardId !== undefined ? { rateCardId: quote.rateCardId } : {}),
      ...(quote.rateCardName !== undefined ? { rateCardName: quote.rateCardName } : {}),
      ...(quote.rateGradeKey ? { rateGradeKey: quote.rateGradeKey } : {}),
      ...(quote.rateProvenanceByGrade
        ? { rateProvenanceByGrade: structuredClone(quote.rateProvenanceByGrade) }
        : {}),
      ...(quote.feeArrangementCapCategoryKey
        ? { feeArrangementCapCategoryKey: quote.feeArrangementCapCategoryKey }
        : {}),
      ...(quote.feeArrangementPercent !== undefined
        ? { feeArrangementPercent: quote.feeArrangementPercent }
        : {}),
      ...(quote.feeArrangementCapBaseKey
        ? { feeArrangementCapBaseKey: quote.feeArrangementCapBaseKey }
        : {}),
      ...(quote.feeArrangementCapBaseDescription
        ? {
            feeArrangementCapBaseDescription:
              quote.feeArrangementCapBaseDescription,
          }
        : {}),
      ...(quote.feeArrangementAppliedCapPercent !== undefined
        ? {
            feeArrangementAppliedCapPercent:
              quote.feeArrangementAppliedCapPercent,
          }
        : {}),
      ...(quote.feeArrangementCapLevel
        ? { feeArrangementCapLevel: quote.feeArrangementCapLevel }
        : {}),
    });

    const appliedVatRatePercent =
      input.refreshVatRate === false
        ? priorVatRatePercent
        : effectiveCostsConfig.vatRatePercent;

    let revisedHourlyRateGbp =
      input.feeBasis === 'Hourly rate with estimate'
        ? Math.max(0, Number(input.hourlyRateGbp) || 0) || null
        : null;
    const rateGradeKey = input.rateGradeKey?.trim() || quote.rateGradeKey || 'associate';
    if (input.refreshRates !== false) {
      const quoteAsAtDate = resolveTenantLocalDateAndHour(
        now,
        tenantCfg.timeZone || 'Europe/London',
      ).localDate;
      const targetClientId =
        quote.clientType === 'existing'
          ? (quote.linkedOrganisationId ?? quote.linkedPersonId ?? null)
          : null;
      const targetClientType: ClientRateOverrideClientType | undefined =
        quote.linkedOrganisationId
          ? 'organisation'
          : quote.linkedPersonId
            ? 'person'
            : undefined;
      const resolvedRates = await getRateOverrideRepository().resolveApplicableRates(ctx, {
        clientId: targetClientId,
        clientType: targetClientType ?? null,
        practiceAreaId: quote.practiceAreaId,
        asAtDate: quoteAsAtDate,
        baseMatterCostsConfig: tenantCfg.matterCosts,
        fallbackRateCardConfig: effectiveCostsConfig,
        timeZone: tenantCfg.timeZone,
      });
      const gradeRes =
        resolvedRates.grades[rateGradeKey] ?? resolvedRates.grades['associate'];
      if (input.feeBasis === 'Hourly rate with estimate' && revisedHourlyRateGbp === null) {
        revisedHourlyRateGbp = (gradeRes?.rateGbp ?? resolvedRates.associateRateGbp) || null;
      }
      const hourlyMatchesResolved =
        revisedHourlyRateGbp === null ||
        !gradeRes ||
        hourlyGbpMatchesMinorUnits(revisedHourlyRateGbp, gradeRes.rateMinorUnits);
      quote.rateSource =
        input.feeBasis === 'Hourly rate with estimate' && !hourlyMatchesResolved
          ? 'custom_override'
          : (gradeRes?.source ?? resolvedRates.dominantSource);
      quote.rateTier =
        quote.rateSource === 'custom_override'
          ? undefined
          : (gradeRes?.tier ?? resolvedRates.dominantTier);
      quote.rateAsAtDate = resolvedRates.asAtDate;
      quote.rateCardId = resolvedRates.rateCardId;
      quote.rateCardName = resolvedRates.rateCardName;
      quote.rateGradeKey = rateGradeKey;
      quote.rateProvenanceByGrade = resolvedRates.grades;
    } else if (
      input.feeBasis === 'Hourly rate with estimate' &&
      revisedHourlyRateGbp !== quote.hourlyRateGbp
    ) {
      quote.rateSource = 'custom_override';
      quote.rateTier = undefined;
      quote.rateGradeKey = rateGradeKey;
    }

    const totals = calculateQuoteTotals(
      input.feeAmountExVat,
      input.vatOverridden ? input.vatAmount : null,
      disbursements,
      appliedVatRatePercent,
    );

    quote.version = nextVersion;
    quote.feeBasis = input.feeBasis;
    quote.feeAmountExVat = totals.feeAmountExVat;
    quote.hourlyRateGbp = revisedHourlyRateGbp;
    quote.vatRatePercent = appliedVatRatePercent;
    quote.vatAmount = totals.vatOnFee;
    quote.vatOverridden = Boolean(input.vatOverridden);
    quote.disbursements = disbursements;
    quote.totalIncVat = totals.totalIncVat;
    quote.capturedAt = nowIso;
    if (validatedFeeArrangement) {
      quote.feeArrangementCapCategoryKey =
        validatedFeeArrangement.feeArrangementCapCategoryKey;
      quote.feeArrangementPercent =
        validatedFeeArrangement.feeArrangementPercent;
      quote.feeArrangementCapBaseKey =
        validatedFeeArrangement.feeArrangementCapBaseKey;
      quote.feeArrangementCapBaseDescription =
        validatedFeeArrangement.feeArrangementCapBaseDescription;
      quote.feeArrangementAppliedCapPercent =
        validatedFeeArrangement.feeArrangementAppliedCapPercent;
      quote.feeArrangementCapLevel =
        validatedFeeArrangement.feeArrangementCapLevel;
    } else {
      delete quote.feeArrangementCapCategoryKey;
      delete quote.feeArrangementPercent;
      delete quote.feeArrangementCapBaseKey;
      delete quote.feeArrangementCapBaseDescription;
      delete quote.feeArrangementAppliedCapPercent;
      delete quote.feeArrangementCapLevel;
    }
    quote.scope = input.scope.trim();
    quote.assumptions = (input.assumptions ?? '').trim();
    quote.validUntil = input.validUntil || toIsoDate(addDays(now, 30));
    quote.followUpAfterDays = followUpAfterDays;
    quote.outcomeAt = null;
    quote.outcomeNote = undefined;
    quote.declineReason = null;
    quote.declineNote = undefined;
    quote.updatedAt = nowIso;
    quote.updatedById = byId;

    const markSent = Boolean(input.markAsSent);
    if (markSent) {
      quote.status = 'Sent';
      quote.sentAt = nowIso;
      quote.nextFollowUpDate = toIsoDate(addDays(now, followUpAfterDays));
    } else {
      quote.status = 'Draft';
      quote.sentAt = null;
      quote.nextFollowUpDate = null;
    }

    quote.timeline.push({
      id: `QT-${Date.now()}-rev`,
      kind: 'revised',
      at: nowIso,
      byId,
      title: `Revised quote to v${nextVersion} (v${prevVersion} marked Superseded)`,
      detail:
        input.revisionNote?.trim() ||
        `Updated to ${quote.feeBasis} — £${quote.feeAmountExVat.toLocaleString('en-GB')} + VAT`,
    });

    if (markSent) {
      quote.timeline.push({
        id: `QT-${Date.now()}-sent`,
        kind: 'sent',
        at: nowIso,
        byId,
        title: `v${nextVersion} marked as sent`,
        detail: `Next follow-up scheduled for ${quote.nextFollowUpDate}`,
      });
    }

    await intakeRepo.putQuote(ctx, quote);
    writeAudit(null, {
      recordType: 'quote',
      recordId: quote.id,
      action: 'update',
      field: `Quote revised to v${nextVersion}`,
      oldValue: `v${prevVersion} (Superseded)`,
      newValue: `v${nextVersion} — £${quote.feeAmountExVat.toLocaleString('en-GB')} + VAT (${quote.status})`,
      byId,
      at: nowIso,
    });
    await flushStagedAuditEntries(ctx);
    const nextFeeSummary = formatFeeArrangementAuditSummary(quote);
    if (
      (nextFeeSummary !== null || prevFeeSummary !== null) &&
      nextFeeSummary !== prevFeeSummary
    ) {
      await appendTenantAuditEntries(ctx, [
        {
          recordType: 'quote',
          recordId: quote.id,
          action: 'update',
          field: 'Fee arrangement & cap',
          oldValue: prevFeeSummary,
          newValue: nextFeeSummary ?? 'Standard fee basis (no CFA/DBA cap)',
          byId,
          at: nowIso,
        },
      ]);
    }
    return null;
  });

  if (reviseTxOutcome) {
    return reviseTxOutcome;
  }
  return { quote };
  });
}

export async function recordQuoteOutcomeRecord(
  quoteId: string,
  input: {
    outcome: 'Accepted' | 'Declined';
    declineReason?: QuoteDeclineReason | null;
    note?: string;
  },
  byId: string,
): Promise<{ quote?: Quote; error?: string } & Partial<ActionDenied>> {
  return runWithAuditStagingScope(async () => {
  const ctx = resolveDefaultServiceTenantContext(null, byId);
  const intakeRepo = getIntakeQuoteRepository();
  const scoped = await loadScopedQuoteForEdit(
    ctx,
    byId,
    quoteId,
    'You do not have permission (quote:edit) to record a quote outcome.',
  );
  if (!scoped.ok) return scoped.denied;
  const { quote } = scoped;

  if (input.outcome === 'Declined') {
    if (!input.declineReason) {
      return { error: 'Please select a reason for declining the quote.' };
    }
    if (input.declineReason === 'Other' && !input.note?.trim()) {
      return { error: 'Please provide a note when selecting "Other" as the decline reason.' };
    }
  }

  const nowIso = new Date().toISOString();
  const prevStatus = quote.status;
  quote.status = input.outcome;
  quote.outcomeAt = nowIso;
  quote.nextFollowUpDate = null;
  quote.updatedAt = nowIso;
  quote.updatedById = byId;

  if (input.outcome === 'Accepted') {
    quote.outcomeNote = input.note?.trim() || undefined;
    quote.declineReason = null;
    quote.declineNote = undefined;
    quote.timeline.push({
      id: `QT-${Date.now()}`,
      kind: 'accepted',
      at: nowIso,
      byId,
      title: 'Outcome recorded: Accepted',
      detail: input.note?.trim() || 'Client accepted the quote.',
    });
  } else {
    quote.declineReason = input.declineReason!;
    quote.declineNote = input.note?.trim() || undefined;
    quote.timeline.push({
      id: `QT-${Date.now()}`,
      kind: 'declined',
      at: nowIso,
      byId,
      title: `Outcome recorded: Declined (${input.declineReason})`,
      detail: input.note?.trim() || undefined,
    });
  }

  await intakeRepo.withTenantTransaction(ctx, async () => {
    await intakeRepo.putQuote(ctx, quote);
    writeAudit(null, {
      recordType: 'quote',
      recordId: quote.id,
      action: 'status-change',
      field: 'Quote outcome',
      oldValue: prevStatus,
      newValue:
        input.outcome === 'Declined'
          ? `Declined · ${input.declineReason}${input.note?.trim() ? ` (${input.note.trim()})` : ''}`
          : `Accepted${input.note?.trim() ? ` (${input.note.trim()})` : ''}`,
      byId,
      at: nowIso,
    });
    await flushStagedAuditEntries(ctx);
  });

  return { quote };
  });
}

/**
 * Prepare a quote for conversion to a matter:
 * Ensures a Person and/or Organisation record exists for the client/prospect,
 * links them on the quote, and returns clientId & instructingContactId for /matters/new.
 */
export async function prepareQuoteConversionRecord(
  quoteId: string,
  byId: string,
): Promise<{
  ok: boolean;
  conflictBlocked?: boolean;
  conflictReasons?: string[];
  conflictWarnings?: string[];
  clientId?: string;
  instructingContactId?: string | null;
  quoteId?: string;
  enquiryId?: string | null;
  error?: string;
} & Partial<Omit<ActionDenied, 'ok'>>> {
  return runWithAuditStagingScope(async () => {
  const ctx = resolveDefaultServiceTenantContext(null, byId);
  const partyRepo = getPartyRepository();
  const matterRepo = getMatterRepository();
  const intakeRepo = getIntakeQuoteRepository();
  const [store, staffPeople, quoteDirect, teams, rbacConfig] = await Promise.all([
    loadTenantCatalogueStoreView(ctx),
    loadStaffPeople(ctx),
    intakeRepo.getQuoteById<Quote>(ctx, quoteId, { includeRestricted: true }),
    getHrAndRbacRepository().listAllTeams<Team>(ctx),
    loadEffectiveTenantRbacConfig(ctx),
  ]);
  const actor = staffPeople.find((p) => p.id === byId) ?? null;
  if (
    !hasPersonPermission(actor, 'matter:create', {
      allPeople: staffPeople,
      teams,
      config: { rbac: rbacConfig },
    })
  ) {
    const msg = 'You do not have permission (matter:create) to convert a quote to a matter.';
    return {
      ...buildActionDenied('FORBIDDEN', msg),
      ok: false,
      error: msg,
      conflictReasons: [msg],
    };
  }
  if (!quoteDirect) {
    return { ok: false, error: 'Quote not found.' };
  }
  const quote = quoteDirect;
  const linkedEnq = quote.linkedEnquiryId
    ? await intakeRepo.getEnquiryById<Enquiry>(ctx, quote.linkedEnquiryId, {
        includeRestricted: true,
      })
    : null;
  const refMatterIds = Array.from(
    new Set(
      [quote.convertedMatterId, linkedEnq?.convertedMatterId].filter(
        (x): x is string => Boolean(x),
      ),
    ),
  );
  const refMatters =
    refMatterIds.length > 0
      ? await matterRepo.listMattersByIds<Matter>(ctx, refMatterIds, {
          includeRestricted: true,
        })
      : [];
  const visibility = buildRecordVisibility(store, actor, {
    people: staffPeople,
    matters: refMatters,
    enquiries: linkedEnq ? [linkedEnq] : [],
    quotes: [quote],
    teams,
    hiddenMatterKeyDateIds: EMPTY_HIDDEN_KEY_DATE_IDS,
    rbacConfig,
  });
  if (!visibility.canViewQuote(quote)) {
    return { ok: false, error: 'Quote not found.' };
  }

  const now = new Date();
  const nowIso = now.toISOString();
  const today = toIsoDate(now);
  const actorName = actor ? personDisplayName(actor) : byId;
  const actorHasRiskView = hasPersonPermission(actor, 'risk:view', {
    allPeople: staffPeople,
    teams,
    config: { rbac: rbacConfig },
  });

  let personId = quote.linkedPersonId;
  let orgId = quote.linkedOrganisationId;

  // If linked to an enquiry that already has linkedPersonId / linkedOrganisationId, inherit if missing
  if (linkedEnq) {
    if (!personId && linkedEnq.linkedPersonId) personId = linkedEnq.linkedPersonId;
    if (!orgId && linkedEnq.linkedOrganisationId) orgId = linkedEnq.linkedOrganisationId;
  }

  const [existingOrgDirect, existingPersonDirect, referrerPersonDirect] =
    await Promise.all([
      orgId
        ? partyRepo.getOrganisationById<Organisation>(ctx, orgId)
        : Promise.resolve<Organisation | null>(null),
      personId
        ? partyRepo.getPersonById<Person>(ctx, personId)
        : Promise.resolve<Person | null>(null),
      linkedEnq?.referrerPersonId
        ? partyRepo.getPersonById<Person>(ctx, linkedEnq.referrerPersonId)
        : Promise.resolve<Person | null>(null),
    ]);

  const hasOrgName = Boolean(quote.prospectOrganisationName.trim());
  const hasPersonName = Boolean(quote.prospectName.trim());
  const existingOrg = existingOrgDirect ?? undefined;
  const existingPerson = existingPersonDirect ?? undefined;
  const clientOrgName = existingOrg?.legalName || quote.prospectOrganisationName.trim();
  const clientPersonName = existingPerson
    ? personDisplayName(existingPerson)
    : quote.prospectName.trim();

  const submittedParties: ConflictCheckParty[] = [];
  if (clientOrgName) {
    submittedParties.push({
      id: 'cp-client-1',
      name: clientOrgName,
      entityType: 'organisation',
      role: 'Client',
      linkedRecordId: orgId ?? null,
      isClientFixed: true,
    });
    if (clientPersonName) {
      submittedParties.push({
        id: 'cp-instructing-1',
        name: clientPersonName,
        entityType: 'person',
        role: 'Client contact',
        linkedRecordId: personId ?? null,
        isClientFixed: true,
      });
    }
  } else if (clientPersonName) {
    submittedParties.push({
      id: 'cp-client-1',
      name: clientPersonName,
      entityType: 'person',
      role: 'Client',
      linkedRecordId: personId ?? null,
      isClientFixed: true,
    });
  }

  const enqOtherPartyNames = (linkedEnq?.otherPartiesNamed ?? '')
    .split(/[,;/\n]+/)
    .map((s) => s.trim())
    .filter(Boolean);
  enqOtherPartyNames.forEach((opName, idx) => {
    submittedParties.push({
      id: `cp-party-${idx + 1}`,
      name: opName,
      entityType: 'organisation',
      role: 'Opponent',
      linkedRecordId: null,
    });
  });

  const nameParts = clientPersonName.split(/\s+/).filter(Boolean);
  const firstNameForSearch = existingPerson?.firstName ?? (nameParts[0] || '');
  const lastNameForSearch = existingPerson?.surname ?? nameParts.slice(1).join(' ');
  const searchEmail =
    quote.prospectEmail ||
    existingPerson?.emails[0]?.address ||
    existingOrg?.generalEmail ||
    '';
  const searchPhone =
    quote.prospectPhone ||
    existingPerson?.phones[0]?.number ||
    existingOrg?.mainPhone ||
    '';
  const graph = await loadFullConflictSearchGraph(
    ctx,
    {
      terms: [
        clientOrgName,
        clientPersonName,
        firstNameForSearch,
        lastNameForSearch,
        ...enqOtherPartyNames,
      ].filter(Boolean),
      emails: [searchEmail].filter(Boolean),
      phones: [searchPhone].filter(Boolean),
      postcodes: [
        existingOrg?.registeredAddress?.postcode ?? '',
        existingOrg?.billingAddress?.postcode ?? '',
        existingPerson?.addresses[0]?.postcode ?? '',
        linkedEnq?.address?.postcode ?? '',
      ].filter(Boolean),
      companyNumbers: [existingOrg?.companyNumber ?? ''].filter(Boolean),
      linkedPersonIds: [personId, linkedEnq?.referrerPersonId ?? null].filter(
        (x): x is string => Boolean(x),
      ),
      linkedOrganisationIds: [orgId].filter((x): x is string => Boolean(x)),
      excludeEnquiryId: quote.linkedEnquiryId ?? null,
    },
    byId,
    staffPeople,
    teams,
    rbacConfig,
  );
  const people = dedupeById([
    ...staffPeople,
    ...graph.people,
    ...(existingPerson ? [existingPerson] : []),
    ...(referrerPersonDirect ? [referrerPersonDirect] : []),
  ]);
  const organisations = dedupeById([
    ...graph.organisations,
    ...(existingOrg ? [existingOrg] : []),
  ]);
  const matters = graph.matters;
  const enquiries = graph.enquiries;
  const links = graph.links;

  const effectiveParties = buildEffectiveConflictParties({
    submittedParties,
    clientId: orgId || personId || null,
    instructingContactId: orgId ? personId : null,
    referrerContactId: linkedEnq?.referrerPersonId ?? null,
    people,
    organisations,
  });

  const rawMatterMatches = searchMatterConflicts(
    {
      currentMatterId: null,
      sourceEnquiryId: quote.linkedEnquiryId ?? null,
      parties: effectiveParties,
      canReviewConditions: actorHasRiskView,
      reviewerUserId: actorHasRiskView ? byId : null,
      reviewerDisplayName: actorHasRiskView ? actorName : null,
      reviewedAtIso: nowIso,
    },
    {
      matters,
      enquiries,
      people,
      organisations,
      links,
      tenantId: getActiveTenantConfiguration().tenantId,
      canView: graph.canViewMatter,
      canViewEnquiry: graph.canViewEnquiry,
    },
  );
  const reconciledMatches = reconcileServerConflictMatches({
    serverMatches: rawMatterMatches,
    canReviewConditions: actorHasRiskView,
    reviewerUserId: actorHasRiskView ? byId : null,
    reviewerDisplayName: actorHasRiskView ? actorName : null,
    reviewedAtIso: nowIso,
  });

  const prelimConflicts = runEnquiryConflictSearch(
    {
      firstName: firstNameForSearch,
      lastName: lastNameForSearch,
      callingOnBehalfOf: clientOrgName,
      otherPartiesNamed: linkedEnq?.otherPartiesNamed ?? '',
      email: searchEmail,
      phone: searchPhone,
      linkedPersonId: personId ?? null,
      linkedOrganisationId: orgId ?? null,
    },
    people,
    organisations,
    matters,
    store.values,
    enquiries.filter((e) => graph.canViewEnquiry(e)),
    quote.linkedEnquiryId ?? null,
    links,
    graph.canViewMatter,
    getActiveTenantConfiguration().tenantId,
  );

  const hasRestrictedMatch = hasUnapprovedRestrictedMatches(reconciledMatches, []);
  const declinedOrgAssessment = assessDeclinedOrganisation(
    organisations,
    existingOrg,
    clientOrgName,
  );
  const { existingOrgDeclined, hasDeclinedOrgNameMatch } = declinedOrgAssessment;
  const isConflictBlocked =
    existingOrgDeclined ||
    hasRestrictedMatch ||
    prelimConflicts.hasBlockingConflict;

  const totalMatchesCount = Math.max(
    reconciledMatches.length,
    prelimConflicts.allConflicts.length,
  );

  if (isConflictBlocked) {
    const reasons: string[] = [];
    if (declinedOrgAssessment.blockedReason) {
      reasons.push(declinedOrgAssessment.blockedReason);
    }
    if (hasRestrictedMatch) {
      reasons.push(
        'This matter must be referred to Risk because a match was found on a restricted record.',
      );
    }
    for (const hit of prelimConflicts.allConflicts.filter((h) => h.blocking || h.severity === 'high')) {
      if (!reasons.includes(hit.reason)) {
        reasons.push(hit.reason);
      }
    }
    if (reasons.length === 0) {
      reasons.push('This quote cannot convert until its conflict check is cleared or approved by Risk.');
    }

    const decisionSummary = `Potential conflict identified by ${actorName} on ${today} (${totalMatchesCount} ${totalMatchesCount === 1 ? 'match' : 'matches'})`;
    const decisionSnapshot = {
      outcome: 'Potential conflict' as const,
      decidedById: byId,
      decidedByName: actorName,
      decidedAt: nowIso,
      sourceRecordId: quote.id,
      matchesCount: totalMatchesCount,
      searchedSources: [...CONFLICT_SEARCHED_SOURCES],
      summary: decisionSummary,
    };

    // R254: Never overwrite an existing organisation's conflict status or conflictDecision.
    // Record the blocked decision on the quote audit trail (`conflict-decision`, R258).
    await intakeRepo.withTenantTransaction(ctx, async () => {
      writeAudit(store, {
        recordType: 'quote',
        recordId: quote.id,
        action: 'conflict-decision',
        field: 'Quote conversion blocked by conflict check',
        oldValue: null,
        newValue: `${decisionSummary} · ${reasons.join(' · ')}`,
        byId,
        at: nowIso,
        snapshot: decisionSnapshot,
      });
      await flushStagedAuditEntries(ctx);
    });

    return {
      ok: false,
      conflictBlocked: true,
      conflictReasons: reasons,
      error: reasons[0],
    };
  }

  const conflictWarnings = prelimConflicts.allConflicts
    .filter((h) => !h.blocking && h.severity !== 'high')
    .map((h) => h.reason);
  if (
    declinedOrgAssessment.nameMatchWarning &&
    !conflictWarnings.includes(declinedOrgAssessment.nameMatchWarning)
  ) {
    conflictWarnings.push(declinedOrgAssessment.nameMatchWarning);
  }

  // Conflict check passed: determine outcome status from search result, not a hard-coded Cleared
  const hasNonSelfMatches =
    hasDeclinedOrgNameMatch ||
    reconciledMatches.some(
      (m) => m.matchedRecordId !== orgId && m.matchedRecordId !== personId,
    ) ||
    prelimConflicts.allConflicts.length > 0;
  const outcomeLabel: 'Cleared' | 'Potential conflict' = hasNonSelfMatches
    ? 'Potential conflict'
    : 'Cleared';
  const decisionSummary = `${outcomeLabel} by ${actorName} on ${today} (${totalMatchesCount} ${totalMatchesCount === 1 ? 'match' : 'matches'})`;
  const conflictReference = `${quote.reference} · ${decisionSummary}`;
  const decisionSnapshot = {
    outcome: outcomeLabel,
    decidedById: byId,
    decidedByName: actorName,
    decidedAt: nowIso,
    sourceRecordId: quote.id,
    matchesCount: totalMatchesCount,
    searchedSources: [...CONFLICT_SEARCHED_SOURCES],
    summary: decisionSummary,
    ...(conflictWarnings.length > 0 ? { warnings: [...conflictWarnings] } : {}),
  };

  return intakeRepo.withTenantTransaction(ctx, async () => {
    const isBusinessQuote = Boolean(orgId || hasOrgName);
    const targetPersonRoleId = resolveListValueId(
      store.values,
      'person_role',
      isBusinessQuote ? 'client_contact' : 'private_client',
      isBusinessQuote ? 'Client contact' : 'Private client',
    );
    if (personId) {
      await ensurePersonHasRoleInTx(
        ctx,
        store,
        partyRepo,
        personId,
        targetPersonRoleId,
        byId,
        nowIso,
      );
    } else if (hasPersonName) {
      const parts = quote.prospectName.trim().split(/\s+/);
      const firstName = parts[0] || 'Client';
      const surname = parts.slice(1).join(' ') || 'Contact';

      const createdPerson = await savePersonRecord(
        {
          firstName,
          surname,
          emails: quote.prospectEmail
            ? [
                {
                  id: `em_${Date.now()}`,
                  address: quote.prospectEmail,
                  typeId: vid('email_type', hasOrgName ? 'Work' : 'Personal'),
                  isPrimary: true,
                },
              ]
            : [],
          phones: quote.prospectPhone
            ? [
                {
                  id: `ph_${Date.now()}`,
                  number: quote.prospectPhone,
                  typeId: vid('phone_type', 'Mobile'),
                },
              ]
            : [],
          relationshipStatusId: vid('relationship_status', 'Prospective'),
          relationshipRoleIds: [targetPersonRoleId],
          relationshipOwnerId: quote.feeEarnerId || byId,
          sourceId: vid('data_source', 'Manual entry'),
        },
        { byId, internalSystemStep: 'quote_conversion' },
      );
      if (!createdPerson.person) {
        throw new Error(
          createdPerson.message ||
            Object.values(createdPerson.errors ?? {}).join(' ') ||
            'Failed to create person during quote conversion.',
        );
      }
      personId = createdPerson.person.id;
    }

    let createdNewClientOrg = false;
    if (!orgId && hasOrgName) {
      const createdOrg = await saveOrganisationRecord(
        {
          legalName: quote.prospectOrganisationName.trim(),
          generalEmail: quote.prospectEmail,
          mainPhone: quote.prospectPhone,
          relationshipPartnerId: quote.feeEarnerId || byId,
          relationshipTypeIds: [vid('organisation_relationship_type', 'Prospect')],
          relationshipStatusId: vid('relationship_status', 'Prospective'),
          conflictStatusId: vid('conflict_status', outcomeLabel),
          conflictReference,
          reviewDate: today,
          reviewerId: byId,
        },
        { byId, internalSystemStep: 'quote_conversion' },
      );
      orgId = createdOrg.organisation.id;
      createdNewClientOrg = true;

      if (personId && orgId) {
        const personLinks = await partyRepo.listLinksForPerson<PersonOrganisationLink>(
          ctx,
          personId,
        );
        const linkExists = personLinks.some((l) => l.organisationId === orgId);
        if (!linkExists) {
          await createOrUpdateLink(
            {
              personId,
              organisationId: orgId,
              jobTitle: '',
              department: '',
              roleWithinOrganisation: 'Instructing contact',
              contactRoleIds: [vid('contact_role', 'Key relationship contact')],
              isPrimaryContact: true,
              isCurrent: true,
              startDate: today,
              endDate: null,
              contactStatusId: vid('contact_status', 'Active'),
            },
            byId,
            { internalSystemStep: true },
          );
        }
      }
    }

    // R254: Set conflict status and conflictDecision only on organisations created by this conversion.
    if (createdNewClientOrg && orgId) {
      const orgRecord = await partyRepo.getOrganisationById<Organisation>(ctx, orgId);
      if (orgRecord) {
        orgRecord.conflictStatusId = vid('conflict_status', outcomeLabel);
        orgRecord.conflictReference = conflictReference;
        orgRecord.reviewDate = today;
        orgRecord.reviewerId = byId;
        orgRecord.conflictDecision = decisionSnapshot;
        await partyRepo.putOrganisation(ctx, orgRecord);
        writeAudit(store, {
          recordType: 'organisation',
          recordId: orgId,
          action: 'conflict-decision',
          field: 'Conflict check decision recorded on quote conversion',
          oldValue: null,
          newValue: conflictReference,
          byId,
          at: nowIso,
          snapshot: decisionSnapshot,
        });
      }
    }

    writeAudit(store, {
      recordType: 'quote',
      recordId: quote.id,
      action: 'conflict-decision',
      field: 'Conflict check completed on quote conversion',
      oldValue: null,
      newValue: conflictReference,
      byId,
      at: nowIso,
      snapshot: decisionSnapshot,
    });

    quote.conflictDecision = decisionSnapshot;
    quote.linkedPersonId = personId;
    quote.linkedOrganisationId = orgId;
    quote.updatedAt = nowIso;
    quote.updatedById = byId;

    await intakeRepo.putQuote(ctx, quote);
    await flushStagedAuditEntries(ctx);

    const clientId = orgId || personId || '';
    const instructingContactId = orgId ? personId : personId;

    return {
      ok: true,
      clientId,
      instructingContactId,
      quoteId: quote.id,
      enquiryId: quote.linkedEnquiryId,
      ...(conflictWarnings.length > 0 ? { conflictWarnings } : {}),
    };
  });
  });
}

async function finalizeQuoteConversionToMatter(
  store: FirmStore,
  quoteId: string,
  matter: Matter,
  byId: string,
  now: string,
  ctx: TenantContext,
): Promise<void> {
  const intakeRepo = getIntakeQuoteRepository();
  const quote = await intakeRepo.getQuoteById<Quote>(ctx, quoteId, {
    includeRestricted: true,
  });
  if (!quote) return;

  const alreadyConverted = quote.convertedMatterId === matter.id;
  quote.status = 'Accepted';
  quote.convertedMatterId = matter.id;
  if (!quote.outcomeAt) quote.outcomeAt = now;
  quote.nextFollowUpDate = null;
  quote.updatedAt = now;
  quote.updatedById = byId;
  if (quote.conflictDecision) {
    matter.conflictDecision = quote.conflictDecision;
  }

  if (!alreadyConverted) {
    quote.timeline.push({
      id: `QT-${Date.now()}-conv`,
      kind: 'converted',
      at: now,
      byId,
      title: `Converted to matter ${matter.matterNumber === 'DRAFT' ? '(Draft)' : matter.matterNumber}`,
      detail: `${matter.title} (${matter.id})`,
    });

    writeAudit(store, {
      recordType: 'quote',
      recordId: quote.id,
      action: 'convert',
      field: 'Converted to matter',
      oldValue: quote.reference,
      newValue: `${matter.matterNumber} — ${matter.title} (${matter.id})`,
      byId,
      at: now,
    });
  }

  await intakeRepo.putQuote(ctx, quote);

  // Also close any linked enquiry and link it to the matter
  if (quote.linkedEnquiryId) {
    if (!matter.sourceEnquiryId) {
      matter.sourceEnquiryId = quote.linkedEnquiryId;
    }
    await finalizeEnquiryConversionToMatter(
      store,
      quote.linkedEnquiryId,
      matter,
      byId,
      now,
      ctx,
    );
  }
}

export async function saveMatterCostsConfig(
  config: MatterCostsConfig,
  byId: string,
): Promise<MatterCostsConfig> {
  const tenantCfg = getActiveTenantConfiguration();
  if (!tenantCfg.featureFlags?.enableMatterCostsGovernance) {
    throw new AuthorisationError({
      code: 'FORBIDDEN',
      message:
        'Forbidden: Matter costs governance is disabled for this tenant (featureFlags.enableMatterCostsGovernance is false).',
      tenantId: tenantCfg.tenantId,
      correlationId: `corr-costs-cfg-${randomUUID()}`,
      actorUserId: byId,
    });
  }
  if (config.vatRatePercent !== undefined) {
    if (
      typeof config.vatRatePercent !== 'number' ||
      !Number.isFinite(config.vatRatePercent) ||
      config.vatRatePercent < 0 ||
      config.vatRatePercent > 100
    ) {
      throw new Error('Standard VAT rate must be a percentage between 0% and 100%.');
    }
  }
  if (config.partnerSignOffThresholdGbp !== undefined) {
    if (
      typeof config.partnerSignOffThresholdGbp !== 'number' ||
      !Number.isFinite(config.partnerSignOffThresholdGbp) ||
      config.partnerSignOffThresholdGbp < 0
    ) {
      throw new Error('Partner cost sign-off threshold must be a non-negative GBP amount.');
    }
  }

  if (config.feeArrangementCaps !== undefined) {
    const capValidation = validateFirmFeeCapEntries(config.feeArrangementCaps);
    if (!capValidation.ok) {
      throw new FeeCapValidationError(
        capValidation.code,
        `${capValidation.code}: ${capValidation.message}`,
      );
    }
  }

  const ctx = resolveDefaultServiceTenantContext(null, byId);
  const catalogueRepo = getCatalogueRepository();
  const now = new Date().toISOString();
  let savedConfig!: MatterCostsConfig;
  await runWithAuditStagingScope(() =>
    catalogueRepo.withTenantTransaction(ctx, async () => {
      const previous = await catalogueRepo.getMatterCostsConfig<MatterCostsConfig>(ctx);
      const effectiveThreshold =
        config.partnerSignOffThresholdGbp !== undefined
          ? config.partnerSignOffThresholdGbp
          : previous?.partnerSignOffThresholdGbp ??
            tenantCfg.matterCosts.partnerSignOffThresholdGbp;
      const effectiveVatRate =
        config.vatRatePercent !== undefined
          ? config.vatRatePercent
          : previous?.vatRatePercent ?? tenantCfg.matterCosts.vatRatePercent;
      const effectiveFeeArrangementCaps =
        config.feeArrangementCaps !== undefined
          ? validateFirmFeeCapEntries(config.feeArrangementCaps)
          : null;
      if (effectiveFeeArrangementCaps && !effectiveFeeArrangementCaps.ok) {
        throw new FeeCapValidationError(
          effectiveFeeArrangementCaps.code,
          `${effectiveFeeArrangementCaps.code}: ${effectiveFeeArrangementCaps.message}`,
        );
      }
      const nextFeeCaps =
        effectiveFeeArrangementCaps && effectiveFeeArrangementCaps.ok
          ? effectiveFeeArrangementCaps.entries
          : previous?.feeArrangementCaps ??
            tenantCfg.matterCosts.feeArrangementCaps ??
            createDefaultFirmFeeArrangementCaps();
      const formatCapsSummary = (
        caps: MatterCostsConfig['feeArrangementCaps'] | undefined,
      ) =>
        (caps ?? [])
          .map((c) => `${c.capCategoryKey}=${c.maxPercent}%@${c.capBaseKey}`)
          .join(', ');
      const next: MatterCostsConfig = {
        ...config,
        partnerSignOffThresholdGbp: effectiveThreshold,
        vatRatePercent: effectiveVatRate,
        feeArrangementCaps: nextFeeCaps,
        updatedAt: now,
        updatedById: byId,
      };
      await catalogueRepo.putMatterCostsConfig(ctx, next, byId);
      savedConfig = next;
      writeAudit(null, {
        recordType: 'matter',
        recordId: 'FIRM-MATTER-COSTS-CONFIG',
        action: 'update',
        field: 'Matter Costs & Rates Table Config',
        oldValue: previous
          ? `${previous.clientProfileName} (${previous.rateSourceMode}, overrides=${previous.allowMatterRateOverrides}, threshold=£${previous.partnerSignOffThresholdGbp ?? 25000}, vat=${previous.vatRatePercent ?? 20}%, ${previous.rateCards?.length ?? 0} rate cards, feeCaps=[${formatCapsSummary(previous.feeArrangementCaps)}])`
          : null,
        newValue: `${next.clientProfileName} (${next.rateSourceMode}, overrides=${next.allowMatterRateOverrides}, threshold=£${next.partnerSignOffThresholdGbp}, vat=${next.vatRatePercent}%, ${next.rateCards.length} rate cards, feeCaps=[${formatCapsSummary(next.feeArrangementCaps)}])`,
        byId,
        at: now,
      });
      await flushStagedAuditEntries(ctx);
    }),
  );
  return savedConfig;
}

export async function syncMatterCostsRatesFromPms(
  byId: string,
  options?: { tenantCtx?: TenantContext | null; mfaVerified?: boolean },
): Promise<MatterCostsConfig> {
  const tenantCfg = getActiveTenantConfiguration();
  if (!tenantCfg.featureFlags?.enablePmsLiveRateSync) {
    throw new AuthorisationError({
      code: 'FORBIDDEN',
      message:
        'Forbidden: PMS live rate sync is disabled for this tenant (featureFlags.enablePmsLiveRateSync is false).',
      tenantId: tenantCfg.tenantId,
      correlationId: `corr-pms-rates-${randomUUID()}`,
      actorUserId: byId,
    });
  }
  const ctx = resolveDefaultServiceTenantContext(null, byId, options);
  const activeSession = getActiveActorSession();
  const [syncPeople, syncTeams] = await Promise.all([
    loadStaffPeople(ctx),
    getHrAndRbacRepository().listAllTeams<Team>(ctx),
  ]);
  const syncActor = syncPeople.find((p) => p.id === byId && !p.mergedIntoId) ?? null;
  const syncMfaVerified =
    options?.mfaVerified !== undefined
      ? options.mfaVerified === true
      : options?.tenantCtx
        ? options.tenantCtx.mfaVerified === true
        : activeSession?.personId === byId
          ? activeSession.mfaVerified === true
          : false;
  const syncTokenRoles = options?.tenantCtx?.actorRoles
    ? options.tenantCtx.actorRoles
    : activeSession?.personId === byId
      ? activeSession.tokenRoles
      : undefined;
  const syncPermSet = resolvePersonPermissionSet(syncActor, {
    allPeople: syncPeople,
    teams: syncTeams,
    tokenRoles: syncTokenRoles,
    tokenRolesActorId: byId,
    mfaVerified: syncMfaVerified,
    context:
      ctx.tenantId === tenantCfg.tenantId ? (options?.tenantCtx ?? ctx) : undefined,
  });
  if (!syncPermSet.permissions.has('admin:access')) {
    throw new AuthorisationError({
      code: 'FORBIDDEN',
      message:
        'Forbidden: Permission "admin:access" is required to sync PMS fee earner rates.',
      tenantId: ctx.tenantId,
      correlationId: ctx.correlationId,
      actorUserId: byId,
    });
  }
  if (syncPermSet.mfaPendingPermissions.has('admin:access')) {
    throw new AuthorisationError({
      code: 'MFA_REQUIRED',
      message:
        'MFA_REQUIRED: Multi-factor authentication (MFA) is required for administrative permission "admin:access".',
      tenantId: ctx.tenantId,
      correlationId: ctx.correlationId,
      actorUserId: byId,
    });
  }
  const catalogueRepo = getCatalogueRepository();
  let next!: MatterCostsConfig;
  await runWithAuditStagingScope(() =>
    catalogueRepo.withTenantTransaction(ctx, async () => {
      const [store, feeEarners, dbOverride] = await Promise.all([
        loadTenantCatalogueStoreView(ctx),
        getPmsRepository().listFeeEarnersOnly(ctx),
        catalogueRepo.getMatterCostsConfig<MatterCostsConfig>(ctx),
      ]);
      const base = resolveEffectiveMatterCostsConfig(
        tenantCfg,
        dbOverride ?? store.matterCostsConfig,
        {
          values: store.values,
          clientProfileCode: tenantCfg.tenantId,
          displayName: tenantCfg.displayName,
          primaryDomain: tenantCfg.branding.primaryDomain,
        },
      );
      const synced = syncRateCardsWithPmsFeeEarners(
        base,
        feeEarners,
        store.values,
      );
      const now = new Date().toISOString();
      next = {
        ...synced,
        pmsLinkActive: true,
        updatedAt: now,
        updatedById: byId,
      };
      await catalogueRepo.putMatterCostsConfig(ctx, next, byId);
      writeAudit(null, {
        recordType: 'matter',
        recordId: 'FIRM-MATTER-COSTS-CONFIG',
        action: 'update',
        field: 'PMS Rate Cards Sync',
        oldValue: base.pmsLastSyncedAt ?? 'Never',
        newValue: `Synced ${feeEarners.length} fee earner rates from PMS (${now})`,
        byId,
        at: now,
      });
      await flushStagedAuditEntries(ctx);
    }),
  );
  return next;
}

export async function resolveOrProvisionEntraEmployee(
  claims: EntraIdRawTokenClaims & Record<string, unknown>,
  options?: { correlationId?: string },
): Promise<{
  person: Person;
  verifiedToken: VerifiedOidcTokenClaims;
  rbacConfig: RbacConfiguration;
}> {
  const activeTenantConfig = getActiveTenantConfiguration();
  const activeTenantId = activeTenantConfig.tenantId;
  const correlationId = resolveRequestCorrelationId(
    options?.correlationId ??
      (getActiveActorSession() as { correlationId?: string } | null)
        ?.correlationId,
    'corr-entra-signin',
  );
  const defaultRbacConfig = getDefaultTenantRbacConfig(activeTenantId);
  const {
    verifiedToken,
  } = resolvePersonForEntraClaims({
    claims,
    people: [],
    teams: [],
    tenantId: activeTenantId,
    rbacConfig: defaultRbacConfig,
    primaryDomain: activeTenantConfig.branding.primaryDomain,
  });

  const now = new Date().toISOString();
  const oid = claims.oid?.trim() || verifiedToken.sub;
  const claimEmail = (
    claims.preferred_username ||
    claims.upn ||
    (claims.xms_edov === true ? claims.email : '') ||
    ''
  ).trim();
  const signInCtx = resolveCurrentTenantContext(
    createSignInActorFromVerifiedOidcToken(verifiedToken, {
      oid,
      email:
        verifiedToken.email ||
        `${verifiedToken.sub}@${activeTenantConfig.branding.primaryDomain}`,
      correlationId,
    }),
    activeTenantConfig,
  );
  const hrRepo = getHrAndRbacRepository();
  const [prelimPeople, prelimTeams, dbRbacOverride] = await Promise.all([
    loadStaffPeople(signInCtx),
    hrRepo.listAllTeams<Team>(signInCtx),
    hrRepo.getRbacConfigOverride<RbacConfiguration>(signInCtx),
  ]);
  const rbacConfig = await loadEffectiveTenantRbacConfig(
    signInCtx,
    dbRbacOverride,
  );
  if (claimEmail) {
    await getPartyRepository().findActivePeopleByEmail(signInCtx, claimEmail);
  }
  const {
    ambiguousEmailMatchPersonIds,
    refusedPrivilegedEmailLinkPersonId,
  } = resolvePersonForEntraClaims({
    claims,
    people: prelimPeople,
    teams: prelimTeams,
    tenantId: activeTenantId,
    rbacConfig,
    primaryDomain: activeTenantConfig.branding.primaryDomain,
  });
  const authorityMode = rbacConfig.identityMapping?.authorityMode ?? 'hybrid';

  if (refusedPrivilegedEmailLinkPersonId) {
    await appendTenantAuditEntries(signInCtx, [
      {
        recordType: 'person',
        recordId: refusedPrivilegedEmailLinkPersonId,
        action: 'entra-link',
        field: 'Entra ID Email Link Refused',
        oldValue: 'unlinked',
        newValue: `Refused automatic email link for privileged employee ${refusedPrivilegedEmailLinkPersonId} (correlationId=${correlationId})`,
        byId: 'system',
        at: now,
      },
    ]);
    console.warn(
      JSON.stringify({
        event: 'ENTRA_EMAIL_LINK_PRIVILEGED_REFUSED',
        tenantId: activeTenantId,
        correlationId,
        personId: refusedPrivilegedEmailLinkPersonId,
      }),
    );
    throw new Error('Your account needs to be linked by an administrator.');
  }

  if (ambiguousEmailMatchPersonIds && ambiguousEmailMatchPersonIds.length > 1) {
    await appendTenantAuditEntries(signInCtx, [
      {
        recordType: 'person',
        recordId: ambiguousEmailMatchPersonIds[0]!,
        action: 'entra-link',
        field: 'Entra ID Email Link Ambiguous',
        oldValue: 'unlinked',
        newValue: `Refused automatic email link across ${ambiguousEmailMatchPersonIds.length} unbound employees (${ambiguousEmailMatchPersonIds.join(', ')}; correlationId=${correlationId})`,
        byId: 'system',
        at: now,
      },
    ]);
    console.warn(
      JSON.stringify({
        event: 'ENTRA_EMAIL_LINK_AMBIGUOUS',
        tenantId: activeTenantId,
        correlationId,
        candidateCount: ambiguousEmailMatchPersonIds.length,
      }),
    );
    throw new Error('Your account needs to be linked by an administrator.');
  }

  return runWithAuditStagingScope(async () => {
    const partyRepo = getPartyRepository();
    const [people, teams] = await Promise.all([
      loadStaffPeople(signInCtx),
      hrRepo.listAllTeams<Team>(signInCtx),
    ]);
    const {
      person: matchedPerson,
      matchedByEmailOnly,
    } = resolvePersonForEntraClaims({
      claims,
      people,
      teams,
      tenantId: activeTenantId,
      rbacConfig,
      primaryDomain: activeTenantConfig.branding.primaryDomain,
    });

    if (matchedPerson) {
      const prevOid = matchedPerson.entraObjectId?.trim() || null;
      const isFirstEmailLink = Boolean(matchedByEmailOnly && !prevOid && oid);
      await partyRepo.withTenantTransaction(signInCtx, async () => {
        if (isFirstEmailLink && oid) {
          matchedPerson.entraObjectId = oid;
          writeAudit(null, {
            recordType: 'person',
            recordId: matchedPerson.id,
            action: 'entra-link',
            field: 'Entra ID Email Link',
            oldValue: 'unlinked',
            newValue: `Linked employee ${matchedPerson.id} on first verified-domain sign-in`,
            byId: matchedPerson.id,
            at: now,
          });
          console.info(
            JSON.stringify({
              event: 'ENTRA_EMAIL_LINK_BOUND',
              tenantId: activeTenantId,
              correlationId,
              personId: matchedPerson.id,
            }),
          );
        }
        if (authorityMode === 'token_only') {
          matchedPerson.roles = [...verifiedToken.roles];
          matchedPerson.appRole = matchedPerson.roles.includes('admin')
            ? 'admin'
            : matchedPerson.roles.length > 0
              ? 'fee_earner'
              : null;
          if (matchedPerson.roles.length === 0) {
            matchedPerson.employeeRoleId = null;
          } else if (matchedPerson.roles.includes('admin')) {
            matchedPerson.employeeRoleId = 'employee_role.system_administrator';
          }
        }
        matchedPerson.updatedAt = now;
        await partyRepo.putPerson(signInCtx, matchedPerson);
        writeAudit(null, {
          recordType: 'person',
          recordId: matchedPerson.id,
          action: 'update',
          field: 'Entra ID OIDC Sign-In',
          oldValue: prevOid ? 'bound' : 'unlinked',
          newValue: `personId=${matchedPerson.id}; roles=${verifiedToken.roles.join(',') || 'none'}; mfa=${verifiedToken.mfaVerified}; correlationId=${correlationId}`,
          byId: matchedPerson.id,
          at: now,
        });
        await flushStagedAuditEntries(signInCtx);
      });
      return { person: matchedPerson, verifiedToken, rbacConfig };
    }

    // Provision a linked employee record for this authenticated Entra user (R52: no default 'admin' or hardcoded 'DEPT-EXEC')
    const rawName =
      (typeof claims.name === 'string' && claims.name.trim()) ||
      claimEmail.split('@')[0] ||
      'Entra User';
    const nameParts = rawName.split(/\s+/).filter(Boolean);
    const firstName = nameParts[0] || 'Entra';
    const surname = nameParts.length > 1 ? nameParts.slice(1).join(' ') : 'User';

    const defaultRoleKeys = rbacConfig.identityMapping?.defaultRoleKeys ?? [];
    const mappedRoles =
      verifiedToken.roles.length > 0
        ? [...verifiedToken.roles]
        : [...defaultRoleKeys];
    const isAdmin = mappedRoles.includes('admin');
    const isPartner =
      mappedRoles.includes('managing_partner') || mappedRoles.includes('partner');

    let newEmployee!: Person;
    await partyRepo.withTenantTransaction(signInCtx, async () => {
      const newId = await partyRepo.allocateNextPersonId(signInCtx);
      newEmployee = {
        id: newId,
        recordType: 'person',
        recordOwnerId: newId,
        recordStatusId: 'person_record_status.active',
        createdById: newId,
        createdAt: now,
        updatedById: newId,
        updatedAt: now,
        sourceId: null,
        lastVerifiedAt: now,
        tags: ['entra-id'],
        duplicateStatusId: 'duplicate_status.none',
        notDuplicateOf: [],
        possibleMatchIds: [],
        mergedIntoId: null,
        lastInteractionAt: now,
        customFields: {},
        titleId: null,
        firstName,
        middleNames: '',
        surname,
        preferredName: '',
        dateOfBirth: null,
        otherNames: [],
        jobTitle: isAdmin
          ? 'System Administrator (Entra ID)'
          : isPartner
            ? 'Partner (Entra ID)'
            : mappedRoles.length > 0
              ? 'Solicitor (Entra ID)'
              : 'Unassigned Employee (Entra ID)',
        emails: claimEmail
          ? [
              {
                id: `em-${newId}-1`,
                address: claimEmail,
                typeId: 'email_type.work',
                isPrimary: true,
              },
            ]
          : [],
        phones: [],
        preferredContactMethodId: null,
        preferredLanguageId: null,
        addresses: [],
        website: '',
        relationshipOwnerId: null,
        relationshipStatusId: null,
        relationshipStandingId: null,
        relationshipRoleIds: [],
        originId: null,
        firstKnownAt: now.slice(0, 10),
        engagementLevelId: null,
        interests: '',
        relationshipNotes: '',
        marketingConsentId: null,
        consentRecord: '',
        verificationStatusId: null,
        verifiedAt: null,
        verificationMethodId: null,
        verificationReviewerId: null,
        riskReferences: '',
        isEmployee: true,
        employeeRoleId: isAdmin
          ? 'employee_role.system_administrator'
          : isPartner
            ? 'employee_role.partner'
            : mappedRoles.length > 0
              ? 'employee_role.solicitor'
              : null,
        departmentId: null,
        appRole: isAdmin ? 'admin' : mappedRoles.length > 0 ? 'fee_earner' : null,
        roles: mappedRoles,
        entraObjectId: oid,
      };

      await partyRepo.putPerson(signInCtx, newEmployee);
      writeAudit(null, {
        recordType: 'person',
        recordId: newEmployee.id,
        action: 'create',
        field: 'Entra ID OIDC Provisioned Employee',
        oldValue: null,
        newValue: `personId=${newEmployee.id}; roles=${mappedRoles.join(',') || 'none'}; mfa=${verifiedToken.mfaVerified}; correlationId=${correlationId}`,
        byId: newEmployee.id,
        at: now,
      });
      await flushStagedAuditEntries(signInCtx);
    });

    return { person: newEmployee, verifiedToken, rbacConfig };
  });
}

// ============================================================================
// Key Dates & Limitation Module Service Functions (§1–§9)
// ============================================================================

function resolveActorFromPeopleForKeyDates(
  people: readonly Person[],
  byId: string,
): Person | null {
  if (!byId || !byId.trim()) return null;
  return (
    people.find((p) => p.id === byId && p.isEmployee && !p.mergedIntoId) ??
    null
  );
}

async function resolveKeyDatesActorAndData(
  store: FirmStore | null,
  byId: string,
  options?: {
    tenantCtx?: TenantContext | null;
    matterId?: string | null;
    includeVisibleMatters?: boolean;
  },
): Promise<{
  ctx: TenantContext;
  actor: Person | null;
  people: Person[];
  matters: Matter[];
  teams: Team[];
  rbacOptions: ResolvePersonPermissionsOptions;
  personRbacOptions: ResolvePersonPermissionsOptions;
} | null> {
  if (!byId || !byId.trim()) return null;
  let prelimCtx: TenantContext;
  try {
    prelimCtx = resolveDefaultServiceTenantContext(store, null, {
      tenantCtx: options?.tenantCtx,
    });
  } catch {
    return null;
  }
  const [people, teams, rbacConfig] = await Promise.all([
    loadStaffPeople(prelimCtx),
    getHrAndRbacRepository().listAllTeams<Team>(prelimCtx),
    loadEffectiveTenantRbacConfig(prelimCtx),
  ]);
  const actor = resolveActorFromPeopleForKeyDates(people, byId);
  const activeSession = getActiveActorSession();
  const tokenRoles =
    actor &&
    activeSession &&
    activeSession.tenantId === prelimCtx.tenantId &&
    activeSession.personId === actor.id
      ? activeSession.tokenRoles
      : undefined;
  const personRbacOptions: ResolvePersonPermissionsOptions = {
    allPeople: people,
    teams,
    config: { rbac: rbacConfig },
    tenantId: prelimCtx.tenantId,
  };
  const baseRbacOptions: ResolvePersonPermissionsOptions = {
    ...personRbacOptions,
    tokenRoles,
    context: prelimCtx,
    tokenRolesActorId: actor?.id,
  };
  if (!actor) {
    return {
      ctx: prelimCtx,
      actor: null,
      people,
      matters: [],
      teams,
      rbacOptions: baseRbacOptions,
      personRbacOptions,
    };
  }
  const ctx = resolveDefaultServiceTenantContext(store, actor.id, {
    tenantCtx: options?.tenantCtx,
  });
  const finalRbacOptions: ResolvePersonPermissionsOptions = {
    ...baseRbacOptions,
    context: ctx,
    tokenRolesActorId: actor.id,
    tenantId: ctx.tenantId,
  };
  let matters: Matter[] = [];
  if (options?.matterId?.trim()) {
    const m = await getMatterRepository().getMatterById<Matter>(
      ctx,
      options.matterId.trim(),
      { includeRestricted: true },
    );
    if (m) matters = [m];
  } else if (options?.includeVisibleMatters) {
    const hasRestrictedAccess = hasPersonPermission(
      actor,
      'matter:restricted:access',
      finalRbacOptions,
    );
    matters = await getMatterRepository().listVisibleMatters<Matter>(ctx, {
      viewerId: actor.id,
      hasRestrictedMatterAccess: hasRestrictedAccess,
    });
  }
  return {
    ctx,
    actor,
    people,
    matters,
    teams,
    rbacOptions: finalRbacOptions,
    personRbacOptions: {
      ...personRbacOptions,
      tenantId: ctx.tenantId,
    },
  };
}

function assertKeyDatesModuleEnabled(
  config: KeyDatesConfig,
): { ok: false; error: string } | null {
  if (!config.enabled) {
    return {
      ok: false,
      error:
        'KEY_DATES_MODULE_DISABLED: The Key Dates & Limitation module is disabled for this tenant.',
    };
  }
  return null;
}

function resolvePrelimKeyDatesTenantContext(
  byId: string,
  options?: { tenantCtx?: TenantContext | null },
): TenantContext | null {
  if (!byId || !byId.trim()) return null;
  try {
    return resolveDefaultServiceTenantContext(null, null, {
      tenantCtx: options?.tenantCtx,
    });
  } catch {
    return null;
  }
}

const CALENDAR_SYNC_WARNING_MESSAGE =
  'Key date changes were saved, but Outlook calendar synchronisation failed and is queued for retry (see Compliance exceptions).';

async function acquireKeyDateScopeAdvisoryLock(
  ctx: TenantContext,
  scope: {
    matterId?: string | null;
    enquiryId?: string | null;
    keyDateTypeId: string;
  },
): Promise<void> {
  const scopeKey = scope.matterId
    ? `matter:${scope.matterId}`
    : scope.enquiryId
      ? `enquiry:${scope.enquiryId}`
      : null;
  if (!scopeKey) return;
  await getKeyDateRepository().acquireKeyDateTypeScopeLock(
    ctx,
    scopeKey,
    scope.keyDateTypeId,
  );
}

async function runPostCommitKeyDateCalendarSync(params: {
  ctx: TenantContext;
  config?: KeyDatesConfig;
  nowIso: string;
  existingSyncs?: KeyDateCalendarSync[];
  items: Array<{ keyDate: KeyDate; matter: Matter | null; enquiry: Enquiry | null }>;
  adapter?: GraphCalendarAdapter;
  leaseTtlMs?: number;
}): Promise<{ calendarSyncWarning?: string }> {
  if (params.items.length === 0) return {};
  const keyDateRepo = getKeyDateRepository();
  const matterRepo = getMatterRepository();
  const intakeRepo = getIntakeQuoteRepository();
  const uniqueKeyDateIds = Array.from(
    new Set(params.items.map((item) => item.keyDate.id)),
  );
  const leaseTtlMs = params.leaseTtlMs ?? 30_000;
  const failures: Array<{ keyDateId: string; attempts: number; error: string }> = [];
  const adapterIsConfigured =
    Boolean(params.adapter) &&
    !(
      params.adapter instanceof ManagedIdentityGraphCalendarAdapter &&
      !params.adapter.isConfigured
    );
  const deleteDisplacedEvents = async (
    events: ReadonlyArray<{ target: string; eventId: string }>,
  ): Promise<void> => {
    if (!adapterIsConfigured || !params.adapter || events.length === 0) return;
    for (const ext of events) {
      try {
        await params.adapter.deleteEvent({
          target: ext.target,
          eventId: ext.eventId,
        });
      } catch {
        // Best-effort cleanup of displaced external calendar events after lease loss or skew
      }
    }
  };

  for (const keyDateId of uniqueKeyDateIds) {
    const maxAttempts = 3;
    const myLeaseToken = randomUUID();
    let completed = false;
    const observedExternalEvents: Array<{ target: string; eventId: string }> = [];

    for (let attempt = 1; attempt <= maxAttempts; attempt += 1) {
      let claimedLeaseInTx1 = false;
      try {
        // Short TX 1 (R607, R627): claim single-flight sync lease and read latest committed state before Graph HTTP
        let tx1:
          | {
              latestKd: KeyDate;
              latestSync: KeyDateCalendarSync;
              latestMatter: Matter | null;
              latestEnquiry: Enquiry | null;
              latestConfig: KeyDatesConfig;
            }
          | null = null;
        let skippedByActiveLease = false;

        for (let leaseWait = 0; leaseWait <= 2; leaseWait += 1) {
          const claimAttempt = await keyDateRepo.withTenantTransaction(
            params.ctx,
            async () => {
              const { keyDate: latestKd, calendarSync: latestSync } =
                await keyDateRepo.readKeyDateAndCalendarSyncForUpdate(
                  params.ctx,
                  keyDateId,
                );
              if (!latestKd) {
                return { status: 'missing' as const };
              }
              const nowMs = Date.now();
              const activeOtherLease =
                latestSync?.state === 'syncing' &&
                Boolean(latestSync.leaseToken) &&
                latestSync.leaseToken !== myLeaseToken &&
                Boolean(latestSync.leaseExpiresAt) &&
                Date.parse(latestSync.leaseExpiresAt!) > nowMs;
              if (activeOtherLease) {
                return { status: 'busy' as const };
              }

              const leaseExpiresAt = new Date(nowMs + leaseTtlMs).toISOString();
              const claimedSync: KeyDateCalendarSync = {
                keyDateId,
                state: 'syncing',
                externalEvents: latestSync?.externalEvents ?? [],
                ...(latestSync?.lastSyncedAt
                  ? { lastSyncedAt: latestSync.lastSyncedAt }
                  : {}),
                ...(latestSync?.lastError ? { lastError: latestSync.lastError } : {}),
                attempts: latestSync?.attempts ?? 0,
                leaseToken: myLeaseToken,
                leaseExpiresAt,
              };
              const savedClaim = await keyDateRepo.putCalendarSync(
                params.ctx,
                claimedSync,
              );

              const [latestMatter, latestEnquiry, latestConfig] = await Promise.all([
                latestKd.matterId
                  ? matterRepo.getMatterById<Matter>(params.ctx, latestKd.matterId, {
                      includeRestricted: true,
                    })
                  : Promise.resolve(null),
                latestKd.enquiryId
                  ? intakeRepo.getEnquiryById<Enquiry>(params.ctx, latestKd.enquiryId, {
                      includeRestricted: true,
                    })
                  : Promise.resolve(null),
                getKeyDatesConfig({ ctx: params.ctx }),
              ]);
              return {
                status: 'claimed' as const,
                latestKd,
                latestSync: savedClaim,
                latestMatter: latestMatter ?? null,
                latestEnquiry: latestEnquiry ?? null,
                latestConfig,
              };
            },
          );

          if (claimAttempt.status === 'missing') {
            completed = true;
            break;
          }
          if (claimAttempt.status === 'busy') {
            if (leaseWait < 2) {
              await new Promise((r) => setTimeout(r, 25));
              continue;
            }
            skippedByActiveLease = true;
            completed = true;
            break;
          }
          tx1 = claimAttempt;
          claimedLeaseInTx1 = true;
          break;
        }

        if (skippedByActiveLease || !tx1) {
          completed = true;
          break;
        }

        const observedVersion = tx1.latestKd.version;
        const baseSync: KeyDateCalendarSync = structuredClone(tx1.latestSync);
        if (observedExternalEvents.length > 0) {
          const mergedMap = new Map(
            baseSync.externalEvents.map((e) => [e.target, e.eventId]),
          );
          for (const ext of observedExternalEvents) {
            if (!mergedMap.has(ext.target)) {
              mergedMap.set(ext.target, ext.eventId);
            }
          }
          baseSync.externalEvents = Array.from(mergedMap.entries()).map(
            ([target, eventId]) => ({ target, eventId }),
          );
        }

        // Run Graph call outside any database transaction or lock (R607, R617)
        let updatedSync: KeyDateCalendarSync;
        try {
          const workingSyncs = [baseSync];
          updatedSync = await syncKeyDateToOutlookCalendar({
            keyDate: tx1.latestKd,
            config: tx1.latestConfig,
            matter: tx1.latestMatter,
            enquiry: tx1.latestEnquiry,
            calendarSyncs: workingSyncs,
            ...(params.adapter ? { adapter: params.adapter } : {}),
            nowIso: params.nowIso,
          });
        } catch (graphErr) {
          updatedSync = {
            ...baseSync,
            state: 'failed',
            lastError: sanitizeCalendarSyncError(graphErr),
            attempts: (baseSync.attempts ?? 0) + 1,
          };
        }

        for (const ext of updatedSync.externalEvents) {
          if (
            !observedExternalEvents.some(
              (e) => e.target === ext.target && e.eventId === ext.eventId,
            )
          ) {
            observedExternalEvents.push(ext);
          }
        }

        // Short TX 2 (R607, R627): verify lease ownership & key date version before committing sync state
        const tx2Result = await keyDateRepo.withTenantTransaction(params.ctx, async () => {
          const { keyDate: recheckedKd, calendarSync: currentDbSync } =
            await keyDateRepo.readKeyDateAndCalendarSyncForUpdate(
              params.ctx,
              keyDateId,
            );
          if (!recheckedKd) {
            return {
              action: 'done' as const,
              displacedEvents: updatedSync.externalEvents,
            };
          }

          if (currentDbSync?.leaseToken !== myLeaseToken) {
            const displacedEvents = updatedSync.externalEvents.filter(
              (ext) =>
                !currentDbSync?.externalEvents.some(
                  (c) => c.target === ext.target && c.eventId === ext.eventId,
                ),
            );
            return {
              action: 'done' as const,
              finalSync: currentDbSync ?? undefined,
              displacedEvents,
            };
          }

          if (recheckedKd.version === observedVersion) {
            const committedSync: KeyDateCalendarSync = {
              keyDateId: updatedSync.keyDateId,
              state: updatedSync.state,
              externalEvents: updatedSync.externalEvents,
              ...(updatedSync.lastSyncedAt
                ? { lastSyncedAt: updatedSync.lastSyncedAt }
                : {}),
              ...(updatedSync.lastError ? { lastError: updatedSync.lastError } : {}),
              attempts: updatedSync.attempts,
            };
            await keyDateRepo.putCalendarSync(params.ctx, committedSync);
            return {
              action: 'done' as const,
              finalSync: committedSync,
              displacedEvents: [] as Array<{ target: string; eventId: string }>,
            };
          }

          const mergedByTarget = new Map(
            (currentDbSync?.externalEvents ?? []).map((e) => [e.target, e.eventId]),
          );
          const displacedEvents: Array<{ target: string; eventId: string }> = [];
          for (const ext of updatedSync.externalEvents) {
            const existingWinner = mergedByTarget.get(ext.target);
            if (!existingWinner) {
              mergedByTarget.set(ext.target, ext.eventId);
            } else if (existingWinner !== ext.eventId) {
              displacedEvents.push(ext);
            }
          }
          const mergedEvents = Array.from(mergedByTarget.entries()).map(
            ([target, eventId]) => ({ target, eventId }),
          );
          const isFinalAttempt = attempt >= maxAttempts;
          const skewedSync: KeyDateCalendarSync = {
            keyDateId,
            state: isFinalAttempt ? 'failed' : 'syncing',
            externalEvents: mergedEvents,
            ...(currentDbSync?.lastSyncedAt
              ? { lastSyncedAt: currentDbSync.lastSyncedAt }
              : {}),
            ...(isFinalAttempt
              ? { lastError: 'CONCURRENT_CALENDAR_SYNC_VERSION_SKEW' }
              : currentDbSync?.lastError
                ? { lastError: currentDbSync.lastError }
                : {}),
            attempts: Math.max(
              currentDbSync?.attempts ?? 0,
              updatedSync.attempts ?? 0,
            ),
            ...(isFinalAttempt
              ? {}
              : {
                  leaseToken: myLeaseToken,
                  leaseExpiresAt: new Date(Date.now() + leaseTtlMs).toISOString(),
                }),
          };
          await keyDateRepo.putCalendarSync(params.ctx, skewedSync);
          return {
            action: isFinalAttempt ? ('failed' as const) : ('retry' as const),
            finalSync: skewedSync,
            displacedEvents,
          };
        });

        await deleteDisplacedEvents(tx2Result.displacedEvents);

        if (tx2Result.action === 'done') {
          if (tx2Result.finalSync?.state === 'failed') {
            failures.push({
              keyDateId,
              attempts: tx2Result.finalSync.attempts ?? 1,
              error:
                tx2Result.finalSync.lastError ?? 'Microsoft Graph calendar sync error',
            });
          }
          completed = true;
          break;
        }
        if (tx2Result.action === 'failed') {
          failures.push({
            keyDateId,
            attempts: tx2Result.finalSync?.attempts ?? attempt,
            error:
              tx2Result.finalSync?.lastError ??
              'CONCURRENT_CALENDAR_SYNC_VERSION_SKEW',
          });
          completed = true;
          break;
        }
      } catch (err) {
        const redacted = sanitizeCalendarSyncError(err);
        let recordedAttempts = attempt;
        try {
          if (claimedLeaseInTx1) {
            const existingFailed = await keyDateRepo.getCalendarSync(
              params.ctx,
              keyDateId,
            );
            if (!existingFailed?.leaseToken || existingFailed.leaseToken === myLeaseToken) {
              recordedAttempts = (existingFailed?.attempts ?? 0) + 1;
              await keyDateRepo.putCalendarSync(
                params.ctx,
                {
                  keyDateId,
                  state: 'failed',
                  externalEvents:
                    existingFailed?.externalEvents ?? observedExternalEvents,
                  ...(existingFailed?.lastSyncedAt
                    ? { lastSyncedAt: existingFailed.lastSyncedAt }
                    : {}),
                  lastError: redacted,
                  attempts: recordedAttempts,
                },
              );
            }
          }
        } catch {
          // Best-effort retry persistence; key date mutation is already committed
        }
        failures.push({
          keyDateId,
          attempts: recordedAttempts,
          error: redacted,
        });
        completed = true;
        break;
      }
    }

    if (!completed) {
      failures.push({
        keyDateId,
        attempts: maxAttempts,
        error: 'CONCURRENT_CALENDAR_SYNC_VERSION_SKEW',
      });
    }
  }

  if (failures.length > 0) {
    for (const failure of failures) {
      console.warn(
        JSON.stringify({
          level: 'warn',
          event: 'keydate.calendar_sync_failed',
          tenantId: params.ctx.tenantId,
          correlationId: params.ctx.correlationId,
          keyDateId: failure.keyDateId,
          attempts: failure.attempts,
          error: failure.error,
        }),
      );
    }
    return { calendarSyncWarning: CALENDAR_SYNC_WARNING_MESSAGE };
  }
  return {};
}

async function loadKeyDateReminderTasks(
  ctx: TenantContext,
  keyDateIds: readonly string[],
  reminderStates: readonly KeyDateReminderState[] = [],
): Promise<Task[]> {
  const cleanKdIds = Array.from(
    new Set(keyDateIds.map((id) => id?.trim()).filter((id): id is string => Boolean(id))),
  );
  const taskIds = Array.from(
    new Set(
      reminderStates
        .map((rs) => rs.taskId?.trim())
        .filter((id): id is string => Boolean(id)),
    ),
  );
  const idempotencyKeys = cleanKdIds.map((kdId) =>
    buildKeyDateReminderIdempotencyKey(kdId, ctx.tenantId),
  );
  if (taskIds.length === 0 && cleanKdIds.length === 0 && idempotencyKeys.length === 0) {
    return [];
  }
  return getTaskWorkflowRepository().listTasksByIdsOrIdempotencyKeys<Task>(ctx, {
    ids: taskIds,
    keyDateIds: cleanKdIds,
    idempotencyKeys,
  });
}

async function commitKeyDateDomainWritesInPostgres(params: {
  ctx: TenantContext;
  keyDatesToUpsert?: readonly KeyDate[];
  expectedVersionsById?: ReadonlyMap<string, number | null>;
  notApplicableToUpsert?: readonly KeyDateNotApplicable[];
  reminderStatesToUpsert?: KeyDateReminderState[];
  reminderStatesToDeleteKeyDateIds?: readonly string[];
  calendarSyncsToUpsert?: readonly KeyDateCalendarSync[];
  tasksToUpsert?: Task[];
  tasksToDeleteIds?: readonly string[];
  notificationsToUpsert?: NotificationItem[];
  auditEntries: AuditEntry[];
}): Promise<void> {
  const keyDateRepo = getKeyDateRepository();
  const taskRepo = getTaskWorkflowRepository();
  await keyDateRepo.withTenantTransaction(params.ctx, async (tx) => {
    for (const deletedKdId of params.reminderStatesToDeleteKeyDateIds ?? []) {
      await keyDateRepo.removeReminderState(params.ctx, deletedKdId);
    }
    for (const deletedId of params.tasksToDeleteIds ?? []) {
      await tx.query('DELETE FROM tasks WHERE tenant_id = $1 AND id = $2', [
        params.ctx.tenantId,
        deletedId,
      ]);
    }
    for (const t of params.tasksToUpsert ?? []) {
      if (t.id.startsWith('TSK-PENDING-')) {
        const oldId = t.id;
        const realId = await taskRepo.allocateNextTaskId(params.ctx);
        t.id = realId;
        t.reference = realId;
        for (const rs of params.reminderStatesToUpsert ?? []) {
          if (rs.taskId === oldId) rs.taskId = realId;
        }
        for (const a of params.auditEntries) {
          if (a.recordId === oldId) a.recordId = realId;
        }
      }
      await taskRepo.putTask(params.ctx, t);
    }
    for (const n of params.notificationsToUpsert ?? []) {
      if (n.id.startsWith('NTF-PENDING-')) {
        n.id = await taskRepo.allocateNextNotificationId(params.ctx);
      }
      await taskRepo.putNotification(params.ctx, n);
    }
    for (const kd of params.keyDatesToUpsert ?? []) {
      const expectedVersion = params.expectedVersionsById?.get(kd.id);
      if (expectedVersion === undefined) {
        throw new Error(
          `KEY_DATE_VALIDATION_ERROR: commitKeyDateDomainWritesInPostgres requires expectedVersion for KeyDate "${kd.id}".`,
        );
      }
      const savedKd = await keyDateRepo.putKeyDate(params.ctx, kd, {
        expectedVersion,
      });
      kd.version = savedKd.version;
    }
    for (const na of params.notApplicableToUpsert ?? []) {
      await keyDateRepo.putNotApplicable(params.ctx, na);
    }
    for (const rs of params.reminderStatesToUpsert ?? []) {
      await keyDateRepo.putReminderState(params.ctx, rs);
    }
    for (const cs of params.calendarSyncsToUpsert ?? []) {
      await keyDateRepo.putCalendarSync(params.ctx, cs);
    }
    if (params.auditEntries.length > 0) {
      const auditInputs: FirmAuditEntryInput[] = params.auditEntries.map((a) => ({
        ...(a.id && !a.id.startsWith('AU-PENDING') ? { id: a.id } : {}),
        recordType: a.recordType,
        recordId: a.recordId,
        action: a.action,
        field: a.field,
        oldValue: a.oldValue,
        newValue: a.newValue,
        byId: a.byId,
        at: a.at,
        ...(a.reason !== undefined ? { reason: a.reason } : {}),
        ...(a.snapshot !== undefined ? { snapshot: a.snapshot } : {}),
      }));
      await appendTenantAuditEntries(params.ctx, auditInputs);
    }
  });
}

export async function getMatterKeyDatesSnapshot(
  matterId: string,
  userId: string,
): Promise<{
  keyDates: KeyDate[];
  keyDateNotApplicable: KeyDateNotApplicable[];
  keyDateReminderStates: KeyDateReminderState[];
  keyDateCalendarSyncs: KeyDateCalendarSync[];
  canVerifyByKeyDateId: Record<string, { allowed: boolean; reason?: string }>;
}> {
  let resolved: Awaited<ReturnType<typeof resolveKeyDatesActorAndData>> = null;
  try {
    resolved = await resolveKeyDatesActorAndData(null, userId, { matterId });
  } catch {
    resolved = null;
  }
  if (!resolved || !resolved.actor) {
    return {
      keyDates: [],
      keyDateNotApplicable: [],
      keyDateReminderStates: [],
      keyDateCalendarSyncs: [],
      canVerifyByKeyDateId: {},
    };
  }
  const { ctx, actor: user, people, matters, teams, rbacOptions } = resolved;
  const config = await getKeyDatesConfig({ ctx, userId: user.id });
  if (
    !hasKeyDatePermission(user, 'keydate:view', {
      config,
      allPeople: people,
      teams,
      rbac: rbacOptions,
    })
  ) {
    return {
      keyDates: [],
      keyDateNotApplicable: [],
      keyDateReminderStates: [],
      keyDateCalendarSyncs: [],
      canVerifyByKeyDateId: {},
    };
  }
  const matter = matters.find((m) => m.id === matterId);
  if (!matter || !canViewerAccessMatterKeyDates(matter, user.id, user, people, rbacOptions)) {
    return {
      keyDates: [],
      keyDateNotApplicable: [],
      keyDateReminderStates: [],
      keyDateCalendarSyncs: [],
      canVerifyByKeyDateId: {},
    };
  }
  const keyDateRepo = getKeyDateRepository();
  const [keyDates, keyDateNotApplicable] = await Promise.all([
    keyDateRepo.listKeyDatesForMatter(ctx, matter.id, user.id),
    keyDateRepo.listNotApplicableForMatter(ctx, matter.id, user.id),
  ]);
  const keyDateIds = keyDates.map((kd) => kd.id);
  const [keyDateReminderStates, keyDateCalendarSyncs] = await Promise.all([
    keyDateRepo.listReminderStatesForKeyDateIds(ctx, keyDateIds, user.id),
    keyDateRepo.listCalendarSyncsForKeyDateIds(ctx, keyDateIds, user.id),
  ]);
  const canVerifyByKeyDateId: Record<
    string,
    { allowed: boolean; reason?: string }
  > = {};
  for (const kd of keyDates) {
    canVerifyByKeyDateId[kd.id] = canUserVerifyKeyDate(user, kd, {
      config,
      allPeople: people,
      teams,
    });
  }
  return {
    keyDates,
    keyDateNotApplicable,
    keyDateReminderStates,
    keyDateCalendarSyncs,
    canVerifyByKeyDateId,
  };
}

export async function previewLimitationCalculationRecord(
  input: {
    ruleSetId: string;
    ruleId: string;
    triggerValues: Record<string, string>;
    standstillPeriods?: StandstillPeriod[];
    calendarCodeOverride?: string;
  },
  byId: string,
): Promise<{ ok: boolean; result?: CalculationResult; error?: string }> {
  try {
    const resolved = await resolveKeyDatesActorAndData(null, byId);
    if (!resolved || !resolved.actor) {
      return { ok: false, error: `Unknown or unauthenticated user "${byId}".` };
    }
    const { ctx, actor, people, teams } = resolved;
    const config = await getKeyDatesConfig({ ctx, userId: actor.id });
    if (
      !hasKeyDatePermission(actor, 'keydate:view', {
        config,
        allPeople: people,
        teams,
      })
    ) {
      return {
        ok: false,
        error:
          'KEY_DATE_PERMISSION_DENIED: You need "keydate:view" permission to preview limitation calculations.',
      };
    }
    const found = findLimitationRule(config, input.ruleSetId, input.ruleId);
    if (!found) {
      return {
        ok: false,
        error: `Rule "${input.ruleId}" in rule set "${input.ruleSetId}" was not found.`,
      };
    }
    const calCode =
      input.calendarCodeOverride ||
      found.rule.calendarId ||
      config.businessCalendars?.[0]?.id;
    const calendar = findBusinessCalendar(config, calCode);
    const result = calculateLimitationDate(
      found.rule,
      {
        ...input.triggerValues,
        ...(input.standstillPeriods ? { standstillPeriods: input.standstillPeriods } : {}),
      },
      calendar,
      { ruleSetReviewStatus: found.ruleSet.reviewStatus },
    );
    return { ok: true, result };
  } catch (err) {
    return {
      ok: false,
      error: err instanceof Error ? err.message : 'Calculation failed.',
    };
  }
}

export async function createOrProposeKeyDateRecord(
  input: {
    matterId?: string;
    enquiryId?: string;
    keyDateTypeId: string;
    title?: string;
    dueDate: string;
    dueTime?: string;
    isCritical?: boolean;
    source?: KeyDateSource;
    teamId?: string;
    responsiblePersonIds?: string[];
    calculation?: KeyDateCalculation;
    notes?: string;
    sourceDocumentId?: string;
    intent?: 'provisional' | 'propose';
  },
  byId: string,
  options?: { calendarAdapter?: GraphCalendarAdapter },
): Promise<{
  ok: boolean;
  keyDate?: KeyDate;
  calendarSyncWarning?: string;
  error?: string;
  denied?: true;
  code?: ActionDenied['code'];
  message?: string;
}> {
  try {
    const prelimCtx = resolvePrelimKeyDatesTenantContext(byId);
    if (!prelimCtx) {
      return { ok: false, error: `Unknown or unauthenticated user "${byId}".` };
    }
    const keyDateRepo = getKeyDateRepository();
    const taskRepo = getTaskWorkflowRepository();

    const txResult = await keyDateRepo.withTenantTransaction(
      prelimCtx,
      async () => {
        const resolved = await resolveKeyDatesActorAndData(null, byId, {
          matterId: input.matterId,
        });
        if (!resolved || !resolved.actor) {
          return {
            ok: false as const,
            error: `Unknown or unauthenticated user "${byId}".`,
          };
        }
        const { ctx, actor, people, matters, teams, rbacOptions, personRbacOptions } = resolved;
        const config = await getKeyDatesConfig({ ctx, userId: actor.id });
        const disabledErr = assertKeyDatesModuleEnabled(config);
        if (disabledErr) return disabledErr;

        const nowIso = new Date().toISOString();
        const todayIso = toIsoDate(new Date());

        const matter = input.matterId
          ? matters.find((m) => m.id === input.matterId) ?? null
          : null;
        const enquiry = input.enquiryId
          ? await getIntakeQuoteRepository().getEnquiryById<Enquiry>(ctx, input.enquiryId, {
              includeRestricted: true,
            })
          : null;

        if (
          input.matterId &&
          (!matter || !canViewerAccessMatterKeyDates(matter, actor.id, actor, people, rbacOptions))
        ) {
          return { ok: false as const, error: 'Matter not found or restricted.' };
        }

        const resolvedSource = resolveKeyDateSource({
          source: input.source,
          hasCalculation: Boolean(input.calculation),
          allowSystemSource: false,
        });
        if (!resolvedSource.ok) {
          return buildActionDenied('FORBIDDEN', resolvedSource.error);
        }
        const manualCheck = validateKeyDateManualEntry(
          config,
          input.keyDateTypeId,
          resolvedSource.source,
        );
        if (!manualCheck.ok) {
          return buildActionDenied('FORBIDDEN', manualCheck.error);
        }

        // R608: Serialise with recordKeyDateNotApplicableRecord before reading N/A rows
        await acquireKeyDateScopeAdvisoryLock(ctx, {
          matterId: matter?.id,
          enquiryId: enquiry?.id,
          keyDateTypeId: input.keyDateTypeId,
        });

        const newKdId = await keyDateRepo.allocateNextKeyDateId(ctx);
        const stagedAudit: AuditEntry[] = [];
        let pendingIdx = 0;

        const kd = createOrProposeKeyDate({
          id: newKdId,
          matter,
          enquiry,
          keyDateTypeId: input.keyDateTypeId,
          title: input.title,
          dueDate: input.dueDate,
          dueTime: input.dueTime,
          isCritical: input.isCritical,
          source: resolvedSource.source,
          teamId: input.teamId,
          responsiblePersonIds: input.responsiblePersonIds,
          calculation: input.calculation,
          notes: input.notes,
          sourceDocumentId: input.sourceDocumentId,
          intent: input.intent,
          actor,
          nowIso,
          config,
          teams,
          people,
          rbacOptions,
          audit: stagedAudit,
          nextAuditId: () => `AU-PENDING-${++pendingIdx}`,
        });

        const reminderStatesWorking: KeyDateReminderState[] = [];
        let changedTasks: Task[] = [];
        let deletedTaskIds: string[] = [];

        if (kd.status === 'confirmed') {
          const existingNaForMatter = kd.matterId
            ? await keyDateRepo.listNotApplicableForMatter(ctx, kd.matterId, actor.id)
            : [];
          const isMarkedNotApplicable = existingNaForMatter.some(
            (na) => na.keyDateTypeId === kd.keyDateTypeId && Boolean(na.reason?.trim()),
          );
          if (!isMarkedNotApplicable) {
            const storeTasks = await loadKeyDateReminderTasks(
              ctx,
              [kd.id],
              reminderStatesWorking,
            );
            const beforeTaskJsonById = new Map(
              storeTasks.map((t) => [t.id, JSON.stringify(t)]),
            );
            let pendingTaskIdx = 0;
            syncReminderForConfirmedKeyDate({
              keyDate: kd,
              config,
              tasks: storeTasks,
              reminderStates: reminderStatesWorking,
              matters: matter ? [matter] : [],
              people,
              rbacOptions: personRbacOptions,
              audit: stagedAudit,
              nextAuditId: () => `AU-PENDING-${++pendingIdx}`,
              todayIso,
              nowIso,
              actorId: actor.id,
              tenantId: ctx.tenantId,
              nextTaskId: () => `TSK-PENDING-${++pendingTaskIdx}`,
            });
            changedTasks = storeTasks.filter(
              (t) => beforeTaskJsonById.get(t.id) !== JSON.stringify(t),
            );
            const currentIds = new Set(storeTasks.map((t) => t.id));
            deletedTaskIds = [...beforeTaskJsonById.keys()].filter(
              (id) => !currentIds.has(id),
            );
          }
        }

        await commitKeyDateDomainWritesInPostgres({
          ctx,
          keyDatesToUpsert: [kd],
          expectedVersionsById: new Map([[kd.id, null]]),
          reminderStatesToUpsert: reminderStatesWorking,
          tasksToUpsert: changedTasks,
          tasksToDeleteIds: deletedTaskIds,
          auditEntries: stagedAudit,
        });

        return {
          ok: true as const,
          keyDate: kd,
          postCommitSync: {
            ctx,
            config,
            nowIso,
            existingSyncs: [] as KeyDateCalendarSync[],
            items: [{ keyDate: kd, matter, enquiry }],
            adapter: options?.calendarAdapter,
          },
        };
      },
    );

    if (!txResult.ok || !('postCommitSync' in txResult)) {
      return txResult;
    }
    const syncOutcome = await runPostCommitKeyDateCalendarSync(txResult.postCommitSync);
    return {
      ok: true,
      keyDate: txResult.keyDate,
      ...(syncOutcome.calendarSyncWarning
        ? { calendarSyncWarning: syncOutcome.calendarSyncWarning }
        : {}),
    };
  } catch (err) {
    return {
      ok: false,
      error: err instanceof Error ? err.message : 'Failed to create key date.',
    };
  }
}

export async function proposeProvisionalKeyDateRecord(
  keyDateId: string,
  byId: string,
  options?: { calendarAdapter?: GraphCalendarAdapter },
): Promise<{
  ok: boolean;
  keyDate?: KeyDate;
  calendarSyncWarning?: string;
  error?: string;
}> {
  try {
    const prelimCtx = resolvePrelimKeyDatesTenantContext(byId);
    if (!prelimCtx) {
      return { ok: false, error: `Unknown or unauthenticated user "${byId}".` };
    }
    const keyDateRepo = getKeyDateRepository();
    const taskRepo = getTaskWorkflowRepository();

    const txResult = await keyDateRepo.withTenantTransaction(
      prelimCtx,
      async () => {
        const resolved = await resolveKeyDatesActorAndData(null, byId);
        if (!resolved || !resolved.actor) {
          return {
            ok: false as const,
            error: `Unknown or unauthenticated user "${byId}".`,
          };
        }
        const { ctx, actor, people, matters, teams, rbacOptions, personRbacOptions } = resolved;
        const config = await getKeyDatesConfig({ ctx, userId: actor.id });
        const disabledErr = assertKeyDatesModuleEnabled(config);
        if (disabledErr) return disabledErr;

        // R608: Acquire advisory scope lock BEFORE row-locking key_dates
        const preScope = await keyDateRepo.getKeyDateScopeSummary(ctx, keyDateId);
        if (preScope) {
          await acquireKeyDateScopeAdvisoryLock(ctx, preScope);
        }

        const nowIso = new Date().toISOString();
        const todayIso = toIsoDate(new Date());

        const loaded = await loadKeyDateForActorOrClassifyError(
          ctx,
          null,
          keyDateId,
          actor,
          people,
          matters,
          teams,
          rbacOptions,
          { forUpdate: true },
        );
        if (!loaded.kd) {
          return { ok: false as const, error: loaded.error ?? 'Key date not found.' };
        }
        const { kd, matter, enquiry } = loaded;
        const expectedVersion = kd.version;

        const stagedAudit: AuditEntry[] = [];
        let pendingIdx = 0;

        proposeProvisionalKeyDate({
          keyDate: kd,
          actor,
          nowIso,
          config,
          matter,
          enquiry,
          teams,
          people,
          audit: stagedAudit,
          nextAuditId: () => `AU-PENDING-${++pendingIdx}`,
        });

        const existingReminder = await keyDateRepo.getReminderState(ctx, kd.id, actor.id);
        const reminderStatesWorking: KeyDateReminderState[] = existingReminder
          ? [existingReminder]
          : [];
        const existingSync = await keyDateRepo.getCalendarSync(ctx, kd.id, actor.id);

        let changedTasks: Task[] = [];
        let deletedTaskIds: string[] = [];
        if (kd.status === 'confirmed') {
          const existingNaForMatter = kd.matterId
            ? await keyDateRepo.listNotApplicableForMatter(ctx, kd.matterId, actor.id)
            : [];
          const isMarkedNotApplicable = existingNaForMatter.some(
            (na) => na.keyDateTypeId === kd.keyDateTypeId && Boolean(na.reason?.trim()),
          );
          if (!isMarkedNotApplicable) {
            const storeTasks = await loadKeyDateReminderTasks(
              ctx,
              [kd.id],
              reminderStatesWorking,
            );
            const beforeTaskJsonById = new Map(
              storeTasks.map((t) => [t.id, JSON.stringify(t)]),
            );
            let pendingTaskIdx = 0;
            syncReminderForConfirmedKeyDate({
              keyDate: kd,
              config,
              tasks: storeTasks,
              reminderStates: reminderStatesWorking,
              matters: matter ? [matter] : [],
              people,
              rbacOptions: personRbacOptions,
              audit: stagedAudit,
              nextAuditId: () => `AU-PENDING-${++pendingIdx}`,
              todayIso,
              nowIso,
              actorId: actor.id,
              tenantId: ctx.tenantId,
              nextTaskId: () => `TSK-PENDING-${++pendingTaskIdx}`,
            });
            changedTasks = storeTasks.filter(
              (t) => beforeTaskJsonById.get(t.id) !== JSON.stringify(t),
            );
            const currentIds = new Set(storeTasks.map((t) => t.id));
            deletedTaskIds = [...beforeTaskJsonById.keys()].filter(
              (id) => !currentIds.has(id),
            );
          }
        }

        await commitKeyDateDomainWritesInPostgres({
          ctx,
          keyDatesToUpsert: [kd],
          expectedVersionsById: new Map([[kd.id, expectedVersion]]),
          reminderStatesToUpsert: reminderStatesWorking,
          tasksToUpsert: changedTasks,
          tasksToDeleteIds: deletedTaskIds,
          auditEntries: stagedAudit,
        });

        return {
          ok: true as const,
          keyDate: kd,
          postCommitSync: {
            ctx,
            config,
            nowIso,
            existingSyncs: existingSync ? [existingSync] : [],
            items: [{ keyDate: kd, matter, enquiry }],
            adapter: options?.calendarAdapter,
          },
        };
      },
    );

    if (!txResult.ok || !('postCommitSync' in txResult)) {
      return txResult;
    }
    const syncOutcome = await runPostCommitKeyDateCalendarSync(txResult.postCommitSync);
    return {
      ok: true,
      keyDate: txResult.keyDate,
      ...(syncOutcome.calendarSyncWarning
        ? { calendarSyncWarning: syncOutcome.calendarSyncWarning }
        : {}),
    };
  } catch (err) {
    return {
      ok: false,
      error: err instanceof Error ? err.message : 'Failed to propose key date.',
    };
  }
}

async function loadKeyDateForActorOrClassifyError(
  ctx: TenantContext,
  _store: FirmStore | null,
  keyDateId: string,
  actor: Person,
  people: readonly Person[],
  matters: readonly Matter[],
  teams: readonly Team[],
  rbacOptions?: ResolvePersonPermissionsOptions,
  options?: { forUpdate?: boolean },
): Promise<{ kd: KeyDate | null; error?: string; matter: Matter | null; enquiry: Enquiry | null }> {
  const keyDateRepo = getKeyDateRepository();
  const kd = options?.forUpdate
    ? await keyDateRepo.getKeyDateByIdForUpdate(ctx, keyDateId, actor.id)
    : await keyDateRepo.getKeyDateById(ctx, keyDateId, actor.id);
  if (!kd) {
    // Distinguish missing key date vs restricted/orphan matter key date (R30, R82):
    const probeExists = await keyDateRepo.withTenantReadTransaction(ctx, async (tx) => {
      const res = await tx.query<{ matter_id: string | null }>(
        'SELECT matter_id FROM key_dates WHERE tenant_id = $1 AND id = $2',
        [ctx.tenantId, keyDateId],
      );
      return res.rows[0] ?? null;
    });
    if (probeExists?.matter_id) {
      return { kd: null, error: 'Matter not found or restricted.', matter: null, enquiry: null };
    }
    return { kd: null, error: 'Key date not found.', matter: null, enquiry: null };
  }
  const matter = kd.matterId
    ? matters.find((m) => m.id === kd.matterId) ??
      (await getMatterRepository().getMatterById<Matter>(ctx, kd.matterId, {
        includeRestricted: true,
      }))
    : null;
  const enquiry = kd.enquiryId
    ? await getIntakeQuoteRepository().getEnquiryById<Enquiry>(ctx, kd.enquiryId, {
        includeRestricted: true,
      })
    : null;
  const effectiveRbacOptions: ResolvePersonPermissionsOptions = rbacOptions ?? {
    allPeople: people,
    teams,
    config: { rbac: await loadEffectiveTenantRbacConfig(ctx) },
    tenantId: ctx.tenantId,
  };
  if (
    kd.matterId &&
    (!matter ||
      !canViewerAccessMatterKeyDates(
        matter,
        actor.id,
        actor,
        people as Person[],
        effectiveRbacOptions,
      ))
  ) {
    return { kd: null, error: 'Matter not found or restricted.', matter: null, enquiry: null };
  }
  return { kd, matter, enquiry };
}

export async function verifyProposedKeyDateRecord(
  keyDateId: string,
  byId: string,
  options?: { calendarAdapter?: GraphCalendarAdapter },
): Promise<{
  ok: boolean;
  keyDate?: KeyDate;
  calendarSyncWarning?: string;
  error?: string;
}> {
  try {
    const prelimCtx = resolvePrelimKeyDatesTenantContext(byId);
    if (!prelimCtx) {
      return { ok: false, error: `Unknown or unauthenticated user "${byId}".` };
    }
    const keyDateRepo = getKeyDateRepository();
    const taskRepo = getTaskWorkflowRepository();

    const txResult = await keyDateRepo.withTenantTransaction(
      prelimCtx,
      async () => {
        const resolved = await resolveKeyDatesActorAndData(null, byId);
        if (!resolved || !resolved.actor) {
          return {
            ok: false as const,
            error: `Unknown or unauthenticated user "${byId}".`,
          };
        }
        const { ctx, actor: verifier, people, matters, teams, rbacOptions, personRbacOptions } = resolved;
        const config = await getKeyDatesConfig({ ctx, userId: verifier.id });
        const disabledErr = assertKeyDatesModuleEnabled(config);
        if (disabledErr) return disabledErr;

        // R608: Acquire advisory scope lock BEFORE row-locking key_dates
        const preScope = await keyDateRepo.getKeyDateScopeSummary(ctx, keyDateId);
        if (preScope) {
          await acquireKeyDateScopeAdvisoryLock(ctx, preScope);
        }

        const loaded = await loadKeyDateForActorOrClassifyError(
          ctx,
          null,
          keyDateId,
          verifier,
          people,
          matters,
          teams,
          rbacOptions,
          { forUpdate: true },
        );
        if (!loaded.kd) {
          return { ok: false as const, error: loaded.error ?? 'Key date not found.' };
        }
        const { kd, matter, enquiry } = loaded;
        const expectedVersion = kd.version;
        const nowIso = new Date().toISOString();
        const todayIso = toIsoDate(new Date());

        const stagedAudit: AuditEntry[] = [];
        let pendingIdx = 0;

        verifyProposedKeyDate({
          keyDate: kd,
          verifier,
          nowIso,
          config,
          teams,
          people,
          audit: stagedAudit,
          nextAuditId: () => `AU-PENDING-${++pendingIdx}`,
        });

        const reminderStatesWorking = await keyDateRepo.listAllReminderStates(
          ctx,
          verifier.id,
        );
        const existingSync = await keyDateRepo.getCalendarSync(ctx, kd.id, verifier.id);

        const storeTasks = await loadKeyDateReminderTasks(
          ctx,
          [kd.id, kd.supersedesKeyDateId].filter((id): id is string => Boolean(id)),
          reminderStatesWorking,
        );
        const beforeTaskJsonById = new Map(
          storeTasks.map((t) => [t.id, JSON.stringify(t)]),
        );
        const existingNaForMatter = kd.matterId
          ? await keyDateRepo.listNotApplicableForMatter(ctx, kd.matterId, verifier.id)
          : [];
        const isMarkedNotApplicable = existingNaForMatter.some(
          (na) => na.keyDateTypeId === kd.keyDateTypeId && Boolean(na.reason?.trim()),
        );
        let pendingTaskIdx = 0;
        if (!isMarkedNotApplicable) {
          syncReminderForConfirmedKeyDate({
            keyDate: kd,
            config,
            tasks: storeTasks,
            reminderStates: reminderStatesWorking,
            matters: matter ? [matter] : [],
            people,
            rbacOptions: personRbacOptions,
            audit: stagedAudit,
            nextAuditId: () => `AU-PENDING-${++pendingIdx}`,
            todayIso,
            nowIso,
            actorId: verifier.id,
            tenantId: ctx.tenantId,
            nextTaskId: () => `TSK-PENDING-${++pendingTaskIdx}`,
            transferredFromKeyDateId: kd.supersedesKeyDateId,
          });
        }

        const changedTasks = storeTasks.filter(
          (t) => beforeTaskJsonById.get(t.id) !== JSON.stringify(t),
        );
        const currentIds = new Set(storeTasks.map((t) => t.id));
        const deletedTaskIds = [...beforeTaskJsonById.keys()].filter(
          (id) => !currentIds.has(id),
        );

        const targetReminders = reminderStatesWorking.filter(
          (rs) => rs.keyDateId === kd.id || rs.keyDateId === kd.supersedesKeyDateId,
        );

        await commitKeyDateDomainWritesInPostgres({
          ctx,
          keyDatesToUpsert: [kd],
          expectedVersionsById: new Map([[kd.id, expectedVersion]]),
          reminderStatesToUpsert: targetReminders,
          tasksToUpsert: changedTasks,
          tasksToDeleteIds: deletedTaskIds,
          auditEntries: stagedAudit,
        });

        return {
          ok: true as const,
          keyDate: kd,
          postCommitSync: {
            ctx,
            config,
            nowIso,
            existingSyncs: existingSync ? [existingSync] : [],
            items: [{ keyDate: kd, matter, enquiry }],
            adapter: options?.calendarAdapter,
          },
        };
      },
    );

    if (!txResult.ok || !('postCommitSync' in txResult)) {
      return txResult;
    }
    const syncOutcome = await runPostCommitKeyDateCalendarSync(txResult.postCommitSync);
    return {
      ok: true,
      keyDate: txResult.keyDate,
      ...(syncOutcome.calendarSyncWarning
        ? { calendarSyncWarning: syncOutcome.calendarSyncWarning }
        : {}),
    };
  } catch (err) {
    return {
      ok: false,
      error: err instanceof Error ? err.message : 'Failed to verify key date.',
    };
  }
}

