export async function recordKeyDateNotApplicableRecord(
  input: {
    matterId: string;
    keyDateTypeId: string;
    reason: string;
  },
  byId: string,
): Promise<{ ok: boolean; record?: KeyDateNotApplicable; error?: string }> {
  try {
    const prelimCtx = resolvePrelimKeyDatesTenantContext(byId);
    if (!prelimCtx) {
      return { ok: false, error: `Unknown or unauthenticated user "${byId}".` };
    }
    const keyDateRepo = getKeyDateRepository();

    return await keyDateRepo.withTenantTransaction(prelimCtx, async () => {
      const resolved = await resolveKeyDatesActorAndData(null, byId, {
        matterId: input.matterId,
      });
      if (!resolved || !resolved.actor) {
        return { ok: false, error: `Unknown or unauthenticated user "${byId}".` };
      }
      const { ctx, actor, people, matters, teams, rbacOptions } = resolved;
      const config = await getKeyDatesConfig({ ctx, userId: actor.id });
      const disabledErr = assertKeyDatesModuleEnabled(config);
      if (disabledErr) return disabledErr;

      const matter = matters.find((m) => m.id === input.matterId);
      if (!matter || !canViewerAccessMatterKeyDates(matter, actor.id, actor, people, rbacOptions)) {
        return { ok: false, error: 'Matter not found or restricted.' };
      }

      // R608: Lock (tenant, scope, keyDateTypeId) advisory lock before reading N/A or locking key_dates
      await acquireKeyDateScopeAdvisoryLock(ctx, {
        matterId: matter.id,
        keyDateTypeId: input.keyDateTypeId,
      });

      const existingNaList = await keyDateRepo.listNotApplicableForMatter(
        ctx,
        matter.id,
        actor.id,
      );
      const nowIso = new Date().toISOString();
      const stagedAudit: AuditEntry[] = [];
      let pendingIdx = 0;

      const rec = recordKeyDateNotApplicable({
        matterId: matter.id,
        matterTypeId: matter.matterTypeId || matter.practiceAreaId,
        keyDateTypeId: input.keyDateTypeId,
        reason: input.reason,
        actor,
        nowIso,
        config,
        notApplicableList: existingNaList,
        teams,
        people,
        audit: stagedAudit,
        nextAuditId: () => `AU-PENDING-${++pendingIdx}`,
      });

      const matterKeyDates = await keyDateRepo.listKeyDatesForMatter(
        ctx,
        matter.id,
        actor.id,
        { forUpdate: true, keyDateTypeId: input.keyDateTypeId },
      );
      const matchingKeyDateIds = matterKeyDates
        .filter((kd) => kd.keyDateTypeId === input.keyDateTypeId)
        .map((kd) => kd.id);
      const deletedTaskIds: string[] = [];
      if (matchingKeyDateIds.length > 0) {
        const storeTasks = await loadKeyDateReminderTasks(ctx, matchingKeyDateIds);
        const idempotencyKeys = new Set(
          matchingKeyDateIds.map((kdId) =>
            buildKeyDateReminderIdempotencyKey(kdId, ctx.tenantId),
          ),
        );
        for (const t of storeTasks) {
          if (t.idempotencyKey && idempotencyKeys.has(t.idempotencyKey)) {
            deletedTaskIds.push(t.id);
          }
        }
      }

      await commitKeyDateDomainWritesInPostgres({
        ctx,
        notApplicableToUpsert: [rec],
        reminderStatesToDeleteKeyDateIds: matchingKeyDateIds,
        tasksToDeleteIds: deletedTaskIds,
        auditEntries: stagedAudit,
      });

      return { ok: true, record: rec };
    });
  } catch (err) {
    return {
      ok: false,
      error:
        err instanceof Error
          ? err.message
          : 'Failed to record key date as not applicable.',
    };
  }
}

export async function acknowledgeKeyDateReminderRecord(
  keyDateId: string,
  byId: string,
): Promise<{ ok: boolean; reminderState?: KeyDateReminderState; error?: string }> {
  try {
    const prelimCtx = resolvePrelimKeyDatesTenantContext(byId);
    if (!prelimCtx) {
      return { ok: false, error: `Unknown or unauthenticated user "${byId}".` };
    }
    const keyDateRepo = getKeyDateRepository();
    const taskRepo = getTaskWorkflowRepository();

    return await keyDateRepo.withTenantTransaction(prelimCtx, async () => {
      const resolved = await resolveKeyDatesActorAndData(null, byId);
      if (!resolved || !resolved.actor) {
        return { ok: false, error: `Unknown or unauthenticated user "${byId}".` };
      }
      const { ctx, actor, people, matters, teams, rbacOptions, personRbacOptions } = resolved;
      const config = await getKeyDatesConfig({ ctx, userId: actor.id });
      const disabledErr = assertKeyDatesModuleEnabled(config);
      if (disabledErr) return disabledErr;

      if (
        !hasKeyDatePermission(actor, 'keydate:view', {
          config,
          allPeople: people,
          teams,
          rbac: rbacOptions,
        })
      ) {
        return {
          ok: false,
          error:
            'KEY_DATE_PERMISSION_DENIED: You need "keydate:view" permission to acknowledge key date reminders.',
        };
      }

      // R608: Acquire advisory scope lock BEFORE row-locking key_dates
      const preScope = await keyDateRepo.getKeyDateScopeSummary(ctx, keyDateId);
      if (preScope) {
        await acquireKeyDateScopeAdvisoryLock(ctx, preScope);
      }

      const loaded = await loadKeyDateForActorOrClassifyError(
        ctx,
        null,
        keyDateId,
        actor,
        people,
        matters,
        teams,
        rbacOptions,
        { forUpdate: true },
      );
      if (!loaded.kd) {
        return { ok: false, error: loaded.error ?? 'Key date not found.' };
      }
      const { kd, matter } = loaded;

      if (kd.status !== 'confirmed') {
        return {
          ok: false,
          error: `KEY_DATE_INVALID_STATE: Reminders can only be acknowledged for confirmed key dates (current status: "${kd.status}").`,
        };
      }

      if (kd.matterId) {
        const naList = await keyDateRepo.listNotApplicableForMatter(
          ctx,
          kd.matterId,
          actor.id,
        );
        if (
          naList.some(
            (na) => na.keyDateTypeId === kd.keyDateTypeId && Boolean(na.reason?.trim()),
          )
        ) {
          return {
            ok: false,
            error:
              'KEY_DATE_INVALID_STATE: Reminders cannot be acknowledged for a key date type marked not applicable.',
          };
        }
      }

      const owningTeam = teams.find((t) => t.id === kd.teamId);
      const isResponsiblePerson = kd.responsiblePersonIds.includes(actor.id);
      const isOwningTeamLead = Boolean(owningTeam?.leadIds.includes(actor.id));
      if (!isResponsiblePerson && !isOwningTeamLead) {
        return {
          ok: false,
          error:
            'KEY_DATE_PERMISSION_DENIED: Only a responsible person on the key date or the owning team lead may acknowledge a reminder stage.',
        };
      }

      const nowIso = new Date().toISOString();
      const todayIso = toIsoDate(new Date());
      const existingReminder = await keyDateRepo.getReminderState(
        ctx,
        keyDateId,
        actor.id,
        { forUpdate: true },
      );
      const reminderStatesWorking: KeyDateReminderState[] = existingReminder
        ? [existingReminder]
        : [];
      const stagedAudit: AuditEntry[] = [];
      let pendingIdx = 0;

      let changedTasks: Task[] = [];
      let deletedTaskIds: string[] = [];
      if (reminderStatesWorking.length === 0) {
        const storeTasks = await loadKeyDateReminderTasks(ctx, [keyDateId]);
        const beforeTaskJsonById = new Map(
          storeTasks.map((t) => [t.id, JSON.stringify(t)]),
        );
        let pendingTaskIdx = 0;
        syncReminderForConfirmedKeyDate({
          keyDate: kd,
          config,
          tasks: storeTasks,
          reminderStates: reminderStatesWorking,
          matters: matter ? [matter] : [],
          people,
          rbacOptions: personRbacOptions,
          audit: stagedAudit,
          nextAuditId: () => `AU-PENDING-${++pendingIdx}`,
          todayIso,
          nowIso,
          actorId: actor.id,
          tenantId: ctx.tenantId,
          nextTaskId: () => `TSK-PENDING-${++pendingTaskIdx}`,
        });
        changedTasks = storeTasks.filter(
          (t) => beforeTaskJsonById.get(t.id) !== JSON.stringify(t),
        );
        const currentIds = new Set(storeTasks.map((t) => t.id));
        deletedTaskIds = [...beforeTaskJsonById.keys()].filter(
          (id) => !currentIds.has(id),
        );
      }

      const state = acknowledgeKeyDateReminderStage({
        keyDateId,
        actorId: actor.id,
        nowIso,
        reminderStates: reminderStatesWorking,
        audit: stagedAudit,
        nextAuditId: () => `AU-PENDING-${++pendingIdx}`,
      });

      await commitKeyDateDomainWritesInPostgres({
        ctx,
        reminderStatesToUpsert: reminderStatesWorking,
        tasksToUpsert: changedTasks,
        tasksToDeleteIds: deletedTaskIds,
        auditEntries: stagedAudit,
      });

      return { ok: true, reminderState: state };
    });
  } catch (err) {
    return {
      ok: false,
      error:
        err instanceof Error
          ? err.message
          : 'Failed to acknowledge key date reminder.',
    };
  }
}

export interface KeyDateRemindersJobSummary extends Record<string, number> {
  readonly evaluatedCount: number;
  readonly stagesAdvancedCount: number;
  readonly remindersSent: number;
  readonly tasksCreated: number;
  readonly notificationsCreated: number;
  readonly escalationsSent: number;
  readonly exceptionsFound: number;
  readonly skippedCount: number;
}

export interface ExecuteKeyDateRemindersForTenantOptions {
  readonly triggerSource: 'scheduled' | 'manual';
  readonly triggeredById: string;
  readonly timeZone?: string;
  readonly defaultRunHourLocal?: number;
  readonly statementTimeoutMs?: number;
  readonly calendarAdapter?: GraphCalendarAdapter;
  readonly skippedLockRetryDelayMs?: number;
  readonly tenantConfig?: TenantConfiguration;
  readonly signal?: AbortSignal;
}

/**
 * Single-transaction per-tenant Key Date reminder execution shared by scheduled
 * hourly ticks (`system:key-date-reminders`) and manual Admin triggers (`actor.id`)
 * (ADR 0030 §§4–6 / Slice S0-19).
 *
 * Inside one `withTenantTransaction`:
 * 1. Acquires `pg_try_advisory_xact_lock(hashtext('onesquared_job:key-date-reminders:' || tenantId))`.
 * 2. Checks `job_runs` for scheduled runs (`localHour >= 02:00` and no `status = 'succeeded'` row for `local_date`).
 * 3. Reads an unlocked snapshot, identifies candidate key dates needing reminder/task updates, and locks ONLY those candidates (`FOR UPDATE SKIP LOCKED`) so concurrent user edits/acknowledgements on other rows are never blocked (R629).
 * 4. Evaluates due reminders, escalations, tasks, notifications, and audit entries and writes them on the same transaction client.
 * 5. Inserts the `status = 'succeeded'` row in `job_runs` before `COMMIT` releases the advisory lock atomically, then retries any previously `'failed'` calendar sync records strictly post-commit when a configured Graph adapter is supplied (R628).
 */
export async function executeKeyDateRemindersForTenant(
  ctx: TenantContext,
  options: ExecuteKeyDateRemindersForTenantOptions,
): Promise<
  ControlledJobRunOutcome<{
    result: ReturnType<typeof runTenantKeyDateReminderJob>;
    summary: KeyDateRemindersJobSummary;
  }>
> {
  const tenantConfig = resolveVerifiedTenantConfiguration(
    ctx,
    options.tenantConfig,
  );
  const effectiveTimeZone =
    options.timeZone?.trim() || tenantConfig.timeZone || 'Europe/London';
  const now = new Date();
  const nowIso = now.toISOString();
  let postCommitFailedSyncItems: Array<{
    keyDate: KeyDate;
    matter: Matter | null;
    enquiry: Enquiry | null;
  }> = [];

  const jobOutcome = await getJobRunRepository().executeControlledTenantJobRun(ctx, {
    jobKey: 'key-date-reminders',
    triggerSource: options.triggerSource,
    triggeredById: options.triggeredById,
    timeZone: effectiveTimeZone,
    targetLocalHour: options.defaultRunHourLocal ?? 2,
    now,
    statementTimeoutMs: options.statementTimeoutMs,
    signal: options.signal,
    work: async ({ localDate }) => {
      const keyDateRepo = getKeyDateRepository();
      const taskRepo = getTaskWorkflowRepository();
      const partyRepo = getPartyRepository();
      const matterRepo = getMatterRepository();
      const hrRepo = getHrAndRbacRepository();
      const catalogueRepo = getCatalogueRepository();
      const intakeRepo = getIntakeQuoteRepository();

      // R629: Read unlocked snapshot first so unaffected rows are never locked by the batch sweep
      const keyDatesSnapshot = await keyDateRepo.listAllKeyDatesUnfilteredForScheduler(
        ctx,
      );
      const reminderStatesSnapshot =
        await keyDateRepo.listAllReminderStatesUnfilteredForScheduler(ctx);

      const [
        people,
        matters,
        storeTasksSnapshot,
        teams,
        values,
        config,
        notApplicableSnapshot,
        calendarSyncsWorking,
        rbacConfig,
      ] = await Promise.all([
        partyRepo.listAllPeople<Person>(ctx),
        matterRepo.listAllMattersUnfiltered<Matter>(ctx),
        taskRepo.listAllTasksUnfiltered<Task>(ctx),
        hrRepo.listAllTeams<Team>(ctx),
        catalogueRepo.listAllChoiceValues<ChoiceValue>(ctx),
        getKeyDatesConfig({
          ctx,
          userId: options.triggeredById,
          tenantConfig,
        }),
        keyDateRepo.listAllNotApplicableUnfilteredForScheduler(ctx),
        keyDateRepo.listAllCalendarSyncsUnfilteredForScheduler(ctx),
        loadEffectiveTenantRbacConfig(ctx, undefined, tenantConfig),
      ]);
      const recipientRbacOptions: ResolvePersonPermissionsOptions = {
        allPeople: people,
        teams,
        config: { rbac: rbacConfig },
        tenantId: ctx.tenantId,
      };
      const actorRbacOptions: ResolvePersonPermissionsOptions = {
        ...recipientRbacOptions,
        tokenRoles: ctx.actorRoles,
        context: ctx,
        tokenRolesActorId: options.triggeredById,
      };

      if (options.triggerSource === 'manual') {
        const actorInTx = resolveActorFromPeopleForKeyDates(
          people,
          options.triggeredById,
        );
        if (
          !actorInTx ||
          !hasKeyDatePermission(actorInTx, 'keydate:configure', {
            config,
            allPeople: people,
            teams,
            rbac: actorRbacOptions,
          })
        ) {
          const permErr = new Error(
            'KEY_DATE_PERMISSION_DENIED: You need "keydate:configure" permission to trigger the key date reminder scheduler.',
          );
          (permErr as Error & { code?: string }).code =
            'KEY_DATE_PERMISSION_DENIED';
          throw permErr;
        }
      }

      // Collect any failed Outlook calendar syncs to retry strictly post-commit (R628),
      // respecting restricted-matter visibility unless running as a verified keydate:run_reminders job (R637).
      const snapshotKdById = new Map(keyDatesSnapshot.map((k) => [k.id, k]));
      const matterById = new Map(matters.map((m) => [m.id, m]));
      const isSystemSchedulerCtx =
        ctx.actorId.startsWith('system:') &&
        Boolean(ctx.actorSub?.startsWith('system:')) &&
        Boolean(ctx.jobPermissions?.includes('keydate:run_reminders'));
      const isMatterVisibleToRunContext = (matterId?: string): boolean => {
        if (isSystemSchedulerCtx || !matterId) return true;
        const m = matterById.get(matterId);
        if (!m) return false;
        const allowIds = m.restrictedAccessUserIds ?? [];
        const isRestricted =
          Boolean(m.isStaffMatter) ||
          Boolean(m.hasEthicalWall) ||
          allowIds.length > 0;
        return !isRestricted || allowIds.includes(ctx.actorId);
      };
      const failedSyncItems: Array<{
        keyDate: KeyDate;
        matter: Matter | null;
        enquiry: Enquiry | null;
      }> = [];
      for (const cs of calendarSyncsWorking) {
        if (cs.state !== 'failed') continue;
        const failedKd = snapshotKdById.get(cs.keyDateId);
        if (!failedKd || !isMatterVisibleToRunContext(failedKd.matterId)) continue;
        const failedEnquiry = failedKd.enquiryId
          ? ((await intakeRepo.getEnquiryById<Enquiry>(ctx, failedKd.enquiryId, {
              includeRestricted: true,
            })) ?? null)
          : null;
        failedSyncItems.push({
          keyDate: failedKd,
          matter: failedKd.matterId ? (matterById.get(failedKd.matterId) ?? null) : null,
          enquiry: failedEnquiry,
        });
      }
      postCommitFailedSyncItems = failedSyncItems;

      // Pass 1 (unlocked): determine which confirmed key dates require reminder/task changes
      const dryKeyDates = structuredClone(keyDatesSnapshot);
      const dryReminders = structuredClone(reminderStatesSnapshot);
      const dryTasks = structuredClone(storeTasksSnapshot);
      const beforeDryRemJsonByKd = new Map(
        dryReminders.map((rs) => [rs.keyDateId, JSON.stringify(rs)]),
      );
      const beforeDryTaskJsonById = new Map(
        dryTasks.map((t) => [t.id, JSON.stringify(t)]),
      );
      let dryTaskIdx = 0;
      let dryNotifIdx = 0;
      let dryAuditIdx = 0;

      const dryResult = runTenantBackgroundJob(
        {
          jobId: `keydate-reminder-scheduler:${ctx.tenantId}:${localDate}`,
          tenantId: ctx.tenantId,
          correlationId: ctx.correlationId,
          payload: { todayIso: localDate, nowIso },
        },
        (job) =>
          runTenantKeyDateReminderJob({
            tenantId: job.tenantId,
            actorId: options.triggeredById,
            todayIso: job.payload.todayIso,
            nowIso: job.payload.nowIso,
            config,
            keyDates: dryKeyDates,
            reminderStates: dryReminders,
            notApplicable: notApplicableSnapshot,
            tasks: dryTasks,
            matters,
            teams,
            people,
            rbacOptions: recipientRbacOptions,
            notifications: [],
            audit: [],
            nextTaskId: () => `TSK-DRY-${++dryTaskIdx}`,
            nextNotificationId: () => `NTF-DRY-${++dryNotifIdx}`,
            nextAuditId: () => `AU-DRY-${++dryAuditIdx}`,
          }),
      );

      const idempotencyKeyToKdId = new Map(
        keyDatesSnapshot.map((k) => [
          buildKeyDateReminderIdempotencyKey(k.id, ctx.tenantId),
          k.id,
        ]),
      );
      const linkTaskKeyDateId = (t: Task): string | undefined =>
        t.linkedKeyDateId ??
        (t.idempotencyKey ? idempotencyKeyToKdId.get(t.idempotencyKey) : undefined);

      const candidateKeyDateIdSet = new Set<string>();
      for (const rs of dryReminders) {
        if (beforeDryRemJsonByKd.get(rs.keyDateId) !== JSON.stringify(rs)) {
          candidateKeyDateIdSet.add(rs.keyDateId);
        }
      }
      const afterDryRemKdIds = new Set(dryReminders.map((rs) => rs.keyDateId));
      for (const prevKdId of beforeDryRemJsonByKd.keys()) {
        if (!afterDryRemKdIds.has(prevKdId)) {
          candidateKeyDateIdSet.add(prevKdId);
        }
      }
      for (const t of dryTasks) {
        if (beforeDryTaskJsonById.get(t.id) !== JSON.stringify(t)) {
          const kdId = linkTaskKeyDateId(t);
          if (kdId) candidateKeyDateIdSet.add(kdId);
        }
      }
      const afterDryTaskIds = new Set(dryTasks.map((t) => t.id));
      for (const t of storeTasksSnapshot) {
        if (!afterDryTaskIds.has(t.id)) {
          const kdId = linkTaskKeyDateId(t);
          if (kdId) candidateKeyDateIdSet.add(kdId);
        }
      }

      let manualRestrictedSkippedCount = 0;
      if (!isSystemSchedulerCtx) {
        for (const kdId of Array.from(candidateKeyDateIdSet)) {
          const kd = snapshotKdById.get(kdId);
          if (kd && !isMatterVisibleToRunContext(kd.matterId)) {
            candidateKeyDateIdSet.delete(kdId);
            manualRestrictedSkippedCount += 1;
          }
        }
      }

      const keyDatesForExceptionsMap = new Map(keyDatesSnapshot.map((k) => [k.id, k]));
      const remindersForExceptionsMap = new Map(
        reminderStatesSnapshot.map((r) => [r.keyDateId, r]),
      );
      let notApplicableWorking = notApplicableSnapshot;
      let result: ReturnType<typeof runTenantKeyDateReminderJob> = {
        ...dryResult,
        evaluatedCount: Math.max(0, dryResult.evaluatedCount - manualRestrictedSkippedCount),
        stagesAdvancedCount: 0,
        escalationsTriggeredCount: 0,
        notificationsSentCount: 0,
      };
      let changedReminders: KeyDateReminderState[] = [];
      let changedTasks: Task[] = [];
      let deletedTaskIds: string[] = [];
      let newTasksCount = 0;
      let stillSkippedIds: string[] = [];
      const createdNotifications: NotificationItem[] = [];
      const stagedAudit: AuditEntry[] = [];

      if (candidateKeyDateIdSet.size > 0) {
        // Pass 2 (R629, R638): lock ONLY candidates with FOR UPDATE SKIP LOCKED; if any are temporarily locked,
        // retry them once after a brief back-off pause before evaluating fresh DB state.
        const lockResult = await keyDateRepo.lockKeyDatesAndRemindersForSchedulerWrite(
          ctx,
          Array.from(candidateKeyDateIdSet),
        );
        let lockedKeyDates = lockResult.keyDates;
        let lockedReminderStates = lockResult.reminderStates;
        stillSkippedIds = lockResult.skippedKeyDateIds;

        if (stillSkippedIds.length > 0) {
          const retryDelayMs = Math.max(0, options.skippedLockRetryDelayMs ?? 50);
          if (retryDelayMs > 0) {
            await new Promise((resolve) => setTimeout(resolve, retryDelayMs));
          }
          const retryLock =
            await keyDateRepo.lockKeyDatesAndRemindersForSchedulerWrite(
              ctx,
              stillSkippedIds,
            );
          if (retryLock.keyDates.length > 0) {
            lockedKeyDates = [...lockedKeyDates, ...retryLock.keyDates].sort(
              (a, b) => a.id.localeCompare(b.id),
            );
            const mergedRemindersByKdId = new Map(
              lockedReminderStates.map((r) => [r.keyDateId, r]),
            );
            for (const rs of retryLock.reminderStates) {
              mergedRemindersByKdId.set(rs.keyDateId, rs);
            }
            lockedReminderStates = Array.from(mergedRemindersByKdId.values()).sort(
              (a, b) => a.keyDateId.localeCompare(b.keyDateId),
            );
          }
          stillSkippedIds = retryLock.skippedKeyDateIds;
        }

        const [storeTasksFresh, notApplicableFresh] = await Promise.all([
          taskRepo.listAllTasksUnfiltered<Task>(ctx),
          keyDateRepo.listAllNotApplicableUnfilteredForScheduler(ctx),
        ]);
        notApplicableWorking = notApplicableFresh;

        if (lockedKeyDates.length > 0) {
          const candidateKeyDates = structuredClone(lockedKeyDates);
          const candidateReminders = structuredClone(lockedReminderStates);
          const beforeReminderStageByKd = new Map(
            candidateReminders.map((rs) => [rs.keyDateId, rs.currentStageDaysBefore]),
          );
          const beforeReminderJsonByKd = new Map(
            candidateReminders.map((rs) => [rs.keyDateId, JSON.stringify(rs)]),
          );
          const beforeTaskJsonById = new Map(
            storeTasksFresh.map((t) => [t.id, JSON.stringify(t)]),
          );
          let pendingIdx = 0;
          let pendingTaskIdx = 0;
          let pendingNotifIdx = 0;

          const candidateResult = runTenantKeyDateReminderJob({
            tenantId: ctx.tenantId,
            actorId: options.triggeredById,
            todayIso: localDate,
            nowIso,
            config,
            keyDates: candidateKeyDates,
            reminderStates: candidateReminders,
            notApplicable: notApplicableFresh,
            tasks: storeTasksFresh,
            matters,
            teams,
            people,
            rbacOptions: recipientRbacOptions,
            notifications: createdNotifications,
            audit: stagedAudit,
            nextTaskId: () => `TSK-PENDING-${++pendingTaskIdx}`,
            nextNotificationId: () => `NTF-PENDING-${++pendingNotifIdx}`,
            nextAuditId: () => `AU-PENDING-${++pendingIdx}`,
          });

          result = {
            ...candidateResult,
            evaluatedCount: Math.max(
              0,
              dryResult.evaluatedCount -
                (stillSkippedIds.length + manualRestrictedSkippedCount),
            ),
          };

          changedTasks = storeTasksFresh.filter(
            (t) => beforeTaskJsonById.get(t.id) !== JSON.stringify(t),
          );
          newTasksCount = changedTasks.filter((t) =>
            t.id.startsWith('TSK-PENDING-'),
          ).length;
          const currentIds = new Set(storeTasksFresh.map((t) => t.id));
          deletedTaskIds = [...beforeTaskJsonById.keys()].filter(
            (id) => !currentIds.has(id),
          );
          changedReminders = candidateReminders.filter(
            (rs) => beforeReminderJsonByKd.get(rs.keyDateId) !== JSON.stringify(rs),
          );

          for (const rs of changedReminders) {
            const alreadyAudited = stagedAudit.some(
              (a) => a.recordId === rs.keyDateId,
            );
            if (!alreadyAudited) {
              const prevStage = beforeReminderStageByKd.get(rs.keyDateId);
              stagedAudit.push({
                id: `AU-PENDING-${++pendingIdx}`,
                recordType: 'key_date',
                recordId: rs.keyDateId,
                action: 'update',
                field: 'currentStageDaysBefore',
                oldValue: prevStage !== undefined ? String(prevStage) : null,
                newValue: String(rs.currentStageDaysBefore),
                byId: options.triggeredById,
                at: nowIso,
                reason: `Key date reminder stage evaluated (${localDate})`,
              });
            }
          }

          if (
            changedReminders.length > 0 ||
            changedTasks.length > 0 ||
            deletedTaskIds.length > 0 ||
            createdNotifications.length > 0 ||
            stagedAudit.length > 0
          ) {
            await commitKeyDateDomainWritesInPostgres({
              ctx,
              reminderStatesToUpsert: changedReminders,
              tasksToUpsert: changedTasks,
              tasksToDeleteIds: deletedTaskIds,
              notificationsToUpsert: createdNotifications,
              auditEntries: stagedAudit,
            });
          }

          for (const kd of candidateKeyDates) {
            keyDatesForExceptionsMap.set(kd.id, kd);
          }
          for (const rs of candidateReminders) {
            remindersForExceptionsMap.set(rs.keyDateId, rs);
          }
        } else {
          result = {
            ...result,
            evaluatedCount: Math.max(
              0,
              dryResult.evaluatedCount -
                (stillSkippedIds.length + manualRestrictedSkippedCount),
            ),
          };
        }
      }

      const skippedCount = stillSkippedIds.length + manualRestrictedSkippedCount;
      const keyDatesWorking = Array.from(keyDatesForExceptionsMap.values());
      const reminderStatesWorking = Array.from(remindersForExceptionsMap.values());

      const syntheticViewer: Person =
        people.find((p) => p.id === options.triggeredById) ??
        ({
          id: options.triggeredById,
          firstName: 'System',
          surname: 'Scheduler',
          isEmployee: true,
          roles: ['admin'],
          appRole: 'admin',
        } as unknown as Person);
      const exceptions = computeKeyDateExceptions({
        viewer: syntheticViewer,
        todayIso: localDate,
        nowIso,
        config,
        keyDates: keyDatesWorking,
        notApplicable: notApplicableWorking,
        reminderStates: reminderStatesWorking,
        calendarSyncs: calendarSyncsWorking,
        matters,
        teams,
        people,
        rbacOptions: actorRbacOptions,
        values,
      });

      const summary: KeyDateRemindersJobSummary = {
        evaluatedCount: result.evaluatedCount,
        stagesAdvancedCount: result.stagesAdvancedCount,
        remindersSent: changedReminders.length,
        tasksCreated: newTasksCount,
        notificationsCreated: createdNotifications.length,
        escalationsSent: result.escalationsTriggeredCount,
        exceptionsFound: exceptions.length,
        skippedCount,
      };

      return {
        result: { result, summary },
        summary,
        ...(skippedCount > 0 ? { deferDailyCompletion: true } : {}),
      };
    },
  });

  if (
    jobOutcome.outcome === 'executed' &&
    postCommitFailedSyncItems.length > 0 &&
    options.calendarAdapter &&
    !(
      options.calendarAdapter instanceof ManagedIdentityGraphCalendarAdapter &&
      !options.calendarAdapter.isConfigured
    )
  ) {
    await runPostCommitKeyDateCalendarSync({
      ctx,
      nowIso: new Date().toISOString(),
      items: postCommitFailedSyncItems,
      adapter: options.calendarAdapter,
    });
  }

  return jobOutcome;
}

export interface UsageRetentionPurgeJobSummary extends Record<string, number> {
  readonly purgedEventsCount: number;
  readonly purgedSummaryBucketsCount: number;
  readonly retentionMonths: number;
}

export interface ExecuteUsageRetentionPurgeForTenantOptions {
  readonly triggerSource?: 'scheduled' | 'manual';
  readonly triggeredById?: string;
  readonly timeZone?: string;
  readonly defaultRunHourLocal?: number;
  readonly statementTimeoutMs?: number;
  readonly tenantConfig?: TenantConfiguration;
  readonly signal?: AbortSignal;
}

/**
 * Single-transaction per-tenant document-generation usage retention purge job
 * (`system:usage-retention-purge`, ADR 0030 §§4–6 / Slice S0-19).
 */
export async function executeUsageRetentionPurgeForTenant(
  ctx: TenantContext,
  options: ExecuteUsageRetentionPurgeForTenantOptions = {},
): Promise<
  ControlledJobRunOutcome<{
    purgedEventsCount: number;
    purgedSummaryBucketsCount: number;
    retentionMonths: number;
  }>
> {
  const tenantConfig = resolveVerifiedTenantConfiguration(
    ctx,
    options.tenantConfig,
  );
  const effectiveTimeZone =
    options.timeZone?.trim() || tenantConfig.timeZone || 'Europe/London';
  const triggeredById =
    options.triggeredById?.trim() || 'system:usage-retention-purge';
  const now = new Date();
  const nowIso = now.toISOString();

  return getJobRunRepository().executeControlledTenantJobRun(ctx, {
    jobKey: 'usage-retention-purge',
    triggerSource: options.triggerSource ?? 'scheduled',
    triggeredById,
    timeZone: effectiveTimeZone,
    targetLocalHour: options.defaultRunHourLocal ?? 2,
    now,
    statementTimeoutMs: options.statementTimeoutMs,
    signal: options.signal,
    work: async ({ localDate }) => {
      const docRepo = getDocumentRepository();
      const effectiveConfig = await getEffectiveTenantConfig(
        ctx,
        docRepo,
        tenantConfig,
      );
      const retentionMonths =
        effectiveConfig.documentGeneration.usage.retentionMonths ??
        tenantConfig.documentGeneration.usage.retentionMonths;

      const purged = await executeUsageRetentionPurgeJob(ctx, docRepo, {
        jobId: `usage-retention-purge:${ctx.tenantId}:${localDate}`,
        tenantId: ctx.tenantId,
        correlationId: ctx.correlationId,
        payload: {
          retentionMonths,
          nowIso,
        },
      });

      await appendTenantAuditEntries(ctx, [
        {
          recordType: 'matter',
          recordId: 'FIRM-DOCGEN-USAGE-RETENTION',
          action: 'update',
          field: 'documentGeneration.usage.retentionMonths',
          oldValue: null,
          newValue: `purgedEvents=${purged.purgedEventsCount}; purgedSummaries=${purged.purgedSummaryBucketsCount}; retentionMonths=${retentionMonths}`,
          byId: triggeredById,
          at: nowIso,
          reason: `Scheduled usage retention purge (${localDate})`,
        },
      ]);

      const summary: UsageRetentionPurgeJobSummary = {
        purgedEventsCount: purged.purgedEventsCount,
        purgedSummaryBucketsCount: purged.purgedSummaryBucketsCount,
        retentionMonths,
      };

      return {
        result: summary,
        summary,
      };
    },
  });
}

function assertTestOnlyTenantConfigOverride(
  override: Record<string, TenantConfiguration> | undefined,
): void {
  if (override && process.env.NODE_ENV !== 'test') {
    throw new Error(
      'SECURITY_ERROR: tenantConfigOverrideByTenantId is only permitted when NODE_ENV === "test".',
    );
  }
}

export async function runScheduledEnquiryRetentionAnonymisationJobSweep(options?: {
  readonly registry?: TenantRegistry;
  readonly timeoutMs?: number;
  readonly defaultRunHourLocal?: number;
  readonly guardedJobOptions?: GuardedJobOptions;
  readonly tenantConfigOverrideByTenantId?: Record<string, TenantConfiguration>;
}): Promise<ScheduledTenantJobSweepSummary> {
  assertTestOnlyTenantConfigOverride(options?.tenantConfigOverrideByTenantId);
  const registry = options?.registry ?? loadActiveTenantRegistry();
  const succeededTenants: string[] = [];
  const skippedTenants: Array<{
    readonly tenantId: string;
    readonly status: 'skipped' | 'already_running';
    readonly reason?: string;
  }> = [];
  const failedTenants: Array<{
    readonly tenantId: string;
    readonly errorCode?: string;
  }> = [];

  for (const entry of registry.tenants) {
    if (!entry.enabled) {
      continue;
    }
    try {
      const outcome = await guardedJob(
        'enquiry-retention-anonymise',
        entry,
        async ({ tenantContext, tenantEntry, timeoutMs, signal }) => {
          const tenantConfig =
            options?.tenantConfigOverrideByTenantId?.[tenantEntry.tenantId] ??
            getTenantConfigurationForRegistryEntry(
              tenantEntry,
              registry.hostingMode,
            );
          return runEnquiryRetentionAnonymisationForTenant(tenantContext, {
            triggerSource: 'scheduled',
            actorId: 'system:enquiry-retention-anonymise',
            timeZone: tenantEntry.timeZone,
            defaultRunHourLocal: options?.defaultRunHourLocal ?? 2,
            statementTimeoutMs: timeoutMs,
            tenantConfig,
            signal,
          });
        },
        {
          registry,
          timeoutMs: options?.timeoutMs,
          ...options?.guardedJobOptions,
        },
      );
      if (outcome.outcome === 'executed') {
        succeededTenants.push(entry.tenantId);
      } else {
        skippedTenants.push({
          tenantId: entry.tenantId,
          status:
            outcome.outcome === 'already_running'
              ? 'already_running'
              : 'skipped',
          reason: outcome.outcome,
        });
      }
    } catch (err) {
      failedTenants.push({
        tenantId: entry.tenantId,
        errorCode: sanitizeJobErrorCode(err),
      });
    }
  }

  return {
    exitCode: failedTenants.length > 0 ? 1 : 0,
    succeededTenants,
    skippedTenants,
    failedTenants,
  };
}

export interface ScheduledTenantJobSweepSummary {
  readonly exitCode: number;
  readonly succeededTenants: string[];
  readonly skippedTenants: Array<{
    readonly tenantId: string;
    readonly status: 'skipped' | 'already_running';
    readonly reason?: string;
  }>;
  readonly failedTenants: Array<{
    readonly tenantId: string;
    readonly errorCode?: string;
  }>;
}

