export async function runKeyDateReminderSchedulerRecord(
  options?: {
    tenantCtx?: TenantContext | null;
    session?: VerifiedEntraSessionPayload | null;
    byId: string;
    mfaVerified?: boolean;
  } | null,
): Promise<{
  ok: boolean;
  result?: ReturnType<typeof runTenantKeyDateReminderJob>;
  jobRun?: JobRunRecord;
  jobStatus?: 'succeeded' | 'skipped' | 'already_running';
  triggeredBy?: string;
  error?: string;
}> {
  if (
    !options ||
    typeof options !== 'object' ||
    options.tenantCtx === null ||
    (!options.tenantCtx && !options.byId && !options.session)
  ) {
    runTenantBackgroundJob(
      {
        jobId: 'keydate-reminder-job:missing-context',
        tenantId: '',
        correlationId: '',
        payload: {},
      },
      () => undefined,
    );
  }

  const requestedById = (options?.byId ?? '').trim();
  const providedCtx = options?.tenantCtx ?? null;
  const verifiedSession =
    options?.session ??
    (getActiveActorSession()?.verifiedSession as
      | VerifiedEntraSessionPayload
      | undefined);

  if (providedCtx && requestedById && providedCtx.actorId !== requestedById) {
    throw new Error(
      `TENANCY_ACTOR_MISMATCH: Tenant context actorId "${providedCtx.actorId}" does not match requested actor "${requestedById}".`,
    );
  }
  if (verifiedSession && requestedById && verifiedSession.personId !== requestedById) {
    throw new Error(
      `TENANCY_ACTOR_MISMATCH: Verified session personId "${verifiedSession.personId}" does not match requested actor "${requestedById}".`,
    );
  }

  const effectiveTenantCtx =
    providedCtx ??
    (verifiedSession
      ? resolveCurrentTenantContext(
          createVerifiedSessionActorFromEntraSession(verifiedSession),
        )
      : null);

  if (
    effectiveTenantCtx &&
    requestedById &&
    effectiveTenantCtx.actorId !== requestedById
  ) {
    throw new Error(
      `TENANCY_ACTOR_MISMATCH: Tenant context actorId "${effectiveTenantCtx.actorId}" does not match requested actor "${requestedById}".`,
    );
  }

  const actorId = effectiveTenantCtx?.actorId ?? requestedById;
  // Take MFA from the verified context when present; never let a caller flag override a non-MFA context (R449).
  const mfaVerified = effectiveTenantCtx
    ? effectiveTenantCtx.mfaVerified === true && options?.mfaVerified !== false
    : options?.mfaVerified === true;

  let prelimPeople: Person[] = [];
  let prelimTeams: Team[] = [];
  try {
    const readPeopleCtx =
      effectiveTenantCtx ??
      resolveDefaultServiceTenantContext(null, null);
    [prelimPeople, prelimTeams] = await Promise.all([
      loadStaffPeople(readPeopleCtx),
      getHrAndRbacRepository().listAllTeams<Team>(readPeopleCtx),
    ]);
  } catch {
    prelimPeople = [];
    prelimTeams = [];
  }
  const actor = resolveActorFromPeopleForKeyDates(prelimPeople, actorId);
  if (!actor) {
    return { ok: false, error: `Unknown or unauthenticated user "${actorId}".` };
  }

  // Evaluate permission and MFA before reading any key-date repository or configuration rows from PostgreSQL (R449).
  const inMemoryKeyDatesConfig =
    getActiveTenantConfiguration().keyDates as KeyDatesConfig | undefined;
  if (
    !hasKeyDatePermission(actor, 'keydate:configure', {
      config: inMemoryKeyDatesConfig,
      allPeople: prelimPeople,
      teams: prelimTeams,
      rbac: effectiveTenantCtx
        ? {
            tokenRoles: effectiveTenantCtx.actorRoles,
            context: effectiveTenantCtx,
            tokenRolesActorId: actor.id,
          }
        : undefined,
    })
  ) {
    return {
      ok: false,
      error:
        'KEY_DATE_PERMISSION_DENIED: You need "keydate:configure" permission to trigger the key date reminder scheduler.',
    };
  }

  const configurePermDef = PERMISSION_REGISTRY['keydate:configure'];
  if ((configurePermDef?.requiresMfa ?? true) && mfaVerified !== true) {
    return {
      ok: false,
      error:
        'MFA_REQUIRED: Multi-factor authentication (MFA) is required to trigger the key date reminder scheduler.',
    };
  }

  if (!effectiveTenantCtx) {
    runTenantBackgroundJob(
      {
        jobId: 'keydate-reminder-job:missing-context',
        tenantId: '',
        correlationId: '',
        payload: {},
      },
      () => undefined,
    );
  }

  try {
    const outcome = await executeKeyDateRemindersForTenant(effectiveTenantCtx!, {
      triggerSource: 'manual',
      triggeredById: actor.id,
    });

    if (outcome.outcome === 'executed') {
      return {
        ok: true,
        result: outcome.result.result,
        jobRun: outcome.jobRun,
        jobStatus: 'succeeded',
        triggeredBy: actor.id,
      };
    }

    return {
      ok: true,
      result: {
        tenantId: effectiveTenantCtx!.tenantId,
        evaluatedCount: 0,
        stagesAdvancedCount: 0,
        escalationsTriggeredCount: 0,
        notificationsSentCount: 0,
      },
      jobStatus:
        outcome.outcome === 'already_running' ? 'already_running' : 'skipped',
      triggeredBy: actor.id,
    };
  } catch (err) {
    return {
      ok: false,
      error:
        err instanceof Error
          ? err.message
          : 'Failed to execute key date reminder scheduler.',
    };
  }
}

export async function queryKeyDatesTeamDiaryRecord(
  query: TeamDiaryQuery,
  byId: string,
  todayIso: string = toIsoDate(new Date()),
): Promise<TeamDiaryEntry[]> {
  let resolved: Awaited<ReturnType<typeof resolveKeyDatesActorAndData>> = null;
  try {
    resolved = await resolveKeyDatesActorAndData(null, byId, {
      includeVisibleMatters: true,
    });
  } catch {
    resolved = null;
  }
  if (!resolved || !resolved.actor) return [];
  const { ctx, actor: viewer, people, matters, teams, rbacOptions } = resolved;
  const config = await getKeyDatesConfig({ ctx, userId: viewer.id });
  const keyDateRepo = getKeyDateRepository();
  const intakeRepo = getIntakeQuoteRepository();
  const hasRestrictedMatterAccess = hasPersonPermission(
    viewer,
    'matter:restricted:access',
    rbacOptions,
  );
  const [keyDates, reminderStates, enquiries] = await Promise.all([
    keyDateRepo.listAllVisibleKeyDates(ctx, viewer.id),
    keyDateRepo.listAllReminderStates(ctx, viewer.id),
    intakeRepo.listVisibleEnquiries<Enquiry>(ctx, viewer.id, {
      hasRestrictedMatterAccess,
    }),
  ]);
  const visibleMatters = matters.filter((m) =>
    canPersonAccessMatter(m, viewer.id, viewer, rbacOptions),
  );
  return queryTeamDiaryEntries({
    viewer,
    query,
    todayIso,
    config,
    keyDates,
    reminderStates,
    matters: visibleMatters,
    enquiries,
    teams,
    people,
    rbacOptions,
  });
}

export async function getKeyDateExceptionsReportRecord(
  filter: { teamIds?: string[]; kinds?: KeyDateExceptionKind[] } = {},
  byId: string,
  todayIso: string = toIsoDate(new Date()),
): Promise<KeyDateException[]> {
  let resolved: Awaited<ReturnType<typeof resolveKeyDatesActorAndData>> = null;
  try {
    resolved = await resolveKeyDatesActorAndData(null, byId, {
      includeVisibleMatters: true,
    });
  } catch {
    resolved = null;
  }
  if (!resolved || !resolved.actor) return [];
  const { ctx, actor: viewer, people, matters, teams, rbacOptions } = resolved;
  const config = await getKeyDatesConfig({ ctx, userId: viewer.id });
  const canConfigure = hasKeyDatePermission(viewer, 'keydate:configure', {
    config,
    allPeople: people,
    teams,
    rbac: rbacOptions,
  });
  const keyDateRepo = getKeyDateRepository();
  const [keyDates, notApplicable, reminderStates, calendarSyncs, values] =
    await Promise.all([
      keyDateRepo.listKeyDatesForExceptionsReport(ctx, viewer.id, {
        includeMissingMatterOrphans: canConfigure,
      }),
      keyDateRepo.listAllVisibleNotApplicable(ctx, viewer.id),
      keyDateRepo.listAllReminderStates(ctx, viewer.id),
      keyDateRepo.listAllVisibleCalendarSyncs(ctx, viewer.id),
      getCatalogueRepository().listAllChoiceValues<ChoiceValue>(ctx),
    ]);
  const visibleMatters = matters.filter((m) =>
    canPersonAccessMatter(m, viewer.id, viewer, rbacOptions),
  );
  return computeKeyDateExceptions({
    viewer,
    todayIso,
    nowIso: new Date().toISOString(),
    config,
    keyDates,
    notApplicable,
    reminderStates,
    calendarSyncs,
    matters: visibleMatters,
    teams,
    people,
    values,
    filterTeamIds: filter.teamIds,
    filterKinds: filter.kinds,
    rbacOptions,
  });
}

export async function exportKeyDateExceptionsReportRecord(
  filter: {
    teamIds?: string[];
    kinds?: KeyDateExceptionKind[];
    format?: 'csv' | 'json';
  } = {},
  byId: string,
  todayIso: string = toIsoDate(new Date()),
): Promise<{ ok: boolean; content?: string; filename?: string; count?: number; error?: string }> {
  let resolved: Awaited<ReturnType<typeof resolveKeyDatesActorAndData>> = null;
  try {
    resolved = await resolveKeyDatesActorAndData(null, byId);
  } catch {
    resolved = null;
  }
  if (!resolved || !resolved.actor) {
    return { ok: false, error: `Unknown or unauthenticated user "${byId}".` };
  }
  const { ctx, actor: viewer, people, teams } = resolved;
  const config = await getKeyDatesConfig({ ctx, userId: viewer.id });

  if (
    !hasKeyDatePermission(viewer, 'keydate:view_any_team', {
      config,
      allPeople: people,
      teams,
    })
  ) {
    return {
      ok: false,
      error: 'You need "keydate:view_any_team" to view or export compliance exceptions.',
    };
  }

  const exceptions = await getKeyDateExceptionsReportRecord(filter, byId, todayIso);
  const format = filter.format ?? 'csv';
  const nowIso = new Date().toISOString();

  // Audit the compliance exceptions export in PostgreSQL audit_entries (§6, R41, S0-15)
  await appendTenantAuditEntries(ctx, [
    {
      recordType: 'key_date',
      recordId: 'KEY-DATE-EXCEPTIONS-EXPORT',
      action: 'keydate-export',
      field: 'Compliance exceptions export',
      oldValue: null,
      newValue: `Exported ${exceptions.length} exception(s) as ${format.toUpperCase()}`,
      byId: viewer.id,
      at: nowIso,
      reason: `Filter teams=${filter.teamIds?.join(',') || 'all'} kinds=${filter.kinds?.join(',') || 'all'}`,
    },
  ]);

  if (format === 'json') {
    return {
      ok: true,
      content: JSON.stringify(exceptions, null, 2),
      filename: `key-date-exceptions-${todayIso}.json`,
      count: exceptions.length,
    };
  }

  const header = 'Kind,TeamId,MatterId,KeyDateId,DetectedAt,Detail';
  const escapeCsv = (val: string | undefined) =>
    `"${String(val ?? '').replace(/"/g, '""')}"`;
  const rows = exceptions.map((ex) =>
    [
      escapeCsv(ex.kind),
      escapeCsv(ex.teamId),
      escapeCsv(ex.matterId),
      escapeCsv(ex.keyDateId),
      escapeCsv(ex.detectedAt),
      escapeCsv(ex.detail),
    ].join(','),
  );
  return {
    ok: true,
    content: [header, ...rows].join('\n'),
    filename: `key-date-exceptions-${todayIso}.csv`,
    count: exceptions.length,
  };
}

export async function saveKeyDatesConfigRecord(
  newConfigInput: KeyDatesConfig,
  reason: string,
  byId: string,
  options?: { mfaVerified?: boolean } | boolean,
): Promise<{ ok: boolean; config?: KeyDatesConfig; error?: string }> {
  try {
    const prelimCtx = resolvePrelimKeyDatesTenantContext(byId);
    if (!prelimCtx) {
      return { ok: false, error: `Unknown or unauthenticated user "${byId}".` };
    }
    const keyDateRepo = getKeyDateRepository();

    return await keyDateRepo.withTenantTransaction(prelimCtx, async () => {
      const resolved = await resolveKeyDatesActorAndData(null, byId);
      if (!resolved || !resolved.actor) {
        return { ok: false, error: `Unknown or unauthenticated user "${byId}".` };
      }
      const { ctx, actor, people, teams } = resolved;
      const permCheckConfig = await getKeyDatesConfig({ ctx, userId: actor.id });

      if (
        !hasKeyDatePermission(actor, 'keydate:configure', {
          config: permCheckConfig,
          allPeople: people,
          teams,
        })
      ) {
        return {
          ok: false,
          error: 'You need "keydate:configure" permission to modify Key Dates configuration.',
        };
      }

      const mfaVerified =
        typeof options === 'boolean' ? options : options?.mfaVerified;
      const configurePermDef = PERMISSION_REGISTRY['keydate:configure'];
      if ((configurePermDef?.requiresMfa ?? true) && mfaVerified !== true) {
        return {
          ok: false,
          error:
            'MFA_REQUIRED: Multi-factor authentication (MFA) is required to modify Key Dates configuration.',
        };
      }

      for (const rs of newConfigInput.limitationRuleSets ?? []) {
        const rawStatus = (rs as { reviewStatus?: unknown }).reviewStatus;
        if (rawStatus !== 'reviewed' && rawStatus !== 'unreviewed') {
          return {
            ok: false,
            error: `Invalid reviewStatus "${String(rawStatus)}" on limitation rule set "${rs.id}". Expected "reviewed" or "unreviewed".`,
          };
        }
      }

      const validated = validateKeyDatesConfig(newConfigInput) as unknown as KeyDatesConfig;

      // R617: Acquire advisory lock + ensure default row exists (ON CONFLICT DO NOTHING) + FOR UPDATE AFTER permission & MFA checks
      const currentConfig = (await keyDateRepo.ensureAndLockKeyDatesTenantConfig(
        ctx,
        permCheckConfig as unknown as KeyDatesConfiguration,
        actor.id,
      )) as unknown as KeyDatesConfig;

      const nowIso = new Date().toISOString();
      const todayIso = nowIso.slice(0, 10);
      const prevRuleSetsById = new Map(
        (currentConfig.limitationRuleSets ?? []).map((rs) => [rs.id, rs]),
      );
      if (validated.limitationRuleSets) {
        validated.limitationRuleSets = validated.limitationRuleSets.map((rs) => {
          if (rs.reviewStatus === 'unreviewed') {
            const nextUnreviewed = { ...rs, reviewStatus: 'unreviewed' as const };
            delete nextUnreviewed.reviewedBy;
            delete nextUnreviewed.reviewedOn;
            return nextUnreviewed;
          }
          const prev = prevRuleSetsById.get(rs.id);
          const keepPreviousReviewer =
            prev?.reviewStatus === 'reviewed' &&
            prev.version === rs.version &&
            Boolean(prev.reviewedBy);
          return {
            ...rs,
            reviewStatus: 'reviewed' as const,
            reviewedBy: keepPreviousReviewer ? prev!.reviewedBy : actor.id,
            reviewedOn: keepPreviousReviewer
              ? (prev!.reviewedOn ?? todayIso)
              : todayIso,
          };
        });
      }

      await keyDateRepo.putKeyDatesTenantConfig(
        ctx,
        validated as unknown as KeyDatesConfiguration,
        actor.id,
      );
      await appendTenantAuditEntries(ctx, [
        {
          recordType: 'key_date',
          recordId: 'FIRM-KEY-DATES-CONFIG',
          action: 'keydate-config-change',
          field: 'keyDates',
          oldValue: `enabled=${currentConfig.enabled}; types=${currentConfig.keyDateTypes?.length ?? 0}; ruleSets=${currentConfig.limitationRuleSets?.length ?? 0}`,
          newValue: `enabled=${validated.enabled}; types=${validated.keyDateTypes?.length ?? 0}; ruleSets=${validated.limitationRuleSets?.length ?? 0}`,
          byId: actor.id,
          at: nowIso,
          reason: reason?.trim() || 'Updated Key Dates configuration in Admin',
          snapshot: {
            before: currentConfig,
            after: validated,
          },
        },
      ]);

      return { ok: true, config: validated };
    });
  } catch (err) {
    return {
      ok: false,
      error:
        err instanceof Error
          ? err.message
          : 'Invalid Key Dates configuration.',
    };
  }
}

export async function saveWorkTypesConfigRecord(
  newConfigInput: WorkTypesConfiguration,
  reason: string,
  byId?: string,
  options?: { mfaVerified?: boolean } | boolean,
): Promise<{
  ok: boolean;
  config?: WorkTypesConfiguration;
  error?: string;
  message?: string;
  code?: 'FORBIDDEN' | 'MFA_REQUIRED' | 'VALIDATION_ERROR' | FeeCapErrorCode;
}> {
  let ctx: TenantContext;
  try {
    ctx = resolveDefaultServiceTenantContext(null, byId);
  } catch {
    return {
      ok: false,
      code: 'FORBIDDEN',
      error: 'Unauthenticated: Signed-in session is required to modify work-type configuration.',
    };
  }

  const effectiveActorId = byId || ctx.actorId;
  const sessionActor = getActiveActorSession();
  const explicitMfa = typeof options === 'boolean' ? options : options?.mfaVerified;
  const mfaVerified =
    explicitMfa !== undefined ? explicitMfa === true : sessionActor?.mfaVerified === true;

  const [store, people, teams, rbacConfig] = await Promise.all([
    loadTenantCatalogueStoreView(ctx),
    loadStaffPeople(ctx),
    getHrAndRbacRepository().listAllTeams<Team>(ctx),
    loadEffectiveTenantRbacConfig(ctx),
  ]);
  const actor =
    people.find((p) => p.id === effectiveActorId || p.id === ctx.actorId) ?? null;

  if (
    !actor ||
    !actor.isEmployee ||
    !hasPersonPermission(actor, 'admin:access', {
      allPeople: people,
      teams,
      mfaVerified: true,
      config: { rbac: rbacConfig },
    })
  ) {
    return {
      ok: false,
      code: 'FORBIDDEN',
      error: 'Forbidden: admin:access permission is required to modify work-type configuration.',
    };
  }

  if (mfaVerified !== true) {
    return {
      ok: false,
      code: 'MFA_REQUIRED',
      error: 'MFA_REQUIRED: Multi-factor authentication is required to modify work-type configuration.',
    };
  }

  let validated: WorkTypesConfiguration;
  try {
    validated = validateWorkTypesConfig(newConfigInput);
  } catch (err) {
    const errMessage =
      err instanceof Error ? err.message : 'Invalid work-type configuration.';
    const feeCapCodeMatch = new RegExp(
      `\\b(${FEE_CAP_CONFIG_EXCEEDS_STATUTORY_CODE}|${FEE_CAP_BASE_MISMATCH_CODE}|${FEE_CAP_CATEGORY_UNMAPPED_CODE})\\b`,
    ).exec(errMessage);
    const code: 'VALIDATION_ERROR' | FeeCapErrorCode = feeCapCodeMatch
      ? (feeCapCodeMatch[1] as FeeCapErrorCode)
      : 'VALIDATION_ERROR';
    return {
      ok: false,
      code,
      error: errMessage,
      message: errMessage,
    };
  }

  const activeTenantCfg = getActiveTenantConfiguration();
  const previousEffective =
    store.workTypesConfig ??
    resolveEffectiveWorkTypesConfig(activeTenantCfg, store.workTypeConfigsOverride ?? null);
  const nextEffective = resolveEffectiveWorkTypesConfig(activeTenantCfg, validated);
  const countOverrides = (cfg: WorkTypesConfiguration) =>
    (cfg.items ?? []).reduce(
      (sum, item) => sum + (item.workTypeCapOverrides?.length ?? 0),
      0,
    );
  const catalogueRepo = getCatalogueRepository();
  const nowIso = new Date().toISOString();

  await catalogueRepo.withTenantTransaction(ctx, async () => {
    await catalogueRepo.putWorkTypeConfigs(ctx, validated, actor.id);
    await appendTenantAuditEntries(ctx, [
      {
        recordType: 'system',
        recordId: 'FIRM-WORK-TYPES-CONFIG',
        action: 'update',
        field: 'workTypes',
        oldValue: `defaultsRetention=${previousEffective.defaults?.retention?.retentionYears ?? 6}; items=${previousEffective.items?.length ?? 0}; capOverrides=${countOverrides(previousEffective)}`,
        newValue: `defaultsRetention=${nextEffective.defaults?.retention?.retentionYears ?? 6}; items=${nextEffective.items?.length ?? 0}; capOverrides=${countOverrides(nextEffective)}`,
        byId: actor.id,
        at: nowIso,
        reason: reason?.trim() || 'Updated work-type configuration in Admin',
        snapshot: {
          before: store.workTypeConfigsOverride ?? null,
          after: validated,
        },
      },
    ]);
  });

  return { ok: true, config: nextEffective };
}

export async function updateMatterLifecycleStatusRecord(
  matterId: string,
  action: 'close' | 'reopen',
  opts: {
    closedAt?: string | null;
    reason?: string;
    expectedRowVersion?: number | null;
  } = {},
  byId?: string,
): Promise<{
  matter: Matter | null;
  errors?: Record<string, string>;
  code?: string;
  message?: string;
}> {
  let ctx: TenantContext;
  try {
    ctx = resolveDefaultServiceTenantContext(null, byId);
  } catch {
    return {
      matter: null,
      code: 'UNAUTHENTICATED',
      message: 'UNAUTHENTICATED: Verified session is required.',
      errors: { permission: 'Unauthenticated: Verified session is required.' },
    };
  }

  const actorId = byId || ctx.actorId;
  const matterRepo = getMatterRepository();
  const partyRepo = getPartyRepository();
  const hrRepo = getHrAndRbacRepository();
  const catalogueRepo = getCatalogueRepository();
  const tenantCfg = getActiveTenantConfiguration();

  return runWithAuditStagingScope(async () => {
    const stagedAuditMark = getStagedAuditWatermark();
    let auditFlushed = false;
    try {
      return await matterRepo.withTenantTransaction(
        ctx,
        async (
          tx,
        ): Promise<{
          matter: Matter | null;
          errors?: Record<string, string>;
          code?: string;
          message?: string;
        }> => {
        await tx.query(
          'SELECT id FROM public.matters WHERE tenant_id = $1 AND id = $2 FOR UPDATE',
          [ctx.tenantId, matterId],
        );

        const existing = await matterRepo.getMatterById<Matter>(ctx, matterId, {
          includeRestricted: true,
        });
        const people = await loadStaffPeople(ctx);
        const teams = await hrRepo.listAllTeams<Team>(ctx);
        const rbacConfig = await loadEffectiveTenantRbacConfig(ctx);
        const dbMatterStatusValues =
          await catalogueRepo.listChoiceValuesForList<ChoiceValue>(
            ctx,
            'matter_status',
          );
        const allDbValues =
          await catalogueRepo.listAllChoiceValues<ChoiceValue>(ctx);

        const actingUser = people.find((p) => p.id === actorId) ?? null;
        if (
          !existing ||
          !actingUser ||
          !actingUser.isEmployee ||
          !canPersonAccessMatter(existing, actingUser.id, actingUser, {
            allPeople: people,
            teams,
            config: { rbac: rbacConfig },
          })
        ) {
          return {
            matter: null,
            code: 'NOT_FOUND',
            message: 'NOT_FOUND: Matter not found or restricted.',
            errors: { access: 'Matter not found or restricted.' },
          };
        }

        if (
          !hasPersonPermission(actingUser, 'matter:edit', {
            allPeople: people,
            teams,
            config: { rbac: rbacConfig },
          })
        ) {
          return {
            matter: null,
            code: 'FORBIDDEN',
            message:
              'FORBIDDEN: You do not have permission (matter:edit) to update matter status.',
            errors: {
              permission:
                'You do not have permission (matter:edit) to update matter status.',
            },
          };
        }

        const existingRowVersion =
          (existing as Matter & { rowVersion?: number }).rowVersion ?? 1;
        if (
          opts.expectedRowVersion !== undefined &&
          opts.expectedRowVersion !== null &&
          (typeof opts.expectedRowVersion !== 'number' ||
            !Number.isInteger(opts.expectedRowVersion) ||
            opts.expectedRowVersion < 1 ||
            opts.expectedRowVersion !== existingRowVersion)
        ) {
          return {
            matter: null,
            code: MATTER_CONCURRENCY_CONFLICT_CODE,
            message: MATTER_CONCURRENCY_CONFLICT_MESSAGE,
            errors: { conflict: MATTER_CONCURRENCY_CONFLICT_MESSAGE },
          };
        }

        const trimmedSuppliedClosedAt =
          typeof opts.closedAt === 'string' ? opts.closedAt.trim() : '';
        const currentlyClosedOrArchived = isClosedOrArchivedMatterStatus(
          existing.matterStatusId,
          dbMatterStatusValues,
        );

        if (action === 'reopen') {
          if (trimmedSuppliedClosedAt) {
            const msg =
              'INVALID_CLOSURE_DATE: Closure date may only be supplied when closing a matter.';
            return {
              matter: null,
              code: 'INVALID_CLOSURE_DATE',
              message: msg,
              errors: { closedAt: msg },
            };
          }
          if (
            !existing.openedAt?.trim() ||
            isProspectiveMatterStatus(existing.matterStatusId, dbMatterStatusValues) ||
            existing.matterNumber.startsWith('DRAFT')
          ) {
            const msg =
              'This matter has not been opened. Delete or abandon it instead of closing it.';
            return {
              matter: null,
              code: 'MATTER_NOT_OPENED',
              message: msg,
              errors: { matterStatusId: msg },
            };
          }
          if (!currentlyClosedOrArchived) {
            const msg =
              'MATTER_NOT_CLOSED: Only closed or archived matters can be reopened.';
            return {
              matter: null,
              code: 'MATTER_NOT_CLOSED',
              message: msg,
              errors: { matterStatusId: msg },
            };
          }
        } else {
          if (currentlyClosedOrArchived) {
            const msg =
              'MATTER_ALREADY_CLOSED: Matter is already closed; reopen it before recording a new closure date.';
            return {
              matter: null,
              code: 'MATTER_ALREADY_CLOSED',
              message: msg,
              errors: { matterStatusId: msg },
            };
          }
          if (
            !existing.openedAt?.trim() ||
            isProspectiveMatterStatus(existing.matterStatusId, dbMatterStatusValues) ||
            existing.matterNumber.startsWith('DRAFT')
          ) {
            const msg =
              'This matter has not been opened. Delete or abandon it instead of closing it.';
            return {
              matter: null,
              code: 'MATTER_NOT_OPENED',
              message: msg,
              errors: { matterStatusId: msg },
            };
          }
        }

        // R496: Resolve target status strictly by systemKey / canonical ID, never display label; fail closed if absent/inactive
        const targetSystemKey = action === 'close' ? 'closed' : 'active';
        const nextStatusId = resolveMatterLifecycleTargetStatusId(
          dbMatterStatusValues,
          targetSystemKey,
        );
        if (!nextStatusId) {
          const msg = `MATTER_STATUS_NOT_CONFIGURED: Tenant has no active "${targetSystemKey}" matter status configured.`;
          return {
            matter: null,
            code: 'MATTER_STATUS_NOT_CONFIGURED',
            message: msg,
            errors: { matterStatusId: msg },
          };
        }

        const todayIso = resolveTenantLocalDateAndHour(
          new Date(),
          tenantCfg.timeZone || 'Europe/London',
        ).localDate;

        // R495: Validate closure date bounds against openedAt and today in the tenant time zone
        let validatedClosedAt: string | undefined;
        if (action === 'close') {
          const dateCheck = validateMatterClosureDate({
            rawClosedAt: opts.closedAt,
            openedAt: existing.openedAt,
            tenantTodayIso: todayIso,
            timeZone: tenantCfg.timeZone || 'Europe/London',
          });
          if (!dateCheck.ok) {
            return {
              matter: null,
              code: dateCheck.code,
              message: dateCheck.message,
              errors: { closedAt: dateCheck.message },
            };
          }
          validatedClosedAt = dateCheck.closedAt;

          // R497: Enforce Key Dates closure gate inside the active transaction
          const kdConfig = await getKeyDatesConfig({ ctx });
          if (kdConfig.enabled) {
            const targetMatterTypeId =
              existing.matterTypeId || existing.practiceAreaId;
            const matterKds =
              await getKeyDateRepository().listKeyDatesForMatter(
                ctx,
                existing.id,
                actorId,
              );
            const closeGate = evaluateMatterKeyDateClosureGate(
              kdConfig,
              targetMatterTypeId,
              matterKds,
            );
            if (!closeGate.canClose) {
              const msg = `Cannot close matter while ${closeGate.openKeyDates.length} key date(s) remain open (${closeGate.openKeyDates.map((d) => `${d.title} [${d.status}]`).join(', ')}). Resolve them as met, missed, or waived first.`;
              return {
                matter: null,
                code: 'OPEN_KEY_DATES_BLOCK_CLOSURE',
                message: `OPEN_KEY_DATES_BLOCK_CLOSURE: ${msg}`,
                errors: { keyDates: msg },
              };
            }
          }
        }

        const workTypeConfigsOverride =
          await catalogueRepo.getWorkTypeConfigs<WorkTypesConfiguration>(ctx);
        const workTypesConfig = resolveEffectiveWorkTypesConfig(
          tenantCfg,
          workTypeConfigsOverride ?? null,
        );
        const now = nextMonotonicIsoTimestamp(existing.updatedAt);

        const retentionOutcome = computeServerWorkTypeRetentionState({
          prevMatter: existing,
          nextStatusId,
          closedAtInput: action === 'close' ? validatedClosedAt : undefined,
          workTypeSubcategoryId: existing.workTypeSubcategoryId,
          practiceAreaId: existing.practiceAreaId,
          workTypesConfig,
          values: allDbValues,
          todayIso,
        });

        const updatedMatter: Matter = {
          ...existing,
          matterStatusId: nextStatusId,
          recordStatusId: nextStatusId,
          closedAt: retentionOutcome.closedAt,
          destructionDueAt: retentionOutcome.destructionDueAt,
          retentionPeriod: retentionOutcome.retentionPeriod,
          updatedById: actorId,
          updatedAt: now,
        };

        const saved = await putMatterWithInTxRestrictions(ctx, updatedMatter, {
          expectedRowVersion:
            opts.expectedRowVersion !== undefined
              ? opts.expectedRowVersion
              : null,
        });

        writeAudit(null, {
          recordType: 'matter',
          recordId: saved.id,
          action: 'update',
          field:
            action === 'close'
              ? 'Matter closed & retention scheduled'
              : 'Matter reopened & destruction date cleared',
          oldValue: `${resolveLabel(allDbValues, existing.matterStatusId)} (Retention: ${existing.retentionPeriod || 'None'}; Closed: ${existing.closedAt ?? 'None'}; Destruction due: ${existing.destructionDueAt ?? 'None'})`,
          newValue: `${resolveLabel(allDbValues, saved.matterStatusId)} (Retention: ${saved.retentionPeriod}; Closed: ${saved.closedAt ?? 'Cleared'}; Destruction due: ${saved.destructionDueAt ?? 'Cleared'})`,
          byId: actorId,
          at: now,
          ...(opts.reason?.trim() ? { reason: opts.reason.trim() } : {}),
        });
        await flushStagedAuditEntries(ctx);
        auditFlushed = true;
        return { matter: saved };
      });
    } catch (err) {
      if (
        (err as { code?: string })?.code === MATTER_CONCURRENCY_CONFLICT_CODE
      ) {
        return {
          matter: null,
          code: MATTER_CONCURRENCY_CONFLICT_CODE,
          message: MATTER_CONCURRENCY_CONFLICT_MESSAGE,
          errors: { conflict: MATTER_CONCURRENCY_CONFLICT_MESSAGE },
        };
      }
      throw err;
    } finally {
      if (!auditFlushed) {
        discardStagedAuditEntriesSince(stagedAuditMark);
      }
    }
  });
}

// ============================================================================
// Negotiated Client, Parent-Group & Matter Rate Overrides (ADR 0034 §2 / S0-28a)
// ============================================================================

const CLIENT_RATE_VIEW_PERMS: readonly PermissionKey[] = [
  'finance:view',
  'finance:view_matter',
  'finance:credit_control',
  'admin:access',
];

const CLIENT_RATE_MANAGE_PERMS: readonly PermissionKey[] = [
  'matter:costs:sign_off',
  'finance:credit_control',
  'admin:access',
];

const MATTER_RATE_VIEW_PERMS: readonly PermissionKey[] = [
  'finance:view',
  'finance:view_matter',
  'finance:credit_control',
  'admin:access',
  'matter:costs:sign_off',
];

const RESOLVE_RATE_PERMS: readonly PermissionKey[] = [
  'finance:view',
  'finance:view_matter',
  'finance:credit_control',
  'admin:access',
  'quote:view',
  'quote:edit',
  'matter:edit',
];

const MATTER_RATE_MANAGE_PERMS: readonly PermissionKey[] = [
  'matter:costs:sign_off',
  'finance:credit_control',
  'admin:access',
];

async function resolveRateOverrideActor(
  ctx: TenantContext,
  byId: string,
): Promise<{
  people: Person[];
  teams: Team[];
  rbacConfig: RbacConfiguration;
  actor: Person | null;
  permSet: ResolvedPermissionSet;
}> {
  const [people, teams, rbacOverride] = await Promise.all([
    loadStaffPeople(ctx),
    getHrAndRbacRepository().listAllTeams<Team>(ctx),
    getHrAndRbacRepository().getRbacConfigOverride<RbacConfiguration>(ctx),
  ]);
  const actor = people.find((p) => p.id === byId) ?? null;
  const rbacConfig = await loadEffectiveTenantRbacConfig(ctx, rbacOverride);
  const permSet = resolvePersonPermissionSet(actor, {
    allPeople: people,
    teams,
    config: { rbac: rbacConfig },
    context: ctx,
    mfaVerified: ctx.mfaVerified,
    tokenRoles: ctx.actorRoles,
    tokenRolesActorId: actor?.id ?? byId,
  });
  return { people, teams, rbacConfig, actor, permSet };
}

function checkRateManagePermissions(
  permSet: ResolvedPermissionSet,
  ctx: TenantContext,
  allowedPerms: readonly PermissionKey[],
  options: { requireMfaAlways: boolean; deniedMessage: string; mfaMessage: string },
): ActionDenied | null {
  const held = allowedPerms.filter((perm) => permSet.permissions.has(perm));
  if (held.length === 0) {
    return buildActionDenied('FORBIDDEN', options.deniedMessage);
  }
  if (options.requireMfaAlways) {
    if (ctx.mfaVerified !== true) {
      return buildActionDenied('MFA_REQUIRED', options.mfaMessage);
    }
    return null;
  }
  const hasUnblockedPerm = held.some(
    (perm) => !permSet.mfaPendingPermissions.has(perm),
  );
  if (!hasUnblockedPerm) {
    return buildActionDenied('MFA_REQUIRED', options.mfaMessage);
  }
  return null;
}

function hasAnyResolvedPermission(
  permSet: ResolvedPermissionSet,
  perms: readonly PermissionKey[],
): boolean {
  return perms.some((perm) => permSet.permissions.has(perm));
}

function formatClientOverrideSummary(override: ClientRateOverrideRecord): string {
  const scope = override.practiceAreaId || 'all practice areas';
  const window = `${override.effectiveFrom}..${override.effectiveTo ?? 'open-ended'}`;
  return `${override.clientId} (${override.clientType}) [${override.gradeKey} | ${scope}] £${override.rateGbp.toFixed(2)} (${window})`;
}

function formatMatterOverrideSummary(override: MatterRateOverrideRecord): string {
  const window = `${override.effectiveFrom}..${override.effectiveTo ?? 'open-ended'}`;
  return `${override.matterId} [${override.gradeKey}] £${override.rateGbp.toFixed(2)} (${window})`;
}

export interface InheritedParentRateOverrideView {
  parentOrganisationId: string;
  parentOrganisationName: string;
  overrides: ClientRateOverrideRecord[];
}

export async function listClientRateOverridesRecord(
  params: {
    clientType: ClientRateOverrideClientType;
    clientId: string;
  },
  byId: string,
): Promise<
  {
    overrides: ClientRateOverrideRecord[];
    parentChain: ParentChainNodeSummary[];
    inheritedOverrides: InheritedParentRateOverrideView[];
    error?: string;
    code?: ActionDenialCode | string;
    message?: string;
  } & Partial<Omit<ActionDenied, 'code'>>
> {
  const ctx = resolveDefaultServiceTenantContext(null, byId);
  const partyRepo = getPartyRepository();
  const { permSet } = await resolveRateOverrideActor(ctx, byId);
  if (!hasAnyResolvedPermission(permSet, CLIENT_RATE_VIEW_PERMS)) {
    const msg =
      'You do not have permission to view negotiated client rate overrides.';
    return {
      ...buildActionDenied('FORBIDDEN', msg),
      overrides: [],
      parentChain: [],
      inheritedOverrides: [],
      error: msg,
    };
  }

  const clientId = params.clientId?.trim() || '';
  if (!clientId) {
    return {
      overrides: [],
      parentChain: [],
      inheritedOverrides: [],
      code: RATE_OVERRIDE_VALIDATION_ERROR_CODE,
      message: `${RATE_OVERRIDE_VALIDATION_ERROR_CODE}: Client ID is required.`,
      error: 'Client ID is required.',
    };
  }

  if (params.clientType === 'organisation') {
    const org = await partyRepo.getOrganisationById<Organisation>(ctx, clientId);
    if (!org) {
      const msg = `NOT_FOUND: Organisation "${clientId}" not found.`;
      return {
        overrides: [],
        parentChain: [],
        inheritedOverrides: [],
        code: 'NOT_FOUND',
        message: msg,
        error: msg,
      };
    }
  } else {
    const person = await partyRepo.getPersonById<Person>(ctx, clientId);
    if (!person) {
      const msg = `NOT_FOUND: Person "${clientId}" not found.`;
      return {
        overrides: [],
        parentChain: [],
        inheritedOverrides: [],
        code: 'NOT_FOUND',
        message: msg,
        error: msg,
      };
    }
  }

  const repo = getRateOverrideRepository();
  const overrides = await repo.listClientRateOverrides(ctx, {
    clientType: params.clientType,
    clientId,
  });

  if (params.clientType !== 'organisation') {
    return { overrides, parentChain: [], inheritedOverrides: [] };
  }

  const parentChain = await repo.listActiveParentOrganisationChain(ctx, clientId);
  const inheritedOverrides: InheritedParentRateOverrideView[] = [];
  for (const node of parentChain) {
    const parentRows = await repo.listClientRateOverrides(ctx, {
      clientType: 'organisation',
      clientId: node.id,
    });
    inheritedOverrides.push({
      parentOrganisationId: node.id,
      parentOrganisationName: node.legalName,
      overrides: parentRows,
    });
  }

  return { overrides, parentChain, inheritedOverrides };
}

export async function saveClientRateOverrideRecord(
  input: {
    id?: string;
    clientType: ClientRateOverrideClientType;
    clientId: string;
    practiceAreaId?: string | null;
    gradeKey: string;
    rateGbp?: number;
    rateMinorUnits?: number;
    currency?: string;
    effectiveFrom: string;
    effectiveTo?: string | null;
    notes?: string;
  },
  byId: string,
): Promise<
  {
    override?: ClientRateOverrideRecord;
    code?: ActionDenialCode | string;
    message?: string;
    error?: string;
  } & Partial<Omit<ActionDenied, 'code'>>
> {
  const ctx = resolveDefaultServiceTenantContext(null, byId);
  const partyRepo = getPartyRepository();
  const { permSet } = await resolveRateOverrideActor(ctx, byId);
  const clientWriteDenial = checkRateManagePermissions(
    permSet,
    ctx,
    CLIENT_RATE_MANAGE_PERMS,
    {
      requireMfaAlways: true,
      deniedMessage:
        'You do not have permission (matter:costs:sign_off, finance:credit_control, or admin:access) to manage negotiated client rate overrides.',
      mfaMessage:
        'MFA_REQUIRED: Multi-factor authentication is required to manage negotiated client rate overrides.',
    },
  );
  if (clientWriteDenial) {
    return {
      ...clientWriteDenial,
      error: clientWriteDenial.message,
    };
  }

  const clientId = input.clientId?.trim() || '';
  if (!clientId) {
    const msg = `${RATE_OVERRIDE_VALIDATION_ERROR_CODE}: Client ID is required.`;
    return {
      code: RATE_OVERRIDE_VALIDATION_ERROR_CODE,
      message: msg,
      error: msg,
    };
  }

  if (input.clientType === 'organisation') {
    const org = await partyRepo.getOrganisationById<Organisation>(ctx, clientId);
    if (!org || org.mergedIntoId) {
      const msg = `INVALID_CLIENT: Active organisation "${clientId}" was not found in this tenant.`;
      return { code: 'NOT_FOUND', message: msg, error: msg };
    }
  } else {
    const person = await partyRepo.getPersonById<Person>(ctx, clientId);
    if (!person || person.mergedIntoId) {
      const msg = `INVALID_CLIENT: Active person "${clientId}" was not found in this tenant.`;
      return { code: 'NOT_FOUND', message: msg, error: msg };
    }
  }

  const repo = getRateOverrideRepository();
  try {
    const saved = await repo.withTenantTransaction(ctx, async () => {
      const existing = input.id?.trim()
        ? await repo.getClientRateOverrideById(ctx, input.id.trim())
        : null;
      if (input.id?.trim() && !existing) {
        const err = new Error(
          `NOT_FOUND: Client rate override "${input.id.trim()}" was not found.`,
        ) as Error & { code: string };
        err.code = 'NOT_FOUND';
        throw err;
      }
      if (existing && existing.clientId !== clientId) {
        const err = new Error(
          `${RATE_OVERRIDE_VALIDATION_ERROR_CODE}: Client rate override "${existing.id}" belongs to "${existing.clientId}", not "${clientId}".`,
        ) as Error & { code: string };
        err.code = RATE_OVERRIDE_VALIDATION_ERROR_CODE;
        throw err;
      }

      const persisted = await repo.upsertClientRateOverride(ctx, {
        ...input,
        clientId,
        byId,
      });

      const nowIso = persisted.updatedAt || new Date().toISOString();
      const summaryNew = formatClientOverrideSummary(persisted);
      const summaryOld = existing ? formatClientOverrideSummary(existing) : null;
      const auditPayload: FirmAuditEntryInput[] = [
        {
          recordType: 'client_rate_override',
          recordId: persisted.id,
          action: existing ? 'update' : 'create',
          field: existing ? 'Client rate override updated' : 'Client rate override created',
          oldValue: summaryOld,
          newValue: summaryNew,
          byId,
          at: nowIso,
          snapshot: persisted,
        },
        {
          recordType: persisted.clientType,
          recordId: persisted.clientId,
          action: 'rate-override-upsert',
          field: `Negotiated rate override (${persisted.id} · ${persisted.gradeKey})`,
          oldValue: summaryOld,
          newValue: summaryNew,
          byId,
          at: nowIso,
          snapshot: persisted,
        },
      ];
      await appendTenantAuditEntries(ctx, auditPayload);
      return persisted;
    });

    return { override: saved };
  } catch (err) {
    const coded = err as { code?: string; message?: string };
    if (
      coded?.code === RATE_OVERRIDE_DATE_OVERLAP_CODE ||
      coded?.code === RATE_OVERRIDE_INVALID_DATE_RANGE_CODE ||
      coded?.code === RATE_OVERRIDE_VALIDATION_ERROR_CODE ||
      coded?.code === 'NOT_FOUND'
    ) {
      return {
        code: coded.code,
        message: coded.message ?? 'Invalid rate override.',
        error: coded.message ?? 'Invalid rate override.',
      };
    }
    throw err;
  }
}

export async function deleteClientRateOverrideRecord(
  id: string,
  byId: string,
): Promise<
  {
    deleted: boolean;
    code?: ActionDenialCode | string;
    message?: string;
    error?: string;
  } & Partial<Omit<ActionDenied, 'code'>>
> {
  const ctx = resolveDefaultServiceTenantContext(null, byId);
  const { permSet } = await resolveRateOverrideActor(ctx, byId);
  const clientDeleteDenial = checkRateManagePermissions(
    permSet,
    ctx,
    CLIENT_RATE_MANAGE_PERMS,
    {
      requireMfaAlways: true,
      deniedMessage:
        'You do not have permission (matter:costs:sign_off, finance:credit_control, or admin:access) to delete negotiated client rate overrides.',
      mfaMessage:
        'MFA_REQUIRED: Multi-factor authentication is required to delete negotiated client rate overrides.',
    },
  );
  if (clientDeleteDenial) {
    return {
      ...clientDeleteDenial,
      deleted: false,
      error: clientDeleteDenial.message,
    };
  }

  const trimmedId = id?.trim() || '';
  if (!trimmedId) {
    const msg = 'NOT_FOUND: Client rate override id is required.';
    return { deleted: false, code: 'NOT_FOUND', message: msg, error: msg };
  }

  const repo = getRateOverrideRepository();
  const outcome = await repo.withTenantTransaction(ctx, async () => {
    const existing = await repo.getClientRateOverrideById(ctx, trimmedId);
    if (!existing) {
      return { deleted: false, existing: null as ClientRateOverrideRecord | null };
    }
    const deleted = await repo.deleteClientRateOverride(ctx, trimmedId);
    if (deleted) {
      const nowIso = new Date().toISOString();
      const summaryOld = formatClientOverrideSummary(existing);
      await appendTenantAuditEntries(ctx, [
        {
          recordType: 'client_rate_override',
          recordId: existing.id,
          action: 'rate-override-delete',
          field: 'Client rate override removed',
          oldValue: summaryOld,
          newValue: null,
          byId,
          at: nowIso,
          snapshot: existing,
        },
        {
          recordType: existing.clientType,
          recordId: existing.clientId,
          action: 'rate-override-delete',
          field: `Negotiated rate override removed (${existing.id} · ${existing.gradeKey})`,
          oldValue: summaryOld,
          newValue: null,
          byId,
          at: nowIso,
          snapshot: existing,
        },
      ]);
    }
    return { deleted, existing };
  });

  if (!outcome.deleted) {
    const msg = `NOT_FOUND: Client rate override "${trimmedId}" was not found.`;
    return { deleted: false, code: 'NOT_FOUND', message: msg, error: msg };
  }
  return { deleted: true };
}

export async function listMatterRateOverridesRecord(
  matterId: string,
  byId: string,
): Promise<
  {
    overrides: MatterRateOverrideRecord[];
    code?: ActionDenialCode | string;
    message?: string;
    error?: string;
  } & Partial<Omit<ActionDenied, 'code'>>
> {
  const ctx = resolveDefaultServiceTenantContext(null, byId);
  const [{ people, teams, rbacConfig, actor, permSet }, matter] = await Promise.all([
    resolveRateOverrideActor(ctx, byId),
    getMatterRepository().getMatterById<Matter>(ctx, matterId?.trim() || '', {
      includeRestricted: true,
    }),
  ]);
  if (!hasAnyResolvedPermission(permSet, MATTER_RATE_VIEW_PERMS)) {
    const msg = 'You do not have permission to view matter rate overrides.';
    return {
      ...buildActionDenied('FORBIDDEN', msg),
      overrides: [],
      code: 'FORBIDDEN',
      message: msg,
      error: msg,
    };
  }
  if (!matter || !canPersonAccessMatter(matter, byId, actor, { allPeople: people, teams, config: { rbac: rbacConfig } })) {
    const msg = 'Matter not found or restricted.';
    return {
      ...buildActionDenied('FORBIDDEN', msg),
      overrides: [],
      code: 'FORBIDDEN',
      message: msg,
      error: msg,
    };
  }

  const overrides = await getRateOverrideRepository().listMatterRateOverrides(ctx, {
    matterId: matter.id,
  });
  return { overrides };
}

export async function saveMatterRateOverrideRecord(
  input: {
    id?: string;
    matterId: string;
    gradeKey: string;
    rateGbp?: number;
    rateMinorUnits?: number;
    currency?: string;
    effectiveFrom: string;
    effectiveTo?: string | null;
    notes?: string;
  },
  byId: string,
): Promise<
  {
    override?: MatterRateOverrideRecord;
    code?: ActionDenialCode | string;
    message?: string;
    error?: string;
  } & Partial<Omit<ActionDenied, 'code'>>
> {
  const ctx = resolveDefaultServiceTenantContext(null, byId);
  const tenantCfg = getActiveTenantConfiguration();
  const [{ people, teams, rbacConfig, actor, permSet }, matter] = await Promise.all([
    resolveRateOverrideActor(ctx, byId),
    getMatterRepository().getMatterById<Matter>(ctx, input.matterId?.trim() || '', {
      includeRestricted: true,
    }),
  ]);
  const matterWriteDenial = checkRateManagePermissions(
    permSet,
    ctx,
    MATTER_RATE_MANAGE_PERMS,
    {
      requireMfaAlways: false,
      deniedMessage:
        'You do not have permission (matter:costs:sign_off, finance:credit_control, or admin:access) to manage matter rate overrides.',
      mfaMessage:
        'MFA_REQUIRED: Multi-factor authentication is required for administrative permission "admin:access" to manage matter rate overrides.',
    },
  );
  if (matterWriteDenial) {
    return {
      ...matterWriteDenial,
      error: matterWriteDenial.message,
    };
  }
  if (!matter || !canPersonAccessMatter(matter, byId, actor, { allPeople: people, teams, config: { rbac: rbacConfig } })) {
    const msg = 'Matter not found or restricted.';
    return {
      ...buildActionDenied('FORBIDDEN', msg),
      code: 'FORBIDDEN',
      message: msg,
      error: msg,
    };
  }

  const repo = getRateOverrideRepository();
  const catRepo = getCatalogueRepository();
  try {
    const saved = await repo.withTenantTransaction(ctx, async () => {
      const dbCostsOverride =
        await catRepo.getMatterCostsConfig<MatterCostsConfig>(ctx);
      const effectiveCostsConfig = resolveEffectiveMatterCostsConfig(
        tenantCfg,
        dbCostsOverride,
      );
      if (!effectiveCostsConfig.allowMatterRateOverrides) {
        const err = new Error(
          'MATTER_RATE_OVERRIDES_DISABLED: Matter-level hourly rate overrides are disabled by firm configuration.',
        ) as Error & { code: string };
        err.code = 'MATTER_RATE_OVERRIDES_DISABLED';
        throw err;
      }

      const existing = input.id?.trim()
        ? await repo.getMatterRateOverrideById(ctx, input.id.trim())
        : null;
      if (input.id?.trim() && !existing) {
        const err = new Error(
          `NOT_FOUND: Matter rate override "${input.id.trim()}" was not found.`,
        ) as Error & { code: string };
        err.code = 'NOT_FOUND';
        throw err;
      }
      if (existing && existing.matterId !== matter.id) {
        const err = new Error(
          `${RATE_OVERRIDE_VALIDATION_ERROR_CODE}: Matter rate override "${existing.id}" belongs to "${existing.matterId}", not "${matter.id}".`,
        ) as Error & { code: string };
        err.code = RATE_OVERRIDE_VALIDATION_ERROR_CODE;
        throw err;
      }

      const persisted = await repo.upsertMatterRateOverride(ctx, {
        ...input,
        matterId: matter.id,
        byId,
      });

      const nowIso = persisted.updatedAt || new Date().toISOString();
      const summaryNew = formatMatterOverrideSummary(persisted);
      const summaryOld = existing ? formatMatterOverrideSummary(existing) : null;
      await appendTenantAuditEntries(ctx, [
        {
          recordType: 'matter_rate_override',
          recordId: persisted.id,
          action: existing ? 'update' : 'create',
          field: existing ? 'Matter rate override updated' : 'Matter rate override created',
          oldValue: summaryOld,
          newValue: summaryNew,
          byId,
          at: nowIso,
          snapshot: persisted,
        },
        {
          recordType: 'matter',
          recordId: persisted.matterId,
          action: 'rate-override-upsert',
          field: `Matter rate override (${persisted.id} · ${persisted.gradeKey})`,
          oldValue: summaryOld,
          newValue: summaryNew,
          byId,
          at: nowIso,
          snapshot: persisted,
        },
      ]);
      return persisted;
    });

    return { override: saved };
  } catch (err) {
    const coded = err as { code?: string; message?: string };
    if (
      coded?.code === RATE_OVERRIDE_DATE_OVERLAP_CODE ||
      coded?.code === RATE_OVERRIDE_INVALID_DATE_RANGE_CODE ||
      coded?.code === RATE_OVERRIDE_VALIDATION_ERROR_CODE ||
      coded?.code === 'MATTER_RATE_OVERRIDES_DISABLED' ||
      coded?.code === 'NOT_FOUND'
    ) {
      return {
        code: coded.code,
        message: coded.message ?? 'Invalid matter rate override.',
        error: coded.message ?? 'Invalid matter rate override.',
      };
    }
    throw err;
  }
}

export async function deleteMatterRateOverrideRecord(
  id: string,
  byId: string,
): Promise<
  {
    deleted: boolean;
    code?: ActionDenialCode | string;
    message?: string;
    error?: string;
  } & Partial<Omit<ActionDenied, 'code'>>
> {
  const ctx = resolveDefaultServiceTenantContext(null, byId);
  const trimmedId = id?.trim() || '';
  const repo = getRateOverrideRepository();

  return repo.withTenantTransaction(ctx, async (tx) => {
    const { people, teams, rbacConfig, actor, permSet } =
      await resolveRateOverrideActor(ctx, byId);
    const matterDeleteDenial = checkRateManagePermissions(
      permSet,
      ctx,
      MATTER_RATE_MANAGE_PERMS,
      {
        requireMfaAlways: false,
        deniedMessage:
          'You do not have permission (matter:costs:sign_off, finance:credit_control, or admin:access) to delete matter rate overrides.',
        mfaMessage:
          'MFA_REQUIRED: Multi-factor authentication is required for administrative permission "admin:access" to delete matter rate overrides.',
      },
    );
    if (matterDeleteDenial) {
      return {
        ...matterDeleteDenial,
        deleted: false,
        error: matterDeleteDenial.message,
      };
    }

    if (!trimmedId) {
      const msg = 'NOT_FOUND: Matter rate override id is required.';
      return { deleted: false, code: 'NOT_FOUND', message: msg, error: msg };
    }

    await tx.query(
      'SELECT id FROM public.matter_rate_overrides WHERE tenant_id = $1 AND id = $2 FOR UPDATE',
      [ctx.tenantId, trimmedId],
    );

    const existing = await repo.getMatterRateOverrideById(ctx, trimmedId);
    if (!existing) {
      const msg = `NOT_FOUND: Matter rate override "${trimmedId}" was not found.`;
      return { deleted: false, code: 'NOT_FOUND', message: msg, error: msg };
    }

    const matter = await getMatterRepository().getMatterById<Matter>(ctx, existing.matterId, {
      includeRestricted: true,
    });
    if (!matter || !canPersonAccessMatter(matter, byId, actor, { allPeople: people, teams, config: { rbac: rbacConfig } })) {
      const msg = 'Matter not found or restricted.';
      return {
        ...buildActionDenied('FORBIDDEN', msg),
        deleted: false,
        code: 'FORBIDDEN',
        message: msg,
        error: msg,
      };
    }

    const ok = await repo.deleteMatterRateOverride(ctx, trimmedId);
    if (!ok) {
      const msg = `NOT_FOUND: Matter rate override "${trimmedId}" was not found.`;
      return { deleted: false, code: 'NOT_FOUND', message: msg, error: msg };
    }

    const nowIso = new Date().toISOString();
    const summaryOld = formatMatterOverrideSummary(existing);
    await appendTenantAuditEntries(ctx, [
      {
        recordType: 'matter_rate_override',
        recordId: existing.id,
        action: 'rate-override-delete',
        field: 'Matter rate override removed',
        oldValue: summaryOld,
        newValue: null,
        byId,
        at: nowIso,
        snapshot: existing,
      },
      {
        recordType: 'matter',
        recordId: existing.matterId,
        action: 'rate-override-delete',
        field: `Matter rate override removed (${existing.id} · ${existing.gradeKey})`,
        oldValue: summaryOld,
        newValue: null,
        byId,
        at: nowIso,
        snapshot: existing,
      },
    ]);

    return { deleted: true };
  });
}

export async function resolveApplicableRatesRecord(
  params: {
    matterId?: string | null;
    clientId?: string | null;
    clientType?: ClientRateOverrideClientType | null;
    practiceAreaId?: string | null;
    asAtDate?: string | null;
    rateCardId?: string | null;
    preferredSource?: 'auto' | 'app_table' | 'pms';
  },
  byId: string,
): Promise<
  {
    resolved?: ResolvedApplicableRatesResult;
    code?: ActionDenialCode | string;
    message?: string;
    error?: string;
  } & Partial<Omit<ActionDenied, 'code'>>
> {
  const ctx = resolveDefaultServiceTenantContext(null, byId);
  const tenantCfg = getActiveTenantConfiguration();
  const { people, teams, rbacConfig, actor, permSet } =
    await resolveRateOverrideActor(ctx, byId);
  if (!hasAnyResolvedPermission(permSet, RESOLVE_RATE_PERMS)) {
    const msg = 'You do not have permission to resolve applicable hourly rates.';
    return {
      ...buildActionDenied('FORBIDDEN', msg),
      code: 'FORBIDDEN',
      message: msg,
      error: msg,
    };
  }

  const trimmedMatterId = params.matterId?.trim() || null;
  if (trimmedMatterId) {
    const matter = await getMatterRepository().getMatterById<Matter>(
      ctx,
      trimmedMatterId,
      { includeRestricted: true },
    );
    if (!matter || !canPersonAccessMatter(matter, byId, actor, { allPeople: people, teams, config: { rbac: rbacConfig } })) {
      const msg = 'Matter not found or restricted.';
      return {
        ...buildActionDenied('FORBIDDEN', msg),
        code: 'FORBIDDEN',
        message: msg,
        error: msg,
      };
    }
  }

  const effectiveToday =
    params.asAtDate?.trim() ||
    resolveTenantLocalDateAndHour(new Date(), tenantCfg.timeZone || 'Europe/London')
      .localDate;
  const dbCostsOverride =
    await getCatalogueRepository().getMatterCostsConfig<MatterCostsConfig>(ctx);
  const effectiveCostsConfig = resolveEffectiveMatterCostsConfig(
    tenantCfg,
    dbCostsOverride,
  );

  const resolved = await getRateOverrideRepository().resolveApplicableRates(ctx, {
    matterId: trimmedMatterId,
    clientId: params.clientId?.trim() || null,
    clientType: params.clientType ?? null,
    practiceAreaId: params.practiceAreaId?.trim() || null,
    asAtDate: effectiveToday,
    rateCardId: params.rateCardId?.trim() || null,
    preferredSource: params.preferredSource,
    baseMatterCostsConfig: tenantCfg.matterCosts,
    fallbackRateCardConfig: effectiveCostsConfig,
    timeZone: tenantCfg.timeZone,
  });

  return { resolved };
}

// ============================================================================
// Configurable Registers Engine, Undertakings & Reminder Job (ADR 0032, S0-24)
// ============================================================================

async function resolveRegisterActorAndConfig(
  byId?: string,
  explicitMfa?: boolean,
  explicitOptions?: {
    readonly tenantCtx?: TenantContext | null;
    readonly tenantConfig?: TenantConfiguration;
  },
): Promise<{
  ctx: TenantContext;
  tenantCfg: TenantConfiguration;
  actor: Person;
  people: Person[];
  teams: Team[];
  actorRoles: HomeRoleKey[];
  rbacConfig: RbacConfiguration;
  permSet: ReturnType<typeof resolvePersonPermissionSet>;
}> {
  const ctx = resolveDefaultServiceTenantContext(null, byId, {
    tenantCtx: explicitOptions?.tenantCtx,
  });
  const tenantCfg = resolveVerifiedTenantConfiguration(
    ctx,
    explicitOptions?.tenantConfig,
  );
  const [people, teams, rbacConfig] = await Promise.all([
    loadStaffPeople(ctx),
    getHrAndRbacRepository().listAllTeams<Team>(ctx),
    loadEffectiveTenantRbacConfig(ctx, undefined, tenantCfg),
  ]);
  const actor = people.find((p) => p.id === (byId || ctx.actorId) && !p.mergedIntoId) ?? null;
  if (!actor) {
    throw new AuthorisationError({
      code: 'UNAUTHENTICATED',
      message: 'Signed-in employee record is required for register operations.',
      tenantId: ctx.tenantId,
      correlationId: ctx.correlationId,
      actorUserId: byId || ctx.actorId || 'anonymous',
    });
  }
  const activeSession = getActiveActorSession();
  const matchingExplicitCtx =
    explicitOptions?.tenantCtx && explicitOptions.tenantCtx.actorId === actor.id
      ? explicitOptions.tenantCtx
      : null;
  const effectiveTokenRoles =
    matchingExplicitCtx?.actorRoles ??
    (activeSession?.personId === actor.id ? activeSession.tokenRoles : undefined);
  const effectiveMfa =
    explicitMfa ??
    (matchingExplicitCtx
      ? matchingExplicitCtx.mfaVerified === true
      : activeSession?.personId === actor.id
        ? activeSession.mfaVerified === true
        : false);
  const permSet = resolvePersonPermissionSet(actor, {
    allPeople: people,
    teams,
    tokenRoles: effectiveTokenRoles,
    tokenRolesActorId: actor.id,
    mfaVerified: effectiveMfa,
    ...(matchingExplicitCtx ? { context: matchingExplicitCtx } : {}),
    config: { ...tenantCfg, rbac: rbacConfig },
  });
  const actorRoles = resolveEmployeeRoles(actor, teams);
  return {
    ctx,
    tenantCfg,
    actor,
    people,
    teams,
    actorRoles,
    rbacConfig,
    permSet,
  };
}

export type RegisterServiceDenialOrError =
  | ActionDenied
  | {
      ok: false;
      denied?: false;
      code: string;
      message: string;
      error: string;
    };

function registerServiceFailure(
  code: string,
  message: string,
): RegisterServiceDenialOrError {
  if (code === 'MFA_REQUIRED' || code === 'FORBIDDEN' || code === 'UNAUTHENTICATED') {
    return buildActionDenied(code, message);
  }
  return {
    ok: false,
    code,
    message,
    error: message,
  };
}

function mapRegisterErrorToDenial(err: unknown): RegisterServiceDenialOrError {
  const rawErr = err as { code?: string; message?: string };
  const rawCode = rawErr?.code ?? '';
  if (
    rawCode === 'TENANT_CONFIG_MISMATCH' ||
    rawCode === 'TENANCY_FORGERY_DETECTED'
  ) {
    throw err;
  }
  const msg = rawErr?.message || (err instanceof Error ? err.message : 'Register operation failed.');
  if (rawCode === 'MFA_REQUIRED') {
    return registerServiceFailure('MFA_REQUIRED', msg);
  }
  if (
    rawCode === 'FORBIDDEN' ||
    rawCode === 'UNAUTHENTICATED' ||
    rawCode === REGISTER_DOMAIN_ERROR_CODES.SELF_APPROVAL_FORBIDDEN ||
    rawCode === REGISTER_DOMAIN_ERROR_CODES.APPROVER_MISMATCH ||
    rawCode === REGISTER_DOMAIN_ERROR_CODES.CONCURRENCY_CONFLICT ||
    rawCode === REGISTER_DOMAIN_ERROR_CODES.NOT_FOUND
  ) {
    return registerServiceFailure(rawCode, msg);
  }
  return registerServiceFailure(rawCode || 'INTERNAL_ERROR', msg);
}

export async function listRegistersWorkspaceDataRecord(
  filter: {
    registerTypeKey?: string;
    status?: string;
    matterId?: string;
  } = {},
  byId?: string,
  options?: {
    readonly tenantCtx?: TenantContext | null;
    readonly tenantConfig?: TenantConfiguration;
  },
): Promise<
  | {
      ok: true;
      records: RegisterRecord[];
      transitionsByRecordId: Record<string, RegisterTransition[]>;
      registerTypes: RegisterTypeDefinition[];
      registersConfig: RegistersConfiguration;
      matters: Matter[];
      people: Person[];
    }
  | RegisterServiceDenialOrError
> {
  try {
    const { ctx, tenantCfg, actor, people, teams, rbacConfig, permSet } =
      await resolveRegisterActorAndConfig(byId, undefined, options);
    const canView =
      permSet.permissions.has('register:view') ||
      permSet.permissions.has('undertaking:manage');
    if (!canView) {
      return registerServiceFailure(
        'FORBIDDEN',
        'You do not have permission to view firm registers.',
      );
    }

    const dbOverride = await getCatalogueRepository().getModuleConfig<RegistersConfiguration>(
      ctx,
      'registers',
    );
    const baseRegisters = tenantCfg.registers ?? DEFAULT_REGISTERS_CONFIG;
    const registersConfig = mergeRegistersConfigurations(baseRegisters, dbOverride);
    const registerTypes = resolveEffectiveRegisterTypes(baseRegisters, dbOverride);
    const registerRepo = getRegisterRepository();

    const rawRecords = await registerRepo.listVisibleRegisterRecords(ctx, actor.id, {
      ...(filter.registerTypeKey?.trim()
        ? { registerTypeKey: filter.registerTypeKey.trim() }
        : {}),
      ...(filter.status?.trim() ? { status: filter.status.trim() } : {}),
      ...(filter.matterId?.trim() ? { matterId: filter.matterId.trim() } : {}),
    });

    const hasGeneralRegisterView = permSet.permissions.has('register:view');
    const records = hasGeneralRegisterView
      ? rawRecords
      : rawRecords.filter((r) => r.registerTypeKey === 'undertaking');

    const transitionsByRecordId: Record<string, RegisterTransition[]> = {};
    for (const rec of records) {
      transitionsByRecordId[rec.id] = await registerRepo.listTransitionsForRecord(
        ctx,
        rec.id,
        { viewerId: actor.id },
      );
    }

    const candidateMatters = await getMatterRepository().listVisibleMatters<Matter>(
      ctx,
      {
        viewerId: actor.id,
        hasRestrictedMatterAccess: permSet.permissions.has(
          'matter:restricted:access',
        ),
      },
    );
    const visibleMatters = candidateMatters.filter((m) =>
      canPersonAccessMatter(m, actor.id, actor, {
        allPeople: people,
        teams,
        config: { rbac: rbacConfig },
      }),
    );
    const employeeMatterVisibility = buildMatterVisibilityForEmployeeRecord(
      visibleMatters,
      (m) =>
        canPersonAccessMatter(m, actor.id, actor, {
          allPeople: people,
          teams,
          config: { rbac: rbacConfig },
        }),
    );
    const orgStructure = buildDefaultOrgStructure({ legalName: tenantCfg.displayName });
    const filteredPeople = people
      .filter((p) => !p.mergedIntoId)
      .map((p) =>
        p.employment
          ? {
              ...p,
              employment: filterEmploymentForUser(
                p.employment,
                actor,
                people,
                teams,
                orgStructure,
                { config: { rbac: rbacConfig } },
                employeeMatterVisibility,
              ),
            }
          : p,
      );

    return {
      ok: true,
      records,
      transitionsByRecordId,
      registerTypes,
      registersConfig,
      matters: visibleMatters,
      people: filteredPeople,
    };
  } catch (err) {
    return mapRegisterErrorToDenial(err);
  }
}

export async function getRegisterRecordDetailRecord(
  recordId: string,
  byId?: string,
  options?: {
    readonly tenantCtx?: TenantContext | null;
    readonly tenantConfig?: TenantConfiguration;
  },
): Promise<
  | {
      ok: true;
      record: RegisterRecord;
      transitions: RegisterTransition[];
      registerType: RegisterTypeDefinition | null;
    }
  | RegisterServiceDenialOrError
> {
  try {
    const { ctx, tenantCfg, actor, people, teams, permSet } =
      await resolveRegisterActorAndConfig(byId, undefined, options);
    const trimmedId = recordId?.trim() || '';
    const registerRepo = getRegisterRepository();
    const record = await registerRepo.getRegisterRecordById(ctx, trimmedId, {
      includeRestricted: true,
    });
    if (!record) {
      return registerServiceFailure('NOT_FOUND', `Register record "${trimmedId}" was not found.`);
    }
    const canViewRecord =
      permSet.permissions.has('register:view') ||
      (record.registerTypeKey === 'undertaking' && permSet.permissions.has('undertaking:manage'));
    if (!canViewRecord) {
      return registerServiceFailure(
        'FORBIDDEN',
        'You do not have permission to view this register record.',
      );
    }
    if (record.matterId) {
      const matter = await getMatterRepository().getMatterById<Matter>(ctx, record.matterId, {
        includeRestricted: true,
      });
      if (!matter || !canPersonAccessMatter(matter, actor.id, actor, { allPeople: people, teams })) {
        return registerServiceFailure(
          'FORBIDDEN',
          'You do not have access to the restricted matter linked to this register record.',
        );
      }
    }
    const dbOverride = await getCatalogueRepository().getModuleConfig<RegistersConfiguration>(
      ctx,
      'registers',
    );
    const baseRegisters = tenantCfg.registers ?? DEFAULT_REGISTERS_CONFIG;
    const registerType = findEffectiveRegisterType(
      record.registerTypeKey,
      baseRegisters,
      dbOverride,
    );
    const transitions = await registerRepo.listTransitionsForRecord(ctx, record.id, {
      viewerId: actor.id,
    });
    return {
      ok: true,
      record,
      transitions,
      registerType,
    };
  } catch (err) {
    return mapRegisterErrorToDenial(err);
  }
}

export async function createRegisterRecordService(
  input: {
    registerTypeKey: string;
    title: string;
    matterId?: string | null;
    enquiryId?: string | null;
    personId?: string | null;
    organisationId?: string | null;
    assignedApproverId?: string | null;
    dueAt?: string | null;
    reviewAt?: string | null;
    reminderScheduleDays?: readonly number[] | null;
    fieldValues?: Record<string, unknown>;
  },
  byId?: string,
  options?: {
    readonly tenantCtx?: TenantContext | null;
    readonly tenantConfig?: TenantConfiguration;
    readonly authorizedViaFinanceCreditControl?: boolean;
  },
): Promise<
  | {
      ok: true;
      record: RegisterRecord;
      isolatedHookErrors?: string[];
    }
  | RegisterServiceDenialOrError
> {
  try {
    const { ctx, tenantCfg, actor, people, teams, permSet } =
      await resolveRegisterActorAndConfig(byId, undefined, options);
    const catRepo = getCatalogueRepository();
    const matterRepo = getMatterRepository();
    const registerRepo = getRegisterRepository();
    const dbOverridePre = await catRepo.getModuleConfig<RegistersConfiguration>(ctx, 'registers');
    const baseRegisters = tenantCfg.registers ?? DEFAULT_REGISTERS_CONFIG;
    const registerTypePre = findEffectiveRegisterType(
      input.registerTypeKey?.trim() || '',
      baseRegisters,
      dbOverridePre,
    );
    if (!registerTypePre) {
      return registerServiceFailure(
        'VALIDATION_ERROR',
        `Register type "${input.registerTypeKey}" is not configured.`,
      );
    }
    const hasCreatePermission =
      permSet.permissions.has(registerTypePre.createPermission) ||
      Boolean(
        options?.authorizedViaFinanceCreditControl &&
          registerTypePre.key === 'sign_off' &&
          permSet.permissions.has('finance:credit_control'),
      );
    if (!hasCreatePermission) {
      return registerServiceFailure(
        'FORBIDDEN',
        `Missing required permission "${registerTypePre.createPermission}" to create ${registerTypePre.label}.`,
      );
    }

    const matterIdClean = input.matterId?.trim() || null;
    if (matterIdClean) {
      const matter = await matterRepo.getMatterById<Matter>(ctx, matterIdClean, {
        includeRestricted: true,
      });
      if (!matter || !canPersonAccessMatter(matter, actor.id, actor, { allPeople: people, teams })) {
        return registerServiceFailure('FORBIDDEN', 'Matter not found or restricted.');
      }
    }

    const validatedPre = validateRegisterCreateInput({
      registerType: registerTypePre,
      title: input.title ?? '',
      matterId: matterIdClean,
      dueAt: input.dueAt ?? null,
      reviewAt: input.reviewAt ?? null,
      fieldValues: input.fieldValues ?? {},
    });

    // Execute pre-create extension hooks STRICTLY OUTSIDE any PostgreSQL write transaction.
    const hookCfg = tenantCfg;
    const hookResult = await getPlatformExtensionHost().executeRegisterBeforeCreateHook(
      ctx,
      hookCfg,
      {
        tenantId: ctx.tenantId,
        actorId: actor.id,
        correlationId: ctx.correlationId,
        registerType: registerTypePre,
        draft: {
          registerTypeKey: registerTypePre.key,
          title: validatedPre.title,
          matterId: matterIdClean,
          enquiryId: input.enquiryId?.trim() || null,
          personId: input.personId?.trim() || null,
          organisationId: input.organisationId?.trim() || null,
          ownerId: actor.id,
          assignedApproverId: input.assignedApproverId?.trim() || null,
          dueAt: validatedPre.dueAt,
          reviewAt: validatedPre.reviewAt,
          fieldValues: validatedPre.fieldValues,
        },
      },
    );
    if (!hookResult.allowProceed) {
      return registerServiceFailure(
        'VALIDATION_ERROR',
        hookResult.rejectionReason || 'Extension blocked register record creation.',
      );
    }

    let notificationsQueued = false;
    const createdRecord = await registerRepo.withTenantTransaction(ctx, async () => {
      const dbOverrideTx = await catRepo.getModuleConfig<RegistersConfiguration>(ctx, 'registers');
      const registerTypeTx = findEffectiveRegisterType(
        registerTypePre.key,
        baseRegisters,
        dbOverrideTx,
      );
      if (!registerTypeTx || !registerTypeTx.enabled) {
        const msg = `Register type "${registerTypePre.key}" is disabled or removed.`;
        throw Object.assign(new Error(msg), { code: REGISTER_DOMAIN_ERROR_CODES.TYPE_DISABLED });
      }
      if (matterIdClean) {
        const matterTx = await matterRepo.getMatterById<Matter>(ctx, matterIdClean, {
          includeRestricted: true,
        });
        if (!matterTx || !canPersonAccessMatter(matterTx, actor.id, actor, { allPeople: people, teams })) {
          const msg = 'Matter not found or restricted.';
          throw Object.assign(new Error(msg), { code: 'FORBIDDEN' });
        }
      }

      const finalValidated = validateRegisterCreateInput({
        registerType: registerTypeTx,
        title: input.title ?? '',
        matterId: matterIdClean,
        dueAt: hookResult.dueAt,
        reviewAt: hookResult.reviewAt,
        fieldValues: hookResult.mergedFieldValues,
      });

      const idPrefix = registerTypeTx.key === 'sign_off' ? 'SO' : 'REG';
      const newId = await registerRepo.allocateNextRecordId(ctx, { idPrefix });
      const reference =
        registerTypeTx.key === 'sign_off'
          ? newId
          : await registerRepo.allocateNextRecordId(ctx, {
              idPrefix: registerTypeTx.referencePrefix,
            });
      const nowIso = new Date().toISOString();

      const created = await registerRepo.createRegisterRecord(ctx, {
        id: newId,
        registerTypeKey: registerTypeTx.key,
        reference,
        title: finalValidated.title,
        status: registerTypeTx.initialStatus,
        matterId: matterIdClean,
        enquiryId: input.enquiryId?.trim() || null,
        personId: input.personId?.trim() || null,
        organisationId: input.organisationId?.trim() || null,
        ownerId: actor.id,
        assignedApproverId: input.assignedApproverId?.trim() || null,
        dueAt: finalValidated.dueAt,
        reviewAt: finalValidated.reviewAt,
        reminderScheduleDays: input.reminderScheduleDays ?? null,
        fieldValues: finalValidated.fieldValues,
        createdById: actor.id,
      });
      await appendTenantAuditEntries(ctx, [
        {
          recordType: 'register_record',
          recordId: newId,
          action: 'create',
          field: 'Status',
          oldValue: '',
          newValue: `${reference}: ${registerTypeTx.initialStatus} (${finalValidated.title})`,
          byId: actor.id,
          at: nowIso,
        },
      ]);

      const recordHref =
        created.registerTypeKey === 'sign_off'
          ? '/?panel=partner_sign_off_queue'
          : `/registers?record=${created.id}`;
      if (registerTypeTx.approvalRules !== null && created.assignedApproverId) {
        const pushed = await pushNotification(ctx, {
          recipientId: created.assignedApproverId,
          kind: 'approval_requested',
          title: `Approval requested: ${created.reference}`,
          detail: `${registerTypeTx.label} "${created.title}" requires your approval decision.`,
          href: recordHref,
          recordId: created.id,
          matterId: created.matterId ?? null,
          knownMatterIds: matterIdClean ? [matterIdClean] : undefined,
          tenantConfig: tenantCfg,
          byId: actor.id,
          at: nowIso,
        });
        if (pushed) notificationsQueued = true;
      } else if (
        (registerTypeTx.approvalRules === null && created.assignedApproverId) ||
        Boolean(created.reviewAt)
      ) {
        const reviewerId = created.assignedApproverId || created.ownerId;
        if (reviewerId) {
          const pushed = await pushNotification(ctx, {
            recipientId: reviewerId,
            kind: 'register_review_assigned',
            title: `Register review assigned: ${created.reference}`,
            detail: `${registerTypeTx.label} "${created.title}" has been assigned for your review.`,
            href: `/registers?record=${created.id}`,
            recordId: created.id,
            matterId: created.matterId ?? null,
            knownMatterIds: matterIdClean ? [matterIdClean] : undefined,
            tenantConfig: tenantCfg,
            byId: actor.id,
            at: nowIso,
          });
          if (pushed) notificationsQueued = true;
        }
      }
      return created;
    });

    if (notificationsQueued) {
      await drainNotificationOutboxesBestEffort(ctx, tenantCfg, actor.id);
    }

    return {
      ok: true,
      record: createdRecord,
      ...(hookResult.isolatedErrors.length > 0
        ? { isolatedHookErrors: hookResult.isolatedErrors }
        : {}),
    };
  } catch (err) {
    return mapRegisterErrorToDenial(err);
  }
}

export async function transitionRegisterRecordService(
  input: {
    recordId: string;
    transitionKey: string;
    comment?: string | null;
    fieldUpdates?: Record<string, unknown>;
    expectedRowVersion?: number;
  },
  byId?: string,
  options?: {
    readonly tenantCtx?: TenantContext | null;
    readonly tenantConfig?: TenantConfiguration;
    readonly viaHomeSignOffAdapter?: boolean;
  },
): Promise<
  | {
      ok: true;
      record: RegisterRecord;
      transition: RegisterTransition;
      isolatedHookErrors?: string[];
    }
  | RegisterServiceDenialOrError
> {
  try {
    const { ctx, tenantCfg, actor, people, teams, actorRoles, permSet } =
      await resolveRegisterActorAndConfig(byId, undefined, options);
    const catRepo = getCatalogueRepository();
    const matterRepo = getMatterRepository();
    const registerRepo = getRegisterRepository();

    const existingPre = await registerRepo.getRegisterRecordById(ctx, input.recordId?.trim() || '', {
      includeRestricted: true,
    });
    if (!existingPre) {
      return registerServiceFailure(
        'NOT_FOUND',
        `Register record "${input.recordId}" was not found.`,
      );
    }
    if (options?.viaHomeSignOffAdapter && existingPre.registerTypeKey !== 'sign_off') {
      return registerServiceFailure(
        'NOT_FOUND',
        `Sign-off record "${input.recordId}" was not found.`,
      );
    }
    if (existingPre.matterId) {
      const matterPre = await matterRepo.getMatterById<Matter>(ctx, existingPre.matterId, {
        includeRestricted: true,
      });
      if (!matterPre || !canPersonAccessMatter(matterPre, actor.id, actor, { allPeople: people, teams })) {
        return registerServiceFailure(
          'FORBIDDEN',
          'You do not have access to the restricted matter linked to this register record.',
        );
      }
    }

    const dbOverridePre = await catRepo.getModuleConfig<RegistersConfiguration>(ctx, 'registers');
    const baseRegisters = tenantCfg.registers ?? DEFAULT_REGISTERS_CONFIG;
    const registerTypePre = findEffectiveRegisterType(
      existingPre.registerTypeKey,
      baseRegisters,
      dbOverridePre,
    );
    if (!registerTypePre) {
      return registerServiceFailure(
        'VALIDATION_ERROR',
        `Register type "${existingPre.registerTypeKey}" is not configured.`,
      );
    }

    const effectivePermSet =
      options?.viaHomeSignOffAdapter &&
      existingPre.registerTypeKey === 'sign_off' &&
      permSet.permissions.has('signoff:approve')
        ? new Set([...permSet.permissions, 'register:approve' as PermissionKey])
        : permSet.permissions;
    const effectiveExpectedRowVersion =
      input.expectedRowVersion !== undefined
        ? input.expectedRowVersion
        : existingPre.rowVersion;

    const preValidated = validateRegisterTransitionExecution({
      registerType: registerTypePre,
      record: existingPre,
      transitionKey: input.transitionKey,
      actorId: actor.id,
      actorRoles,
      actorPermissionSet: effectivePermSet,
      comment: input.comment ?? null,
      expectedRowVersion: effectiveExpectedRowVersion,
    });

    // Execute beforeTransition hook STRICTLY OUTSIDE any PostgreSQL write transaction.
    const hookCfg = tenantCfg;
    const beforeHookRes = await getPlatformExtensionHost().executeRegisterBeforeTransitionHook(
      ctx,
      hookCfg,
      {
        tenantId: ctx.tenantId,
        actorId: actor.id,
        correlationId: ctx.correlationId,
        registerType: registerTypePre,
        record: existingPre,
        transition: preValidated.transition,
        comment: input.comment?.trim() || null,
        fieldUpdates: input.fieldUpdates,
      },
    );
    if (!beforeHookRes.allowProceed) {
      return registerServiceFailure(
        'VALIDATION_ERROR',
        beforeHookRes.rejectionReason || 'Extension rejected register transition.',
      );
    }

    let finalRegisterType = registerTypePre;
    let notificationsQueued = false;
    const txOutcome = await registerRepo.withTenantTransaction(ctx, async () => {
      const outcome = await registerRepo.lockAndExecuteTransition(ctx, {
        recordId: existingPre.id,
        transitionKey: input.transitionKey,
        actorId: actor.id,
        comment: input.comment?.trim() || null,
        validateAndCompute: async (lockedRecord) => {
          const dbOverrideTx = await catRepo.getModuleConfig<RegistersConfiguration>(
            ctx,
            'registers',
          );
          finalRegisterType =
            findEffectiveRegisterType(
              lockedRecord.registerTypeKey,
              baseRegisters,
              dbOverrideTx,
            ) ?? registerTypePre;
          if (lockedRecord.matterId) {
            const matterTx = await matterRepo.getMatterById<Matter>(ctx, lockedRecord.matterId, {
              includeRestricted: true,
            });
            if (
              !matterTx ||
              !canPersonAccessMatter(matterTx, actor.id, actor, { allPeople: people, teams })
            ) {
              throw Object.assign(
                new Error('You do not have access to the restricted matter linked to this register record.'),
                { code: 'FORBIDDEN' },
              );
            }
          }
          const revalidated = validateRegisterTransitionExecution({
            registerType: finalRegisterType,
            record: lockedRecord,
            transitionKey: input.transitionKey,
            actorId: actor.id,
            actorRoles,
            actorPermissionSet: effectivePermSet,
            comment: input.comment ?? null,
            expectedRowVersion: effectiveExpectedRowVersion,
          });
          const nextFieldInput: Record<string, unknown> = {
            ...lockedRecord.fieldValues,
            ...beforeHookRes.mergedFieldUpdates,
          };
          if (lockedRecord.registerTypeKey === 'sign_off') {
            delete nextFieldInput.legacySignOffStatus;
            if (input.transitionKey === 'discuss') {
              nextFieldInput.discussionNote =
                input.comment?.trim() || 'Partner requested discussion before sign-off.';
            }
          }
          const mergedFields = validateRegisterFieldValues({
            registerType: finalRegisterType,
            fieldValues: nextFieldInput,
            applyDefaults: false,
            enforceRequired: true,
          });
          return {
            nextStatus: revalidated.nextStatus,
            setsDecidedAt: Boolean(revalidated.transition.setsDecidedAt),
            mergedFieldValues: mergedFields,
          };
        },
      });
      const auditRows: FirmAuditEntryInput[] = [
        {
          recordType: 'register_record',
          recordId: outcome.updatedRecord.id,
          action: 'status-change',
          field: 'Status',
          oldValue: outcome.previousRecord.status,
          newValue: `${outcome.updatedRecord.status}${outcome.transition.comment ? ` (${outcome.transition.comment})` : ''}`,
          byId: actor.id,
          at: outcome.transition.transitionedAt,
          ...(outcome.transition.comment ? { reason: outcome.transition.comment } : {}),
        },
      ];
      if (
        outcome.updatedRecord.registerTypeKey === 'sign_off' &&
        (input.transitionKey === 'approve' || input.transitionKey === 'discuss')
      ) {
        const discussionNote = String(
          outcome.updatedRecord.fieldValues.discussionNote ??
            outcome.transition.comment ??
            '',
        );
        auditRows.push({
          recordType: outcome.updatedRecord.matterId ? 'matter' : 'system',
          recordId: outcome.updatedRecord.matterId ?? outcome.updatedRecord.id,
          action: 'status-change',
          field: 'Partner sign-off',
          oldValue:
            outcome.previousRecord.status === 'discussing' ? 'Discussing' : 'Pending',
          newValue:
            input.transitionKey === 'approve'
              ? `Approved: ${outcome.updatedRecord.title}`
              : `Discussing: ${outcome.updatedRecord.title} (${discussionNote})`,
          byId: actor.id,
          at: outcome.transition.transitionedAt,
        });
      }
      await appendTenantAuditEntries(ctx, auditRows);

      if (
        outcome.updatedRecord.registerTypeKey === 'sign_off' &&
        input.transitionKey === 'discuss' &&
        outcome.updatedRecord.ownerId
      ) {
        const discussionNote = String(
          outcome.updatedRecord.fieldValues.discussionNote ??
            outcome.transition.comment ??
            'Partner requested discussion before sign-off.',
        );
        await runWithAuditStagingScope(async () => {
          const linkedRecords: TaskLinkedRecord[] = [];
          if (outcome.updatedRecord.matterId) {
            linkedRecords.push({
              recordType: 'matter',
              recordId: outcome.updatedRecord.matterId,
            });
          }
          await saveTaskRecord(
            {
              title: `Discuss partner sign-off: ${outcome.updatedRecord.title}`,
              description: discussionNote,
              taskTypeId: vid('task_type', 'Review'),
              priorityId: vid('task_priority', 'High'),
              dueAt: toIsoDate(new Date()),
              assignedPersonId: outcome.updatedRecord.ownerId,
              linkedRecords,
            },
            actor.id,
            { internalSystemStep: true },
          );
          await flushStagedAuditEntries(ctx);
        });
      }

      const transitionDef = finalRegisterType.transitions.find(
        (t) => t.key === input.transitionKey,
      );
      const isApprovalDecision =
        input.transitionKey === 'approve' ||
        input.transitionKey === 'discuss' ||
        input.transitionKey === 'reject' ||
        (finalRegisterType.approvalRules !== null && Boolean(transitionDef?.setsDecidedAt));
      if (isApprovalDecision && outcome.updatedRecord.ownerId) {
        const pushed = await pushNotification(ctx, {
          recipientId: outcome.updatedRecord.ownerId,
          kind: 'approval_decided',
          title: `${finalRegisterType.label} decision: ${outcome.updatedRecord.reference}`,
          detail: `${outcome.updatedRecord.title} moved to ${outcome.updatedRecord.status}.`,
          href:
            outcome.updatedRecord.registerTypeKey === 'sign_off'
              ? '/?panel=partner_sign_off_queue'
              : `/registers?record=${outcome.updatedRecord.id}`,
          recordId: outcome.updatedRecord.id,
          matterId: outcome.updatedRecord.matterId ?? null,
          knownMatterIds: outcome.updatedRecord.matterId
            ? [outcome.updatedRecord.matterId]
            : undefined,
          tenantConfig: tenantCfg,
          byId: actor.id,
          at: outcome.transition.transitionedAt,
        });
        if (pushed) notificationsQueued = true;
      }

      return outcome;
    });

    if (notificationsQueued) {
      await drainNotificationOutboxesBestEffort(ctx, tenantCfg, actor.id);
    }

    // Execute afterTransition hook STRICTLY POST-COMMIT outside any write transaction.
    const afterHookRes = await getPlatformExtensionHost().executeRegisterAfterTransitionHook(
      ctx,
      hookCfg,
      {
        tenantId: ctx.tenantId,
        actorId: actor.id,
        correlationId: ctx.correlationId,
        registerType: finalRegisterType,
        previousRecord: txOutcome.previousRecord,
        updatedRecord: txOutcome.updatedRecord,
        transition: txOutcome.transition,
      },
    );
    if (afterHookRes.isolatedErrors.length > 0) {
      console.warn(
        JSON.stringify({
          level: 'warn',
          event: 'register.after_transition_hook_isolated_errors',
          tenantId: ctx.tenantId,
          correlationId: ctx.correlationId,
          count: afterHookRes.isolatedErrors.length,
        }),
      );
    }

    return {
      ok: true,
      record: txOutcome.updatedRecord,
      transition: txOutcome.transition,
      ...(afterHookRes.isolatedErrors.length > 0
        ? { isolatedHookErrors: afterHookRes.isolatedErrors }
        : {}),
    };
  } catch (err) {
    return mapRegisterErrorToDenial(err);
  }
}

export async function updateRegisterRecordDetailsService(
  input: {
    recordId: string;
    expectedRowVersion?: number;
    title?: string;
    assignedApproverId?: string | null;
    dueAt?: string | null;
    reviewAt?: string | null;
    fieldValues?: Record<string, unknown>;
  },
  byId?: string,
  options?: {
    readonly tenantCtx?: TenantContext | null;
    readonly tenantConfig?: TenantConfiguration;
  },
): Promise<
  | { ok: true; record: RegisterRecord }
  | RegisterServiceDenialOrError
> {
  try {
    const { ctx, tenantCfg, actor, people, teams, permSet } =
      await resolveRegisterActorAndConfig(byId, undefined, options);
    const registerRepo = getRegisterRepository();
    const catRepo = getCatalogueRepository();
    const existing = await registerRepo.getRegisterRecordById(ctx, input.recordId?.trim() || '', {
      includeRestricted: true,
    });
    if (!existing) {
      return registerServiceFailure(
        'NOT_FOUND',
        `Register record "${input.recordId}" was not found.`,
      );
    }
    if (existing.matterId) {
      const matter = await getMatterRepository().getMatterById<Matter>(ctx, existing.matterId, {
        includeRestricted: true,
      });
      if (!matter || !canPersonAccessMatter(matter, actor.id, actor, { allPeople: people, teams })) {
        return registerServiceFailure(
          'FORBIDDEN',
          'You do not have access to the restricted matter linked to this register record.',
        );
      }
    }
    const dbOverride = await catRepo.getModuleConfig<RegistersConfiguration>(ctx, 'registers');
    const baseRegisters = tenantCfg.registers ?? DEFAULT_REGISTERS_CONFIG;
    const registerType = findEffectiveRegisterType(
      existing.registerTypeKey,
      baseRegisters,
      dbOverride,
    );
    if (!registerType) {
      return registerServiceFailure(
        'VALIDATION_ERROR',
        `Register type "${existing.registerTypeKey}" is not configured.`,
      );
    }
    if (!permSet.permissions.has(registerType.editPermission)) {
      return registerServiceFailure(
        'FORBIDDEN',
        `Missing permission "${registerType.editPermission}" to edit ${registerType.label}.`,
      );
    }

    const validatedFields = validateRegisterFieldValues({
      registerType,
      fieldValues: { ...existing.fieldValues, ...(input.fieldValues ?? {}) },
      applyDefaults: false,
      enforceRequired: true,
    });
    const nowIso = new Date().toISOString();
    let notificationsQueued = false;
    const updatedRecord = await registerRepo.withTenantTransaction(ctx, async () => {
      const { updatedRecord: updated } = await registerRepo.updateRegisterRecordDetails(ctx, {
        recordId: existing.id,
        expectedRowVersion: input.expectedRowVersion,
        ...(input.title !== undefined ? { title: input.title.trim() } : {}),
        ...(input.assignedApproverId !== undefined
          ? { assignedApproverId: input.assignedApproverId?.trim() || null }
          : {}),
        ...(input.dueAt !== undefined ? { dueAt: input.dueAt } : {}),
        ...(input.reviewAt !== undefined ? { reviewAt: input.reviewAt } : {}),
        fieldValues: validatedFields,
        updatedById: actor.id,
      });
      await appendTenantAuditEntries(ctx, [
        {
          recordType: 'register_record',
          recordId: existing.id,
          action: 'update',
          field: 'Details',
          oldValue: existing.title,
          newValue: (input.title ?? existing.title).trim(),
          byId: actor.id,
          at: nowIso,
        },
      ]);

      const approverChanged =
        updated.assignedApproverId !== null &&
        updated.assignedApproverId !== existing.assignedApproverId;
      const reviewChanged =
        Boolean(updated.reviewAt) &&
        (updated.reviewAt !== existing.reviewAt ||
          updated.assignedApproverId !== existing.assignedApproverId);
      if (
        registerType.approvalRules !== null &&
        approverChanged &&
        updated.assignedApproverId
      ) {
        const pushed = await pushNotification(ctx, {
          recipientId: updated.assignedApproverId,
          kind: 'approval_requested',
          title: `Approval requested: ${updated.reference}`,
          detail: `${registerType.label} "${updated.title}" has been assigned to you for approval.`,
          href:
            updated.registerTypeKey === 'sign_off'
              ? '/?panel=partner_sign_off_queue'
              : `/registers?record=${updated.id}`,
          recordId: updated.id,
          matterId: updated.matterId ?? null,
          knownMatterIds: updated.matterId ? [updated.matterId] : undefined,
          tenantConfig: tenantCfg,
          byId: actor.id,
          at: nowIso,
        });
        if (pushed) notificationsQueued = true;
      } else if (
        (registerType.approvalRules === null && approverChanged) ||
        reviewChanged
      ) {
        const reviewerId = updated.assignedApproverId || updated.ownerId;
        if (reviewerId) {
          const pushed = await pushNotification(ctx, {
            recipientId: reviewerId,
            kind: 'register_review_assigned',
            title: `Register review assigned: ${updated.reference}`,
            detail: `${registerType.label} "${updated.title}" has been assigned for your review.`,
            href: `/registers?record=${updated.id}`,
            recordId: updated.id,
            matterId: updated.matterId ?? null,
            knownMatterIds: updated.matterId ? [updated.matterId] : undefined,
            tenantConfig: tenantCfg,
            byId: actor.id,
            at: nowIso,
          });
          if (pushed) notificationsQueued = true;
        }
      }
      return updated;
    });
    if (notificationsQueued) {
      await drainNotificationOutboxesBestEffort(ctx, tenantCfg, actor.id);
    }
    return { ok: true, record: updatedRecord };
  } catch (err) {
    return mapRegisterErrorToDenial(err);
  }
}

export async function saveRegistersConfigRecord(
  newConfigInput: RegistersConfiguration,
  reason: string,
  byId?: string,
  options?:
    | {
        readonly mfaVerified?: boolean;
        readonly tenantCtx?: TenantContext | null;
        readonly tenantConfig?: TenantConfiguration;
      }
    | boolean,
): Promise<
  | { ok: true; config: RegistersConfiguration; registerTypes: RegisterTypeDefinition[] }
  | RegisterServiceDenialOrError
> {
  try {
    const explicitMfa = typeof options === 'boolean' ? options : options?.mfaVerified;
    const { ctx, tenantCfg, actor, permSet } = await resolveRegisterActorAndConfig(
      byId,
      explicitMfa,
      typeof options === 'boolean' ? undefined : options,
    );
    if (!permSet.permissions.has('register:configure')) {
      return registerServiceFailure('FORBIDDEN', 'Missing required permission "register:configure".');
    }
    if (!permSet.mfaVerified) {
      return registerServiceFailure(
        'MFA_REQUIRED',
        'Multi-factor authentication is required to configure firm registers.',
      );
    }
    const cleanReason = reason?.trim();
    if (!cleanReason) {
      return registerServiceFailure(
        'VALIDATION_ERROR',
        'An audited change reason is required to save register configuration.',
      );
    }

    const validated = validateRegistersConfig(newConfigInput);
    const baseRegisters = tenantCfg.registers ?? DEFAULT_REGISTERS_CONFIG;
    const effectiveTypes = resolveEffectiveRegisterTypes(baseRegisters, validated);

    const catRepo = getCatalogueRepository();
    const nowIso = new Date().toISOString();
    const saved = await catRepo.withTenantTransaction(ctx, async () => {
      const previous = await catRepo.getModuleConfig<RegistersConfiguration>(ctx, 'registers');
      const stored = await catRepo.putModuleConfig<RegistersConfiguration>(
        ctx,
        'registers',
        validated,
        actor.id,
      );
      await appendTenantAuditEntries(ctx, [
        {
          recordType: 'registers_config',
          recordId: 'FIRM-REGISTERS-CONFIG',
          action: 'update',
          field: 'Registers configuration',
          oldValue: `${previous?.customTypes?.length ?? 0} custom registers`,
          newValue: `${stored.customTypes?.length ?? 0} custom registers`,
          byId: actor.id,
          at: nowIso,
          reason: cleanReason,
        },
      ]);
      return stored;
    });

    return {
      ok: true,
      config: saved,
      registerTypes: effectiveTypes,
    };
  } catch (err) {
    return mapRegisterErrorToDenial(err);
  }
}

export interface RegisterRemindersJobSummary {
  readonly tenantId: string;
  readonly localDate: string;
  readonly candidatesEvaluated: number;
  readonly remindersDispatched: number;
  readonly skippedAlreadyNotified: number;
  readonly skippedRestrictedOrMissingRecipients: number;
}

export async function executeRegisterRemindersForTenant(
  ctx: TenantContext,
  options: {
    triggerSource: 'scheduled' | 'manual';
    triggeredById: string;
    timeZone?: string;
    defaultRunHourLocal?: number;
    statementTimeoutMs?: number;
    signal?: AbortSignal;
    tenantConfig?: TenantConfiguration;
  },
): Promise<ControlledJobRunOutcome<{ summary: RegisterRemindersJobSummary }>> {
  const tenantConfig = resolveVerifiedTenantConfiguration(ctx, options.tenantConfig);
  const effectiveTimeZone =
    options.timeZone?.trim() ||
    tenantConfig.timeZone ||
    'Europe/London';
  const now = new Date();
  const nowIso = now.toISOString();

  const preModuleOverride = await getCatalogueRepository().getModuleConfig<RegistersConfiguration>(
    ctx,
    'registers',
  );
  const baseRegisters = tenantConfig.registers ?? DEFAULT_REGISTERS_CONFIG;
  const preMergedConfig = mergeRegistersConfigurations(baseRegisters, preModuleOverride);
  const targetLocalHour =
    options.defaultRunHourLocal ?? getEffectiveReminderHourLocal(preMergedConfig);

  return getJobRunRepository().executeControlledTenantJobRun(ctx, {
    jobKey: 'register-reminders',
    triggerSource: options.triggerSource,
    triggeredById: options.triggeredById,
    timeZone: effectiveTimeZone,
    targetLocalHour,
    now,
    statementTimeoutMs: options.statementTimeoutMs,
    signal: options.signal,
    work: async ({ localDate }) => {
      const registerRepo = getRegisterRepository();
      const taskRepo = getTaskWorkflowRepository();
      const partyRepo = getPartyRepository();
      const matterRepo = getMatterRepository();
      const hrRepo = getHrAndRbacRepository();
      const catRepo = getCatalogueRepository();

      const [people, matters, teams, rbacOverride, moduleOverride, candidates] =
        await Promise.all([
          partyRepo.listAllPeople<Person>(ctx),
          matterRepo.listAllMattersUnfiltered<Matter>(ctx),
          hrRepo.listAllTeams<Team>(ctx),
          hrRepo.getRbacConfigOverride<RbacConfiguration>(ctx),
          catRepo.getModuleConfig<RegistersConfiguration>(ctx, 'registers'),
          registerRepo.listReminderCandidateRecords(ctx),
        ]);

      const registersCfg = mergeRegistersConfigurations(baseRegisters, moduleOverride);
      const effectiveTypes = resolveEffectiveRegisterTypes(baseRegisters, moduleOverride);
      const typeByKey = new Map(effectiveTypes.map((t) => [t.key, t] as const));
      const matterById = new Map(matters.map((m) => [m.id, m] as const));
      const personById = new Map(people.map((p) => [p.id, p] as const));
      const rbacConfig = await loadEffectiveTenantRbacConfig(ctx, rbacOverride, tenantConfig);

      let candidatesEvaluated = 0;
      let remindersDispatched = 0;
      let skippedAlreadyNotified = 0;
      let skippedRestrictedOrMissingRecipients = 0;

      for (const record of candidates) {
        const regType = typeByKey.get(record.registerTypeKey);
        if (!regType) continue;
        const stages = evaluateRegisterDueAndReviewReminders({
          record,
          registerType: regType,
          registersConfig: registersCfg,
          localDateYmd: localDate,
          timeZone: effectiveTimeZone,
        });
        if (stages.length === 0) continue;

        const linkedMatter = record.matterId
          ? matterById.get(record.matterId) ?? null
          : null;

        for (const stage of stages) {
          candidatesEvaluated += 1;
          if (record.matterId && !linkedMatter) {
            skippedRestrictedOrMissingRecipients += 1;
            await registerRepo.withTenantTransaction(ctx, async (tx) => {
              await registerRepo.tryAcquireReminderDispatchInTx(tx, ctx, {
                registerRecordId: record.id,
                idempotencyKey: stage.idempotencyKey,
                triggerKind: stage.triggerKind,
                stageDaysBefore: stage.stageDaysBefore,
                lastNotifiedAt: null,
                lastSkippedReason: 'missing_matter',
              });
            });
            continue;
          }

          const rawRecipientIds = new Set<string>();
          if (record.ownerId) rawRecipientIds.add(record.ownerId);
          if (
            regType.reminderSchedule.recipientMode !== 'owner_only' &&
            record.assignedApproverId
          ) {
            rawRecipientIds.add(record.assignedApproverId);
          }
          if (
            regType.reminderSchedule.recipientMode === 'matter_team_and_owner' &&
            linkedMatter
          ) {
            if (linkedMatter.responsiblePartnerId) {
              rawRecipientIds.add(linkedMatter.responsiblePartnerId);
            }
            if (linkedMatter.supervisingPartnerId) {
              rawRecipientIds.add(linkedMatter.supervisingPartnerId);
            }
          }

          const permittedRecipientIds: string[] = [];
          for (const pid of rawRecipientIds) {
            const p = personById.get(pid);
            if (!p || p.mergedIntoId || isLeaverPerson(p)) continue;
            const perms = resolvePersonPermissionSet(p, {
              allPeople: people,
              teams,
              config: { ...tenantConfig, rbac: rbacConfig },
            });
            const canSeeReg =
              perms.permissions.has('register:view') ||
              (record.registerTypeKey === 'undertaking' &&
                perms.permissions.has('undertaking:manage'));
            if (!canSeeReg) continue;
            if (
              linkedMatter &&
              !canPersonAccessMatter(linkedMatter, p.id, p, {
                allPeople: people,
                teams,
              })
            ) {
              continue;
            }
            permittedRecipientIds.push(p.id);
          }

          if (permittedRecipientIds.length === 0) {
            skippedRestrictedOrMissingRecipients += 1;
            await registerRepo.withTenantTransaction(ctx, async (tx) => {
              await registerRepo.tryAcquireReminderDispatchInTx(tx, ctx, {
                registerRecordId: record.id,
                idempotencyKey: stage.idempotencyKey,
                triggerKind: stage.triggerKind,
                stageDaysBefore: stage.stageDaysBefore,
                lastNotifiedAt: null,
                lastSkippedReason: 'no_permitted_recipients',
              });
            });
            continue;
          }

          await registerRepo.withTenantTransaction(ctx, async (tx) => {
            const acquired = await registerRepo.tryAcquireReminderDispatchInTx(tx, ctx, {
              registerRecordId: record.id,
              idempotencyKey: stage.idempotencyKey,
              triggerKind: stage.triggerKind,
              stageDaysBefore: stage.stageDaysBefore,
              lastNotifiedAt: nowIso,
              lastSkippedReason: null,
              metadata: {
                recipientIds: permittedRecipientIds,
                localDate,
              },
            });
            if (!acquired) {
              skippedAlreadyNotified += 1;
              return;
            }

            const ntfIds = await taskRepo.allocateNextNotificationIds(
              ctx,
              permittedRecipientIds.length,
            );
            const timingLabel = stage.isOverdue
              ? `${Math.abs(stage.stageDaysBefore)}d overdue`
              : stage.stageDaysBefore === 0
                ? 'due today'
                : `${stage.stageDaysBefore}d remaining`;
            const kindLabel = stage.triggerKind === 'review' ? 'Review' : 'Compliance deadline';

            for (let idx = 0; idx < permittedRecipientIds.length; idx++) {
              const recipientId = permittedRecipientIds[idx]!;
              const notifItem: NotificationItem = {
                id: ntfIds[idx]!,
                recipientId,
                kind: 'register_reminder',
                title: `${regType.label} reminder: ${record.reference}`,
                detail: `${record.title} — ${kindLabel} (${timingLabel})`,
                href: `/registers?record=${record.id}`,
                recordId: record.id,
                matterId: record.matterId ?? null,
                byId: options.triggeredById,
                read: false,
                createdAt: nowIso,
              };
              await taskRepo.upsertNotificationInTx(tx, ctx, notifItem);
              await enqueueNotificationEmailIfImmediate(ctx, notifItem, {
                byId: options.triggeredById,
                tenantConfig,
                drainImmediately: false,
                recipientPerson: personById.get(recipientId) ?? null,
                accessAlreadyVerified: true,
              });
              await enqueueNotificationTeamsActivityIfEnabled(ctx, notifItem, {
                byId: options.triggeredById,
                tenantConfig,
                drainImmediately: false,
                accessAlreadyVerified: true,
              });
            }

            await appendTenantAuditEntries(ctx, [
              {
                recordType: 'register_record',
                recordId: record.id,
                action: 'update',
                field: 'Reminder dispatched',
                oldValue: '',
                newValue: stage.idempotencyKey,
                byId: options.triggeredById,
                at: nowIso,
                reason: `${kindLabel} reminder (${timingLabel}) sent to ${permittedRecipientIds.length} recipient(s).`,
              },
            ]);
            remindersDispatched += 1;
          });
        }
      }

      if (remindersDispatched > 0) {
        await drainNotificationOutboxesBestEffort(
          ctx,
          tenantConfig,
          options.triggeredById,
        );
      }

      const summary: RegisterRemindersJobSummary = {
        tenantId: ctx.tenantId,
        localDate,
        candidatesEvaluated,
        remindersDispatched,
        skippedAlreadyNotified,
        skippedRestrictedOrMissingRecipients,
      };

      console.info(
        JSON.stringify({
          level: 'info',
          event: 'register_reminders.completed',
          tenantId: ctx.tenantId,
          correlationId: ctx.correlationId,
          localDate,
          candidatesEvaluated,
          remindersDispatched,
          skippedAlreadyNotified,
          skippedRestrictedOrMissingRecipients,
        }),
      );

      return {
        result: { summary },
        summary: {
          candidatesEvaluated,
          remindersDispatched,
          skippedAlreadyNotified,
          skippedRestrictedOrMissingRecipients,
        },
      };
    },
  });
}

export async function runScheduledRegisterRemindersJobSweep(options?: {
  readonly registry?: TenantRegistry;
  readonly timeoutMs?: number;
  readonly defaultRunHourLocal?: number;
  readonly guardedJobOptions?: GuardedJobOptions;
  readonly tenantConfigOverrideByTenantId?: Record<string, TenantConfiguration>;
}): Promise<ScheduledTenantJobSweepSummary> {
  assertTestOnlyTenantConfigOverride(options?.tenantConfigOverrideByTenantId);
  const registry = options?.registry ?? loadActiveTenantRegistry();
  const succeededTenants: string[] = [];
  const skippedTenants: Array<{
    readonly tenantId: string;
    readonly status: 'skipped' | 'already_running';
    readonly reason?: string;
  }> = [];
  const failedTenants: Array<{
    readonly tenantId: string;
    readonly errorCode?: string;
  }> = [];

  for (const entry of registry.tenants) {
    if (!entry.enabled) continue;
    try {
      const outcome = await guardedJob(
        'register-reminders',
        entry,
        async ({ tenantContext, tenantEntry, timeoutMs, signal }) => {
          const tenantConfig =
            options?.tenantConfigOverrideByTenantId?.[tenantEntry.tenantId] ??
            getTenantConfigurationForRegistryEntry(
              tenantEntry,
              registry.hostingMode,
            );
          return executeRegisterRemindersForTenant(tenantContext, {
            triggerSource: 'scheduled',
            triggeredById: 'system:register-reminders',
            timeZone: tenantEntry.timeZone,
            defaultRunHourLocal: options?.defaultRunHourLocal,
            statementTimeoutMs: timeoutMs,
            tenantConfig,
            signal,
          });
        },
        {
          registry,
          timeoutMs: options?.timeoutMs,
          ...options?.guardedJobOptions,
        },
      );
      if (outcome.outcome === 'executed') {
        succeededTenants.push(entry.tenantId);
      } else {
        skippedTenants.push({
          tenantId: entry.tenantId,
          status: outcome.outcome === 'already_running' ? 'already_running' : 'skipped',
          reason: outcome.outcome,
        });
      }
    } catch (err) {
      failedTenants.push({
        tenantId: entry.tenantId,
        errorCode: sanitizeJobErrorCode(err),
      });
    }
  }

  return {
    exitCode: failedTenants.length > 0 ? 1 : 0,
    succeededTenants,
    skippedTenants,
    failedTenants,
  };
}

export interface QuoteExpiryJobSummary {
  readonly tenantId: string;
  readonly localDate: string;
  readonly candidatesEvaluated: number;
  readonly expiredCount: number;
}

/**
 * Transitions overdue `Sent` and `Follow-up due` quotes (`validUntil < localDate`)
 * to `'Expired'`, appends a single `'Quote expired'` timeline entry, and writes a
 * zero-PII audit entry in PostgreSQL (ADR 0030, `R663`).
 */
export async function executeQuoteExpiryForTenant(
  ctx: TenantContext,
  options: {
    triggerSource: 'scheduled' | 'manual';
    triggeredById: string;
    timeZone?: string;
    defaultRunHourLocal?: number;
    statementTimeoutMs?: number;
    signal?: AbortSignal;
    tenantConfig?: TenantConfiguration;
    /** Test-only hook invoked right before expiring each candidate quote (`R675`). */
    onBeforeExpireQuote?: (quoteId: string) => Promise<void>;
  },
): Promise<ControlledJobRunOutcome<{ summary: QuoteExpiryJobSummary }>> {
  const tenantConfig = resolveVerifiedTenantConfiguration(ctx, options.tenantConfig);
  const effectiveTimeZone =
    options.timeZone?.trim() ||
    tenantConfig.timeZone ||
    'Europe/London';
  const now = new Date();
  const nowIso = now.toISOString();

  return getJobRunRepository().executeControlledTenantJobRun(ctx, {
    jobKey: 'quote-expiry',
    triggerSource: options.triggerSource,
    triggeredById: options.triggeredById,
    timeZone: effectiveTimeZone,
    targetLocalHour: options.defaultRunHourLocal ?? 2,
    now,
    statementTimeoutMs: options.statementTimeoutMs,
    signal: options.signal,
    work: async ({ localDate }) => {
      const intakeRepo = getIntakeQuoteRepository();
      const candidates = await intakeRepo.listOverdueQuotesForLifecycleSweep<Quote>(
        ctx,
        localDate,
      );
      const lifecycleNow = new Date(`${localDate}T${nowIso.slice(11)}`);
      let expiredCount = 0;

      for (const quote of candidates) {
        if (
          options.onBeforeExpireQuote &&
          (process.env.NODE_ENV === 'test' || Boolean(process.env.VITEST))
        ) {
          await options.onBeforeExpireQuote(quote.id);
        }
        const expireResult = await intakeRepo.expireQuoteIfOverdue<Quote>(
          ctx,
          quote.id,
          {
            localDate,
            applyTransition: (freshQuote) => {
              const previousStatus = freshQuote.status;
              const { changed, newlyExpired } = applyQuoteEffectiveLifecycle(
                freshQuote,
                lifecycleNow,
                { appendExpiredTimeline: true },
              );
              if (!changed && !newlyExpired) {
                return { shouldPersist: false, previousStatus };
              }
              freshQuote.updatedAt = nowIso;
              return { shouldPersist: true, previousStatus };
            },
            onPersistedInTx: async (expiredQuote, previousStatus) => {
              await appendTenantAuditEntries(ctx, [
                {
                  recordType: 'quote',
                  recordId: expiredQuote.id,
                  action: 'status-change',
                  field: 'Quote lifecycle status',
                  oldValue: previousStatus,
                  newValue: expiredQuote.status,
                  byId: options.triggeredById,
                  at: nowIso,
                  reason: `Valid-until date (${expiredQuote.validUntil ?? localDate}) passed without an outcome.`,
                },
              ]);
            },
          },
        );
        if (!expireResult.expired || !expireResult.quote) {
          continue;
        }
        expiredCount += 1;
      }

      const summary: QuoteExpiryJobSummary = {
        tenantId: ctx.tenantId,
        localDate,
        candidatesEvaluated: candidates.length,
        expiredCount,
      };

      console.info(
        JSON.stringify({
          level: 'info',
          event: 'quote_expiry.completed',
          tenantId: ctx.tenantId,
          correlationId: ctx.correlationId,
          localDate,
          candidatesEvaluated: candidates.length,
          expiredCount,
        }),
      );

      return {
        result: { summary },
        summary: {
          candidatesEvaluated: candidates.length,
          expiredCount,
        },
      };
    },
  });
}

