export interface OutboxDrainSweepSummary extends ScheduledTenantJobSweepSummary {
  readonly resultsByTenant: Record<string, CombinedOutboxDrainResult>;
}

/**
 * Scheduled `outbox-drain` sweep across every enabled tenant in `TenantRegistry` (ADR 0027 §6.4 / ADR 0035 §3.1).
 * Runs under `guardedJob('outbox-drain', ...)` with `notification:drain_outbox` (`jobOnly: true`)
 * and bypasses `public.job_runs`'s once-per-local-day uniqueness gate.
 * Drains both `public.email_outbox` and `public.teams_activity_outbox`.
 */
export async function runScheduledOutboxDrainJobSweep(options?: {
  readonly registry?: TenantRegistry;
  readonly timeoutMs?: number;
  readonly guardedJobOptions?: GuardedJobOptions;
  readonly tenantConfigOverrideByTenantId?: Record<string, TenantConfiguration>;
  readonly emailSender?: EmailSender;
  readonly teamsNotifier?: TeamsNotifier;
  readonly teamsDevCatcherHandler?: TeamsDevCatcherHandler;
  readonly secretReader?: KeyVaultSecretReader;
  readonly storageProvider?: DocumentStorageProvider;
  readonly batchSize?: number;
  readonly maxAttempts?: number;
  readonly baseBackoffSeconds?: number;
  readonly now?: Date;
}): Promise<OutboxDrainSweepSummary> {
  assertTestOnlyTenantConfigOverride(options?.tenantConfigOverrideByTenantId);
  const registry = options?.registry ?? loadActiveTenantRegistry();
  const outboxRepo = getOutboxRepository();
  const succeededTenants: string[] = [];
  const skippedTenants: Array<{
    readonly tenantId: string;
    readonly status: 'skipped' | 'already_running';
    readonly reason?: string;
  }> = [];
  const failedTenants: Array<{
    readonly tenantId: string;
    readonly errorCode?: string;
  }> = [];
  const resultsByTenant: Record<string, CombinedOutboxDrainResult> = {};

  for (const entry of registry.tenants) {
    if (!entry.enabled) continue;
    try {
      const outcome = await guardedJob(
        'outbox-drain',
        entry,
        async ({ tenantContext, tenantEntry }) => {
          const tenantConfig =
            options?.tenantConfigOverrideByTenantId?.[tenantEntry.tenantId] ??
            getTenantConfigurationForRegistryEntry(
              tenantEntry,
              registry.hostingMode,
            );
          return drainOutboxForTenant(tenantContext, {
            tenantConfig,
            outboxRepository: outboxRepo,
            emailSender: options?.emailSender,
            teamsNotifier: options?.teamsNotifier,
            teamsDevCatcherHandler: options?.teamsDevCatcherHandler,
            secretReader: options?.secretReader,
            storageProvider: options?.storageProvider,
            actorId: 'system:outbox-drain',
            batchSize: options?.batchSize,
            maxAttempts: options?.maxAttempts,
            baseBackoffSeconds: options?.baseBackoffSeconds,
            now: options?.now,
          });
        },
        {
          registry,
          timeoutMs: options?.timeoutMs,
          ...options?.guardedJobOptions,
        },
      );

      resultsByTenant[entry.tenantId] = outcome;
      if (
        outcome.skippedDisabled &&
        outcome.scrubbedCount === 0 &&
        outcome.teams.scrubbedCount === 0
      ) {
        skippedTenants.push({
          tenantId: entry.tenantId,
          status: 'skipped',
          reason: 'email_and_teams_providers_disabled',
        });
      } else {
        succeededTenants.push(entry.tenantId);
      }
    } catch (err) {
      failedTenants.push({
        tenantId: entry.tenantId,
        errorCode: sanitizeJobErrorCode(err),
      });
    }
  }

  return {
    exitCode: failedTenants.length > 0 ? 1 : 0,
    succeededTenants,
    skippedTenants,
    failedTenants,
    resultsByTenant,
  };
}

export interface NotificationDigestsJobSummary {
  readonly tenantId: string;
  readonly localDate: string;
  readonly isoWeekday: number;
  readonly undigestedExamined: number;
  readonly digestEmailsQueued: number;
  readonly digestedNotificationCount: number;
  readonly suppressedRevokedCount: number;
  readonly deferredWeeklyCount: number;
  readonly nonDigestMarkedCount: number;
}

export type NotificationDigestsJobOutcome =
  | ControlledJobRunOutcome<NotificationDigestsJobSummary>
  | {
      readonly outcome: 'outside_working_days';
      readonly localDate: string;
      readonly localHour: number;
      readonly isoWeekday: number;
    };

function extractNotificationMatterIds(params: {
  readonly item: NotificationItem;
  readonly matterById: ReadonlyMap<string, Matter>;
  readonly taskById: ReadonlyMap<string, Task>;
  readonly keyDateById: ReadonlyMap<string, KeyDate>;
  readonly enquiryById: ReadonlyMap<string, Enquiry>;
  readonly quoteById: ReadonlyMap<string, Quote>;
  readonly registerRecordById: ReadonlyMap<string, RegisterRecord>;
}): {
  readonly matterIds: readonly string[];
  readonly hiddenDraftEnquiry: boolean;
} {
  const { item } = params;
  const matterIds = new Set<string>();
  let hiddenDraftEnquiry = false;

  if (item.matterId?.trim()) {
    matterIds.add(item.matterId.trim());
  }
  if (item.recordId && params.matterById.has(item.recordId)) {
    matterIds.add(item.recordId);
  }
  const hrefMatch = /\/matters\/([^/?#]+)/.exec(item.href ?? '');
  if (hrefMatch?.[1]) {
    matterIds.add(hrefMatch[1]);
  }

  const addEnquiryMatters = (enq: Enquiry | undefined) => {
    if (!enq) return;
    if (
      enq.status === 'Draft' &&
      enq.createdById !== item.recipientId &&
      enq.takenById !== item.recipientId
    ) {
      hiddenDraftEnquiry = true;
    }
    if (enq.convertedMatterId) {
      matterIds.add(enq.convertedMatterId);
    }
    for (const m of params.matterById.values()) {
      if (m.sourceEnquiryId === enq.id) {
        matterIds.add(m.id);
      }
    }
  };

  const addQuoteMatters = (q: Quote | undefined) => {
    if (!q) return;
    if (q.convertedMatterId) matterIds.add(q.convertedMatterId);
    for (const m of params.matterById.values()) {
      if (m.sourceQuoteId === q.id) {
        matterIds.add(m.id);
      }
    }
    if (q.linkedEnquiryId) {
      addEnquiryMatters(params.enquiryById.get(q.linkedEnquiryId));
    }
  };

  const addKeyDateMatters = (kd: KeyDate | undefined) => {
    if (!kd) return;
    if (kd.matterId) matterIds.add(kd.matterId);
    if (kd.enquiryId) {
      addEnquiryMatters(params.enquiryById.get(kd.enquiryId));
    }
  };

  const hrefKdMatch = /\/key-dates\/([^/?#]+)/.exec(item.href ?? '');
  if (hrefKdMatch?.[1]) {
    addKeyDateMatters(params.keyDateById.get(hrefKdMatch[1]));
  }

  const task = item.recordId ? params.taskById.get(item.recordId) : undefined;
  if (task) {
    for (const lr of task.linkedRecords ?? []) {
      if (lr.recordType === 'matter' && lr.recordId) {
        matterIds.add(lr.recordId);
      } else if (lr.recordType === 'enquiry' && lr.recordId) {
        addEnquiryMatters(params.enquiryById.get(lr.recordId));
      } else if (lr.recordType === 'quote' && lr.recordId) {
        addQuoteMatters(params.quoteById.get(lr.recordId));
      } else if ((lr as { recordType: string }).recordType === 'key_date' && lr.recordId) {
        addKeyDateMatters(params.keyDateById.get(lr.recordId));
      }
    }
    if (task.linkedKeyDateId) {
      addKeyDateMatters(params.keyDateById.get(task.linkedKeyDateId));
    }
  }

  addKeyDateMatters(item.recordId ? params.keyDateById.get(item.recordId) : undefined);

  addEnquiryMatters(item.recordId ? params.enquiryById.get(item.recordId) : undefined);
  addQuoteMatters(item.recordId ? params.quoteById.get(item.recordId) : undefined);

  const reg = item.recordId ? params.registerRecordById.get(item.recordId) : undefined;
  if (reg?.matterId) {
    matterIds.add(reg.matterId);
  }

  return {
    matterIds: Array.from(matterIds),
    hiddenDraftEnquiry,
  };
}

function renderDigestEmailContent(params: {
  readonly tenantDisplayName: string;
  readonly localDate: string;
  readonly recipientName: string;
  readonly dailyItems: readonly NotificationItem[];
  readonly weeklyItems: readonly NotificationItem[];
}): {
  readonly subject: string;
  readonly htmlBody: string;
  readonly textBody: string;
} {
  const totalCount = params.dailyItems.length + params.weeklyItems.length;
  const isWeeklyOnly = params.weeklyItems.length > 0 && params.dailyItems.length === 0;
  const heading = isWeeklyOnly
    ? 'Weekly notification digest'
    : params.weeklyItems.length > 0
      ? 'Daily and weekly notification digest'
      : 'Daily notification digest';
  const subject = `[${params.tenantDisplayName}] ${heading} (${params.localDate} — ${totalCount} item${totalCount === 1 ? '' : 's'})`;

  const renderSectionHtml = (title: string, items: readonly NotificationItem[]) => {
    if (items.length === 0) return '';
    const rows = items
      .map(
        (item) =>
          `<li><strong>${escapeHtmlTextForEmail(item.title)}</strong>${item.detail ? ` — ${escapeHtmlTextForEmail(item.detail)}` : ''}${item.href ? ` (<code>${escapeHtmlTextForEmail(item.href)}</code>)` : ''}</li>`,
      )
      .join('');
    return `<h3>${escapeHtmlTextForEmail(title)} (${items.length})</h3><ul>${rows}</ul>`;
  };

  const renderSectionText = (title: string, items: readonly NotificationItem[]) => {
    if (items.length === 0) return '';
    const rows = items
      .map(
        (item) =>
          `- ${item.title}${item.detail ? ` — ${item.detail}` : ''}${item.href ? ` (${item.href})` : ''}`,
      )
      .join('\n');
    return `${title} (${items.length}):\n${rows}`;
  };

  const htmlBody = [
    `<p>Hello ${escapeHtmlTextForEmail(params.recipientName)},</p>`,
    `<p>Here is your ${escapeHtmlTextForEmail(heading.toLowerCase())} for ${escapeHtmlTextForEmail(params.localDate)}.</p>`,
    renderSectionHtml('Daily updates', params.dailyItems),
    renderSectionHtml('Weekly summary updates', params.weeklyItems),
  ]
    .filter(Boolean)
    .join('');

  const textBody = [
    `Hello ${params.recipientName},`,
    `Here is your ${heading.toLowerCase()} for ${params.localDate}.`,
    renderSectionText('Daily updates', params.dailyItems),
    renderSectionText('Weekly summary updates', params.weeklyItems),
  ]
    .filter(Boolean)
    .join('\n\n');

  return { subject, htmlBody, textBody };
}

/**
 * Single-transaction per-tenant daily and weekly email digest compiler (`system:notification-digests`).
 * Runs Mon–Fri in tenant timezone at or after `notifications.digestHourLocal` (default `08:00`),
 * re-verifying matter visibility before queuing any item into `public.email_outbox` (ADR 0035 §2).
 */
export async function executeNotificationDigestsForTenant(
  ctx: TenantContext,
  options: {
    readonly triggerSource?: 'scheduled' | 'manual';
    readonly triggeredById?: string;
    readonly timeZone?: string;
    readonly digestHourLocal?: number;
    readonly now?: Date;
    readonly localDateOverride?: string;
    readonly statementTimeoutMs?: number;
    readonly signal?: AbortSignal;
    readonly tenantConfig?: TenantConfiguration;
    readonly emailSender?: EmailSender;
    readonly secretReader?: KeyVaultSecretReader;
    readonly storageProvider?: DocumentStorageProvider;
    readonly drainAfterCommit?: boolean;
  } = {},
): Promise<NotificationDigestsJobOutcome> {
  const tenantConfig = resolveVerifiedTenantConfiguration(ctx, options.tenantConfig);
  const effectiveTimeZone =
    options.timeZone?.trim() || tenantConfig.timeZone || 'Europe/London';
  const triggeredById =
    options.triggeredById?.trim() || 'system:notification-digests';
  const triggerSource = options.triggerSource ?? 'scheduled';
  const now = options.now ?? new Date();
  const clock = resolveTenantLocalDateAndHour(now, effectiveTimeZone);
  const isoWeekday = resolveTenantIsoWeekday(now, effectiveTimeZone);
  const targetLocalHour =
    options.digestHourLocal ?? tenantConfig.notifications?.digestHourLocal ?? 8;

  // Mon–Fri only on scheduled runs BEFORE inserting any row into public.job_runs
  if (triggerSource === 'scheduled' && (isoWeekday === 6 || isoWeekday === 7)) {
    return {
      outcome: 'outside_working_days',
      localDate: options.localDateOverride?.trim() || clock.localDate,
      localHour: clock.localHour,
      isoWeekday,
    };
  }

  const outboxRepo = getOutboxRepository();

  const outcome = await getJobRunRepository().executeControlledTenantJobRun(
    ctx,
    {
      jobKey: 'notification-digests',
      triggerSource,
      triggeredById,
      timeZone: effectiveTimeZone,
      targetLocalHour,
      now,
      localDateOverride: options.localDateOverride,
      statementTimeoutMs: options.statementTimeoutMs,
      signal: options.signal,
      work: async ({ tx, localDate, nowIso }) => {
        const taskRepo = getTaskWorkflowRepository();
        const partyRepo = getPartyRepository();
        const hrRepo = getHrAndRbacRepository();
        const matterRepo = getMatterRepository();
        const intakeRepo = getIntakeQuoteRepository();
        const keyDateRepo = getKeyDateRepository();
        const registerRepo = getRegisterRepository();

        const [
          undigested,
          people,
          teams,
          matters,
          enquiries,
          quotes,
          tasks,
          keyDates,
          registerRecords,
          storedPrefs,
          effectiveRbac,
        ] = await Promise.all([
          taskRepo.listUndigestedNotificationsForDigest<NotificationItem>(
            ctx,
            { forUpdate: true },
          ),
          partyRepo.listAllPeople<Person>(ctx),
          hrRepo.listAllTeams<Team>(ctx),
          matterRepo.listAllMattersUnfiltered<Matter>(ctx),
          intakeRepo.listAllEnquiriesUnfiltered<Enquiry>(ctx),
          intakeRepo.listAllQuotesUnfiltered<Quote>(ctx),
          taskRepo.listAllTasksUnfiltered<Task>(ctx),
          keyDateRepo.listAllKeyDatesUnfilteredForScheduler(ctx),
          registerRepo.listAllRegisterRecordsUnfiltered(ctx),
          outboxRepo.listAllNotificationPreferences(ctx),
          loadEffectiveTenantRbacConfig(ctx, undefined, tenantConfig),
        ]);

        const personById = new Map(people.map((p) => [p.id, p]));
        const matterById = new Map(matters.map((m) => [m.id, m]));
        const enquiryById = new Map(enquiries.map((e) => [e.id, e]));
        const quoteById = new Map(quotes.map((q) => [q.id, q]));
        const taskById = new Map(tasks.map((t) => [t.id, t]));
        const keyDateById = new Map(keyDates.map((kd) => [kd.id, kd]));
        const registerRecordById = new Map(
          registerRecords.map((r) => [r.id, r]),
        );
        const prefByPersonKind = new Map(
          storedPrefs.map((pref) => [
            `${pref.personId}:${pref.notificationKind}`,
            pref,
          ]),
        );

        const markDigestSentIds: string[] = [];
        let suppressedRevokedCount = 0;
        let deferredWeeklyCount = 0;
        let nonDigestMarkedCount = 0;

        const bucketsByRecipient = new Map<
          string,
          {
            readonly daily: NotificationItem[];
            readonly weekly: NotificationItem[];
          }
        >();

        for (const item of undigested) {
          const person = personById.get(item.recipientId);
          if (
            !person ||
            person.mergedIntoId ||
            !person.isEmployee ||
            isLeaverPerson(person)
          ) {
            markDigestSentIds.push(item.id);
            suppressedRevokedCount += 1;
            continue;
          }

          const linked = extractNotificationMatterIds({
            item,
            matterById,
            taskById,
            keyDateById,
            enquiryById,
            quoteById,
            registerRecordById,
          });
          let revoked = linked.hiddenDraftEnquiry;
          if (!revoked) {
            for (const mId of linked.matterIds) {
              const linkedMatter = matterById.get(mId);
              if (
                linkedMatter &&
                !canPersonAccessMatter(linkedMatter, person.id, person, {
                  allPeople: people,
                  teams,
                  config: { rbac: effectiveRbac },
                  tenantId: ctx.tenantId,
                })
              ) {
                revoked = true;
                break;
              }
            }
          }
          if (revoked) {
            markDigestSentIds.push(item.id);
            suppressedRevokedCount += 1;
            continue;
          }

          const storedPref = prefByPersonKind.get(
            `${person.id}:${item.kind}`,
          );
          const defaults =
            DEFAULT_NOTIFICATION_PREFERENCES_BY_KIND[item.kind] ??
            DEFAULT_NOTIFICATION_PREFERENCES_BY_KIND.general;
          const emailFrequency =
            storedPref?.emailFrequency ?? defaults.emailFrequency;
          const digestDayOfWeek = storedPref?.digestDayOfWeek ?? 1;

          if (emailFrequency === 'immediate' || emailFrequency === 'none') {
            markDigestSentIds.push(item.id);
            nonDigestMarkedCount += 1;
            continue;
          }

          if (emailFrequency === 'weekly_digest') {
            if (digestDayOfWeek !== isoWeekday) {
              deferredWeeklyCount += 1;
              continue;
            }
            const bucket = bucketsByRecipient.get(person.id) ?? {
              daily: [],
              weekly: [],
            };
            bucket.weekly.push(item);
            bucketsByRecipient.set(person.id, bucket);
            continue;
          }

          const bucket = bucketsByRecipient.get(person.id) ?? {
            daily: [],
            weekly: [],
          };
          bucket.daily.push(item);
          bucketsByRecipient.set(person.id, bucket);
        }

        let digestEmailsQueued = 0;
        let digestedNotificationCount = 0;

        for (const [personId, bucket] of bucketsByRecipient.entries()) {
          const person = personById.get(personId);
          const recipientAddress = person
            ? resolvePrimaryActiveEmailForPerson(person)
            : null;
          const combinedItems = [...bucket.daily, ...bucket.weekly];
          if (!person || !recipientAddress) {
            for (const item of combinedItems) {
              markDigestSentIds.push(item.id);
              nonDigestMarkedCount += 1;
            }
            continue;
          }

          bucket.daily.sort((a, b) =>
            a.createdAt === b.createdAt
              ? a.id.localeCompare(b.id)
              : a.createdAt.localeCompare(b.createdAt),
          );
          bucket.weekly.sort((a, b) =>
            a.createdAt === b.createdAt
              ? a.id.localeCompare(b.id)
              : a.createdAt.localeCompare(b.createdAt),
          );

          const templateKey =
            bucket.weekly.length > 0
              ? 'notification-digest-weekly'
              : 'notification-digest-daily';
          const recipientName =
            person.preferredName?.trim() ||
            [person.firstName, person.surname].filter(Boolean).join(' ').trim() ||
            'Colleague';
          const rendered = renderDigestEmailContent({
            tenantDisplayName: tenantConfig.displayName,
            localDate,
            recipientName,
            dailyItems: bucket.daily,
            weeklyItems: bucket.weekly,
          });

          await outboxRepo.enqueueEmail(ctx, {
            idempotencyKey: `digest:${ctx.tenantId}:${person.id}:${localDate}`,
            templateKey,
            recipients: { to: [recipientAddress] },
            subject: rendered.subject,
            htmlBody: rendered.htmlBody,
            textBody: rendered.textBody,
            nextAttemptAt: nowIso,
            createdByPersonId: triggeredById,
            correlationId: ctx.correlationId,
          });

          digestEmailsQueued += 1;
          digestedNotificationCount += combinedItems.length;
          for (const item of combinedItems) {
            markDigestSentIds.push(item.id);
          }
        }

        if (markDigestSentIds.length > 0) {
          await taskRepo.markNotificationsDigestSentInTx(
            tx,
            ctx,
            markDigestSentIds,
            nowIso,
          );
        }

        if (digestEmailsQueued > 0 || suppressedRevokedCount > 0) {
          await appendTenantAuditEntries(ctx, [
            {
              recordType: 'notification_digest',
              recordId: `DIGEST-${localDate}`,
              action: 'notification-digest-queued',
              field: 'digestQueue',
              oldValue: null,
              newValue: `recipients=${digestEmailsQueued}; items=${digestedNotificationCount}; suppressed=${suppressedRevokedCount}; deferred=${deferredWeeklyCount}`,
              byId: triggeredById,
              at: nowIso,
              reason: `Notification digest run (${localDate}, weekday=${isoWeekday}): queued ${digestEmailsQueued} digest email(s) covering ${digestedNotificationCount} notification(s).`,
            },
          ]);
        }

        const summary: NotificationDigestsJobSummary = {
          tenantId: ctx.tenantId,
          localDate,
          isoWeekday,
          undigestedExamined: undigested.length,
          digestEmailsQueued,
          digestedNotificationCount,
          suppressedRevokedCount,
          deferredWeeklyCount,
          nonDigestMarkedCount,
        };

        return {
          result: summary,
          summary: {
            undigestedExamined: undigested.length,
            digestEmailsQueued,
            digestedNotificationCount,
            suppressedRevokedCount,
            deferredWeeklyCount,
            nonDigestMarkedCount,
          },
        };
      },
    },
  );

  if (
    outcome.outcome === 'executed' &&
    outcome.result.digestEmailsQueued > 0 &&
    options.drainAfterCommit !== false &&
    (resolveEmailIntegrationConfig(tenantConfig).provider ?? 'disabled') !==
      'disabled'
  ) {
    try {
      await drainOutboxForTenant(ctx, {
        tenantConfig,
        outboxRepository: outboxRepo,
        emailSender: options.emailSender,
        secretReader: options.secretReader,
        storageProvider: options.storageProvider,
        actorId: triggeredById,
        now,
      });
    } catch {
      // Best-effort post-commit drain: queued emails remain durable in email_outbox.
    }
  }

  return outcome;
}

export async function runScheduledNotificationDigestsJobSweep(options?: {
  readonly registry?: TenantRegistry;
  readonly timeoutMs?: number;
  readonly digestHourLocal?: number;
  readonly guardedJobOptions?: GuardedJobOptions;
  readonly tenantConfigOverrideByTenantId?: Record<string, TenantConfiguration>;
  readonly emailSender?: EmailSender;
  readonly secretReader?: KeyVaultSecretReader;
  readonly storageProvider?: DocumentStorageProvider;
  readonly now?: Date;
}): Promise<ScheduledTenantJobSweepSummary> {
  assertTestOnlyTenantConfigOverride(options?.tenantConfigOverrideByTenantId);
  const registry = options?.registry ?? loadActiveTenantRegistry();
  const succeededTenants: string[] = [];
  const skippedTenants: Array<{
    readonly tenantId: string;
    readonly status: 'skipped' | 'already_running';
    readonly reason?: string;
  }> = [];
  const failedTenants: Array<{
    readonly tenantId: string;
    readonly errorCode?: string;
  }> = [];

  for (const entry of registry.tenants) {
    if (!entry.enabled) continue;
    try {
      const outcome = await guardedJob(
        'notification-digests',
        entry,
        async ({ tenantContext, tenantEntry, timeoutMs, signal }) => {
          const tenantConfig =
            options?.tenantConfigOverrideByTenantId?.[tenantEntry.tenantId] ??
            getTenantConfigurationForRegistryEntry(
              tenantEntry,
              registry.hostingMode,
            );
          return executeNotificationDigestsForTenant(tenantContext, {
            triggerSource: 'scheduled',
            triggeredById: 'system:notification-digests',
            timeZone: tenantEntry.timeZone,
            digestHourLocal: options?.digestHourLocal,
            statementTimeoutMs: timeoutMs,
            signal,
            tenantConfig,
            emailSender: options?.emailSender,
            secretReader: options?.secretReader,
            storageProvider: options?.storageProvider,
            now: options?.now,
          });
        },
        {
          registry,
          timeoutMs: options?.timeoutMs,
          ...options?.guardedJobOptions,
        },
      );
      if (outcome.outcome === 'executed') {
        succeededTenants.push(entry.tenantId);
      } else {
        skippedTenants.push({
          tenantId: entry.tenantId,
          status:
            outcome.outcome === 'already_running' ? 'already_running' : 'skipped',
          reason: outcome.outcome,
        });
      }
    } catch (err) {
      failedTenants.push({
        tenantId: entry.tenantId,
        errorCode: sanitizeJobErrorCode(err),
      });
    }
  }

  return {
    exitCode: failedTenants.length > 0 ? 1 : 0,
    succeededTenants,
    skippedTenants,
    failedTenants,
  };
}

export interface SearchGlobalRecordsInput {
  readonly query: string;
  readonly entityTypes?: readonly GlobalSearchEntityType[];
  readonly limit?: number;
  readonly offset?: number;
}

/**
 * Executes a tenant-scoped server-side hybrid search (FTS + trigram + ILIKE) across
 * all nine searchable record types, enforcing RBAC permissions and record-level
 * visibility inside PostgreSQL BEFORE ranking, pagination, or facet counting.
 */
export async function searchGlobalRecords(
  input: SearchGlobalRecordsInput,
  byId?: string,
  options?: { tenantCtx?: TenantContext | null },
): Promise<GlobalSearchResponse> {
  const startedAt = Date.now();
  const ctx =
    options?.tenantCtx ?? resolveDefaultServiceTenantContext(null, byId);
  const [people, teams, rbacConfig] = await Promise.all([
    loadStaffPeople(ctx),
    getHrAndRbacRepository().listAllTeams<Team>(ctx),
    loadEffectiveTenantRbacConfig(ctx),
  ]);
  const actorId = (byId ?? ctx.actorId).trim();
  const actor = people.find((p) => p.id === actorId && !p.mergedIntoId) ?? null;
  if (!actor) {
    return {
      query: input.query,
      normalizedQuery: input.query.trim().replace(/\s+/g, ' '),
      hits: [],
      totalCount: 0,
      countsByType: createZeroGlobalSearchCounts(),
      limit: Math.min(Math.max(Math.trunc(input.limit ?? 20), 1), 50),
      offset: Math.max(Math.trunc(input.offset ?? 0), 0),
      hasMore: false,
    };
  }

  const permSet = resolvePersonPermissionSet(actor, {
    teams,
    config: { rbac: rbacConfig },
  });
  const keyDatesConfig = await getKeyDatesConfig({ ctx, userId: actor.id });
  const keyDatePermissionOptions = {
    config: keyDatesConfig,
    allPeople: people,
    teams,
    rbac: { config: { rbac: rbacConfig } },
  };
  const canViewKeyDates =
    Boolean(keyDatesConfig.enabled) &&
    hasKeyDatePermission(actor, 'keydate:view', keyDatePermissionOptions);
  const permittedDiaryTeamIds = canViewKeyDates
    ? resolvePermittedDiaryTeamIds(
        actor,
        undefined,
        teams,
        keyDatePermissionOptions,
      )
    : [];

  const response = await getSearchRepository().searchRecords(ctx, {
    query: input.query,
    entityTypes: input.entityTypes,
    limit: input.limit,
    offset: input.offset,
    actor: {
      actorId: actor.id,
      hasRestrictedMatterAccess: permSet.permissions.has('matter:restricted:access'),
      canViewDocuments: permSet.permissions.has('document:view'),
      canViewQuotes: permSet.permissions.has('quote:view'),
      canViewFinance:
        permSet.permissions.has('finance:view') ||
        permSet.permissions.has('finance:view_matter'),
      canViewKeyDates,
      permittedDiaryTeamIds,
      canViewRegisters: permSet.permissions.has('register:view'),
      canManageUndertakings: permSet.permissions.has('undertaking:manage'),
    },
  });

  emitTenantTelemetryEvent({
    eventName: 'search.global.executed',
    tenantId: ctx.tenantId,
    correlationId: await resolveCurrentRequestCorrelationId(ctx.correlationId),
    properties: {
      resultCount: response.totalCount,
      returnedCount: response.hits.length,
      durationMs: Date.now() - startedAt,
      entityFilterCount: input.entityTypes?.length ?? 0,
    },
  });

  return response;
}

const INTAKE_PREVIEW_REQUIRED_PERMISSIONS = [
  'contact:create',
  'contact:edit',
  'employee:edit_core',
  'enquiry:create',
  'enquiry:edit',
  'quote:edit',
  'matter:create',
  'matter:edit',
] as const satisfies readonly PermissionKey[];

/**
 * Server-side read-only duplicate, known-entity, and optional preliminary conflict preview
 * for Person, Organisation, Enquiry, Quote, and Home Quick Capture forms (S1-02b C2).
 *
 * Uses SQL candidate queries when `includeConflicts !== true`, and `loadFullConflictSearchGraph`
 * with viewer visibility filtering + restricted matter redaction ONLY when `includeConflicts`
 * is true (backlog B22). Never mutates matters, writes audit logs, or returns HR/payroll data.
 */
export async function previewIntakeDuplicatesAndConflictsRecord(
  input: IntakePreviewInput,
  byId?: string,
  options?: { tenantCtx?: TenantContext | null },
): Promise<IntakePreviewResult> {
  const ctx =
    options?.tenantCtx ?? resolveDefaultServiceTenantContext(null, byId);
  const partyRepo = getPartyRepository();
  const intakeRepo = getIntakeQuoteRepository();
  const catalogueRepo = getCatalogueRepository();

  const [staffPeople, teams, rbacConfig, choiceValues] = await Promise.all([
    loadStaffPeople(ctx),
    getHrAndRbacRepository().listAllTeams<Team>(ctx),
    loadEffectiveTenantRbacConfig(ctx),
    catalogueRepo.listAllChoiceValues<ChoiceValue>(ctx),
  ]);

  const actorId = (byId ?? ctx.actorId ?? '').trim();
  const actor = staffPeople.find((p) => p.id === actorId && !p.mergedIntoId) ?? null;
  if (!actor) {
    throw new AuthorisationError({
      code: 'UNAUTHENTICATED',
      message: 'Authentication is required to preview duplicates and conflicts.',
      tenantId: ctx.tenantId,
      correlationId: ctx.correlationId,
      actorUserId: actorId || 'anonymous',
    });
  }

  const activeSession = getActiveActorSession();
  const effectiveTokenRoles =
    activeSession?.personId === actor.id ? activeSession.tokenRoles : undefined;
  const permSet = resolvePersonPermissionSet(actor, {
    allPeople: staffPeople,
    teams,
    tokenRoles: effectiveTokenRoles,
    tokenRolesActorId: actor.id,
    config: { rbac: rbacConfig },
    context: ctx,
  });

  const canPreviewIntake = INTAKE_PREVIEW_REQUIRED_PERMISSIONS.some((perm) =>
    permSet.permissions.has(perm),
  );
  if (!canPreviewIntake) {
    throw new AuthorisationError({
      code: 'FORBIDDEN',
      message: 'You do not have permission to preview intake duplicates or conflicts.',
      tenantId: ctx.tenantId,
      correlationId: ctx.correlationId,
      actorUserId: actor.id,
      requiredPermission: 'enquiry:create',
    });
  }

  const hasRestrictedMatterAccess = permSet.permissions.has('matter:restricted:access');
  const firstName = input.firstName?.trim() ?? '';
  const surname = (input.surname ?? input.lastName ?? '').trim();
  const lastName = (input.lastName ?? input.surname ?? '').trim();
  const preferredName = input.preferredName?.trim() ?? '';
  const otherNames = (input.otherNames ?? []).map((n) => n.trim()).filter(Boolean);
  const companyNumber = input.companyNumber?.trim() ?? '';
  const otherPartiesNamed = input.otherPartiesNamed?.trim() ?? '';
  const emails = (input.emails ?? []).map((e) => e.trim()).filter(Boolean);
  const phones = (input.phones ?? []).map((p) => p.trim()).filter(Boolean);
  const addresses = (input.addresses ?? []).filter(Boolean);
  const postcodes = addresses.map((a) => a.postcode?.trim() ?? '').filter(Boolean);
  const linkedPersonId = input.linkedPersonId?.trim() || null;
  const linkedOrganisationId = input.linkedOrganisationId?.trim() || null;
  const excludeId = input.excludeId?.trim() || undefined;
  const excludeEnquiryId = input.excludeEnquiryId?.trim() || null;
  const dismissedDuplicateIds = input.dismissedDuplicateIds ?? [];

  const [linkedPersonDirect, linkedOrgDirect] = await Promise.all([
    linkedPersonId
      ? partyRepo.getPersonById<Person>(ctx, linkedPersonId)
      : Promise.resolve<Person | null>(null),
    linkedOrganisationId
      ? partyRepo.getOrganisationById<Organisation>(ctx, linkedOrganisationId)
      : Promise.resolve<Organisation | null>(null),
  ]);

  let behalfRaw = (input.callingOnBehalfOf ?? input.legalName ?? '').trim();
  if (!behalfRaw && input.kind === 'person' && linkedOrgDirect) {
    behalfRaw = linkedOrgDirect.legalName;
  }

  const personOtherTerms = [...otherNames];
  if (behalfRaw && behalfRaw.includes(' ')) {
    personOtherTerms.push(behalfRaw);
  }
  const hasPersonSignal = Boolean(
    firstName ||
      surname ||
      preferredName ||
      personOtherTerms.length > 0 ||
      emails.length > 0 ||
      phones.length > 0 ||
      postcodes.length > 0,
  );
  const hasOrgSignal = Boolean(
    behalfRaw ||
      otherNames.length > 0 ||
      companyNumber ||
      emails.length > 0 ||
      phones.length > 0 ||
      postcodes.length > 0,
  );
  const enquirySearchTerms = Array.from(
    new Set(
      [
        `${firstName} ${lastName}`.trim(),
        preferredName ? `${preferredName} ${lastName}`.trim() : '',
        behalfRaw,
        ...otherNames,
        ...otherPartiesNamed.split(/[,;/\n]+/).map((s) => s.trim()),
      ].filter(Boolean),
    ),
  );
  const hasEnquirySignal = Boolean(
    enquirySearchTerms.length > 0 ||
      emails.length > 0 ||
      phones.length > 0 ||
      linkedPersonId ||
      linkedOrganisationId,
  );

  const [sqlCandidatePeople, sqlCandidateOrgs, sqlCandidateEnquiries, quoteOpenEnquiries] =
    await Promise.all([
      hasPersonSignal
        ? partyRepo.findSqlDuplicateCandidates<Person>(ctx, {
            kind: 'person',
            id: excludeId,
            firstName,
            preferredName,
            surname,
            otherNames: personOtherTerms,
            emails,
            phones,
            postcodes,
            fuzzy: true,
          })
        : Promise.resolve<Person[]>([]),
      hasOrgSignal
        ? partyRepo.findSqlDuplicateCandidates<Organisation>(ctx, {
            kind: 'organisation',
            id: excludeId,
            legalName: behalfRaw,
            otherNames,
            companyNumber,
            emails,
            phones,
            postcodes,
            fuzzy: true,
          })
        : Promise.resolve<Organisation[]>([]),
      hasEnquirySignal
        ? intakeRepo.findSqlConflictEnquiryCandidates<Enquiry>(ctx, {
            terms: enquirySearchTerms,
            emails,
            phones,
            linkedPersonIds: linkedPersonId ? [linkedPersonId] : [],
            linkedOrganisationIds: linkedOrganisationId ? [linkedOrganisationId] : [],
            excludeEnquiryId,
            viewerId: actor.id,
            hasRestrictedMatterAccess,
          })
        : Promise.resolve<Enquiry[]>([]),
      input.kind === 'quote' && (linkedPersonId || linkedOrganisationId)
        ? Promise.all([
            linkedPersonId
              ? intakeRepo.listVisibleEnquiries<Enquiry>(ctx, actor.id, {
                  openOnly: true,
                  linkedPersonId,
                  hasRestrictedMatterAccess,
                  limit: 25,
                })
              : Promise.resolve<Enquiry[]>([]),
            linkedOrganisationId
              ? intakeRepo.listVisibleEnquiries<Enquiry>(ctx, actor.id, {
                  openOnly: true,
                  linkedOrganisationId,
                  hasRestrictedMatterAccess,
                  limit: 25,
                })
              : Promise.resolve<Enquiry[]>([]),
          ]).then(([byP, byO]) => dedupeById([...byP, ...byO]))
        : Promise.resolve<Enquiry[]>([]),
    ]);

  const candidatePeopleAll = dedupeById([
    ...sqlCandidatePeople,
    ...(linkedPersonDirect ? [linkedPersonDirect] : []),
  ]).map((p) => sanitizePersonForClientPreview(p));
  const candidateOrgsAll = dedupeById([
    ...sqlCandidateOrgs,
    ...(linkedOrgDirect ? [linkedOrgDirect] : []),
  ]);

  const candidatePeopleWithoutSelf = excludeId
    ? candidatePeopleAll.filter((p) => p.id !== excludeId)
    : candidatePeopleAll;
  const candidateOrgsWithoutSelf = excludeId
    ? candidateOrgsAll.filter((o) => o.id !== excludeId)
    : candidateOrgsAll;

  const visibleEnquiriesForMerge = sqlCandidateEnquiries.map((e) => ({
    ...e,
    conflictSnapshot: undefined,
  }));

  const duplicatePeople =
    input.kind === 'person' || input.kind === 'quick_enquiry'
      ? findPersonDuplicates(
          {
            id: excludeId,
            firstName,
            surname,
            preferredName,
            emails,
            phones,
            addresses: addresses.filter((a) => (a.line1 ?? '').trim() && (a.postcode ?? '').trim()),
          },
          mergePeopleWithEnquiries(
            candidatePeopleAll,
            visibleEnquiriesForMerge,
            choiceValues,
            excludeEnquiryId,
          ),
          [...dismissedDuplicateIds],
          { fuzzy: true },
        )
          .filter(
            (m) =>
              input.kind !== 'person' ||
              m.reasons.some((r) => r !== 'address' && r !== 'postcode'),
          )
          .map((m) => ({
            ...m,
            record: sanitizePersonForClientPreview(m.record),
          }))
      : [];

  const duplicateOrganisations =
    input.kind === 'organisation' || (input.kind === 'quick_enquiry' && Boolean(behalfRaw))
      ? findOrganisationDuplicates(
          {
            id: excludeId,
            legalName: behalfRaw,
            otherNames,
            companyNumber,
            emails,
            phones,
            addresses: addresses.filter((a) => (a.line1 ?? '').trim() && (a.postcode ?? '').trim()),
          },
          candidateOrgsAll,
          [...dismissedDuplicateIds],
          { fuzzy: true },
        ).filter(
          (m) =>
            input.kind !== 'organisation' ||
            m.reasons.some((r) => r !== 'address' && r !== 'postcode'),
        )
      : [];

  const primaryAddr = addresses[0];
  const entityMatchesPeoplePool =
    input.kind === 'organisation'
      ? mergePeopleWithEnquiries(
          candidatePeopleWithoutSelf,
          visibleEnquiriesForMerge,
          choiceValues,
          excludeEnquiryId,
        )
      : candidatePeopleWithoutSelf;

  const entityMatchesRaw = findEnquiryEntityMatches(
    {
      firstName: input.kind === 'organisation' ? '' : firstName,
      lastName: input.kind === 'organisation' ? '' : lastName,
      email: emails[0] ?? '',
      phone: phones[0] ?? '',
      callingOnBehalfOf: behalfRaw,
      postcode: primaryAddr?.postcode ?? '',
      addressLine1: primaryAddr?.line1 ?? '',
      addressLine2: primaryAddr?.line2 ?? '',
      otherPartiesNamed:
        input.kind === 'organisation' ? '' : otherPartiesNamed,
    },
    entityMatchesPeoplePool,
    candidateOrgsWithoutSelf,
    visibleEnquiriesForMerge,
    excludeEnquiryId,
  );

  const entityMatches = {
    people: entityMatchesRaw.people.map((entry) => ({
      ...entry,
      person: sanitizePersonForClientPreview(entry.person),
    })),
    organisations: entityMatchesRaw.organisations,
  };

  let activeLinkedEnquiries: Enquiry[] = [];
  if (input.kind === 'quote') {
    const pNorm = normaliseComparableName(
      linkedPersonDirect
        ? `${linkedPersonDirect.firstName} ${linkedPersonDirect.surname}`
        : `${firstName} ${surname}`,
    );
    const oNorm = normaliseComparableName(
      linkedOrgDirect?.legalName || behalfRaw,
    );
    const openCandidates = dedupeById([
      ...quoteOpenEnquiries,
      ...visibleEnquiriesForMerge.filter((e) => isEnquiryOpen(e)),
    ]);
    activeLinkedEnquiries = openCandidates
      .filter((e) => {
        if (!isEnquiryOpen(e)) return false;
        if (linkedPersonId && (e.linkedPersonId === linkedPersonId || e.id === linkedPersonId)) {
          return true;
        }
        if (linkedOrganisationId && e.linkedOrganisationId === linkedOrganisationId) {
          return true;
        }
        if (pNorm && normaliseComparableName(`${e.firstName} ${e.lastName}`) === pNorm) {
          return true;
        }
        if (oNorm && e.callingOnBehalfOf && normaliseComparableName(e.callingOnBehalfOf) === oNorm) {
          return true;
        }
        return false;
      })
      .map((e) => ({ ...e, conflictSnapshot: undefined }));
  }

  let conflictSearch: IntakePreviewResult['conflictSearch'] = null;
  let possibleConflicts: IntakePreviewResult['possibleConflicts'] = [];

  const hasConflictSignal = Boolean(
    enquirySearchTerms.length > 0 ||
      emails.length > 0 ||
      phones.length > 0 ||
      postcodes.length > 0 ||
      linkedPersonId ||
      linkedOrganisationId,
  );

  if (input.includeConflicts && hasConflictSignal) {
    const graph = await loadFullConflictSearchGraph(
      ctx,
      {
        terms: enquirySearchTerms,
        emails,
        phones,
        postcodes,
        linkedPersonIds: linkedPersonId ? [linkedPersonId] : [],
        linkedOrganisationIds: linkedOrganisationId ? [linkedOrganisationId] : [],
        excludeEnquiryId,
      },
      actor.id,
      staffPeople,
      teams,
      rbacConfig,
    );
    const graphPeople = dedupeById([
      ...staffPeople,
      ...graph.people,
      ...(linkedPersonDirect ? [linkedPersonDirect] : []),
    ]);
    const graphOrgs = dedupeById([
      ...graph.organisations,
      ...(linkedOrgDirect ? [linkedOrgDirect] : []),
    ]);
    const finalGraphPeople = excludeId
      ? graphPeople.filter((p) => p.id !== excludeId)
      : graphPeople;
    const finalGraphOrgs = excludeId
      ? graphOrgs.filter((o) => o.id !== excludeId)
      : graphOrgs;
    const visibleEnquiriesForConflict = graph.enquiries.filter((e) =>
      graph.canViewEnquiry(e),
    );

    const searchRes = runEnquiryConflictSearch(
      {
        firstName: input.kind === 'organisation' ? '' : firstName,
        lastName: input.kind === 'organisation' ? '' : lastName,
        callingOnBehalfOf: behalfRaw,
        otherPartiesNamed,
        email: emails[0] ?? '',
        phone: phones[0] ?? '',
        address: {
          line1: primaryAddr?.line1 ?? '',
          line2: primaryAddr?.line2 ?? '',
          postcode: primaryAddr?.postcode ?? '',
        },
        linkedPersonId:
          input.kind === 'person' || input.kind === 'organisation'
            ? null
            : linkedPersonId,
        linkedOrganisationId:
          input.kind === 'organisation' ? null : linkedOrganisationId,
      },
      finalGraphPeople,
      finalGraphOrgs,
      graph.matters,
      choiceValues,
      visibleEnquiriesForConflict,
      excludeEnquiryId,
      graph.links,
      graph.canViewMatter,
      ctx.tenantId,
    );
    conflictSearch = searchRes;
    possibleConflicts = searchRes.allConflicts;
  }

  return {
    duplicatePeople,
    duplicateOrganisations,
    entityMatches,
    activeLinkedEnquiries,
    possibleConflicts,
    conflictSearch,
  };
}

/**
 * Server-side scoped entity picker lookup for link dropdowns, client lookups,
 * prospect pickers, and corporate-group expansion (S1-02b C2).
 *
 * Enforces RBAC, restricted matter / personal-Draft enquiry SQL filtering, and
 * strips all HR/employment, payroll, sensitive, override, and Entra fields.
 */
export async function searchEntityPickerRecord(
  input: EntityPickerSearchInput,
  byId?: string,
  options?: { tenantCtx?: TenantContext | null },
): Promise<EntityPickerSearchResult> {
  const ctx =
    options?.tenantCtx ?? resolveDefaultServiceTenantContext(null, byId);
  const partyRepo = getPartyRepository();
  const matterRepo = getMatterRepository();
  const intakeRepo = getIntakeQuoteRepository();

  const [staffPeople, teams, rbacConfig] = await Promise.all([
    loadStaffPeople(ctx),
    getHrAndRbacRepository().listAllTeams<Team>(ctx),
    loadEffectiveTenantRbacConfig(ctx),
  ]);
  const actorId = (byId ?? ctx.actorId ?? '').trim();
  const actor = staffPeople.find((p) => p.id === actorId && !p.mergedIntoId) ?? null;
  if (!actor) {
    throw new AuthorisationError({
      code: 'UNAUTHENTICATED',
      message: 'Authentication is required to search records.',
      tenantId: ctx.tenantId,
      correlationId: ctx.correlationId,
      actorUserId: actorId || 'anonymous',
    });
  }

  const activeSession = getActiveActorSession();
  const effectiveTokenRoles =
    activeSession?.personId === actor.id ? activeSession.tokenRoles : undefined;
  const permSet = resolvePersonPermissionSet(actor, {
    allPeople: staffPeople,
    teams,
    tokenRoles: effectiveTokenRoles,
    tokenRolesActorId: actor.id,
    config: { rbac: rbacConfig },
    context: ctx,
  });

  const hasRestrictedMatterAccess = permSet.permissions.has('matter:restricted:access');
  const canViewQuotes = permSet.permissions.has('quote:view');
  const limit = Math.max(1, Math.min(50, Math.floor(input.limit ?? 20)));
  const excludeIds = Array.from(
    new Set((input.excludeIds ?? []).map((id) => id?.trim()).filter(Boolean) as string[]),
  );
  const excludeSet = new Set(excludeIds);
  const types = new Set(input.entityTypes);

  if (input.corporateGroupOfOrgId?.trim()) {
    const groupOrgId = input.corporateGroupOfOrgId.trim();
    const [targetOrg, groupOrgs] = await Promise.all([
      partyRepo.getOrganisationById<Organisation>(ctx, groupOrgId),
      partyRepo.expandCorporateGroupOrganisationIds<Organisation>(ctx, [groupOrgId]),
    ]);
    const combinedOrgs = dedupeById([
      ...(targetOrg?.parentOrganisationId
        ? await partyRepo.listOrganisationsByIds<Organisation>(ctx, [
            targetOrg.parentOrganisationId,
          ])
        : []),
      ...groupOrgs,
    ]).filter((o) => !o.mergedIntoId && o.id !== groupOrgId && !excludeSet.has(o.id));
    return {
      items: combinedOrgs.slice(0, limit).map((o) => ({
        id: o.id,
        recordType: 'organisation' as const,
        label: o.legalName,
        subtitle:
          targetOrg?.parentOrganisationId === o.id
            ? 'Parent company'
            : o.parentOrganisationId === groupOrgId
              ? 'Subsidiary company'
              : 'Group company',
        reference: o.id,
        href: `/organisations/${o.id}`,
        organisation: o,
      })),
    };
  }

  if (input.personQuery) {
    const fn = input.personQuery.firstName?.trim() ?? '';
    const sn = input.personQuery.surname?.trim() ?? '';
    const orgQ = input.personQuery.organisationName?.trim() ?? '';
    if (!fn && !sn && !orgQ) {
      return { items: [] };
    }
    const wantPeople = types.has('person');
    const wantOrgs = types.has('organisation');
    const [candPeople, candOrgsDirect, candEnquiries] = await Promise.all([
      wantPeople
        ? partyRepo.findSqlDuplicateCandidates<Person>(ctx, {
            kind: 'person',
            firstName: fn,
            surname: sn,
            otherNames: orgQ ? [orgQ] : [],
            fuzzy: true,
          })
        : Promise.resolve<Person[]>([]),
      wantOrgs || orgQ
        ? partyRepo.findSqlDuplicateCandidates<Organisation>(ctx, {
            kind: 'organisation',
            legalName: orgQ || `${fn} ${sn}`.trim(),
            fuzzy: true,
          })
        : Promise.resolve<Organisation[]>([]),
      wantPeople && input.includeEnquiryProspects
        ? intakeRepo.findSqlConflictEnquiryCandidates<Enquiry>(ctx, {
            terms: [fn, sn, `${fn} ${sn}`.trim(), orgQ].filter(Boolean),
            viewerId: actor.id,
            hasRestrictedMatterAccess,
          })
        : Promise.resolve<Enquiry[]>([]),
    ]);

    const mergedPeople = input.includeEnquiryProspects
      ? mergePeopleWithEnquiries(candPeople, candEnquiries, [])
      : candPeople;
    const personIds = mergedPeople.map((p) => p.id);
    const links =
      personIds.length > 0
        ? await partyRepo.listLinksForEntities<PersonOrganisationLink>(ctx, {
            personIds,
          })
        : [];
    const linkedOrgIds = Array.from(
      new Set(links.map((l) => l.organisationId).filter(Boolean)),
    );
    const missingOrgIds = linkedOrgIds.filter(
      (id) => !candOrgsDirect.some((o) => o.id === id),
    );
    const linkedOrgsExtra =
      missingOrgIds.length > 0
        ? await partyRepo.listOrganisationsByIds<Organisation>(ctx, missingOrgIds)
        : [];
    const allOrgs = dedupeById([...candOrgsDirect, ...linkedOrgsExtra]);

    return {
      items: scoreFuzzyPersonOrgQuery({
        personQuery: input.personQuery,
        people: mergedPeople,
        organisations: allOrgs,
        links,
        includePeople: wantPeople,
        includeOrganisations: wantOrgs,
        excludeIds: excludeSet,
        excludeDemo: input.excludeDemo,
        employeesOnly: input.employeesOnly,
        nonEmployeesOnly: input.nonEmployeesOnly,
        limit,
      }),
    };
  }

  const query = input.query?.trim() ?? '';
  const fetchLimit = Math.min(100, limit * 2);

  const [peopleRaw, orgsRaw, mattersRaw, enquiriesRaw, quotesRaw] =
    await Promise.all([
      types.has('person')
        ? partyRepo.searchPeople<Person>(ctx, query, {
            includeMerged: false,
            employeesOnly: input.employeesOnly,
            excludeIds,
            limit: fetchLimit,
          })
        : Promise.resolve<Person[]>([]),
      types.has('organisation')
        ? partyRepo.searchOrganisations<Organisation>(ctx, query, {
            includeMerged: false,
            excludeIds,
            limit,
          })
        : Promise.resolve<Organisation[]>([]),
      types.has('matter')
        ? matterRepo.searchVisibleMatters<Matter>(ctx, query, {
            viewerId: actor.id,
            hasRestrictedMatterAccess,
            includeMerged: false,
            excludeIds,
            limit,
          })
        : Promise.resolve<Matter[]>([]),
      types.has('enquiry')
        ? intakeRepo.listVisibleEnquiries<Enquiry>(ctx, actor.id, {
            query,
            excludeIds,
            hasRestrictedMatterAccess,
            limit,
          })
        : Promise.resolve<Enquiry[]>([]),
      types.has('quote') && canViewQuotes
        ? intakeRepo.listVisibleQuotes<Quote>(ctx, actor.id, {
            query,
            excludeIds,
            hasRestrictedMatterAccess,
            limit,
          })
        : Promise.resolve<Quote[]>([]),
    ]);

  const filteredPeople = peopleRaw
    .filter((p) => {
      if (excludeSet.has(p.id)) return false;
      if (input.excludeDemo && p.demo) return false;
      if (input.nonEmployeesOnly && p.isEmployee) return false;
      return true;
    })
    .slice(0, limit);

  let linkedOrgById = new Map<string, Organisation>();
  const personLinksByPersonId = new Map<string, PersonOrganisationLink[]>();
  if (input.includeLinkedOrgs && filteredPeople.length > 0) {
    const pLinks = await partyRepo.listLinksForEntities<PersonOrganisationLink>(
      ctx,
      { personIds: filteredPeople.map((p) => p.id) },
    );
    for (const l of pLinks) {
      if (!l.isCurrent) continue;
      const arr = personLinksByPersonId.get(l.personId) ?? [];
      arr.push(l);
      personLinksByPersonId.set(l.personId, arr);
    }
    const orgIds = Array.from(
      new Set(pLinks.filter((l) => l.isCurrent).map((l) => l.organisationId)),
    );
    if (orgIds.length > 0) {
      const orgRows = await partyRepo.listOrganisationsByIds<Organisation>(ctx, orgIds);
      linkedOrgById = new Map(orgRows.map((o) => [o.id, o]));
    }
  }

  const matterClientIds = mattersRaw.map((m) => m.clientId).filter(Boolean);
  const quoteClientPersonIds = quotesRaw
    .map((q) => q.linkedPersonId)
    .filter((id): id is string => Boolean(id));
  const quoteClientOrgIds = quotesRaw
    .map((q) => q.linkedOrganisationId)
    .filter((id): id is string => Boolean(id));
  const batchPersonIds = Array.from(
    new Set([
      ...matterClientIds.filter((id) => id.startsWith('P-')),
      ...quoteClientPersonIds,
    ]),
  );
  const batchOrgIds = Array.from(
    new Set([
      ...matterClientIds.filter((id) => id.startsWith('O-')),
      ...quoteClientOrgIds,
    ]),
  );
  const [batchPeople, batchOrgs] = await Promise.all([
    batchPersonIds.length > 0
      ? partyRepo.listPeopleByIds<Person>(ctx, batchPersonIds)
      : Promise.resolve<Person[]>([]),
    batchOrgIds.length > 0
      ? partyRepo.listOrganisationsByIds<Organisation>(ctx, batchOrgIds)
      : Promise.resolve<Organisation[]>([]),
  ]);
  const clientNameById = new Map<string, string>([
    ...batchPeople.map((p) => [p.id, personDisplayName(p)] as const),
    ...batchOrgs.map((o) => [o.id, o.legalName] as const),
  ]);

  const items: EntityPickerOption[] = [];

  for (const m of mattersRaw) {
    const clientName = clientNameById.get(m.clientId) ?? '';
    items.push({
      id: m.id,
      recordType: 'matter',
      label: `${m.matterNumber} — ${m.title || 'Untitled matter'}`,
      subtitle: clientName,
      reference: m.matterNumber,
      href: `/matters/${m.id}`,
      matter: m,
    });
  }

  for (const e of enquiriesRaw) {
    const safeEnquiry: Enquiry = { ...e, conflictSnapshot: undefined };
    items.push({
      id: safeEnquiry.id,
      recordType: 'enquiry',
      label: `${safeEnquiry.reference} — ${enquiryDisplayName(safeEnquiry, 'Unnamed enquiry')}`,
      subtitle: safeEnquiry.summary || safeEnquiry.callingOnBehalfOf || '',
      reference: safeEnquiry.reference,
      href: `/enquiries/${safeEnquiry.id}`,
      enquiry: safeEnquiry,
    });
  }

  for (const q of quotesRaw) {
    items.push({
      id: q.id,
      recordType: 'quote',
      label: `${q.reference} — ${quoteClientDisplayName(q, batchPeople, batchOrgs)}`,
      subtitle: q.scope || '',
      reference: q.reference,
      href: `/quotes/${q.id}`,
      quote: q,
    });
  }

  for (const o of orgsRaw) {
    items.push({
      id: o.id,
      recordType: 'organisation',
      label: o.legalName,
      subtitle: [
        (o.otherNames ?? []).map((n) => n.name).join(', '),
        o.companyNumber ? `Co. ${o.companyNumber}` : '',
        o.generalEmail,
      ]
        .filter(Boolean)
        .join(' · '),
      reference: o.id,
      href: `/organisations/${o.id}`,
      organisation: o,
    });
  }

  for (const p of filteredPeople) {
    const safePerson = sanitizePersonForClientPreview(p, {
      preserveNonEmployeeDob: true,
    });
    const linkedOrgs = (personLinksByPersonId.get(p.id) ?? [])
      .map((l) => linkedOrgById.get(l.organisationId))
      .filter((o): o is Organisation => Boolean(o && !o.mergedIntoId));
    items.push({
      id: p.id,
      recordType: 'person',
      label: personDisplayName(p),
      subtitle: [p.jobTitle || null, primaryEmail(p), p.addresses?.[0]?.town ?? null]
        .filter(Boolean)
        .join(' · '),
      reference: p.id,
      href: `/people/${p.id}`,
      person: safePerson,
      ...(input.includeLinkedOrgs ? { linkedOrgs } : {}),
    });
  }

  return { items: items.slice(0, limit) };
}

